window.songs=[{"order":2,"id":"02-du-wirst-niemals-eine-lady","title":"Du wirst niemals eine Lady","titleZh":"你永远成不了淑女","lines":[{"id":"rebecca-das-musical-02-001","lineIndex":1,"speaker":"","original":"Sie kennen doch meine Gesellschafterin. Haben Sie sie gesehen?","sourceLineIndex":1,"ipa":"/ziː kˈɛnən dɔx mˌaɪnə ɡəzˈɛlʃaftərˌɪn hˌɑːbən ziː ziː ɡəzˈeːən/","en":"You know my partner. Have you seen her?","zh":"你认识我的搭档。你见过她吗？","note":""},{"id":"rebecca-das-musical-02-002","lineIndex":2,"speaker":"","original":"Bedaure, nein, Madame","sourceLineIndex":2,"ipa":"/bədˈaʊrə nˈaɪn mˈɑdɑːmə/","en":"Sorry, no, madame","zh":"抱歉，不，女士","note":""},{"id":"rebecca-das-musical-02-003","lineIndex":3,"speaker":"","original":"Da bist du ja endlich! Wo um Himmels Willen warst du so lange?","sourceLineIndex":3,"ipa":"/dɑː bɪst duː jˈɑː ˈɛntlɪç vˌoː ʊm hˈɪməls vˈɪlən vɑːɾst duː zoː lˈaŋə/","en":"There you are finally! Where on earth were you for so long?","zh":"你终于来了！这么长时间以来你到底在哪里？","note":""},{"id":"rebecca-das-musical-02-004","lineIndex":4,"speaker":"","original":"Ich musste noch die Modezeitschrift holen","sourceLineIndex":4,"ipa":"/ɪç mˈʊstə nɔx diː mˈoːdeːtsˌaɪtʃrɪft hˈoːlən/","en":"I still had to get the fashion magazine","zh":"我还得拿时尚杂志","note":""},{"id":"rebecca-das-musical-02-005","lineIndex":5,"speaker":"","original":"Warum denn das?","sourceLineIndex":5,"ipa":"/vɑːrˈʊm dɛn das/","en":"Why is that?","zh":"这是为什么呢？","note":""},{"id":"rebecca-das-musical-02-006","lineIndex":6,"speaker":"","original":"Sie wollten sie lesen, Mrs. Van Hopper","sourceLineIndex":6,"ipa":"/ziː vɔltən ziː lˈeːzən ˌɛmˌɛrˈɛs vˈɑːn hˈɔpɜ/","en":"You wanted to read it, Mrs. Van Hopper","zh":"你想读它，范霍珀夫人","note":""},{"id":"rebecca-das-musical-02-007","lineIndex":7,"speaker":"","original":"Ich bezahle für deine Gesellschaft, mein Kind","sourceLineIndex":7,"ipa":"/ɪç bətsˈɑːlə fyːɾ dˌaɪnə ɡəzˈɛlʃaft maɪn kˈɪnt/","en":"I pay for your company, my child","zh":"我为你的公司付钱，我的孩子","note":""},{"id":"rebecca-das-musical-02-008","lineIndex":8,"speaker":"","original":"Und ich hasse es, zu warten","sourceLineIndex":8,"ipa":"/ʊnt ɪç hˈasə ɛs tsuː vˈaɾtən/","en":"And I hate waiting","zh":"我讨厌等待","note":""},{"id":"rebecca-das-musical-02-009","lineIndex":9,"speaker":"","original":"Sorry, Mrs. Van Hopper","sourceLineIndex":9,"ipa":"/sˈɒɹi ˌɛmˌɛrˈɛs vˈɑːn hˈɔpɜ/","en":"Sorry, Mrs. Van Hopper","zh":"对不起，范霍珀夫人","note":""},{"id":"rebecca-das-musical-02-010","lineIndex":10,"speaker":"","original":"Keine Sahne!","sourceLineIndex":10,"ipa":"/kˈaɪnə zˈɑːnə/","en":"No cream!","zh":"没有奶油！","note":""},{"id":"rebecca-das-musical-02-011","lineIndex":11,"speaker":"","original":"Dieser Kellner ist ein Vollidiot","sourceLineIndex":11,"ipa":"/dˌiːzɜ kˈɛlnɜ ɪst aɪn fˈɔliːdˌɪoːt/","en":"This waiter is a complete idiot","zh":"这个服务员简直就是个白痴","note":""},{"id":"rebecca-das-musical-02-012","lineIndex":12,"speaker":"","original":"Ich ruf ihn, Mrs. Van Hopper","sourceLineIndex":12,"ipa":"/ɪç rˈuːf ˈiːn ˌɛmˌɛrˈɛs vˈɑːn hˈɔpɜ/","en":"I'll call him, Mrs. Van Hopper","zh":"我会打电话给他，范霍珀夫人","note":""},{"id":"rebecca-das-musical-02-013","lineIndex":13,"speaker":"","original":"Bitte, Monsieur","sourceLineIndex":13,"ipa":"/bˈɪtə mˌɔnziːˈuːɾ/","en":"Please, monsieur","zh":"请，先生","note":""},{"id":"rebecca-das-musical-02-014","lineIndex":14,"speaker":"","original":"Nenn ihn nicht Monsieur, und bitte ihn nicht!","sourceLineIndex":14,"ipa":"/nˈɛn iːn nˈɪçt mˌɔnziːˈuːɾ ʊnt bˈɪtə iːn nˈɪçt/","en":"Don't call him monsieur, and don't ask him!","zh":"别叫他先生，也别问他！","note":""},{"id":"rebecca-das-musical-02-015","lineIndex":15,"speaker":"","original":"Bitte sehr, etwas Sahne","sourceLineIndex":15,"ipa":"/bˈɪtə zˈeːɾ ˈɛtvɑːs zˈɑːnə/","en":"Please, some cream","zh":"请给我一些奶油","note":""},{"id":"rebecca-das-musical-02-016","lineIndex":16,"speaker":"","original":"Mein Gott!","sourceLineIndex":16,"ipa":"/maɪn ɡˈɔt/","en":"My God!","zh":"天哪！","note":""},{"id":"rebecca-das-musical-02-017","lineIndex":17,"speaker":"","original":"In Fünf-Sterne-Hotels schenkt der zahlende Gast","sourceLineIndex":17,"ipa":"/ɪn fˈʏnfʃtˈɛɾnəhˈoːtəls ʃˈɛŋkt dɛɾ tsˈɑːləndə ɡˈast/","en":"In five-star hotels, the paying guest gives gifts","zh":"五星级酒店，付费客人赠送礼物","note":""},{"id":"rebecca-das-musical-02-018","lineIndex":18,"speaker":"","original":"Dem Kellner kein Lächeln","sourceLineIndex":18,"ipa":"/deːm kˈɛlnɜ kˈaɪn lˈɛçəln/","en":"The paying guest gives the waiter no smile","zh":"付费客人不给服务员一个微笑","note":""},{"id":"rebecca-das-musical-02-019","lineIndex":19,"speaker":"","original":"Sorry, Mrs. Van Hopper","sourceLineIndex":19,"ipa":"/sˈɒɹi ˌɛmˌɛrˈɛs vˈɑːn hˈɔpɜ/","en":"Sorry, Mrs. Van Hopper","zh":"对不起，范霍珀夫人","note":""},{"id":"rebecca-das-musical-02-020","lineIndex":20,"speaker":"","original":"Statt \"Bitte\" zu sagen, das merk dir, mein Kind","sourceLineIndex":20,"ipa":"/ʃtˈat bˈɪtə tsuː zˈɑːɡən das mˈɛɾk dˈiːɾ maɪn kˈɪnt/","en":"Instead of saying \"please, \" remember that, my child","zh":"不要说“请”，请记住，我的孩子","note":""},{"id":"rebecca-das-musical-02-021","lineIndex":21,"speaker":"","original":"Gibt man hier Befehle","sourceLineIndex":21,"ipa":"/ɡˈiːpt man hˈiːɾ bəfˈeːlə/","en":"You give orders here","zh":"你在这里发号施令","note":""},{"id":"rebecca-das-musical-02-022","lineIndex":22,"speaker":"","original":"Ja, Mrs. Van Hopper","sourceLineIndex":22,"ipa":"/jˈɑː ˌɛmˌɛrˈɛs vˈɑːn hˈɔpɜ/","en":"Yes, Mrs. Van Hopper","zh":"是的，范霍珀夫人","note":""},{"id":"rebecca-das-musical-02-023","lineIndex":23,"speaker":"","original":"Verwahrlost und elternlos kamst du zu mir","sourceLineIndex":23,"ipa":"/fɛɾvˈɑːɾlɔst ʊnt ˈɛltɛɾnlˌoːs kˌɑːmst duː tsuː mˈiːɾ/","en":"You came to me neglected and parentless","zh":"你来到我身边时被忽视了，而且失去了父母","note":""},{"id":"rebecca-das-musical-02-024","lineIndex":24,"speaker":"","original":"Ich nahm dich aus Mitleid","sourceLineIndex":24,"ipa":"/ɪç nˈɑːm dɪç ˌaʊs mˈɪtlˌaɪt/","en":"I took you out of pity","zh":"我出于怜悯而带走了你","note":""},{"id":"rebecca-das-musical-02-025","lineIndex":25,"speaker":"","original":"Das weiß ich, Mrs. Van Hopper","sourceLineIndex":25,"ipa":"/das vˈaɪs ɪç ˌɛmˌɛrˈɛs vˈɑːn hˈɔpɜ/","en":"I know that, Mrs. Van Hopper","zh":"我知道，范霍珀夫人","note":""},{"id":"rebecca-das-musical-02-026","lineIndex":26,"speaker":"","original":"Zum Dank muss ich mich täglich für dich genier'n","sourceLineIndex":26,"ipa":"/tsʊm dˈaŋk mˈʊs ɪç mɪç tˈɛːklɪç fyːɾ dɪç ɡənˈiːɾn/","en":"As thanks, I have to feel embarrassed because of you every day","zh":"作为回报，我却每天都要因你感到难堪","note":""},{"id":"rebecca-das-musical-02-027","lineIndex":27,"speaker":"","original":"Und mehr und mehr wird mir klar:","sourceLineIndex":27,"ipa":"/ʊnt mˈeːɾ ʊnt mˈeːɾ vˌɪɾt miːɾ klˈɑːɾ/","en":"And more and more I realize:","zh":"我越来越意识到：","note":""},{"id":"rebecca-das-musical-02-028","lineIndex":28,"speaker":"","original":"Du wirst niemals eine Lady, weil dir jede Klasse fehlt","sourceLineIndex":28,"ipa":"/duː vˌɪɾst nˈiːmɑːls ˌaɪnə lˈeɪdi vˌaɪl diːɾ jˈeːdə klˈasə fˈeːlt/","en":"You'll never be a lady because you lack any class","zh":"你永远成不了淑女，因为你缺乏阶级","note":""},{"id":"rebecca-das-musical-02-029","lineIndex":29,"speaker":"","original":"Du wirst immer eine kleine, unscheinbare scheue graue Maus sein","sourceLineIndex":29,"ipa":"/duː vˌɪɾst ˈɪmɜ ˌaɪnə klˈaɪnə ˈʊnʃˌaɪnbɑːrə ʃˈɔøə ɡɾˈaʊə mˈaʊs zaɪn/","en":"You will always be a small, inconspicuous, shy gray mouse","zh":"你永远是一只小小、不起眼、害羞的灰老鼠","note":""},{"id":"rebecca-das-musical-02-030","lineIndex":30,"speaker":"","original":"So sehr ich mich auch quäle, ganz egal, was ich erzähle","sourceLineIndex":30,"ipa":"/zoː zˈeːɾ ɪç mɪç ˌaʊx kvˈɛːlə ɡˌants eːɡˈɑːl vˈas ɪç ɛɾtsˈɛːlə/","en":"No matter how much I torture myself, no matter what I say","zh":"无论我如何折磨自己，无论我说什么","note":""},{"id":"rebecca-das-musical-02-031","lineIndex":31,"speaker":"","original":"Du wirst es nicht lernen, nein, niemals wirst du eine Lady sein","sourceLineIndex":31,"ipa":"/duː vˌɪɾst ɛs nˈɪçt lˈɛɾnən nˈaɪn nˈiːmɑːls vˌɪɾst duː ˌaɪnə lˈeɪdi zaɪn/","en":"You won't learn, no, you'll never be a lady","zh":"你不会学习，不，你永远不会成为一位女士","note":""},{"id":"rebecca-das-musical-02-032","lineIndex":32,"speaker":"","original":"Hörst du mir überhaupt zu, was gibt's zu glotzen?","sourceLineIndex":32,"ipa":"/hˈøːɾst duː miːɾ ˌyːbɜhˈaʊpt tsˈuː vˈas ɡˈɪpts tsuː ɡlˈɔtsən/","en":"Are you even listening to me, what's there to stare at?","zh":"你到底有没有在听我说话，有什么可看的？","note":""},{"id":"rebecca-das-musical-02-033","lineIndex":33,"speaker":"","original":"In Fünf-Sterne-Hotels, das merk dir, mein Kind","sourceLineIndex":33,"ipa":"/ɪn fˈʏnfʃtˈɛɾnəhˈoːtəls das mˈɛɾk dˈiːɾ maɪn kˈɪnt/","en":"In five-star hotels, remember that, my child","zh":"在五星级酒店，记住这一点，我的孩子","note":""},{"id":"rebecca-das-musical-02-034","lineIndex":34,"speaker":"","original":"Begafft man nicht Fremde","sourceLineIndex":34,"ipa":"/bəɡˈaft man nˈɪçt frˈɛmdə/","en":"Don't stare at strangers","zh":"不要盯着陌生人看","note":""},{"id":"rebecca-das-musical-02-035","lineIndex":35,"speaker":"","original":"Sorry, Mrs. Van Hopper","sourceLineIndex":35,"ipa":"/sˈɒɹi ˌɛmˌɛrˈɛs vˈɑːn hˈɔpɜ/","en":"Sorry, Mrs. Van Hopper","zh":"对不起，范霍珀夫人","note":""},{"id":"rebecca-das-musical-02-036","lineIndex":36,"speaker":"","original":"Oh, hallo! Na, so was!","sourceLineIndex":36,"ipa":"/ˈoː hˈaloː nˈɑː zoː vˈas/","en":"Oh, hello! Well so what!","zh":"哦，你好！好吧那又怎样！","note":""},{"id":"rebecca-das-musical-02-037","lineIndex":37,"speaker":"","original":"Das ist ja Mr. de Winter?","sourceLineIndex":37,"ipa":"/das ɪst jˈɑː ˌɛmˈɛɾ dˈeː vˈɪntɜ/","en":"Is that Mr. de Winter?","zh":"那是德温特先生吗？","note":""},{"id":"rebecca-das-musical-02-038","lineIndex":38,"speaker":"","original":"Ein Bekannter von Ihnen?","sourceLineIndex":38,"ipa":"/aɪn bəkˈantɜ fɔn ˈiːnən/","en":"An acquaintance of yours?","zh":"你的熟人吗？","note":""},{"id":"rebecca-das-musical-02-039","lineIndex":39,"speaker":"","original":"Liest du keine Illustrierten?","sourceLineIndex":39,"ipa":"/lˈiːst duː kˈaɪnə ɪlʊstɾˈiːɾtən/","en":"Don't you read magazines?","zh":"你不看杂志吗？","note":""},{"id":"rebecca-das-musical-02-040","lineIndex":40,"speaker":"","original":"Ich lese lieber Bücher, Mrs. Van Hopper","sourceLineIndex":40,"ipa":"/ɪç lˈeːzə lˈiːbɜ bˈyːçɜ ˌɛmˌɛrˈɛs vˈɑːn hˈɔpɜ/","en":"I prefer reading books, Mrs. Van Hopper","zh":"我更喜欢读书，范霍珀夫人","note":""},{"id":"rebecca-das-musical-02-041","lineIndex":41,"speaker":"","original":"In feiner Gesellschaft, muss man wissen, mein Kind","sourceLineIndex":41,"ipa":"/ɪn fˈaɪnɜ ɡəzˈɛlʃaft mˈʊs man vˈɪsən maɪn kˈɪnt/","en":"In polite company, you have to know, my child","zh":"在有礼貌的公司里，你必须知道，我的孩子","note":""},{"id":"rebecca-das-musical-02-042","lineIndex":42,"speaker":"","original":"Wer begehrt und verehrt wird","sourceLineIndex":42,"ipa":"/vˈeːɾ bəɡˈeːɾt ʊnt fɛɾˈeːɾt vˌɪɾt/","en":"Who is desired and adored","zh":"谁是被渴望和崇拜的人","note":""},{"id":"rebecca-das-musical-02-043","lineIndex":43,"speaker":"","original":"Also, ich haette nicht gedacht, dass er dieses Jahr herkommt","sourceLineIndex":43,"ipa":"/ˈalzoː ɪç hˈɛtə nˈɪçt ɡədˈaxt das ɛɾ dˌiːzəs jˈɑːɾ hˈɛɾkɔmt/","en":"Well, I didn't think he would come here this year","zh":"嗯，我没想到他今年会来这里","note":""},{"id":"rebecca-das-musical-02-044","lineIndex":44,"speaker":"","original":"Wieso, Mrs. Van Hopper?","sourceLineIndex":44,"ipa":"/vˈiːzoː ˌɛmˌɛrˈɛs vˈɑːn hˈɔpɜ/","en":"Why, Mrs. Van Hopper?","zh":"为什么，范霍珀夫人？","note":""},{"id":"rebecca-das-musical-02-045","lineIndex":45,"speaker":"","original":"Seine Frau Rebecca ist letzten Sommer ertrunken","sourceLineIndex":45,"ipa":"/zˌaɪnə frˈaʊ reːbˈɛkɑː ɪst lˈɛtstən zˈɔmɜ ɛɾtɾˈʊŋkən/","en":"His wife Rebecca drowned last summer","zh":"他的妻子丽贝卡去年夏天溺水身亡","note":""},{"id":"rebecca-das-musical-02-046","lineIndex":46,"speaker":"","original":"Eine Tragödie!","sourceLineIndex":46,"ipa":"/ˌaɪnə tɾaɡˈøːdɪə/","en":"A tragedy!","zh":"悲剧了！","note":""},{"id":"rebecca-das-musical-02-047","lineIndex":47,"speaker":"","original":"Er hat es alles in allem voellig bald aufgeworfen","sourceLineIndex":47,"ipa":"/ɛɾ hat ɛs ˈaləs ɪn ˈaləm vˈœlɪç bˈalt ˈaʊfɡəvˌɔɾfən/","en":"All in all, he brought it up pretty soon","zh":"总而言之，他很快就提出来了","note":""},{"id":"rebecca-das-musical-02-048","lineIndex":48,"speaker":"","original":"Das musst du doch mitbekommen haben","sourceLineIndex":48,"ipa":"/das mˈʊst duː dɔx mˈɪtbəkˌɔmən hˈɑːbən/","en":"You must have noticed that","zh":"你一定已经注意到了","note":""},{"id":"rebecca-das-musical-02-049","lineIndex":49,"speaker":"","original":"Die Zeit ist wahnvoll, das vor allem","sourceLineIndex":49,"ipa":"/diː tsˈaɪt ɪst vˈɑːnfɔl das fˌɔɾ ˈaləm/","en":"The time is delusional, that's what it's all about","zh":"时间是虚幻的，这就是一切","note":""},{"id":"rebecca-das-musical-02-050","lineIndex":50,"speaker":"","original":"Nein","sourceLineIndex":50,"ipa":"/nˈaɪn/","en":"No","zh":"没有","note":""},{"id":"rebecca-das-musical-02-051","lineIndex":51,"speaker":"","original":"Mr. de Winter. Hallo!","sourceLineIndex":51,"ipa":"/ˌɛmˈɛɾ dˈeː vˈɪntɜ hˈaloː/","en":"Mr. de Winter. Hello!","zh":"德温特先生。你好！","note":""},{"id":"rebecca-das-musical-02-052","lineIndex":52,"speaker":"","original":"Guten Abend","sourceLineIndex":52,"ipa":"/ɡˈuːtən ˈɑːbənt/","en":"Good evening","zh":"晚上好","note":""},{"id":"rebecca-das-musical-02-053","lineIndex":53,"speaker":"","original":"Oh, wie erinnern Sie sich nicht mehr an mich?","sourceLineIndex":53,"ipa":"/ˈoː viː ɛɾˈɪnɜn ziː zɪç nˈɪçt mˌeːɾ an mɪç/","en":"Oh, how do you not remember me?","zh":"噢，你怎么不记得我了？","note":""},{"id":"rebecca-das-musical-02-054","lineIndex":54,"speaker":"","original":"Edith Van Hopper aus New York!","sourceLineIndex":54,"ipa":"/ˈeːdɪt vˈɑːn hˈɔpɜ ˌaʊs njˈuː jˈɔɾk/","en":"Edith Van Hopper from New York!","zh":"伊迪丝·范·霍珀来自纽约！","note":""},{"id":"rebecca-das-musical-02-056","lineIndex":55,"speaker":"","original":"Dafür haben wir uns in Claridge's kennengelernt","sourceLineIndex":56,"ipa":"/dɑːfˈyːɾ hˌɑːbən viːɾ ʊns ɪn klˈɑrɪdɡˌeːs kˈɛnənɡˌɛlɛɾnt/","en":"That's why we met in Claridge's","zh":"这就是我们在克拉里奇见面的原因","note":""},{"id":"rebecca-das-musical-02-057","lineIndex":56,"speaker":"","original":"Mit Billy","sourceLineIndex":57,"ipa":"/mɪt bˈɪliː/","en":"With Billy","zh":"与比利","note":""},{"id":"rebecca-das-musical-02-058","lineIndex":57,"speaker":"","original":"Ganz angenehm","sourceLineIndex":58,"ipa":"/ɡˌants ˈanɡənˌeːm/","en":"Quite pleasant","zh":"相当愉快","note":""},{"id":"rebecca-das-musical-02-059","lineIndex":58,"speaker":"","original":"Ich erinnere mich lebhaft an Sie","sourceLineIndex":59,"ipa":"/ɪç ɛɾˈɪnərə mɪç lˈeːphaft an ziː/","en":"I remember you vividly","zh":"我清楚地记得你","note":""},{"id":"rebecca-das-musical-02-060","lineIndex":59,"speaker":"","original":"Ich dachte, Sie sind um diese Zeit in Manderley","sourceLineIndex":60,"ipa":"/ɪç dˈaxtə ziː zɪnt ʊm dˌiːzə tsˈaɪt ɪn mˈandɜlˌaɪ/","en":"I thought you were in Manderley at this time","zh":"我以为你这个时候在曼德利","note":""},{"id":"rebecca-das-musical-02-061","lineIndex":60,"speaker":"","original":"Sicher faellt es Ihnen nicht leicht, den verwunschene Schloss am Meer zu verlassen","sourceLineIndex":61,"ipa":"/zˈɪçɜ fˈɛlt ɛs ˌiːnən nˈɪçt lˈaɪçt deːn fɛɾvˈʊnʃənə ʃlˈɔs am mˈeːɾ tsuː fɛɾlˈasən/","en":"It will certainly not be easy for you to leave the enchanted castle by the sea","zh":"离开这座海边的魔法城堡对你来说肯定不是一件容易的事","note":""},{"id":"rebecca-das-musical-02-062","lineIndex":61,"speaker":"","original":"Ja, es ist immer schoen in Manderley","sourceLineIndex":62,"ipa":"/jˈɑː ɛsɪst ˈɪmɜ ʃˈøːn ɪn mˈandɜlˌaɪ/","en":"Yes, it's always nice in Manderley","zh":"是的，曼德利总是很好","note":""},{"id":"rebecca-das-musical-02-063","lineIndex":62,"speaker":"","original":"aber ich hatte ploetzlich geträumt von meiner psychischer... Sonne","sourceLineIndex":63,"ipa":"/ˌɑːbɜ ɪç hˌatə plˈœtslɪç ɡətɾˈɔømt fɔn mˌaɪnɜ pzˈʏçɪʃɜ zˈɔnə/","en":"but I suddenly dreamed of my psychic... sun","zh":"但我突然梦见了我的通灵……太阳","note":""},{"id":"rebecca-das-musical-02-064","lineIndex":63,"speaker":"","original":"Und wie gefällt Ihnen Monte Carlo?","sourceLineIndex":64,"ipa":"/ʊnt viː ɡəfˈɛlt ˌiːnən mˈɔntə kˈaɾloː/","en":"And how do you like Monte Carlo?","zh":"您觉得蒙特卡洛怎么样？","note":""},{"id":"rebecca-das-musical-02-065","lineIndex":64,"speaker":"","original":"Na ja, also... ich finde es irgendwie alle etwas... unwirklich...","sourceLineIndex":65,"ipa":"/nˈɑː jˈɑː ˈalzoː ɪç fˈɪndə ɛs ˌɪɾɡəndvˈiː ˈalə ˈɛtvɑːs ˈʊnvˌɪɾklɪç/","en":"Well, well... I find it all a bit... unreal...","zh":"好吧，好吧……我觉得这一切有点……不真实……","note":""},{"id":"rebecca-das-musical-02-066","lineIndex":65,"speaker":"","original":"Sie ist verwöhnt, Mr de Winter","sourceLineIndex":66,"ipa":"/ziː ɪst fɛɾvˈøːnt ˌɛmˈɛɾ dˈeː vˈɪntɜ/","en":"She's spoiled, Mr. de Winter","zh":"她被宠坏了，德温特先生","note":""},{"id":"rebecca-das-musical-02-067","lineIndex":66,"speaker":"","original":"Die meisten Maedchen in ihrem Alter wuerden ihr Augenlicht dafuer geben","sourceLineIndex":67,"ipa":"/diː mˈaɪstən mˈɛːdçən ɪn ˌiːrəm ˈaltɜ vˈuːɜdən iːɾ ˈaʊɡənlˌɪçt dˈɑfuːɜ ɡˈeːbən/","en":"Most girls her age would give their eyesight for it","zh":"大多数她这个年纪的女孩都会为此献出自己的视力","note":""},{"id":"rebecca-das-musical-02-068","lineIndex":67,"speaker":"","original":"einmal Monte zu sehen","sourceLineIndex":68,"ipa":"/ˈaɪnmˌɑːl mˈɔntə tsuː zˈeːən/","en":"to see Monte once","zh":"去看一次蒙特","note":""},{"id":"rebecca-das-musical-02-069","lineIndex":68,"speaker":"","original":"Ohne Augenlicht duerfen Sie kommen, was Sie dafuer haben","sourceLineIndex":69,"ipa":"/ˈoːnə ˈaʊɡənlˌɪçt dˈuːɜfən ziː kˈɔmən vˈas ziː dˈɑfuːɜ hˈɑːbən/","en":"Without eyesight you can come with whatever you have for it","zh":"没有视力，你可以用任何你拥有的东西来获得它","note":""},{"id":"rebecca-das-musical-02-070","lineIndex":69,"speaker":"","original":"Hoer auf! Sie scherzen Mister de Winter","sourceLineIndex":70,"ipa":"/hˈøːɾ ˈaʊf ziː ʃˈɛɾtsən mˈɪstɜ dˈeː vˈɪntɜ/","en":"Stop it! You are joking, Mr. de Winter","zh":"停下来！您在开玩笑，德温特先生","note":""},{"id":"rebecca-das-musical-02-071","lineIndex":70,"speaker":"","original":"Hat Ihr Butler schon Ihre Sachen ausgepackt?","sourceLineIndex":71,"ipa":"/hat iːɾ bˈʊtlɜ ʃˌoːn ˌiːrə zˈaxən ˈaʊsɡəpˌakt/","en":"Has your butler already unpacked your things?","zh":"您的管家已经打开您的物品了吗？","note":""},{"id":"rebecca-das-musical-02-072","lineIndex":71,"speaker":"","original":"Ich habe keinen Butler","sourceLineIndex":72,"ipa":"/ɪç hɑːbə kˈaɪnən bˈʊtlɜ/","en":"I don't have a butler","zh":"我没有管家","note":""},{"id":"rebecca-das-musical-02-073","lineIndex":72,"speaker":"","original":"Vielleicht macht es Ihnen Spass, mir zu helfen","sourceLineIndex":73,"ipa":"/fɪlˈaɪçt mˈaxt ɛs ˌiːnən ʃpˈas miːɾ tsuː hˈɛlfən/","en":"Maybe you'll enjoy helping me","zh":"也许你会喜欢帮助我","note":""},{"id":"rebecca-das-musical-02-074","lineIndex":73,"speaker":"","original":"Vielleicht solltest du Mr de Winter zur Hand gehen","sourceLineIndex":74,"ipa":"/fɪlˈaɪçt zˈɔltəst duː ˌɛmˈɛɾ dˈeː vˈɪntɜ tsuːɾ hˈant ɡˈeːən/","en":"Maybe you should give Mr. de Winter a hand","zh":"也许你应该帮德温特先生一把","note":""},{"id":"rebecca-das-musical-02-075","lineIndex":74,"speaker":"","original":"Kofferauspacken kannst du ja","sourceLineIndex":75,"ipa":"/kˈɔfeːrˌaʊspakən kˌanst duː jˈɑː/","en":"You can unpack your suitcase","zh":"你可以打开你的行李箱","note":""},{"id":"rebecca-das-musical-02-076","lineIndex":75,"speaker":"","original":"Ein charmantes Angebot, aber mein Motto heisst: Selbst ist der Mann","sourceLineIndex":76,"ipa":"/aɪn ʃaɾmˈantəs ˈanɡəbˌoːt ˌɑːbɜ maɪn mˈɔtoː hˈaɪst zˈɛlpst ɪst dɛɾ mˈan/","en":"A charming offer, but my motto is: The man is himself","zh":"一个迷人的提议，但我的座右铭是：人就是他自己","note":""},{"id":"rebecca-das-musical-02-077","lineIndex":76,"speaker":"","original":"Es war mir ein Vergnügen, meine Damen","sourceLineIndex":77,"ipa":"/ɛs vɑːɾ miːɾ aɪn fɛɾɡənˈyːɡən mˌaɪnə dˈɑːmən/","en":"It was my pleasure, ladies","zh":"这是我的荣幸，女士们","note":""},{"id":"rebecca-das-musical-02-078","lineIndex":77,"speaker":"","original":"Sehr abrupt, dieser Abgang, ich fürchte mein Kind","sourceLineIndex":78,"ipa":"/zˈeːɾ ˈapɾˌʊpt dˌiːzɜ ˈapɡˌaŋ ɪç fˈʏɾçtə maɪn kˈɪnt/","en":"Very abrupt, this departure, I fear my child","zh":"非常突然，这次离开，我害怕我的孩子","note":""},{"id":"rebecca-das-musical-02-079","lineIndex":78,"speaker":"","original":"Du hast ihn vertrieben","sourceLineIndex":79,"ipa":"/duː hast iːn fɛɾtɾˈiːbən/","en":"You drove him away","zh":"你把他赶走了","note":""},{"id":"rebecca-das-musical-02-080","lineIndex":79,"speaker":"","original":"Ich?","sourceLineIndex":80,"ipa":"/ˈɪç/","en":"Me?","zh":"我？","note":""},{"id":"rebecca-das-musical-02-081","lineIndex":80,"speaker":"","original":"Deine vorlaute Antwort war sehr peinlich, mein Kind","sourceLineIndex":81,"ipa":"/dˌaɪnə fˈoːɾlˌaʊtə ˈantvɔɾt vɑːɾ zˈeːɾ pˈaɪnlɪç maɪn kˈɪnt/","en":"Your cheeky answer was very embarrassing, my child","zh":"你厚脸皮的回答非常尴尬，我的孩子","note":""},{"id":"rebecca-das-musical-02-082","lineIndex":81,"speaker":"","original":"Du hast ihn verärgert","sourceLineIndex":82,"ipa":"/duː hast iːn fɛɾˈɛɾɡɜt/","en":"You upset him","zh":"你让他不高兴","note":""},{"id":"rebecca-das-musical-02-083","lineIndex":82,"speaker":"","original":"Das war nicht meine Absicht","sourceLineIndex":83,"ipa":"/das vɑːɾ nˈɪçt mˌaɪnə ˈapzˌɪçt/","en":"That wasn't my intention","zh":"那不是我的本意","note":""},{"id":"rebecca-das-musical-02-084","lineIndex":83,"speaker":"","original":"Du hast die Unterhaltung auf dich gelenkt","sourceLineIndex":84,"ipa":"/duː hast diː ˌʊntɜhˈaltʊŋ aʊf dɪç ɡəlˈɛŋkt/","en":"You've turned the conversation on yourself","zh":"你把话题转向了你自己","note":""},{"id":"rebecca-das-musical-02-085","lineIndex":84,"speaker":"","original":"Und mich und dich blamiert","sourceLineIndex":85,"ipa":"/ʊnt mɪç ʊnt dɪç blamˈiːɾt/","en":"And embarrassed me and you","zh":"让我和你都难堪","note":""},{"id":"rebecca-das-musical-02-086","lineIndex":85,"speaker":"","original":"Ich traf noch keinen Mann wie ihn, so seltsam, so geheimnisvoll","sourceLineIndex":86,"ipa":"/ɪç tɾˈɑːf nɔx kˈaɪnən mˈan viː ˈiːn zoː zˈɛltzɑːm zoː ɡəhˈaɪmnɪsfˌɔl/","en":"I've never met a man like him, so strange, so mysterious","zh":"我从来没有遇到过像他这样的人，如此奇怪，如此神秘","note":""},{"id":"rebecca-das-musical-02-087","lineIndex":86,"speaker":"","original":"Ich hoff', ich seh' ihn wieder","sourceLineIndex":87,"ipa":"/ɪç hˈɔf ɪç zˈeː iːn vˈiːdɜ/","en":"I hope I see him again","zh":"我希望我能再次见到他","note":""},{"id":"rebecca-das-musical-02-088","lineIndex":87,"speaker":"","original":"Du hast nicht sein Niveau, mein Kind","sourceLineIndex":88,"ipa":"/duː hast nˈɪçt zaɪn niːvˈoː maɪn kˈɪnt/","en":"You're not at his level, my child","zh":"你还达不到他的水平，我的孩子","note":""},{"id":"rebecca-das-musical-02-089","lineIndex":88,"speaker":"","original":"Du wirst niemals eine Lady, weil dir jede Klasse fehlt","sourceLineIndex":89,"ipa":"/duː vˌɪɾst nˈiːmɑːls ˌaɪnə lˈeɪdi vˌaɪl diːɾ jˈeːdə klˈasə fˈeːlt/","en":"You'll never be a lady because you lack any class","zh":"你永远成不了淑女，因为你缺乏阶级","note":""},{"id":"rebecca-das-musical-02-090","lineIndex":89,"speaker":"","original":"Du wirst immer eine kleine, unscheinbare, scheue graue Maus sein","sourceLineIndex":90,"ipa":"/duː vˌɪɾst ˈɪmɜ ˌaɪnə klˈaɪnə ˈʊnʃˌaɪnbɑːrə ʃˈɔøə ɡɾˈaʊə mˈaʊs zaɪn/","en":"You will always be a small, inconspicuous, shy gray mouse","zh":"你永远是一只小小、不起眼、害羞的灰老鼠","note":""},{"id":"rebecca-das-musical-02-091","lineIndex":90,"speaker":"","original":"So sehr ich mich auch plage, es ist sinnlos, was ich sage","sourceLineIndex":91,"ipa":"/zoː zˈeːɾ ɪç mɪç ˌaʊx plˈɑːɡə ɛsɪst zˈɪnloːs vˈas ɪç zˈɑːɡə/","en":"As much as I torment myself, what I say is meaningless","zh":"尽管我很折磨自己，但我说的话毫无意义","note":""},{"id":"rebecca-das-musical-02-092","lineIndex":91,"speaker":"","original":"Es fehlt dir die Nonchalance, Darling, die Contenance und Elegance","sourceLineIndex":92,"ipa":"/ɛs fˈeːlt diːɾ diː nˈɒnʃələns dˈaɾlɪŋ diː kəntˈɛnəns ʊnt ˈɛlɪɡəns/","en":"You lack nonchalance, darling, composure and elegance","zh":"亲爱的，你缺乏冷静和优雅","note":""},{"id":"rebecca-das-musical-02-093","lineIndex":92,"speaker":"","original":"Nicht die geringste Chance, Darling, aus dir wird keine Lady, das steht fest!","sourceLineIndex":93,"ipa":"/nˈɪçt diː ɡərˈɪŋstə ʃˈɑ̃sə dˈaɾlɪŋ ˌaʊs diːɾ vˌɪɾt kˈaɪnə lˈeɪdi das ʃtˈeːt fˈɛst/","en":"Not the slightest chance, darling, you won't become a lady, that's for sure!","zh":"没有一点机会，亲爱的，你不会成为一个淑女，这是肯定的！","note":""},{"id":"rebecca-das-musical-02-094","lineIndex":93,"speaker":"","original":"Und jetzt komm, mir geht es miserabel. Ich glaube, ich kriege eine Grippe","sourceLineIndex":94,"ipa":"/ʊnt jˌɛtst kˈɔm miːɾ ɡˈeːt ɛs mˌiːzeːrˈɑːbəl ɪç ɡlˈaʊbə ɪç kɾˈiːɡə ˌaɪnə ɡɾˈɪpə/","en":"Now come on, I'm miserable. I think I'm getting the flu","zh":"现在来吧，我很痛苦。我想我得了流感","note":""},{"id":"rebecca-das-musical-02-095","lineIndex":94,"speaker":"","original":"Ich werde morgen im Bett bleiben","sourceLineIndex":95,"ipa":"/ɪç vˌɛɾdə mˈɔɾɡən ɪm bˈɛt blˈaɪbən/","en":"I'll stay in bed tomorrow","zh":"明天我会留在床上","note":""}],"sourceOrder":2,"displayOrder":1},{"order":4,"id":"04-zauberhaft-naturlich-live","title":"Zauberhaft natürlich","titleZh":"自然得迷人","lines":[{"id":"rebecca-das-musical-04-001","lineIndex":1,"speaker":"","original":"Was ist es, was mich rührt, wenn ich sie sehe?","sourceLineIndex":1,"ipa":"/vˈas ɪst ɛs vˈas mɪç rˈyːɾt vˌɛn ɪç ziː zˈeːə/","en":"What is it that moves me when I see her?","zh":"这是怎么回事？当我看见她的时候，我的内心怎么被触动了？","note":""},{"id":"rebecca-das-musical-04-002","lineIndex":2,"speaker":"","original":"Was gefällt mir an der Art, wie sie spricht?","sourceLineIndex":2,"ipa":"/vˈas ɡəfˈɛlt miːɾ an dɛɾ ˈɑːɾt viː ziː ʃpɾˈɪçt/","en":"What is it I love about the way she speaks?","zh":"是什么让我对她的言语如此喜爱？","note":""},{"id":"rebecca-das-musical-04-003","lineIndex":3,"speaker":"","original":"Ich fühle mich leichter, bin ich in ihrer Nähe","sourceLineIndex":3,"ipa":"/ɪç fˈyːlə mɪç lˈaɪçtɜ bɪn ɪç ɪn ˌiːrɜ nˈɛːə/","en":"I feel lighter when I am near her","zh":"当我和她在一起的时候，感觉真是轻松愉悦","note":""},{"id":"rebecca-das-musical-04-004","lineIndex":4,"speaker":"","original":"Sie befreit mich, denn was ich war oder tat","sourceLineIndex":4,"ipa":"/ziː bəfrˈaɪt mɪç dɛn vˈas ɪç vɑːɾ ˌoːdɜ tˈɑːt/","en":"she sets me free, for she asks nothing of what I was or did","zh":"她把我从过往的牢笼中解放","note":""},{"id":"rebecca-das-musical-04-005","lineIndex":5,"speaker":"","original":"Danach fragt sie mich nicht","sourceLineIndex":5,"ipa":"/danˈax frˈɑːkt ziː mɪç nˈɪçt/","en":"and does not question me about it.","zh":"而从不过问我的过去","note":""},{"id":"rebecca-das-musical-04-006","lineIndex":6,"speaker":"","original":"Sie sieht in mir nur das, was sie bewundern will","sourceLineIndex":6,"ipa":"/ziː zˈiːt ɪn miːɾ nˈuːɾ das vˈas ziː bəvˈʊndɜn vɪl/","en":"She sees in me only what she wishes to admire.","zh":"当她看向我，眼中充满了崇拜","note":""},{"id":"rebecca-das-musical-04-007","lineIndex":7,"speaker":"","original":"Verlegen, beinahe scheu, denn sie ist so Zauberhaft natürlich, jung und doch voll Mut","sourceLineIndex":7,"ipa":"/fɛɾlˈeːɡən bˈaɪnɑːə ʃˈɔø dɛn ziː ɪst zoː tsˈaʊbɜhˌaft nɑːtˈyːɾlɪç jˈʊŋ ʊnt dɔx fˈɔl mˈuːt/","en":"Embarrassed, almost shy — for that is how she is: enchantingly natural, young and yet full of courage.","zh":"旅程中的她，有掩盖不了的羞涩，这就是她的样子！爱情的魔力啊！如此年轻勇敢而又热忱","note":""},{"id":"rebecca-das-musical-04-009","lineIndex":8,"speaker":"","original":"Sie fragt nicht, was ihr nützt Unbegreiflich ehrlich, für diese Welt zu gut","sourceLineIndex":9,"ipa":"/ziː frˈɑːkt nˈɪçt vˈas iːɾ nˈʏtst ˈʊnbəɡɾˌaɪflɪç ˈeːɾlɪç fyːɾ dˌiːzə vˈɛlt tsuː ɡˈuːt/","en":"She does not ask what serves her incomprehensibly honest, too good for this world.","zh":"她对我别无所求她是如此的正直，如此完美，仿佛不属于这个世界","note":""},{"id":"rebecca-das-musical-04-011","lineIndex":9,"speaker":"","original":"Wenn keiner sie beschützt","sourceLineIndex":11,"ipa":"/vˌɛn kˈaɪnɜ ziː bəʃˈʏtst/","en":"If no one protects her","zh":"完美到需要有人保护她","note":""},{"id":"rebecca-das-musical-04-012","lineIndex":10,"speaker":"","original":"Wie sie träumend schweigt, den Kopf zur Seite neigt","sourceLineIndex":12,"ipa":"/viː ziː tɾˈɔømənt ʃvˈaɪkt deːn kˈɔpf tsuːɾ zˈaɪtə nˈaɪkt/","en":"how she falls silent, dreaming, and tilts her head aside","zh":"当她沉入梦乡的时候，她的身体逐渐靠近我","note":""},{"id":"rebecca-das-musical-04-013","lineIndex":11,"speaker":"","original":"Ihr Kinn, ihr Mund, ihr Blick","sourceLineIndex":13,"ipa":"/iːɾ kˈɪn iːɾ mˈʊnt iːɾ blˈɪk/","en":"her chin, her mouth, her gaze —","zh":"她的脸庞，她的嘴，她的眼神","note":""},{"id":"rebecca-das-musical-04-014","lineIndex":12,"speaker":"","original":"Zauberhaft natürlich, ich seh' sie an und fühl'","sourceLineIndex":14,"ipa":"/tsˈaʊbɜhˌaft nɑːtˈyːɾlɪç ɪç zˈeː ziː an ʊnt fˈyːl/","en":"enchantingly natural; I look at her and feel","zh":"爱情的魔力，当我看着她而感到：","note":""},{"id":"rebecca-das-musical-04-015","lineIndex":13,"speaker":"","original":"Endlich wieder so etwas wie Glück","sourceLineIndex":15,"ipa":"/ˈɛntlɪç vˈiːdɜ zoː ˈɛtvɑːs viː ɡlˈʏk/","en":"at last, something like happiness again.","zh":"我们能像现在这样真的是天赐的幸运啊","note":""},{"id":"rebecca-das-musical-04-016","lineIndex":14,"speaker":"","original":"Zauberhaft natürlich, verlegen beinahe scheu","sourceLineIndex":16,"ipa":"/tsˈaʊbɜhˌaft nɑːtˈyːɾlɪç fɛɾlˈeːɡən bˈaɪnɑːə ʃˈɔø/","en":"Enchantingly natural, embarrassed, almost shy","zh":"这就是爱情的魔力啊！掩藏不住的羞涩","note":""},{"id":"rebecca-das-musical-04-017","lineIndex":15,"speaker":"","original":"Ich hab sie wirklich gern","sourceLineIndex":17,"ipa":"/ɪç hˈɑːp ziː vˈɪɾklɪç ɡˈɛɾn/","en":"I truly care for her.","zh":"而我喜欢她是如此的真切","note":""},{"id":"rebecca-das-musical-04-018","lineIndex":16,"speaker":"“我”","original":"Maxim, es ist so schoen hier. Koennen wir nicht noch ein wenig bleiben?","sourceLineIndex":18,"ipa":"/mˈaksiːm ɛsɪst zoː ʃˈøːn hˈiːɾ kˈœnən viːɾ nˈɪçt nɔx aɪn vˈeːnɪç blˈaɪbən/","en":"Maxim, it is so lovely here. Can't we stay a little longer?","zh":"马克西姆，这里真是太美了。我们能在这里再待多一会吗？","note":""},{"id":"rebecca-das-musical-04-019","lineIndex":17,"speaker":"","original":"Willst du nicht dein Zuhaus kennenlernen?","sourceLineIndex":19,"ipa":"/vɪlst duː nˈɪçt daɪn tsuːhˈaʊs kˈɛnənlɜnən/","en":"Don't you want to get to know your home?","zh":"难道你不想去看看你的房子吗？","note":""},{"id":"rebecca-das-musical-04-020","lineIndex":18,"speaker":"","original":"Komm, Manderley wartet auf uns.","sourceLineIndex":20,"ipa":"/kˈɔm mˈandɜlˌaɪ vˈaɾtət aʊf ˈʊns/","en":"Come, Manderley is waiting for us.","zh":"来吧！曼德雷在等着我们。","note":""}],"sourceOrder":4,"displayOrder":2},{"order":8,"id":"08-bist-du-glucklich","title":"Bist du glücklich?","titleZh":"你快乐吗？","lines":[{"id":"rebecca-das-musical-08-001","lineIndex":1,"speaker":"","original":"Schachmatt!","sourceLineIndex":1,"ipa":"/ʃˈaxmat/","en":"Checkmate!","zh":"将军！","note":""},{"id":"rebecca-das-musical-08-002","lineIndex":2,"speaker":"","original":"Nein... Nein!","sourceLineIndex":2,"ipa":"/nˈaɪn nˈaɪn/","en":"No no!","zh":"不……不对！","note":""},{"id":"rebecca-das-musical-08-003","lineIndex":3,"speaker":"","original":"Doch! Du hast verloren, tut mir leid!","sourceLineIndex":3,"ipa":"/dˈɔx duː hast fɛɾlˈoːrən tˈuːt miːɾ lˈaɪt/","en":"But! You lost, I'm sorry!","zh":"就是，就是！你输了，对不起啦！","note":""},{"id":"rebecca-das-musical-08-004","lineIndex":4,"speaker":"","original":"Verflixt! Ich hab dich unterschätzt!","sourceLineIndex":4,"ipa":"/fɛɾflˈɪkst ɪç hˈɑːp dɪç ˌʊntɜʃˈɛtst/","en":"Darn! I underestimated you!","zh":"可恶！我低估你了！","note":""},{"id":"rebecca-das-musical-08-005","lineIndex":5,"speaker":"","original":"Und was kriegt die Siegerin?","sourceLineIndex":5,"ipa":"/ʊnt vˈas kɾˈiːkt diː zˈiːɡərˌɪn/","en":"And what does the winner get?","zh":"那么赢的人有什么奖励吗？","note":""},{"id":"rebecca-das-musical-08-006","lineIndex":6,"speaker":"","original":"Bist du glucklich?","sourceLineIndex":6,"ipa":"/bɪst duː ɡlˈʊklɪç/","en":"Are you happy?","zh":"你快乐吗？","note":""},{"id":"rebecca-das-musical-08-007","lineIndex":7,"speaker":"","original":"Kannst du mich immer noch ertragen?","sourceLineIndex":7,"ipa":"/kˌanst duː mɪç ˈɪmɜ nɔx ɛɾtɾˈɑːɡən/","en":"Can you still tolerate me?","zh":"你还能继续忍受我吗？","note":""},{"id":"rebecca-das-musical-08-008","lineIndex":8,"speaker":"","original":"Ich bin schwierig","sourceLineIndex":8,"ipa":"/ɪç bɪn ʃvˈiːrɪç/","en":"I am difficult","zh":"我很难相处","note":""},{"id":"rebecca-das-musical-08-009","lineIndex":9,"speaker":"","original":"Es lebt sich nicht sehr leicht mit mir","sourceLineIndex":9,"ipa":"/ɛs lˈeːpt zɪç nˈɪçt zˈeːɾ lˈaɪçt mɪt mˈiːɾ/","en":"It's not very easy for me to live with","zh":"和我一起生活并不容易","note":""},{"id":"rebecca-das-musical-08-010","lineIndex":10,"speaker":"","original":"Das ist Unsinn!","sourceLineIndex":10,"ipa":"/das ɪst ˈʊnzˌɪn/","en":"This is nonsense!","zh":"不要胡说！","note":""},{"id":"rebecca-das-musical-08-011","lineIndex":11,"speaker":"","original":"Schau was dir meine augen sagen!","sourceLineIndex":11,"ipa":"/ʃˈaʊ vˈas diːɾ mˌaɪnə ˈaʊɡən zˈɑːɡən/","en":"Look what my eyes tell you!","zh":"看着我的眼睛！","note":""},{"id":"rebecca-das-musical-08-012","lineIndex":12,"speaker":"","original":"Ich lieb dich Maxim!","sourceLineIndex":12,"ipa":"/ɪç lˈiːp dɪç mˈaksiːm/","en":"I love you Maxim!","zh":"我爱你，马克西姆！","note":""},{"id":"rebecca-das-musical-08-013","lineIndex":13,"speaker":"","original":"Ich möchte niemals fort von dir","sourceLineIndex":13,"ipa":"/ɪç mˈœçtə nˈiːmɑːls fˈɔɾt fɔn dˈiːɾ/","en":"I never want to leave you","zh":"我永远不想离开你","note":""},{"id":"rebecca-das-musical-08-014","lineIndex":14,"speaker":"","original":"Bist du glücklich?","sourceLineIndex":14,"ipa":"/bɪst duː ɡlˈʏklɪç/","en":"Are you happy?","zh":"你快乐吗？","note":""},{"id":"rebecca-das-musical-08-015","lineIndex":15,"speaker":"","original":"Ich habe noch so viel zu lernen","sourceLineIndex":15,"ipa":"/ɪç hɑːbə nɔx zoː fˈiːl tsuː lˈɛɾnən/","en":"I still have so much to learn","zh":"我还有很多东西要学","note":""},{"id":"rebecca-das-musical-08-016","lineIndex":16,"speaker":"","original":"Manchmal denk ich dich dauernd nur blamier","sourceLineIndex":16,"ipa":"/mˈançmɑːl dˈɛŋk ɪç dɪç dˈaʊɜnt nˈuːɾ blamˈiːɾ/","en":"Sometimes I just think you're a disgrace all the time","zh":"我有时觉得我总是让你丢脸","note":""},{"id":"rebecca-das-musical-08-017","lineIndex":17,"speaker":"","original":"Du bist jung","sourceLineIndex":17,"ipa":"/duː bɪst jˈʊŋ/","en":"You are young","zh":"你还年轻","note":""},{"id":"rebecca-das-musical-08-018","lineIndex":18,"speaker":"","original":"Du hast bestimmt oft Langweile","sourceLineIndex":18,"ipa":"/duː hast bəʃtˈɪmt ˈɔft lˈaŋvˌaɪlə/","en":"You're probably often bored","zh":"你肯定经常觉得无聊","note":""},{"id":"rebecca-das-musical-08-019","lineIndex":19,"speaker":"","original":"Überhaupt nicht!","sourceLineIndex":19,"ipa":"/ˌyːbɜhˈaʊpt nˈɪçt/","en":"Not at all!","zh":"一点也不","note":""},{"id":"rebecca-das-musical-08-020","lineIndex":20,"speaker":"","original":"Wahrscheinlich fehlt dir vieles hier","sourceLineIndex":20,"ipa":"/vɑːɾʃˈaɪnlɪç fˈeːlt diːɾ fˈiːləs hˈiːɾ/","en":"You're probably missing a lot of things here","zh":"你在这里肯定总觉得少点什么吧","note":""},{"id":"rebecca-das-musical-08-021","lineIndex":21,"speaker":"","original":"Ich habe doch alles was ich brauche","sourceLineIndex":21,"ipa":"/ɪç hɑːbə dɔx ˈaləs vˈas ɪç bɾˈaʊxə/","en":"I have everything I need","zh":"我已经拥有我需要的一切了","note":""},{"id":"rebecca-das-musical-08-022","lineIndex":22,"speaker":"","original":"Was sollte mir denn fehlen?","sourceLineIndex":22,"ipa":"/vˈas zˌɔltə miːɾ dɛn fˈeːlən/","en":"What should I be missing?","zh":"还有什么想要的？","note":""},{"id":"rebecca-das-musical-08-023","lineIndex":23,"speaker":"","original":"Oh ja?","sourceLineIndex":23,"ipa":"/ˈoː jˈɑː/","en":"Oh yeah?","zh":"是吗？","note":""},{"id":"rebecca-das-musical-08-024","lineIndex":24,"speaker":"","original":"Ausflüge, Einladung, Strandpartys, Tanzfeste, Freundinnen","sourceLineIndex":24,"ipa":"/ˈaʊsflˌyːɡə ˈaɪnlˌɑdʊŋ ʃtɾˈantpaɾtˌyːs tˈantsfəstə frˈɔøndɪnən/","en":"Excursions, invitations, beach parties, dance parties, girlfriends","zh":"郊游，邀请，海滩聚会，舞会，女伴","note":""},{"id":"rebecca-das-musical-08-025","lineIndex":25,"speaker":"","original":"Alles was man in deinem Alter halt so macht!","sourceLineIndex":25,"ipa":"/ˈaləs vˈas man ɪn dˌaɪnəm ˈaltɜ hˈalt zoː mˈaxt/","en":"Everything you do at your age!","zh":"所有你这个年纪的女孩都爱做的事情！","note":""},{"id":"rebecca-das-musical-08-026","lineIndex":26,"speaker":"","original":"Beatrice hat mir erzählt","sourceLineIndex":26,"ipa":"/bəˈatɾiːkə hat miːɾ ɛɾtsˈɛːlt/","en":"Beatrice told me","zh":"贝阿特丽丝跟我说","note":""},{"id":"rebecca-das-musical-08-027","lineIndex":27,"speaker":"","original":"Dass es hier auf Manderley jedes Jahr einen Kostümball gab","sourceLineIndex":27,"ipa":"/das ɛs hˈiːɾ aʊf mˈandɜlˌaɪ jˈeːdəs jˈɑːɾ ˌaɪnən kˈɔʃtʏmbˌal ɡˈɑːp/","en":"That there was a fancy dress ball here on Manderley every year","zh":"每年曼德雷都要开化装舞会","note":""},{"id":"rebecca-das-musical-08-028","lineIndex":28,"speaker":"","original":"Lass uns diese Tradition fortsetzen!","sourceLineIndex":28,"ipa":"/lˈas ʊns dˌiːzə tɾˌɑdiːtsjˈoːn fˈɔɾtzɛtsən/","en":"Let's continue this tradition!","zh":"让我们延续这个传统吧！","note":""},{"id":"rebecca-das-musical-08-029","lineIndex":29,"speaker":"","original":"Einen Maskenball, das fände ich lustig!","sourceLineIndex":29,"ipa":"/ˌaɪnən mˈaskənbˌal das fˈɛndə ɪç lˈʊstɪç/","en":"I think a masquerade ball would be fun!","zh":"一个假面舞会，我觉得那会很有趣！","note":""},{"id":"rebecca-das-musical-08-030","lineIndex":30,"speaker":"","original":"Ach, ich weiss nicht...","sourceLineIndex":30,"ipa":"/ˈax ɪç vˈaɪs nˈɪçt/","en":"Oh, I don't know...","zh":"啊，我不确定……","note":""},{"id":"rebecca-das-musical-08-031","lineIndex":31,"speaker":"","original":"Aber es wurde dir gut tun.","sourceLineIndex":31,"ipa":"/ˌɑːbɜ ɛs vˌʊɐdə diːɾ ɡˈuːt tˈuːn/","en":"But it would be good for you.","zh":"但是这对你有好处","note":""},{"id":"rebecca-das-musical-08-032","lineIndex":32,"speaker":"","original":"Bitte Maxim, bitte sag ja.","sourceLineIndex":32,"ipa":"/bˈɪtə mˈaksiːm bˈɪtə zˈɑːk jˈɑː/","en":"Please Maxim, please say yes.","zh":"拜托了马克西姆，同意吧","note":""},{"id":"rebecca-das-musical-08-033","lineIndex":33,"speaker":"","original":"Du müsstest dich um gar nichts kümmern!","sourceLineIndex":33,"ipa":"/duː mˈʏstəst dɪç ʊm ɡˈɑːɾ nˈɪçts kˈʏmɜn/","en":"You wouldn't have to worry about anything!","zh":"你什么都不用操心！","note":""},{"id":"rebecca-das-musical-08-034","lineIndex":34,"speaker":"","original":"Und ich hatte endlich eine Aufgabe...","sourceLineIndex":34,"ipa":"/ʊnt ɪç hˌatə ˈɛntlɪç ˌaɪnə ˈaʊfɡˌɑːbə/","en":"And I finally had a job...","zh":"而我就终于可以给自己找到点事情做了……","note":""},{"id":"rebecca-das-musical-08-035","lineIndex":35,"speaker":"","original":"Na gut, wenn du es gar so gern mochtest","sourceLineIndex":35,"ipa":"/nˈɑː ɡˈuːt vˌɛn duː ɛs ɡˈɑːɾ zoː ɡˈɛɾn mˈɔxtəst/","en":"Well, if you liked it that much","zh":"那好吧，如果你这么想要的话","note":""},{"id":"rebecca-das-musical-08-036","lineIndex":36,"speaker":"","original":"Du bekommst deinen Kostümball","sourceLineIndex":36,"ipa":"/duː bəkˈɔmst dˌaɪnən kˈɔʃtʏmbˌal/","en":"You get your costume ball","zh":"你会拥有一次舞会的","note":""},{"id":"rebecca-das-musical-08-037","lineIndex":37,"speaker":"","original":"Danke Maxim, du bist ein Schatz!","sourceLineIndex":37,"ipa":"/dˈaŋkə mˈaksiːm duː bɪst aɪn ʃˈats/","en":"Thank you Maxim, you are a treasure!","zh":"谢谢你，马克西姆，你真好！","note":""},{"id":"rebecca-das-musical-08-038","lineIndex":38,"speaker":"","original":"Entschuldigen Sie die Störung, Sir","sourceLineIndex":38,"ipa":"/ɛntʃˈʊldɪɡən ziː diː ʃtˈøːrʊŋ zˈiːɾ/","en":"Sorry to bother you, sir","zh":"很抱歉打扰您，先生","note":""},{"id":"rebecca-das-musical-08-039","lineIndex":39,"speaker":"","original":"Was gibt es, Mrs. Danvers?","sourceLineIndex":39,"ipa":"/vˈas ɡˈiːpt ɛs ˌɛmˌɛrˈɛs dˈanfɜs/","en":"What is it, Mrs. Danvers?","zh":"怎么了，丹弗斯夫人？","note":""},{"id":"rebecca-das-musical-08-040","lineIndex":40,"speaker":"","original":"Es geht um den Amor, Sir","sourceLineIndex":40,"ipa":"/ɛs ɡˈeːt ʊm deːn ˈɑmoːɾ zˈiːɾ/","en":"It's about Cupid, sir","zh":"是关于那尊爱神的事，先生","note":""},{"id":"rebecca-das-musical-08-041","lineIndex":41,"speaker":"","original":"Die Porzellanfigur auf dem Sekretär im Morgenzimmer","sourceLineIndex":41,"ipa":"/diː pˌɔɾtsəlˌanfɪɡˈuːɾ aʊf deːm zˌɛkɾeːtˈɛːɾ ɪm mˈɔɾɡəntsˌɪmɜ/","en":"The porcelain figurine on the bureau in the morning room","zh":"就是晨室写字台上的瓷像","note":""},{"id":"rebecca-das-musical-08-042","lineIndex":42,"speaker":"","original":"Ich fürchte, es wurde gestohlen","sourceLineIndex":42,"ipa":"/ɪç fˈʏɾçtə ɛs vˌʊɐdə ɡəʃtˈoːlən/","en":"I'm afraid it was stolen","zh":"我恐怕它被人偷走了","note":""},{"id":"rebecca-das-musical-08-043","lineIndex":43,"speaker":"","original":"Jedenfalls ist er verschwunden","sourceLineIndex":43,"ipa":"/jˈeːdənfˌals ɪst ɛɾ fɛɾʃvˈʊndən/","en":"Anyway, he disappeared","zh":"不管怎样，它不见了","note":""},{"id":"rebecca-das-musical-08-044","lineIndex":44,"speaker":"","original":"Ich habe Robert ins Verhör genommen","sourceLineIndex":44,"ipa":"/ɪç hɑːbə rˈoːbɜt ɪns fɛɾhˈøːɾ ɡənˈɔmən/","en":"I questioned Robert","zh":"我把罗伯特召来问话","note":""},{"id":"rebecca-das-musical-08-045","lineIndex":45,"speaker":"","original":"Aber er schwört, er hätte nichts damit zu zun","sourceLineIndex":45,"ipa":"/ˌɑːbɜ ɛɾ ʃvˈœɾt ɛɾ hˌɛtə nˈɪçts dɑːmˈɪt tsuː tsˈuːn/","en":"But he swears he had nothing to do with it","zh":"可他发誓和他没有关系","note":""},{"id":"rebecca-das-musical-08-046","lineIndex":46,"speaker":"","original":"Und warum behelligen Sie mich damit?","sourceLineIndex":46,"ipa":"/ʊnt vɑːrˈʊm bəhˈɛlɪɡən ziː mɪç dɑːmˈɪt/","en":"And why are you bothering me with this?","zh":"干嘛拿这些事烦我？","note":""},{"id":"rebecca-das-musical-08-047","lineIndex":47,"speaker":"","original":"Der Amor war die Lieblingsfigur von Mrs. de Winter.","sourceLineIndex":47,"ipa":"/dɛɾ ˈɑmoːɾ vɑːɾ diː lˌiːblɪŋsfɪɡˈuːɾ fɔn ˌɛmˌɛrˈɛs dˈeː vˈɪntɜ/","en":"Cupid was Mrs. de Winter's favorite character.","zh":"那尊爱神是德温特夫人生前的最爱","note":""},{"id":"rebecca-das-musical-08-048","lineIndex":48,"speaker":"","original":"Meissner Porzellan, Sir","sourceLineIndex":48,"ipa":"/mˈaɪsnɜ pˌɔɾtsəlˈɑːn zˈiːɾ/","en":"Meissen porcelain, sir","zh":"迈森瓷器，先生","note":""},{"id":"rebecca-das-musical-08-049","lineIndex":49,"speaker":"","original":"Das wertvollste stück im Morgenzimmer!","sourceLineIndex":49,"ipa":"/das vˈɛɾtfɔlstə ʃtˈʏk ɪm mˈɔɾɡəntsˌɪmɜ/","en":"The most valuable piece in the morning room!","zh":"晨室里最贵重的摆设","note":""},{"id":"rebecca-das-musical-08-050","lineIndex":50,"speaker":"","original":"Wie schrecklich!","sourceLineIndex":50,"ipa":"/viː ʃrˈɛklɪç/","en":"How terrible!","zh":"啊真糟糕！","note":""},{"id":"rebecca-das-musical-08-051","lineIndex":51,"speaker":"","original":"Ach, so schlimm ist das nun auch wieder nicht...","sourceLineIndex":51,"ipa":"/ˈax zoː ʃlˈɪm ɪst das nˈuːn ˌaʊx vˈiːdɜ nˈɪçt/","en":"Oh, it's not that bad...","zh":"事情也没有那么糟","note":""},{"id":"rebecca-das-musical-08-052","lineIndex":52,"speaker":"","original":"Im Übrigen ist das dein Ressort, Liebes","sourceLineIndex":52,"ipa":"/ɪm ˈyːbɾɪɡən ɪst das daɪn rˈɛsɔɾt lˈiːbəs/","en":"Besides, that's your department, dear","zh":"顺便说一句，这属于你的管辖范围，亲爱的","note":""},{"id":"rebecca-das-musical-08-053","lineIndex":53,"speaker":"","original":"Maxim, ich habe vergessen, dir das zu sagen...","sourceLineIndex":53,"ipa":"/mˈaksiːm ɪç hɑːbə fɛɾɡˈɛsən diːɾ das tsuː zˈɑːɡən/","en":"Maxim, I forgot to tell you...","zh":"马克西姆，我忘了告诉你……","note":""},{"id":"rebecca-das-musical-08-054","lineIndex":54,"speaker":"","original":"Was?","sourceLineIndex":54,"ipa":"/vˈas/","en":"What?","zh":"什么？","note":""},{"id":"rebecca-das-musical-08-055","lineIndex":55,"speaker":"","original":"Ich habe den Amor zerbrochen","sourceLineIndex":55,"ipa":"/ɪç hɑːbə deːn ˈɑmoːɾ tsɛɾbɾˈɔxən/","en":"I broke Cupid","zh":"是我把那个瓷像打碎了","note":""},{"id":"rebecca-das-musical-08-056","lineIndex":56,"speaker":"","original":"Du?","sourceLineIndex":56,"ipa":"/dˈuː/","en":"You?","zh":"你？","note":""},{"id":"rebecca-das-musical-08-057","lineIndex":57,"speaker":"","original":"Warum zum teufel sagst du das erst jetzt?","sourceLineIndex":57,"ipa":"/vɑːrˈʊm tsʊm tˈɔøfəl zˈɑːkst duː das ˈeːɾst jˈɛtst/","en":"Why the hell are you just saying this now?","zh":"你怎么等到现在才说？","note":""},{"id":"rebecca-das-musical-08-058","lineIndex":58,"speaker":"","original":"Ich wollte mir die Figur ansehen und das ist sie mir einfach aus der Hand gerutscht","sourceLineIndex":58,"ipa":"/ɪç vɔltə miːɾ diː fiːɡˈuːɾ ˈanzˌeːən ʊnt das ɪst ziː miːɾ ˈaɪnfˌax ˌaʊs dɛɾ hˈant ɡərˈʊtʃt/","en":"I wanted to look at the figure and it just slipped out of my hand","zh":"我本想拿起来仔细看看，可后来不小心失手弄掉了","note":""},{"id":"rebecca-das-musical-08-059","lineIndex":59,"speaker":"","original":"Sie hören es, Mrs. Danver","sourceLineIndex":59,"ipa":"/ziː hˈøːrən ɛs ˌɛmˌɛrˈɛs dˈanvɜ/","en":"You hear it, Mrs. Danver","zh":"您都听见了，丹弗斯夫人","note":""},{"id":"rebecca-das-musical-08-060","lineIndex":60,"speaker":"","original":"Mrs. de Winter hat die Figur zerbrochen und vergessen es zu erwähnen","sourceLineIndex":60,"ipa":"/ˌɛmˌɛrˈɛs dˈeː vˈɪntɜ hat diː fiːɡˈuːɾ tsɛɾbɾˈɔxən ʊnt fɛɾɡˈɛsən ɛs tsuː ɛɾvˈɛːnən/","en":"Mrs. de Winter broke the figure and forgot to mention it","zh":"德温特夫人把那尊像打碎了，后来忘了说","note":""},{"id":"rebecca-das-musical-08-061","lineIndex":61,"speaker":"","original":"Es tut mir wirklich sehr leid!","sourceLineIndex":61,"ipa":"/ɛs tˈuːt miːɾ vˈɪɾklɪç zˈeːɾ lˈaɪt/","en":"I'm really very sorry!","zh":"我非常抱歉！","note":""},{"id":"rebecca-das-musical-08-062","lineIndex":62,"speaker":"","original":"Was habe Sie mit den Scherben gemacht, wenn ich fragen darf?","sourceLineIndex":62,"ipa":"/vˈas hɑːbə ziː mɪt deːn ʃˈɛɾbən ɡəmˈaxt vˌɛn ɪç frˈɑːɡən dˈaɾf/","en":"What did you do with the broken pieces, if I may ask?","zh":"我可不可以问一下您把碎片怎么处理了？","note":""},{"id":"rebecca-das-musical-08-063","lineIndex":63,"speaker":"","original":"Sie sind im Sekretär","sourceLineIndex":63,"ipa":"/ziː zɪnt ɪm zˌɛkɾeːtˈɛːɾ/","en":"You are in the secretary","zh":"它们在写字台里","note":""},{"id":"rebecca-das-musical-08-064","lineIndex":64,"speaker":"","original":"Ganz hinten in der rechten Schublade...","sourceLineIndex":64,"ipa":"/ɡˌants hˈɪntən ɪn dɛɾ rˈɛçtən ʃˈʊblɑːdə/","en":"At the back of the right drawer...","zh":"右边抽屉的最底下……","note":""},{"id":"rebecca-das-musical-08-065","lineIndex":65,"speaker":"","original":"Wahrscheinlich hat meine Frau befürchtet, Sie wurden sie verhaften und einsperren, Mrs. Danvers","sourceLineIndex":65,"ipa":"/vɑːɾʃˈaɪnlɪç hat mˌaɪnə frˈaʊ bəfˈʏɾçtət ziː vˌʊɐdən ziː fɛɾhˈaftən ʊnt ˈaɪnʃpˌɛrən ˌɛmˌɛrˈɛs dˈanfɜs/","en":"My wife was probably afraid you were going to arrest her and lock her up, Mrs. Danvers","zh":"看来我的夫人害怕了，怕您会逮捕她，把她关起来，丹弗斯夫人","note":""},{"id":"rebecca-das-musical-08-066","lineIndex":66,"speaker":"","original":"Ich werde mich bei Robert entchuldigen","sourceLineIndex":66,"ipa":"/ɪç vˌɛɾdə mɪç baɪ rˈoːbɜt ɛntçˈʊldɪɡən/","en":"I will apologize to Robert","zh":"我要向罗伯特道歉了","note":""},{"id":"rebecca-das-musical-08-067","lineIndex":67,"speaker":"","original":"Ich konnte ja nicht ahnen","sourceLineIndex":67,"ipa":"/ɪç kˈɔntə jˈɑː nˈɪçt ˈɑːnən/","en":"I couldn't have imagined","zh":"我确实猜不到","note":""},{"id":"rebecca-das-musical-08-068","lineIndex":68,"speaker":"","original":"dass es Madam war, die den Amor zerbrochen hat","sourceLineIndex":68,"ipa":"/das ɛs mˈɑdɑːm vɑːɾ diː deːn ˈɑmoːɾ tsɛɾbɾˈɔxən hat/","en":"that it was Madam who broke Cupid","zh":"会是夫人把爱神像打碎的","note":""},{"id":"rebecca-das-musical-08-069","lineIndex":69,"speaker":"","original":"Gut. Jetzt wissen Sie es.","sourceLineIndex":69,"ipa":"/ɡˈuːt jˌɛtst vˈɪsən ziː ɛs/","en":"Good. Now you know.","zh":"好，现在您知道了","note":""},{"id":"rebecca-das-musical-08-070","lineIndex":70,"speaker":"","original":"Ich hoffe, man kann die Figur wiederherstllen!","sourceLineIndex":70,"ipa":"/ɪç hˈɔfə man kˌan diː fiːɡˈuːɾ viːdɜhˈɛɾstlən/","en":"I hope you can restore the figure!","zh":"我希望能找人把瓷像重新修复","note":""},{"id":"rebecca-das-musical-08-071","lineIndex":71,"speaker":"","original":"Die Angelegenheit ist höchst bedauerlich","sourceLineIndex":71,"ipa":"/diː ˈanɡəlˌeːɡənhˌaɪt ɪst hˈœkst bədˈaʊɜlˌɪç/","en":"The matter is most unfortunate","zh":"这太令人惋惜了，先生","note":""},{"id":"rebecca-das-musical-08-072","lineIndex":72,"speaker":"","original":"Im Morgenzimmer ist bisher noch nie etwas zu Bruch gegangen...","sourceLineIndex":72,"ipa":"/ɪm mˈɔɾɡəntsˌɪmɜ ɪst bɪshˈeːɾ nɔx nˈiː ˈɛtvɑːs tsuː bɾˈʊx ɡəɡˈaŋən/","en":"Nothing has ever broken in the morning room...","zh":"晨室里迄今为止还没有什么东西损坏过","note":""},{"id":"rebecca-das-musical-08-073","lineIndex":73,"speaker":"","original":"Es reicht!","sourceLineIndex":73,"ipa":"/ɛs rˈaɪçt/","en":"Enough!","zh":"够了！","note":""},{"id":"rebecca-das-musical-08-074","lineIndex":74,"speaker":"","original":"Sie können gehen, Mrs. Danvers","sourceLineIndex":74,"ipa":"/ziː kˌœnən ɡˈeːən ˌɛmˌɛrˈɛs dˈanfɜs/","en":"You can go, Mrs. Danvers","zh":"您可以走了，丹弗斯夫人","note":""}],"sourceOrder":8,"displayOrder":3},{"order":9,"id":"09-bist-du-bose","title":"Bist du böse?","titleZh":"你生气了吗？","lines":[{"id":"rebecca-das-musical-09-001","lineIndex":1,"speaker":"","original":"Bist du böse?","sourceLineIndex":1,"ipa":"/bɪst duː bˈøːzə/","en":"Are you evil?","zh":"你生气了吗？","note":""},{"id":"rebecca-das-musical-09-002","lineIndex":2,"speaker":"","original":"Es tut mir leid, das war ein Fehler","sourceLineIndex":2,"ipa":"/ɛs tˈuːt miːɾ lˈaɪt das vɑːɾ aɪn fˈeːlɜ/","en":"I'm sorry, that was a mistake","zh":"我很抱歉，那是个错误","note":""},{"id":"rebecca-das-musical-09-003","lineIndex":3,"speaker":"","original":"Erst die Scherben und dann, dass ich nicht drüber sprach","sourceLineIndex":3,"ipa":"/ˈeːɾst diː ʃˈɛɾbən ʊnt dan das ɪç nˈɪçt dɾˈyːbɜ ʃpɾˈɑːx/","en":"First the broken pieces and then the fact that I didn't talk about it","zh":"先是碎片，之后，我又没说出来","note":""},{"id":"rebecca-das-musical-09-004","lineIndex":4,"speaker":"","original":"Ach vergiss es","sourceLineIndex":4,"ipa":"/ˈax fɛɾɡˈɪs ɛs/","en":"Oh forget it","zh":"啊，忘了它吧！","note":""},{"id":"rebecca-das-musical-09-005","lineIndex":5,"speaker":"","original":"Was interessiert mich dieser Nippes!","sourceLineIndex":5,"ipa":"/vˈas ˌɪntərɛsˈiːɾt mɪç dˌiːzɜ nˈɪpəs/","en":"Why do I care about these knick-knacks!","zh":"这些小东西我根本不在意","note":""},{"id":"rebecca-das-musical-09-006","lineIndex":6,"speaker":"","original":"Vergib mir Maxim...","sourceLineIndex":6,"ipa":"/fɛɾɡˈiːp miːɾ mˈaksiːm/","en":"Forgive me Maxim...","zh":"原谅我，马克西姆……","note":""},{"id":"rebecca-das-musical-09-007","lineIndex":7,"speaker":"","original":"Du reagierst oft wie ein Kind!","sourceLineIndex":7,"ipa":"/duː rˌeːaɡˈiːɾst ˈɔft viː aɪn kˈɪnt/","en":"You often react like a child!","zh":"你的反应就像个小孩","note":""},{"id":"rebecca-das-musical-09-008","lineIndex":8,"speaker":"","original":"Ja, ich weiß ich","sourceLineIndex":8,"ipa":"/jˈɑː ɪç vˈaɪs ɪç/","en":"Yes, I know I do","zh":"是的，我知道","note":""},{"id":"rebecca-das-musical-09-009","lineIndex":9,"speaker":"","original":"Ich hoff nur, dass ich die nicht schade","sourceLineIndex":9,"ipa":"/ɪç hˈɔf nˈuːɾ das ɪç diː nˈɪçt ʃˈɑːdə/","en":"I just hope I don't harm them","zh":"我只希望我没有伤害到你","note":""},{"id":"rebecca-das-musical-09-010","lineIndex":10,"speaker":"","original":"Mir schaden? Wie?","sourceLineIndex":10,"ipa":"/miːɾ ʃˈɑːdən vˈiː/","en":"Harm me? How?","zh":"伤害我？怎么会？","note":""},{"id":"rebecca-das-musical-09-011","lineIndex":11,"speaker":"","original":"Naja, die Leute tratschen gern","sourceLineIndex":11,"ipa":"/nˈɑjɑː diː lˈɔøtə tɾˈatʃən ɡˈɛɾn/","en":"Well, people like to gossip","zh":"嗯，人们总爱说三道四","note":""},{"id":"rebecca-das-musical-09-012","lineIndex":12,"speaker":"","original":"Tratschen gern?!","sourceLineIndex":12,"ipa":"/tɾˈatʃən ɡˈɛɾn/","en":"Like to gossip?!","zh":"说三道四？","note":""},{"id":"rebecca-das-musical-09-013","lineIndex":13,"speaker":"","original":"Was zum teufel weißt du von Gerüchten und Tratsch?","sourceLineIndex":13,"ipa":"/vˈas tsʊm tˈɔøfəl vˈaɪst duː fɔn ɡərˈʏçtən ʊnt tɾˈatʃ/","en":"What the hell do you know about rumors and gossip?","zh":"你都听到了些什么谣言和闲话？","note":""},{"id":"rebecca-das-musical-09-014","lineIndex":14,"speaker":"","original":"Gar nichts, ich mein nur so...","sourceLineIndex":14,"ipa":"/ɡˈɑːɾ nˈɪçts ɪç maɪn nˈuːɾ zˈoː/","en":"Nothing at all, I'm just saying...","zh":"什么也没有，我只是这么说说……","note":""},{"id":"rebecca-das-musical-09-015","lineIndex":15,"speaker":"","original":"Warum horst du auf rederei?!","sourceLineIndex":15,"ipa":"/vɑːrˈʊm hˈoːɾst duː aʊf rˌeːdeːrˈaɪ/","en":"Why are you listening to talk?!","zh":"为什么要听信那些流言蜚语？","note":""},{"id":"rebecca-das-musical-09-016","lineIndex":16,"speaker":"","original":"Mit wem hast du gesprochen?","sourceLineIndex":16,"ipa":"/mɪt vˈeːm hast duː ɡəʃpɾˈɔxən/","en":"Who did you talk to?","zh":"谁跟你说的？","note":""},{"id":"rebecca-das-musical-09-017","lineIndex":17,"speaker":"","original":"Mit keinem!","sourceLineIndex":17,"ipa":"/mɪt kˈaɪnəm/","en":"With no one!","zh":"没有谁！","note":""},{"id":"rebecca-das-musical-09-018","lineIndex":18,"speaker":"","original":"Wie weisst du dann von dem Geschwatz?","sourceLineIndex":18,"ipa":"/viː vˈaɪst duː dan fɔn deːm ɡəʃvˈats/","en":"Then how do you know about this chatter?","zh":"那你怎么知道他们在胡扯？","note":""},{"id":"rebecca-das-musical-09-019","lineIndex":19,"speaker":"","original":"Was macht dich so zornig?","sourceLineIndex":19,"ipa":"/vˈas mˈaxt dɪç zoː tsˈɔɾnɪç/","en":"What makes you so angry?","zh":"你怎么这么生气？","note":""},{"id":"rebecca-das-musical-09-020","lineIndex":20,"speaker":"","original":"Gibt's etwas, das ich nicht weiß?","sourceLineIndex":20,"ipa":"/ɡˈɪpts ˈɛtvɑːs das ɪç nˈɪçt vˈaɪs/","en":"Is there something I don't know?","zh":"有什么我不知道的事吗？","note":""},{"id":"rebecca-das-musical-09-021","lineIndex":21,"speaker":"","original":"Du musst weiss Gott nicht alles wissen!","sourceLineIndex":21,"ipa":"/duː mˈʊst vˈaɪs ɡˈɔt nˈɪçt ˈaləs vˈɪsən/","en":"God knows, you don't have to know everything!","zh":"看在上帝的份上，你没必要对什么都一清二楚！","note":""},{"id":"rebecca-das-musical-09-022","lineIndex":22,"speaker":"","original":"Bitte! Bitte sei mir nicht mehr böse!","sourceLineIndex":22,"ipa":"/bˈɪtə bˈɪtə zˈaɪ miːɾ nˈɪçt mˌeːɾ bˈøːzə/","en":"Please! Please don't be angry with me anymore!","zh":"求你了！求你不要对我这么生气！","note":""},{"id":"rebecca-das-musical-09-023","lineIndex":23,"speaker":"","original":"Ich lieb dich, ich will dich doch nur besser versteh'n","sourceLineIndex":23,"ipa":"/ɪç lˈiːp dˈɪç ɪç vɪl dɪç dɔx nˈuːɾ bˈɛsɜ fɛɾʃtˈeːn/","en":"I love you, I just want to understand you better","zh":"我爱你，我只是想更好地了解你","note":""},{"id":"rebecca-das-musical-09-024","lineIndex":24,"speaker":"","original":"Bist du glüklich?","sourceLineIndex":24,"ipa":"/bɪst duː ɡlˈyːklɪç/","en":"Are you happy?","zh":"你快乐吗？","note":""},{"id":"rebecca-das-musical-09-025","lineIndex":25,"speaker":"","original":"Frag mich nicht!","sourceLineIndex":25,"ipa":"/frˈɑːk mɪç nˈɪçt/","en":"Don't ask me!","zh":"别问我！","note":""},{"id":"rebecca-das-musical-09-026","lineIndex":26,"speaker":"","original":"Bist du glücklich?","sourceLineIndex":26,"ipa":"/bɪst duː ɡlˈʏklɪç/","en":"Are you happy?","zh":"你快乐吗？","note":""},{"id":"rebecca-das-musical-09-027","lineIndex":27,"speaker":"","original":"Glücklich, glücklich!","sourceLineIndex":27,"ipa":"/ɡlˈʏklɪç ɡlˈʏklɪç/","en":"Happy, happy!","zh":"快乐，幸福！","note":""},{"id":"rebecca-das-musical-09-028","lineIndex":28,"speaker":"","original":"Ich weiss nicht, was das ist!","sourceLineIndex":28,"ipa":"/ɪç vˈaɪs nˈɪçt vˈas das ɪst/","en":"I don't know what that is!","zh":"我从来不知道那是什么意思！","note":""}],"sourceOrder":9,"displayOrder":4},{"order":12,"id":"12-unser-geheimnis","title":"Unser Geheimnis","titleZh":"我们的秘密","lines":[{"id":"rebecca-das-musical-12-001","lineIndex":1,"speaker":"","original":"Haben Sie sich schon entschieden, was Sie auf dem Kostümfest tragen werden?","sourceLineIndex":1,"ipa":"/hˌɑːbən ziː zɪç ʃˌoːn ɛntʃˈiːdən vˈas ziː aʊf deːm kˈɔʃtʏmfəst tɾˈɑːɡən vˌɛɾdən/","en":"Have you decided what you're going to wear to the costume party yet?","zh":"你决定穿什么去参加化装舞会了吗？","note":""},{"id":"rebecca-das-musical-12-002","lineIndex":2,"speaker":"","original":"Nein, noch nicht.","sourceLineIndex":2,"ipa":"/nˈaɪn nˈɔx nˈɪçt/","en":"No, not yet.","zh":"不，还没有。","note":""},{"id":"rebecca-das-musical-12-003","lineIndex":3,"speaker":"","original":"Hat Mr. de Winter keinen Wunsch geäußert?","sourceLineIndex":3,"ipa":"/hat ˌɛmˈɛɾ dˈeː vˈɪntɜ kˈaɪnən vˈʊnʃ ɡəˈɔøsɜt/","en":"Didn't Mr. de Winter make a wish?","zh":"德温特先生没有许愿吗？","note":""},{"id":"rebecca-das-musical-12-004","lineIndex":4,"speaker":"","original":"Oh nein. Er überlässt alles mir.","sourceLineIndex":4,"ipa":"/ˈoː nˈaɪn ɛɾ ˌyːbɜlˈɛst ˈaləs mˈiːɾ/","en":"Oh no. He leaves everything to me.","zh":"哦不。他把一切都留给了我。","note":""},{"id":"rebecca-das-musical-12-005","lineIndex":5,"speaker":"","original":"Ah","sourceLineIndex":5,"ipa":"/ˈɑː/","en":"Ah","zh":"啊","note":""},{"id":"rebecca-das-musical-12-006","lineIndex":6,"speaker":"","original":"Also, wenn ich Ihnen einen Vorschlag machen darf","sourceLineIndex":6,"ipa":"/ˈalzoː vˌɛn ɪç ˌiːnən ˌaɪnən fˈoːɾʃlˌɑːk mˈaxən dˈaɾf/","en":"So if I may make you a suggestion","zh":"所以如果我可以给你一个建议","note":""},{"id":"rebecca-das-musical-12-007","lineIndex":7,"speaker":"","original":"Das Lieblingsgemälde Ihres Gatten.","sourceLineIndex":7,"ipa":"/das lˈiːblɪŋsɡˌeːmɛldə ˌiːrəs ɡˈatən/","en":"Your husband's favorite painting.","zh":"你丈夫最喜欢的画。","note":""},{"id":"rebecca-das-musical-12-008","lineIndex":8,"speaker":"","original":"Wirklich?","sourceLineIndex":8,"ipa":"/vˈɪɾklɪç/","en":"Really?","zh":"真的吗？","note":""},{"id":"rebecca-das-musical-12-009","lineIndex":9,"speaker":"","original":"Caroline de Winter","sourceLineIndex":9,"ipa":"/kˌɑroːlˈiːnə dˈeː vˈɪntɜ/","en":"Caroline de Winter","zh":"卡罗琳·德温特","note":""},{"id":"rebecca-das-musical-12-010","lineIndex":10,"speaker":"","original":"Eine Schwester von Mr. de Winters Urgroßvater.","sourceLineIndex":10,"ipa":"/ˌaɪnə ʃvˈɛstɜ fɔn ˌɛmˈɛɾ dˈeː vˈɪntɜs ˈʊɐɡɾoːsfˌɑːtɜ/","en":"A sister of Mr. de Winter's great-grandfather.","zh":"德温特先生的曾祖父的妹妹。","note":""},{"id":"rebecca-das-musical-12-011","lineIndex":11,"speaker":"","original":"Ja, das wäre eine Möglichkeit","sourceLineIndex":11,"ipa":"/jˈɑː das vˈɛːrə ˌaɪnə mˈøːklɪçkˌaɪt/","en":"Yes, that would be a possibility","zh":"是的，有可能","note":""},{"id":"rebecca-das-musical-12-012","lineIndex":12,"speaker":"","original":"Überraschen Sie ihn","sourceLineIndex":12,"ipa":"/ˌyːbɜrˈaʃən ziː ˈiːn/","en":"Surprise him","zh":"给他一个惊喜","note":""},{"id":"rebecca-das-musical-12-013","lineIndex":13,"speaker":"","original":"Ich lasse das Bild auf Ihr Zimmer bringen","sourceLineIndex":13,"ipa":"/ɪç lˈasə das bˈɪlt aʊf iːɾ tsˈɪmɜ bɾˈɪŋən/","en":"I'll have the picture delivered to your room","zh":"我会把照片送到你的房间","note":""},{"id":"rebecca-das-musical-12-014","lineIndex":14,"speaker":"","original":"Die Schneiderin soll es als Vorlage benutzen.","sourceLineIndex":14,"ipa":"/diː ʃnˈaɪdərˌɪn zˌɔl ɛs als fˈoːɾlˌɑːɡə bənˈʊtsən/","en":"The seamstress should use it as a template.","zh":"裁缝师应该使用它作为模板。","note":""},{"id":"rebecca-das-musical-12-015","lineIndex":15,"speaker":"","original":"Vielen Dank, Mrs. Danvers","sourceLineIndex":15,"ipa":"/fˈiːlən dˈaŋk ˌɛmˌɛrˈɛs dˈanfɜs/","en":"Thank you, Mrs. Danvers","zh":"谢谢你，丹弗斯夫人","note":""},{"id":"rebecca-das-musical-12-016","lineIndex":16,"speaker":"","original":"Das ist sehr nett von Ihnen wirklich.","sourceLineIndex":16,"ipa":"/das ɪst zˈeːɾ nˈɛt fɔn ˌiːnən vˈɪɾklɪç/","en":"That's very kind of you really.","zh":"你真是太好了。","note":""},{"id":"rebecca-das-musical-12-017","lineIndex":17,"speaker":"","original":"Es soll unser Geheimnis sein.","sourceLineIndex":17,"ipa":"/ɛs zˌɔl ˌʊnzɜ ɡəhˈaɪmnɪs zaɪn/","en":"It should be our secret.","zh":"这应该是我们的秘密。","note":""},{"id":"rebecca-das-musical-12-018","lineIndex":18,"speaker":"","original":"Schön hier, nicht wahr?","sourceLineIndex":18,"ipa":"/ʃˈøːn hˈiːɾ nˈɪçt vˈɑːɾ/","en":"It's nice here, isn't it?","zh":"这里很好，不是吗？","note":""},{"id":"rebecca-das-musical-12-019","lineIndex":19,"speaker":"","original":"Sehen Sie sich ruhig um","sourceLineIndex":19,"ipa":"/zˈeːən ziː zɪç rˈuːɪç ˈʊm/","en":"Feel free to look around","zh":"随意环顾四周","note":""},{"id":"rebecca-das-musical-12-020","lineIndex":20,"speaker":"","original":"Das Zimmer von Mrs. de Winter","sourceLineIndex":20,"ipa":"/das tsˈɪmɜ fɔn ˌɛmˌɛrˈɛs dˈeː vˈɪntɜ/","en":"Mrs. de Winter's room","zh":"德温特夫人的房间","note":""},{"id":"rebecca-das-musical-12-021","lineIndex":21,"speaker":"","original":"Ein herrlicher Raum.","sourceLineIndex":21,"ipa":"/aɪn hˈɛɾlɪçɜ rˈaʊm/","en":"A wonderful space.","zh":"一个美妙的空间。","note":""},{"id":"rebecca-das-musical-12-022","lineIndex":22,"speaker":"","original":"Ja, wirklich sehr schön","sourceLineIndex":22,"ipa":"/jˈɑː vˈɪɾklɪç zˈeːɾ ʃˈøːn/","en":"Yes, really nice","zh":"是的，真的很好","note":""},{"id":"rebecca-das-musical-12-023","lineIndex":23,"speaker":"","original":"Aber auch ein wenig unheimlich...","sourceLineIndex":23,"ipa":"/ˌɑːbɜ ˌaʊx aɪn vˈeːnɪç ˈʊnhˌaɪmlɪç/","en":"But also a little scary...","zh":"但也有点害怕……","note":""},{"id":"rebecca-das-musical-12-024","lineIndex":24,"speaker":"","original":"Mr. de Winter hat den Westflügel nicht mehr betreten seit seine Frau ertrunken ist","sourceLineIndex":24,"ipa":"/ˌɛmˈɛɾ dˈeː vˈɪntɜ hat deːn vˈɛstflyːɡəl nˈɪçt mˌeːɾ bətɾˈeːtən zaɪt zˌaɪnə frˈaʊ ɛɾtɾˈʊŋkən ɪst/","en":"Mr. de Winter hasn't been in the West Wing since his wife drowned","zh":"自从妻子溺水之后，德温特先生就没有去过西翼","note":""},{"id":"rebecca-das-musical-12-025","lineIndex":25,"speaker":"","original":"Das Rausch, der Brandung","sourceLineIndex":25,"ipa":"/das rˈaʊʃ dɛɾ bɾˈandʊŋ/","en":"The rush, the surf","zh":"急流、海浪","note":""},{"id":"rebecca-das-musical-12-026","lineIndex":26,"speaker":"","original":"Hören Sie das?","sourceLineIndex":26,"ipa":"/hˈøːrən ziː das/","en":"Do you hear that?","zh":"你听到了吗？","note":""},{"id":"rebecca-das-musical-12-027","lineIndex":27,"speaker":"","original":"Das Meer ruft ihren Namen!","sourceLineIndex":27,"ipa":"/das mˈeːɾ rˈʊft ˌiːrən nˈɑːmən/","en":"The sea is calling her name!","zh":"大海在呼唤她的名字！","note":""}],"sourceOrder":12,"displayOrder":5},{"order":13,"id":"13-rebecca-lange-fassung","title":"Rebecca (Lange Fassung)","titleZh":"瑞贝卡（长版）","lines":[{"id":"rebecca-das-musical-13-001","lineIndex":1,"speaker":"","original":"Guten Morgen, Madam","sourceLineIndex":1,"ipa":"/ɡˈuːtən mˈɔɾɡən mˈɑdɑːm/","en":"Good morning, Madam.","zh":"早上好，夫人。","note":""},{"id":"rebecca-das-musical-13-002","lineIndex":2,"speaker":"","original":"Sie sind früh auf heute, Madam","sourceLineIndex":2,"ipa":"/ziː zɪnt frˈyː aʊf hˈɔøtə mˈɑdɑːm/","en":"You're up early today, Madam.","zh":"您今天起得真早，夫人。","note":""},{"id":"rebecca-das-musical-13-003","lineIndex":3,"speaker":"","original":"Haben Sie schlecht geschlafen?","sourceLineIndex":3,"ipa":"/hˌɑːbən ziː ʃlˈɛçt ɡəʃlˈɑːfən/","en":"Did you sleep badly?","zh":"您没睡好吗？","note":""},{"id":"rebecca-das-musical-13-004","lineIndex":4,"speaker":"","original":"Ich habe kein Auge zugemacht","sourceLineIndex":4,"ipa":"/ɪç hɑːbə kˈaɪn ˈaʊɡə tsˈuːɡəmˌaxt/","en":"I didn't close an eye all night.","zh":"我一夜没合眼。","note":""},{"id":"rebecca-das-musical-13-005","lineIndex":5,"speaker":"","original":"Das Wetter, Der Nebel drückt aufs Gemüt","sourceLineIndex":5,"ipa":"/das vˈɛtɜ dɛɾ nˈeːbəl dɾˈʏkt aʊfs ɡəmˈyːt/","en":"This weather — the fog weighs upon the spirit.","zh":"这天气—雾沉沉的，压得人心里发闷。","note":""},{"id":"rebecca-das-musical-13-006","lineIndex":6,"speaker":"","original":"Sie wissen genau, was auf mein Gemüt drückt, Mrs. Danvers","sourceLineIndex":6,"ipa":"/ziː vˈɪsən ɡənˈaʊ vˈas aʊf maɪn ɡəmˈyːt dɾˈʏkt ˌɛmˌɛrˈɛs dˈanfɜs/","en":"You know full well what weighs upon my spirit, Mrs. Danvers.","zh":"您清楚是什么压在我心上，丹弗斯夫人。","note":""},{"id":"rebecca-das-musical-13-007","lineIndex":7,"speaker":"","original":"Ihr Kostümvorschlag... das Ganze war eine böse, hinterhältige Falle!","sourceLineIndex":7,"ipa":"/iːɾ kˈɔʃtʏmfˌoːɾʃlɑːk das ɡˈantsə vɑːɾ ˌaɪnə bˈøːzə hˌɪntɜhˈɛltɪɡə fˈalə/","en":"Your costume suggestion... the whole thing was a cruel, underhanded trap!","zh":"您出的服装主意……从头到尾都是个恶毒阴险的圈套！","note":""},{"id":"rebecca-das-musical-13-008","lineIndex":8,"speaker":"","original":"Wie dumm ich war!","sourceLineIndex":8,"ipa":"/viː dˈʊm ɪç vɑːɾ/","en":"How foolish I was!","zh":"我真是蠢透了！","note":""},{"id":"rebecca-das-musical-13-009","lineIndex":9,"speaker":"","original":"Sie wollten mich bloßstellen","sourceLineIndex":9,"ipa":"/ziː vɔltən mɪç blˈɔsʃtɛlən/","en":"You only meant to humiliate me.","zh":"您只想让我当众出丑。","note":""},{"id":"rebecca-das-musical-13-010","lineIndex":10,"speaker":"","original":"Warum hassen Sie mich? Was habe ich Ihnen getan?","sourceLineIndex":10,"ipa":"/vɑːrˈʊm hˈasən ziː mɪç vˈas hɑːbə ɪç ˌiːnən ɡətˈɑːn/","en":"Why do you hate me? What have I ever done to you?","zh":"您为何这样恨我？我究竟哪里得罪了您？","note":""},{"id":"rebecca-das-musical-13-011","lineIndex":11,"speaker":"","original":"Sie wollen Mrs. de Winters Platz einnehmen","sourceLineIndex":11,"ipa":"/ziː vɔlən ˌɛmˌɛrˈɛs dˈeː vˈɪntɜs plˈats ˈaɪnnˌeːmən/","en":"You would take Mrs. de Winter's place.","zh":"你想取代德温特夫人的位置。","note":""},{"id":"rebecca-das-musical-13-012","lineIndex":12,"speaker":"","original":"Nachts in dem Haus am Meer seufzen die Schatten","sourceLineIndex":12,"ipa":"/nˈaxts ɪn deːm hˈaʊs am mˈeːɾ zˈɔøftsən diː ʃˈatən/","en":"At night, in the house by the sea the shadows sigh.","zh":"夜里，这临海的宅邸中阴影也在叹息。","note":""},{"id":"rebecca-das-musical-13-014","lineIndex":13,"speaker":"","original":"Hüte dich, fürchte dich","sourceLineIndex":14,"ipa":"/hˈyːtə dˈɪç fˈʏɾçtə dˈɪç/","en":"Beware, be afraid —","zh":"当心，畏惧吧—","note":""},{"id":"rebecca-das-musical-13-015","lineIndex":14,"speaker":"","original":"Denn alle Türn sind verboten","sourceLineIndex":15,"ipa":"/dɛn ˈalə tˈʏɾn zɪnt fɛɾbˈoːtən/","en":"for every tower is forbidden","zh":"因为每一座塔楼都禁止入内","note":""},{"id":"rebecca-das-musical-13-016","lineIndex":15,"speaker":"","original":"versperrt und bewacht und wer hier eindringt soll verflucht sein und verloren","sourceLineIndex":16,"ipa":"/fɛɾʃpˈɛɾt ʊnt bəvˈaxt ʊnt vˈeːɾ hˈiːɾ ˈaɪndɾˌɪŋt zˌɔl fɛɾflˈʊxt zaɪn ʊnt fɛɾlˈoːrən/","en":"locked and guarded and whoever trespasses here shall be cursed and lost.","zh":"紧锁且有人把守擅入者必受诅咒万劫不复。","note":""},{"id":"rebecca-das-musical-13-019","lineIndex":16,"speaker":"","original":"Jeder Raum in diesem Haus atmet Melancholie alle Dinge hier warten auf sie","sourceLineIndex":19,"ipa":"/jˈeːdɜ rˈaʊm ɪn dˌiːzəm hˈaʊs ˈatmət mˌeːlançoːlˈiː ˈalə dˈɪŋə hˈiːɾ vˈaɾtən aʊf ziː/","en":"Every room in this house breathes melancholy; all things here await her.","zh":"宅中每个房间都透着哀愁；这里的一切都在等她。","note":""},{"id":"rebecca-das-musical-13-021","lineIndex":17,"speaker":"","original":"REBECCA wo du auch immer bist dein Herz ist ruhlos wie die wilde freie See","sourceLineIndex":21,"ipa":"/reːbˈɛkɑː vˌoː duː ˌaʊx ˈɪmɜ bɪst daɪn hˈɛɾts ɪst rˈuːloːs viː diː vˈɪldə frˈaɪə zˈeː/","en":"REBECCA, wherever you are your heart is restless like the wild and open sea.","zh":"丽贝卡，无论你在何方你的心永不安宁如那狂野开阔的大海。","note":""},{"id":"rebecca-das-musical-13-024","lineIndex":18,"speaker":"","original":"Wenn der Abend beginnt singt der Wind:","sourceLineIndex":24,"ipa":"/vˌɛn dɛɾ ˈɑːbənt bəɡˈɪnt zˈɪŋt dɛɾ vˈɪnt/","en":"When evening falls, the wind sings:","zh":"每当夜幕降临，风便唱道：","note":""},{"id":"rebecca-das-musical-13-025","lineIndex":19,"speaker":"","original":"REBECCA komm heim REBECCA!","sourceLineIndex":25,"ipa":"/reːbˈɛkɑː kˈɔm hˈaɪm reːbˈɛkɑː/","en":"REBECCA, come home, REBECCA!","zh":"丽贝卡，回家吧，丽贝卡！","note":""},{"id":"rebecca-das-musical-13-026","lineIndex":20,"speaker":"","original":"aus dem Nebelreich zurück nach Manderley!","sourceLineIndex":26,"ipa":"/ˌaʊs deːm nˈeːbəlrˌaɪç tsuːrˈʏk nɑːx mˈandɜlˌaɪ/","en":"back from the misty realm to Manderley!","zh":"从雾之国度回到曼德雷！","note":""},{"id":"rebecca-das-musical-13-027","lineIndex":21,"speaker":"","original":"Nichts was ihr sagt und tut bleibt ihr verborgen","sourceLineIndex":27,"ipa":"/nˈɪçts vˈas iːɾ zˈɑːɡt ʊnt tˈuːt blˈaɪpt iːɾ fɛɾbˈɔɾɡən/","en":"Nothing you say or do stays hidden from her.","zh":"你的一言一行都瞒不过她。","note":""},{"id":"rebecca-das-musical-13-029","lineIndex":22,"speaker":"","original":"Hüte dich, fürchte dich Sie lässt sich nicht bestehlen und rächt den Verrat","sourceLineIndex":29,"ipa":"/hˈyːtə dˈɪç fˈʏɾçtə dɪç ziː lˈɛst zɪç nˈɪçt bəʃtˈeːlən ʊnt rˈɛçt deːn fɛɾrˈɑːt/","en":"Beware, be afraid — she will not be robbed and avenges betrayal.","zh":"当心，畏惧吧—她不容人窃取更会报复背叛。","note":""},{"id":"rebecca-das-musical-13-032","lineIndex":23,"speaker":"","original":"Wer sie beleidigt wird es eines Tages büßen","sourceLineIndex":32,"ipa":"/vˈeːɾ ziː bəlˈaɪdɪçt vˌɪɾt ɛs ˌaɪnəs tˈɑːɡəs bˈyːsən/","en":"Whoever insults her shall pay for it one day.","zh":"冒犯她的人终将偿付代价。","note":""},{"id":"rebecca-das-musical-13-033","lineIndex":24,"speaker":"","original":"Dieses Haus ist ihr zu Haus alles wartet auf sie","sourceLineIndex":33,"ipa":"/dˌiːzəs hˈaʊs ɪst iːɾ tsuː hˈaʊs ˈaləs vˈaɾtət aʊf ziː/","en":"This house is her home; everything awaits her.","zh":"这宅子仍是她的宅子；万物都在等她。","note":""},{"id":"rebecca-das-musical-13-035","lineIndex":25,"speaker":"","original":"Die sie liebten vergessen sie nie","sourceLineIndex":35,"ipa":"/diː ziː lˈiːptən fɛɾɡˈɛsən ziː nˈiː/","en":"Those who loved her never forget her.","zh":"爱过她的人永远不会忘记她。","note":""},{"id":"rebecca-das-musical-13-036","lineIndex":26,"speaker":"","original":"REBECCA wo du auch immer bist dein Herz bleibt ruhlos wie die wilde freie See","sourceLineIndex":36,"ipa":"/reːbˈɛkɑː vˌoː duː ˌaʊx ˈɪmɜ bɪst daɪn hˈɛɾts blˈaɪpt rˈuːloːs viː diː vˈɪldə frˈaɪə zˈeː/","en":"REBECCA, wherever you are your heart stays restless like the wild and open sea.","zh":"丽贝卡，无论你在何方你的心永不安宁如那狂野开阔的大海。","note":""},{"id":"rebecca-das-musical-13-039","lineIndex":27,"speaker":"","original":"Wenn der Abend beginnt singt der Wind:","sourceLineIndex":39,"ipa":"/vˌɛn dɛɾ ˈɑːbənt bəɡˈɪnt zˈɪŋt dɛɾ vˈɪnt/","en":"When evening falls, the wind sings:","zh":"每当夜幕降临，风便唱道：","note":""},{"id":"rebecca-das-musical-13-040","lineIndex":28,"speaker":"","original":"REBECCA komm heim REBECCA!","sourceLineIndex":40,"ipa":"/reːbˈɛkɑː kˈɔm hˈaɪm reːbˈɛkɑː/","en":"REBECCA, come home, REBECCA!","zh":"丽贝卡，回家吧，丽贝卡！","note":""},{"id":"rebecca-das-musical-13-041","lineIndex":29,"speaker":"","original":"aus dem Nebelreich zurück nach Manderley!","sourceLineIndex":41,"ipa":"/ˌaʊs deːm nˈeːbəlrˌaɪç tsuːrˈʏk nɑːx mˈandɜlˌaɪ/","en":"back from the misty realm to Manderley!","zh":"从雾之国度回到曼德雷！","note":""},{"id":"rebecca-das-musical-13-042","lineIndex":30,"speaker":"","original":"Tu nicht was sie empört!","sourceLineIndex":42,"ipa":"/tˈuː nˈɪçt vˈas ziː ɛmpˈœɾt/","en":"Do not do what provokes her!","zh":"别做惹怒她的事！","note":""},{"id":"rebecca-das-musical-13-043","lineIndex":31,"speaker":"","original":"Oh nein!","sourceLineIndex":43,"ipa":"/ˈoː nˈaɪn/","en":"Oh no!","zh":"哦，不！","note":""},{"id":"rebecca-das-musical-13-044","lineIndex":32,"speaker":"","original":"Nimm nicht was ihr gehört!","sourceLineIndex":44,"ipa":"/nˈɪm nˈɪçt vˈas iːɾ ɡəhˈœɾt/","en":"Take not what is hers!","zh":"别碰属于她的东西！","note":""},{"id":"rebecca-das-musical-13-045","lineIndex":33,"speaker":"","original":"wer sie stört, wird zerstört!","sourceLineIndex":45,"ipa":"/vˈeːɾ ziː ʃtˈœɾt vˌɪɾt tsɛɾʃtˈœɾt/","en":"Whoever disturbs her shall be destroyed!","zh":"惊扰她的人必被摧毁！","note":""},{"id":"rebecca-das-musical-13-046","lineIndex":34,"speaker":"","original":"Nein!","sourceLineIndex":46,"ipa":"/nˈaɪn/","en":"No!","zh":"不！","note":""},{"id":"rebecca-das-musical-13-047","lineIndex":35,"speaker":"","original":"REBECCA!","sourceLineIndex":47,"ipa":"/reːbˈɛkɑː/","en":"REBECCA!","zh":"丽贝卡！","note":""},{"id":"rebecca-das-musical-13-048","lineIndex":36,"speaker":"","original":"Sie ist fort!","sourceLineIndex":48,"ipa":"/ziː ɪst fˈɔɾt/","en":"She is gone!","zh":"她已经离去！","note":""},{"id":"rebecca-das-musical-13-049","lineIndex":37,"speaker":"","original":"Wo du auch immer bist Weit fort","sourceLineIndex":49,"ipa":"/vˌoː duː ˌaʊx ˈɪmɜ bɪst vˈaɪt fˈɔɾt/","en":"Wherever you are far away.","zh":"无论你身在何方早已远去。","note":""},{"id":"rebecca-das-musical-13-051","lineIndex":38,"speaker":"","original":"Komm heim!","sourceLineIndex":51,"ipa":"/kˈɔm hˈaɪm/","en":"Come home!","zh":"回来！","note":""},{"id":"rebecca-das-musical-13-052","lineIndex":39,"speaker":"","original":"Dein Herz bleibt ruhlos wie die wilde, freie See","sourceLineIndex":52,"ipa":"/daɪn hˈɛɾts blˈaɪpt rˈuːloːs viː diː vˈɪldə frˈaɪə zˈeː/","en":"Your heart stays restless like the wild, free sea.","zh":"你的心永不安宁如那狂野自由的海。","note":""},{"id":"rebecca-das-musical-13-054","lineIndex":40,"speaker":"","original":"Wer tot ist kehrt nicht mehr zurück","sourceLineIndex":54,"ipa":"/vˈeːɾ tˈoːt ɪst kˈeːɾt nˈɪçt mˌeːɾ tsuːrˈʏk/","en":"The dead do not return.","zh":"逝者不会再回还。","note":""},{"id":"rebecca-das-musical-13-055","lineIndex":41,"speaker":"","original":"Wenn der Abend beginnt, singt der Wind:","sourceLineIndex":55,"ipa":"/vˌɛn dɛɾ ˈɑːbənt bəɡˈɪnt zˈɪŋt dɛɾ vˈɪnt/","en":"When evening falls, the wind sings:","zh":"每当夜晚到来，风就开始吟唱：","note":""},{"id":"rebecca-das-musical-13-056","lineIndex":42,"speaker":"","original":"REBECCA","sourceLineIndex":56,"ipa":"/reːbˈɛkɑː/","en":"REBECCA","zh":"丽贝卡","note":""},{"id":"rebecca-das-musical-13-057","lineIndex":43,"speaker":"","original":"Was war ist vorbei","sourceLineIndex":57,"ipa":"/vˈas vɑːɾ ɪst foːɾbˈaɪ/","en":"What is past is over.","zh":"那些都已成过去！","note":""},{"id":"rebecca-das-musical-13-058","lineIndex":44,"speaker":"","original":"Komm heim REBECCA","sourceLineIndex":58,"ipa":"/kˈɔm hˈaɪm reːbˈɛkɑː/","en":"Come home, REBECCA","zh":"回来，丽贝卡！","note":""},{"id":"rebecca-das-musical-13-059","lineIndex":45,"speaker":"","original":"Warum dann hab ich Angst vor...","sourceLineIndex":59,"ipa":"/vɑːrˈʊm dan hˈɑːp ɪç ˈaŋst fˈɔɾ/","en":"Then why am I afraid of...","zh":"为什么我会害怕……","note":""},{"id":"rebecca-das-musical-13-060","lineIndex":46,"speaker":"","original":"Aus dem Nebelreich zurück nach Manderley","sourceLineIndex":60,"ipa":"/ˌaʊs deːm nˈeːbəlrˌaɪç tsuːrˈʏk nɑːx mˈandɜlˌaɪ/","en":"Back from the misty realm to Manderley.","zh":"从那雾的国度再次回到曼德雷！","note":""},{"id":"rebecca-das-musical-13-061","lineIndex":47,"speaker":"","original":"REBECCA","sourceLineIndex":61,"ipa":"/reːbˈɛkɑː/","en":"REBECCA","zh":"丽贝卡！","note":""}],"sourceOrder":13,"displayOrder":6},{"order":14,"id":"14-merkwurdig","title":"Merkwürdig","titleZh":"奇怪","lines":[{"id":"rebecca-das-musical-14-001","lineIndex":1,"speaker":"","original":"Merkwürdig geht es schon dass dieses Wesen uns're Herrin ist","sourceLineIndex":1,"ipa":"/mˈɛɾkvʏɾdˌɪç ɡˈeːt ɛs ʃˌoːn das dˌiːzəs vˈeːzən ˈʊnsrə hˈɛrɪn ɪst/","en":"Strange it is, indeed that this creature is our lady.","zh":"说来也真奇怪这个姑娘竟成了我们的女主人。","note":""},{"id":"rebecca-das-musical-14-003","lineIndex":2,"speaker":"","original":"Sie schleicht durch Gang und Halle wie ein Reh und trifft man sie, erschrickt sie wie ein Lamm","sourceLineIndex":3,"ipa":"/ziː ʃlˈaɪçt dʊɐç ɡˈaŋ ʊnt hˈalə viː aɪn rˈeː ʊnt tɾˈɪft man ziː ɛɾʃrˈɪkt ziː viː aɪn lˈam/","en":"She steals through passage and hall like a deer and when one meets her, she starts like a lamb.","zh":"她像头小鹿，悄悄溜过回廊与大厅被人撞见时，又像羔羊般惊惶。","note":""},{"id":"rebecca-das-musical-14-005","lineIndex":3,"speaker":"","original":"ich denke, wenn ich sie sehe sie ist doch vielmehr zu vereinsamt Madam","sourceLineIndex":5,"ipa":"/ɪç dˈɛŋkə vˌɛn ɪç ziː zˈeːə ziː ɪst dɔx fˈiːlmˌeːɾ tsuː fɛɾˈaɪnzˌamt mˈɑdɑːm/","en":"I think, when I see her she is far too lonely, madam.","zh":"我想，每当我望见她夫人，她实在太孤单了。","note":""},{"id":"rebecca-das-musical-14-007","lineIndex":4,"speaker":"","original":"Wie unerwartet, wie bedauernswert das kann nicht lange gut geh'n, weil sie nicht hierher gehört","sourceLineIndex":7,"ipa":"/viː ˈʊnɛɾvˌaɾtət viː bədˈaʊɜnsvˌeːɾt das kˌan nˈɪçt lˈaŋə ɡˈuːt ɡˈeːn vˌaɪl ziː nˈɪçt hˈiːɾhɜ ɡəhˈœɾt/","en":"How unforeseen, how pitiable this cannot end well, for she does not belong here.","zh":"多么意外，多么可怜这样下去不会长久，因为她本不属于这里。","note":""},{"id":"rebecca-das-musical-14-009","lineIndex":5,"speaker":"","original":"Wie konnte das geschehen?","sourceLineIndex":9,"ipa":"/viː kˈɔntə das ɡəʃˈeːən/","en":"How could this have happened?","zh":"这怎么会发生？","note":""},{"id":"rebecca-das-musical-14-010","lineIndex":6,"speaker":"","original":"Was schönt einen so fatalen Ball?","sourceLineIndex":10,"ipa":"/vˈas ʃˈœnt ˌaɪnən zoː fatˈɑːlən bˈal/","en":"What redeems so fateful a ball?","zh":"是什么让那场要命的舞会还看得过去？","note":""},{"id":"rebecca-das-musical-14-011","lineIndex":7,"speaker":"","original":"Warum nahm er sie mit nach Manderley?","sourceLineIndex":11,"ipa":"/vɑːrˈʊm nˈɑːm ɛɾ ziː mɪt nɑːx mˈandɜlˌaɪ/","en":"Why did he bring her to Manderley?","zh":"他为何带她来曼德雷？","note":""},{"id":"rebecca-das-musical-14-012","lineIndex":8,"speaker":"","original":"Ein Mann mit Trauer, er sieht sie schon einmal Die spielt in scheuer Art entspricht durchaus seinem Ideal","sourceLineIndex":12,"ipa":"/aɪn mˈan mɪt tɾˈaʊɜ ɛɾ zˈiːt ziː ʃˌoːn ˈaɪnmˌɑːl diː ʃpˈiːlt ɪn ʃˈɔøɜ ˈɑːɾt ɛntʃpɾˈɪçt dˈʊɐçˌaʊs zˌaɪnəm ˌiːdeːˈɑːl/","en":"A grieving man — he has seen her like before; she behaves with shyness which answers well to his ideal.","zh":"一个沉浸在哀伤里的男人，似乎早见过她这样的姑娘；她那羞怯的模样正合他的心意。","note":""},{"id":"rebecca-das-musical-14-015","lineIndex":9,"speaker":"","original":"Wie ungewöhnlich, wie zutiefst verkehrt Sie weiß, seit sie ankam, dass sie nicht hierher gehört","sourceLineIndex":15,"ipa":"/viː ˈʊnɡəvˌøːnlɪç viː tsuːtˈiːfst fɛɾkˈeːɾt ziː vˈaɪs zaɪt ziː ˈankˌɑːm das ziː nˈɪçt hˈiːɾhɜ ɡəhˈœɾt/","en":"How unusual, how deeply wrong she has known since her arrival that she does not belong here.","zh":"多么反常，多么大错特错自从踏进这里她就明白，自己不属于此处。","note":""},{"id":"rebecca-das-musical-14-017","lineIndex":10,"speaker":"","original":"Im höchsten Gott fürchte ich wird mal sie gelungen hier man hält auch hier nichts von ihr","sourceLineIndex":17,"ipa":"/ɪm hˈœkstən ɡˈɔt fˈʏɾçtə ɪç vˌɪɾt mˈɑːl ziː ɡəlˈʊŋən hˈiːɾ man hˈɛlt ˌaʊx hˈiːɾ nˈɪçts fɔn iːɾ/","en":"I fear before God that she may yet succeed here; nor is she thought much of here.","zh":"我向上帝发誓，真怕她终会在此得逞；这里的人也同样看不起她。","note":""},{"id":"rebecca-das-musical-14-019","lineIndex":11,"speaker":"","original":"man muss sich fast genieren","sourceLineIndex":19,"ipa":"/man mˈʊs zɪç fˈast ɡənˈiːrən/","en":"one can almost feel ashamed","zh":"简直让人替她难为情—","note":""},{"id":"rebecca-das-musical-14-020","lineIndex":12,"speaker":"","original":"der country club lehnt sie ab","sourceLineIndex":20,"ipa":"/dɛɾ kˈuːntɾiː klˈuːp lˈeːnt ziː ˈap/","en":"the country club rejects her;","zh":"乡村俱乐部将她拒之门外；","note":""},{"id":"rebecca-das-musical-14-021","lineIndex":13,"speaker":"","original":"man spottet über sie","sourceLineIndex":21,"ipa":"/man ʃpˈɔtət ˌyːbɜ ziː/","en":"they mock her;","zh":"人们嘲笑她；","note":""},{"id":"rebecca-das-musical-14-022","lineIndex":14,"speaker":"","original":"das Ansehen und das Haare stehen auf dem Spiel","sourceLineIndex":22,"ipa":"/das ˈanzˌeːən ʊnt das hˈɑːrə ʃtˈeːən aʊf deːm ʃpˈiːl/","en":"reputation and pride are at stake.","zh":"颜面与尊严都悬于一线。","note":""},{"id":"rebecca-das-musical-14-023","lineIndex":15,"speaker":"","original":"Es gibt so viel Gerede wie noch nie man fragt sich, was ihm so an ihr gefiel","sourceLineIndex":23,"ipa":"/ɛs ɡˈiːpt zoː fˈiːl ɡərˈeːdə viː nɔx nˈiː man frˈɑːkt zɪç vˈas iːm zoː an iːɾ ɡəfˈiːl/","en":"There is more gossip than ever one wonders what he found in her to love.","zh":"闲言碎语比以往任何时候都多人人都在猜，他究竟看上她哪一点。","note":""},{"id":"rebecca-das-musical-14-025","lineIndex":16,"speaker":"","original":"Selbst der Verhasste behandelt sie sehr kühl","sourceLineIndex":25,"ipa":"/zˈɛlpst dɛɾ fɛɾhˈastə bəhˈandəlt ziː zˈeːɾ kˈyːl/","en":"Even the most detested treats her coldly.","zh":"就连最讨人厌的那个，也对她冷若冰霜。","note":""}],"sourceOrder":14,"displayOrder":7},{"order":17,"id":"17-ehrlichkeit-und-vertrauen-live","title":"Ehrlichkeit und Vertrauen","titleZh":"诚实与信任","lines":[{"id":"rebecca-das-musical-17-001","lineIndex":1,"speaker":"","original":"Meine Meinung ist nicht wichtig","sourceLineIndex":1,"ipa":"/mˌaɪnə mˈaɪnʊŋ ɪst nˈɪçt vˈɪçtɪç/","en":"My opinion is not important","zh":"我的意见并不重要","note":""},{"id":"rebecca-das-musical-17-002","lineIndex":2,"speaker":"","original":"Doch ich sprech sie offen aus.","sourceLineIndex":2,"ipa":"/dɔx ɪç ʃpɾˈɛç ziː ˈɔfən ˈaʊs/","en":"But I say them openly.","zh":"但我公开地说这些。","note":""},{"id":"rebecca-das-musical-17-003","lineIndex":3,"speaker":"","original":"Was verkehrt ist, und was richtig","sourceLineIndex":3,"ipa":"/vˈas fɛɾkˈeːɾt ɪst ʊnt vˈas rˈɪçtɪç/","en":"What is wrong and what is right","zh":"什么是错，什么是对","note":""},{"id":"rebecca-das-musical-17-004","lineIndex":4,"speaker":"","original":"Stellt sich oft erst später heraus.","sourceLineIndex":4,"ipa":"/ʃtˈɛlt zɪç ˈɔft ˈeːɾst ʃpˈɛːtɜ hɛrˈaʊs/","en":"Often it only becomes clear later.","zh":"通常只有到后来才变得清楚。","note":""},{"id":"rebecca-das-musical-17-005","lineIndex":5,"speaker":"","original":"Und wenn eine Frau nur schön ist","sourceLineIndex":5,"ipa":"/ʊnt vˌɛn ˌaɪnə frˈaʊ nˈuːɾ ʃˈøːn ɪst/","en":"And if a woman is only beautiful","zh":"如果一个女人只是美丽","note":""},{"id":"rebecca-das-musical-17-006","lineIndex":6,"speaker":"","original":"Doch im Innern kalt und leer","sourceLineIndex":6,"ipa":"/dɔx ɪm ˈɪnɜn kˈalt ʊnt lˈeːɾ/","en":"But inside cold and empty","zh":"但内心冰冷空虚","note":""},{"id":"rebecca-das-musical-17-007","lineIndex":7,"speaker":"","original":"Bleibt Fassade, was zu sehn ist.","sourceLineIndex":7,"ipa":"/blˈaɪpt fˈasɑːdə vˈas tsuː zˈeːn ɪst/","en":"What remains is a facade, what can be seen.","zh":"剩下的就是一个门面，也就是看得见的东西。","note":""},{"id":"rebecca-das-musical-17-008","lineIndex":8,"speaker":"","original":"Was ein Mann wirklich braucht, ist viel mehr:","sourceLineIndex":8,"ipa":"/vˈas aɪn mˈan vˈɪɾklɪç bɾˈaʊxt ɪst fˈiːl mˈeːɾ/","en":"What a man really needs is much more:","zh":"男人真正需要的远不止这些：","note":""},{"id":"rebecca-das-musical-17-009","lineIndex":9,"speaker":"","original":"Ehrlichkeit und Vertrauen","sourceLineIndex":9,"ipa":"/ˈeːɾlɪçkˌaɪt ʊnt fɛɾtɾˈaʊən/","en":"honesty and trust","zh":"诚实和信任","note":""},{"id":"rebecca-das-musical-17-010","lineIndex":10,"speaker":"","original":"Freundlichkeit und Herzenswärme","sourceLineIndex":10,"ipa":"/frˈɔøntlɪçkˌaɪt ʊnt hˈɛɾtsənsvˌɛɾmə/","en":"Kindness and warmth of heart","zh":"善良和温暖的心","note":""},{"id":"rebecca-das-musical-17-011","lineIndex":11,"speaker":"","original":"Und die Kraft nach vorn zu schauen","sourceLineIndex":11,"ipa":"/ʊnt diː kɾˈaft nɑːx fˈɔɾn tsuː ʃˈaʊən/","en":"And the strength to look forward","zh":"以及向前看的力量","note":""},{"id":"rebecca-das-musical-17-012","lineIndex":12,"speaker":"","original":"Wenn du dich selber verlierst.","sourceLineIndex":12,"ipa":"/vˌɛn duː dɪç zˈɛlbɜ fɛɾlˈiːɾst/","en":"When you lose yourself.","zh":"当你迷失自己的时候。","note":""},{"id":"rebecca-das-musical-17-013","lineIndex":13,"speaker":"","original":"Ein Mensch, der da ist, wenn du Fragen stellst","sourceLineIndex":13,"ipa":"/aɪn mˈɛnʃ dɛɾ dɑː ˈɪst vˌɛn duː frˈɑːɡən ʃtˈɛlst/","en":"A person who is there when you ask questions","zh":"一个当你提问时在场的人","note":""},{"id":"rebecca-das-musical-17-014","lineIndex":14,"speaker":"","original":"Und der dich auffängt, wenn du fällst","sourceLineIndex":14,"ipa":"/ʊnt dɛɾ dɪç ˈaʊffˌɛŋt vˌɛn duː fˈɛlst/","en":"And who catches you when you fall","zh":"当你跌倒时谁扶住你","note":""},{"id":"rebecca-das-musical-17-015","lineIndex":15,"speaker":"","original":"Ist viel mehr wert als alle Schönheit dieser Welt.","sourceLineIndex":15,"ipa":"/ɪst fˈiːl mˈeːɾ vˈɛɾt als ˈalə ʃˈœnhaɪt dˌiːzɜ vˈɛlt/","en":"Is worth much more than all the beauty in the world.","zh":"比世界上所有的美丽都更有价值。","note":""},{"id":"rebecca-das-musical-17-016","lineIndex":16,"speaker":"","original":"(Danke Frank)","sourceLineIndex":16,"ipa":"/dˈaŋkə frˈaŋk/","en":"(Thanks Frank)","zh":"（谢谢弗兰克）","note":""},{"id":"rebecca-das-musical-17-017","lineIndex":17,"speaker":"","original":"Sicherheit für ein Leben","sourceLineIndex":17,"ipa":"/zˈɪçɜhˌaɪt fyːɾ aɪn lˈeːbən/","en":"security for a life","zh":"一生的保障","note":""},{"id":"rebecca-das-musical-17-018","lineIndex":18,"speaker":"","original":"Zweisamkeit in schweren Stunden","sourceLineIndex":18,"ipa":"/tsvˈaɪzɑːmkˌaɪt ɪn ʃvˈeːrən ʃtˈʊndən/","en":"Togetherness in difficult times","zh":"困难时期团结一致","note":""},{"id":"rebecca-das-musical-17-019","lineIndex":19,"speaker":"","original":"Und den Mut, sich ganz zu geben","sourceLineIndex":19,"ipa":"/ʊnt deːn mˈuːt zɪç ɡˌants tsuː ɡˈeːbən/","en":"And the courage to give yourself completely","zh":"以及完全奉献自己的勇气","note":""},{"id":"rebecca-das-musical-17-020","lineIndex":20,"speaker":"","original":"Ohne zu fragen, was wird","sourceLineIndex":20,"ipa":"/ˈoːnə tsuː frˈɑːɡən vˈas vˌɪɾt/","en":"Without asking what will happen","zh":"不问会发生什么","note":""},{"id":"rebecca-das-musical-17-021","lineIndex":21,"speaker":"","original":"Ein Mensch, der hört wovon dein Schweigen spricht","sourceLineIndex":21,"ipa":"/aɪn mˈɛnʃ dɛɾ hˈœɾt vˈoːvoːn daɪn ʃvˈaɪɡən ʃpɾˈɪçt/","en":"A person who hears what your silence speaks of","zh":"一个听到你沉默所诉说的人","note":""},{"id":"rebecca-das-musical-17-022","lineIndex":22,"speaker":"","original":"Und Angst besiegt durch Zuversicht","sourceLineIndex":22,"ipa":"/ʊnt ˈaŋst bəzˈiːkt dʊɐç tsuːfɛɾzˈɪçt/","en":"And fear conquered by confidence","zh":"恐惧被信心战胜","note":""},{"id":"rebecca-das-musical-17-023","lineIndex":23,"speaker":"","original":"Ist viel mehr wert als alle Schönheit dieser Welt.","sourceLineIndex":23,"ipa":"/ɪst fˈiːl mˈeːɾ vˈɛɾt als ˈalə ʃˈœnhaɪt dˌiːzɜ vˈɛlt/","en":"Is worth much more than all the beauty in the world.","zh":"比世界上所有的美丽都更有价值。","note":""},{"id":"rebecca-das-musical-17-024","lineIndex":24,"speaker":"","original":"Sehr viel mehr.","sourceLineIndex":24,"ipa":"/zˈeːɾ fˈiːl mˈeːɾ/","en":"A lot more.","zh":"还有很多。","note":""}],"sourceOrder":17,"displayOrder":8},{"order":18,"id":"18-i-m-an-american-woman-live","title":"I’m an American Woman","titleZh":"我是一个美国女人","lines":[{"id":"rebecca-das-musical-18-001","lineIndex":1,"speaker":"","original":"Hat einer seine Frau begraben muss er eine neue haben!","sourceLineIndex":1,"ipa":"/hat ˌaɪnɜ zˌaɪnə frˈaʊ bəɡɾˈɑːbən mˈʊs ɛɾ ˌaɪnə nˈɔøə hˈɑːbən/","en":"Someone buried his wife he must have a new one!","zh":"有人埋葬了他的妻子他必须有一个新的！","note":""},{"id":"rebecca-das-musical-18-003","lineIndex":2,"speaker":"","original":"Und keine könnte besser sein als... ich!","sourceLineIndex":3,"ipa":"/ʊnt kˈaɪnə kˈœntə bˈɛsɜ zaɪn ˈals ˈɪç/","en":"And no one could be better than... me!","zh":"没有人能比……我更好！","note":""},{"id":"rebecca-das-musical-18-004","lineIndex":3,"speaker":"","original":"Und wenn er auch Lord Maner wär","sourceLineIndex":4,"ipa":"/ʊnt vˌɛn ɛɾ ˌaʊx lˈɔɾt mˈɑːnɜ vˈɛːɾ/","en":"And if he were also Lord Maner","zh":"如果他也是曼纳勋爵","note":""},{"id":"rebecca-das-musical-18-005","lineIndex":4,"speaker":"","original":"mit Schloß und altem Butler selbst wenn der King sein Gönner wär er findet nichts bessres als mich!","sourceLineIndex":5,"ipa":"/mɪt ʃlˈoːs ʊnt ˈaltəm bˈʊtlɜ zˈɛlpst vˌɛn dɛɾ kˈɪŋ zaɪn ɡˈœnɜ vˈɛːɾ ɛɾ fˈɪndət nˈɪçts bˈɛsrəs als mɪç/","en":"with a castle and an old butler even if the king were his patron he doesn't find anything better than me!","zh":"有一座城堡和一位老管家即使国王是他的赞助人他找不到比我更好的了！","note":""},{"id":"rebecca-das-musical-18-008","lineIndex":5,"speaker":"","original":"Denn sehn Sie:","sourceLineIndex":8,"ipa":"/dɛn zˈeːn ziː/","en":"Because you see:","zh":"因为你看到：","note":""},{"id":"rebecca-das-musical-18-009","lineIndex":6,"speaker":"","original":"I'm an american woman!","sourceLineIndex":9,"ipa":"/ˈiːm an ˌɑmeːriːkˈɑːn voːmˈɑːn/","en":"I'm an American woman!","zh":"我是美国女人！","note":""},{"id":"rebecca-das-musical-18-010","lineIndex":7,"speaker":"","original":"Ich weiß was ich will und will es gleich.","sourceLineIndex":10,"ipa":"/ɪç vˈaɪs vˈas ɪç vɪl ʊnt vɪl ɛs ɡlˈaɪç/","en":"I know what I want and want it right away.","zh":"我知道我想要什么并且马上就想要它。","note":""},{"id":"rebecca-das-musical-18-011","lineIndex":8,"speaker":"","original":"Ich bin nicht diskret, ich möchte, dass man mich versteht!","sourceLineIndex":11,"ipa":"/ɪç bɪn nˈɪçt dˈɪskɾət ɪç mˈœçtə das man mɪç fɛɾʃtˈeːt/","en":"I'm not discreet, I want people to understand me!","zh":"我不谨慎，我希望人们能理解我！","note":""},{"id":"rebecca-das-musical-18-012","lineIndex":9,"speaker":"","original":"Außerdem bin ich reich.","sourceLineIndex":12,"ipa":"/ˈaʊsɜdˌeːm bɪn ɪç rˈaɪç/","en":"Besides, I'm rich.","zh":"另外，我很有钱。","note":""},{"id":"rebecca-das-musical-18-013","lineIndex":10,"speaker":"","original":"Ich hab Swing im Rock und Cola in der Kehle","sourceLineIndex":13,"ipa":"/ɪç hˈɑːp svˈɪŋ ɪm rˈɔk ʊnt kˈoːlɑː ɪn dɛɾ kˈeːlə/","en":"I've got swing in my skirt and coke in my throat","zh":"我的裙子摇摆不定，可乐在我喉咙里","note":""},{"id":"rebecca-das-musical-18-014","lineIndex":11,"speaker":"","original":"und in meiner Seele singt ein Gospelchor denn ich bin von Kopf bis Fuß amerikanisch.","sourceLineIndex":14,"ipa":"/ʊnt ɪn mˌaɪnɜ zˈeːlə zˈɪŋt aɪn ɡˈɔspəlkˌoːɾ dɛn ɪç bɪn fɔn kˈɔpf bɪs fˈuːs ˌɑmeːriːkˈɑnɪʃ/","en":"and in my soul a gospel choir sings because I'm American from head to toe.","zh":"在我的灵魂中，福音唱诗班在歌唱因为我从头到脚都是美国人。","note":""},{"id":"rebecca-das-musical-18-016","lineIndex":12,"speaker":"","original":"Im alten England neigt der Mann an sich zu Vertrottelung.","sourceLineIndex":16,"ipa":"/ɪm ˈaltən ˈɛŋlant nˈaɪkt dɛɾ mˈan an zɪç tsuː fɛɾtɾˈɔtəlˌʊŋ/","en":"In old England, men tend to be idiots.","zh":"在古老的英格兰，男人往往都是白痴。","note":""},{"id":"rebecca-das-musical-18-017","lineIndex":13,"speaker":"","original":"Ich halt ihn jung blas ihm den Marsch bring ihn in Schwung ich tret ihm in den Arsch!","sourceLineIndex":17,"ipa":"/ɪç hˈalt iːn jˈʊŋ blˈɑːs iːm deːn mˈaɾʃ bɾˈɪŋ iːn ɪn ʃvˈʊŋ ɪç tɾˈeːt iːm ɪn deːn ˈaɾʃ/","en":"I keep him young blow his march get him going I'll kick his ass!","zh":"我让他保持年轻吹响他的行军让他走我会踢他的屁股！","note":""},{"id":"rebecca-das-musical-18-021","lineIndex":14,"speaker":"","original":"Denn sehn Sie:","sourceLineIndex":21,"ipa":"/dɛn zˈeːn ziː/","en":"Because you see:","zh":"因为你看到：","note":""},{"id":"rebecca-das-musical-18-022","lineIndex":15,"speaker":"","original":"I'm an american woman!","sourceLineIndex":22,"ipa":"/ˈiːm an ˌɑmeːriːkˈɑːn voːmˈɑːn/","en":"I'm an American woman!","zh":"我是美国女人！","note":""},{"id":"rebecca-das-musical-18-023","lineIndex":16,"speaker":"","original":"Ich pfeif auf Geschmack, ich mag es schrill!","sourceLineIndex":23,"ipa":"/ɪç pfˈaɪf aʊf ɡəʃmˈak ɪç mˈɑːk ɛs ʃrˈɪl/","en":"I don't care about taste, I like it shrill!","zh":"我不在乎味道，我喜欢它的尖锐！","note":""},{"id":"rebecca-das-musical-18-024","lineIndex":17,"speaker":"","original":"Ich bin eine Frau für einen Mann, der sich was traut.","sourceLineIndex":24,"ipa":"/ɪç bɪn ˌaɪnə frˈaʊ fyːɾ ˌaɪnən mˈan dɛɾ zɪç vˈas tɾˈaʊt/","en":"I am a woman for a man who dares to do something.","zh":"我是一个敢于做事的男人的女人。","note":""},{"id":"rebecca-das-musical-18-025","lineIndex":18,"speaker":"","original":"Und tut was ich will!","sourceLineIndex":25,"ipa":"/ʊnt tˈuːt vˈas ɪç vɪl/","en":"And does what I want!","zh":"并且做我想做的事！","note":""},{"id":"rebecca-das-musical-18-026","lineIndex":19,"speaker":"","original":"Ich kann, Mr., mit den den Händen knacken ich kann Cookies backen und gewinn beim Bridge.","sourceLineIndex":26,"ipa":"/ɪç kˈan ˌɛmˈɛɾ mɪt deːn deːn hˈɛndən knˈakən ɪç kˌan kˈoːkiːs bˈakən ʊnt ɡəvˈɪn baɪm bɹˈɪdʒ/","en":"I can crack my hands, Mr. I can bake cookies and win at bridge.","zh":"我的手可以裂开，先生。我可以烤饼干并在桥牌上获胜。","note":""},{"id":"rebecca-das-musical-18-028","lineIndex":20,"speaker":"","original":"Ich kann weiter spucken mehr verschlucken lauter lachen.","sourceLineIndex":28,"ipa":"/ɪç kˌan vˈaɪtɜ ʃpˈʊkən mˈeːɾ fɛɾʃlˈʊkən lˈaʊtɜ lˈaxən/","en":"I can keep spitting swallow more laugh louder.","zh":"我可以继续吐口水吞下更多笑得更大声。","note":""},{"id":"rebecca-das-musical-18-031","lineIndex":21,"speaker":"","original":"Ich kann alles, außer einen Fehler machen!","sourceLineIndex":31,"ipa":"/ɪç kˌan ˈaləs ˈaʊsɜ ˌaɪnən fˈeːlɜ mˈaxən/","en":"I can do anything except make a mistake!","zh":"除了犯错误，我什么都可以做！","note":""},{"id":"rebecca-das-musical-18-032","lineIndex":22,"speaker":"","original":"Was ich träum wird wahr, denn ich bin aus den U-S-A!","sourceLineIndex":32,"ipa":"/vˈas ɪç tɾˈɛːʊm vˌɪɾt vˈɑːɾ dɛn ɪç bɪn ˌaʊs deːn ˈuːˈɛsˈɑː/","en":"What I dream comes true because I'm from the U-S-A!","zh":"我的梦想成真了，因为我来自美国！","note":""}],"sourceOrder":18,"displayOrder":9},{"order":19,"id":"19-heut-nacht-verzauber-ich-die-welt-live","title":"Heut Nacht verzauber’ ich die Welt","titleZh":"今晚我将让世界着迷","lines":[{"id":"rebecca-das-musical-19-001","lineIndex":1,"speaker":"","original":"Sternenstaub im Haar","sourceLineIndex":1,"ipa":"/ʃtˈɛɾnənstˌaʊp ɪm hˈɑːɾ/","en":"Stardust in your hair","zh":"发间缀满星辰碎屑","note":""},{"id":"rebecca-das-musical-19-002","lineIndex":2,"speaker":"","original":"Märchen oder wahr","sourceLineIndex":2,"ipa":"/mˈɛːɾçən ˌoːdɜ vˈɑːɾ/","en":"Fairy tale or true","zh":"恍若童话般真切","note":""},{"id":"rebecca-das-musical-19-003","lineIndex":3,"speaker":"","original":"Ich seh' mich an und kann's kaum glauben","sourceLineIndex":3,"ipa":"/ɪç zˈeː mɪç an ʊnt kˈans kˈaʊm ɡlˈaʊbən/","en":"I look at myself and can hardly believe it","zh":"凝望镜中人难以置信的容颜","note":""},{"id":"rebecca-das-musical-19-004","lineIndex":4,"speaker":"","original":"Diese Frau im Spiegel","sourceLineIndex":4,"ipa":"/dˌiːzə frˈaʊ ɪm ʃpˈiːɡəl/","en":"That woman in the mirror","zh":"这位镜中女子","note":""},{"id":"rebecca-das-musical-19-005","lineIndex":5,"speaker":"","original":"Bin das wirklich ich?","sourceLineIndex":5,"ipa":"/bɪn das vˈɪɾklɪç ɪç/","en":"Is that really me?","zh":"可真是我自己？","note":""},{"id":"rebecca-das-musical-19-006","lineIndex":6,"speaker":"","original":"Alle werden nach mir seh'n","sourceLineIndex":6,"ipa":"/ˈalə vˌɛɾdən nɑːx miːɾ zˈeːn/","en":"Everyone will look after me","zh":"所有人都将注视着我","note":""},{"id":"rebecca-das-musical-19-007","lineIndex":7,"speaker":"","original":"Geheimnisvoll und schön","sourceLineIndex":7,"ipa":"/ɡəhˈaɪmnɪsfˌɔl ʊnt ʃˈøːn/","en":"Mysterious and beautiful","zh":"神秘而优雅动人","note":""},{"id":"rebecca-das-musical-19-008","lineIndex":8,"speaker":"","original":"Werd' ich strahlend in den Ballsaal geh'n","sourceLineIndex":8,"ipa":"/vˈeːɾt ɪç ʃtɾˈɑːlənt ɪn deːn balzˈɑːl ɡˈeːn/","en":"I'll go into the ballroom beaming","zh":"我将璀璨步入舞会厅堂","note":""},{"id":"rebecca-das-musical-19-009","lineIndex":9,"speaker":"","original":"Seht nur da kommt","sourceLineIndex":9,"ipa":"/zˈeːt nˈuːɾ dɑː kˈɔmt/","en":"Just look here it comes","zh":"看啊她来了","note":""},{"id":"rebecca-das-musical-19-010","lineIndex":10,"speaker":"","original":"Die Dame in weiß","sourceLineIndex":10,"ipa":"/diː dˈɑːmə ɪn vˈaɪs/","en":"The lady in white","zh":"那位白衣淑女","note":""},{"id":"rebecca-das-musical-19-011","lineIndex":11,"speaker":"","original":"Und ich schweb' auf Musik","sourceLineIndex":11,"ipa":"/ʊnt ɪç ʃvˈeːp aʊf muːzˈiːk/","en":"And I'm into music","zh":"我随音乐翩然起舞","note":""},{"id":"rebecca-das-musical-19-012","lineIndex":12,"speaker":"","original":"Und ich sehe mich in jedem Blick","sourceLineIndex":12,"ipa":"/ʊnt ɪç zˈeːə mɪç ɪn jˈeːdəm blˈɪk/","en":"And I see myself in every look","zh":"每道目光都映照我的身影","note":""},{"id":"rebecca-das-musical-19-013","lineIndex":13,"speaker":"","original":"Es gibt keinen der mich nicht bewundert","sourceLineIndex":13,"ipa":"/ɛs ɡˈiːpt kˈaɪnən dɛɾ mɪç nˈɪçt bəvˈʊndɜt/","en":"There is no one who doesn't admire me","zh":"无人不为之倾倒","note":""},{"id":"rebecca-das-musical-19-014","lineIndex":14,"speaker":"","original":"Und nichts was mich hält","sourceLineIndex":14,"ipa":"/ʊnt nˈɪçts vˈas mɪç hˈɛlt/","en":"And nothing to hold me","zh":"再无任何束缚","note":""},{"id":"rebecca-das-musical-19-015","lineIndex":15,"speaker":"","original":"Ich bin so wie ich sein will","sourceLineIndex":15,"ipa":"/ɪç bɪn zoː viː ɪç zaɪn vˈɪl/","en":"I am what I want to be","zh":"此刻尽显真我本色","note":""},{"id":"rebecca-das-musical-19-016","lineIndex":16,"speaker":"","original":"Und tu' was mir gefällt","sourceLineIndex":16,"ipa":"/ʊnt tˈuː vˈas miːɾ ɡəfˈɛlt/","en":"And do what I like","zh":"随心而行无所拘束","note":""},{"id":"rebecca-das-musical-19-017","lineIndex":17,"speaker":"","original":"Heut' Nacht verzauber' ich die Welt","sourceLineIndex":17,"ipa":"/hˈɔøt nˈaxt fɛɾtsˈaʊbɜ ɪç diː vˈɛlt/","en":"Tonight I'm enchanting the world","zh":"今夜我要将世界施以魔法","note":""},{"id":"rebecca-das-musical-19-018","lineIndex":18,"speaker":"","original":"Heut' glaub ich dass mich jeder mag","sourceLineIndex":18,"ipa":"/hˈɔøt ɡlˈaʊp ɪç das mɪç jˈeːdɜ mˈɑːk/","en":"Nowadays I think everyone likes me","zh":"此刻深信众人皆爱我","note":""},{"id":"rebecca-das-musical-19-019","lineIndex":19,"speaker":"","original":"Ganz egal was ich auch tu' und sag'","sourceLineIndex":19,"ipa":"/ɡˌants eːɡˈɑːl vˈas ɪç ˌaʊx tˈuː ʊnt zˈɑːk/","en":"No matter what I do and say","zh":"无论言行皆得眷顾","note":""},{"id":"rebecca-das-musical-19-020","lineIndex":20,"speaker":"","original":"Dies ist mein Tag ein Traum","sourceLineIndex":20,"ipa":"/diːs ɪst maɪn tˈɑːk aɪn tɾˈaʊm/","en":"This is my day a dream","zh":"今日如梦似幻","note":""},{"id":"rebecca-das-musical-19-021","lineIndex":21,"speaker":"","original":"Wird heute wahr!","sourceLineIndex":21,"ipa":"/vˌɪɾt hˈɔøtə vˈɑːɾ/","en":"Comes true today!","zh":"终成现实！","note":""},{"id":"rebecca-das-musical-19-022","lineIndex":22,"speaker":"","original":"Denn ich schweb' auf Musik","sourceLineIndex":22,"ipa":"/dɛn ɪç ʃvˈeːp aʊf muːzˈiːk/","en":"Because I'm into music","zh":"因我随音乐翩然起舞","note":""},{"id":"rebecca-das-musical-19-023","lineIndex":23,"speaker":"","original":"Und ich sehe mich in jedem Blick","sourceLineIndex":23,"ipa":"/ʊnt ɪç zˈeːə mɪç ɪn jˈeːdəm blˈɪk/","en":"And I see myself in every look","zh":"每道目光都映照我的身影","note":""},{"id":"rebecca-das-musical-19-024","lineIndex":24,"speaker":"","original":"Es gibt keinen der mich nicht bewundert","sourceLineIndex":24,"ipa":"/ɛs ɡˈiːpt kˈaɪnən dɛɾ mɪç nˈɪçt bəvˈʊndɜt/","en":"There is no one who doesn't admire me","zh":"无人不为之倾倒","note":""},{"id":"rebecca-das-musical-19-025","lineIndex":25,"speaker":"","original":"Und nichts was mich hält","sourceLineIndex":25,"ipa":"/ʊnt nˈɪçts vˈas mɪç hˈɛlt/","en":"And nothing to hold me","zh":"再无任何束缚","note":""},{"id":"rebecca-das-musical-19-026","lineIndex":26,"speaker":"","original":"Einmal im Leben","sourceLineIndex":26,"ipa":"/ˈaɪnmˌɑːl ɪm lˈeːbən/","en":"Once in a lifetime","zh":"此生唯此一刻","note":""},{"id":"rebecca-das-musical-19-027","lineIndex":27,"speaker":"","original":"Bin ich wie's mir gefällt","sourceLineIndex":27,"ipa":"/bɪn ɪç vˈiːs miːɾ ɡəfˈɛlt/","en":"I am as I like it","zh":"纵情活出真我","note":""},{"id":"rebecca-das-musical-19-028","lineIndex":28,"speaker":"","original":"Heut' Nacht verzauber' ich die Welt","sourceLineIndex":28,"ipa":"/hˈɔøt nˈaxt fɛɾtsˈaʊbɜ ɪç diː vˈɛlt/","en":"Tonight I'm enchanting the world","zh":"今夜我要将世界施以魔法","note":""}],"sourceOrder":19,"displayOrder":10},{"order":22,"id":"22-nur-ein-schritt-live","title":"Nur ein Schritt","titleZh":"一步之遥","lines":[{"id":"rebecca-das-musical-22-001","lineIndex":1,"speaker":"","original":"Nur ein Schritt","sourceLineIndex":1,"ipa":"/nˈuːɾ aɪn ʃrˈɪt/","en":"Just one step","zh":"只需一步","note":""},{"id":"rebecca-das-musical-22-002","lineIndex":2,"speaker":"","original":"Von hier zur Ewigkeit","sourceLineIndex":2,"ipa":"/fɔn hˈiːɾ tsuːɾ ˈeːvɪçkˌaɪt/","en":"From here to eternity","zh":"从这里到永恒","note":""},{"id":"rebecca-das-musical-22-003","lineIndex":3,"speaker":"","original":"Tief unter dir rollt und rauscht das Meer","sourceLineIndex":3,"ipa":"/tˈiːf ˌʊntɜ diːɾ rˈɔlt ʊnt rˈaʊʃt das mˈeːɾ/","en":"Deep below you the sea rolls and roars","zh":"在你的深处，大海翻滚咆哮","note":""},{"id":"rebecca-das-musical-22-004","lineIndex":4,"speaker":"","original":"Du wirst nie glücklich werden","sourceLineIndex":4,"ipa":"/duː vˌɪɾst nˈiː ɡlˈʏklɪç vˌɛɾdən/","en":"You will never be happy","zh":"你永远不会幸福","note":""},{"id":"rebecca-das-musical-22-005","lineIndex":5,"speaker":"","original":"Niemand braucht dich hier","sourceLineIndex":5,"ipa":"/nˈiːmant bɾˈaʊxt dɪç hˈiːɾ/","en":"Nobody needs you here","zh":"这里没有人需要你","note":""},{"id":"rebecca-das-musical-22-006","lineIndex":6,"speaker":"","original":"Du bist eine Last für Mr. De Winter","sourceLineIndex":6,"ipa":"/duː bɪst ˌaɪnə lˈast fyːɾ ˌɛmˈɛɾ dˈeː vˈɪntɜ/","en":"You're a burden to Mr. De Winter","zh":"你是德温特先生的负担","note":""},{"id":"rebecca-das-musical-22-007","lineIndex":7,"speaker":"","original":"Spring!","sourceLineIndex":7,"ipa":"/ʃpɾˈɪŋ/","en":"Jump!","zh":"跳！","note":""},{"id":"rebecca-das-musical-22-008","lineIndex":8,"speaker":"","original":"Statt ihr gehörst du in die Friedhofsgruft","sourceLineIndex":8,"ipa":"/ʃtˈat iːɾ ɡəhˈøːɾst duː ɪn diː frˈiːthɔfsɡɾˌʊft/","en":"Instead of her, you belong in the cemetery crypt","zh":"你不属于她，属于墓地的地下室","note":""},{"id":"rebecca-das-musical-22-009","lineIndex":9,"speaker":"","original":"Es wäre besser für ihn und für dich","sourceLineIndex":9,"ipa":"/ɛs vˈɛːrə bˈɛsɜ fyːɾ iːn ʊnt fyːɾ dˈɪç/","en":"It would be better for him and for you","zh":"这对他和你都更好","note":""},{"id":"rebecca-das-musical-22-010","lineIndex":10,"speaker":"","original":"Mach Schluss!","sourceLineIndex":10,"ipa":"/mˈax ʃlˈʊs/","en":"Stop it!","zh":"停下来！","note":""},{"id":"rebecca-das-musical-22-011","lineIndex":11,"speaker":"","original":"Ihr habt es beide besser nicht verdient!","sourceLineIndex":11,"ipa":"/iːɾ hˈɑːpt ɛs bˈaɪdə bˈɛsɜ nˈɪçt fɛɾdˈiːnt/","en":"You both better not deserve it!","zh":"你们俩最好都不值得！","note":""},{"id":"rebecca-das-musical-22-012","lineIndex":12,"speaker":"","original":"Ein Schritt geübt!","sourceLineIndex":12,"ipa":"/aɪn ʃrˈɪt ɡəˈyːpt/","en":"One step practiced!","zh":"一步一练！","note":""},{"id":"rebecca-das-musical-22-013","lineIndex":13,"speaker":"","original":"Spring!","sourceLineIndex":13,"ipa":"/ʃpɾˈɪŋ/","en":"Jump!","zh":"跳！","note":""}],"sourceOrder":22,"displayOrder":11},{"order":23,"id":"23-strandgut-ensemble-ich-crawley-favell","title":"Strandgut","titleZh":"漂流物","lines":[{"id":"rebecca-das-musical-23-001","lineIndex":1,"speaker":"","original":"Was ist das? Was ist los?","sourceLineIndex":1,"ipa":"/vˈas ɪst das vˈas ɪst lˈoːs/","en":"What is that? What's up?","zh":"什么声音？出什么事了？","note":""},{"id":"rebecca-das-musical-23-002","lineIndex":2,"speaker":"","original":"Raketen. Alarm in der Bucht.","sourceLineIndex":2,"ipa":"/rˈɑkətən alˈaɾm ɪn dɛɾ bˈʊxt/","en":"Rockets. Alarm in the bay.","zh":"是信号弹。海湾的警报。","note":""},{"id":"rebecca-das-musical-23-003","lineIndex":3,"speaker":"","original":"Wahrscheinlich is ein Schiff gestrandet.","sourceLineIndex":3,"ipa":"/vɑːɾʃˈaɪnlɪç ˈiːs aɪn ʃˈɪf ɡəʃtɾˈandət/","en":"A ship is probably stranded.","zh":"很可能是有船只搁浅了。","note":""},{"id":"rebecca-das-musical-23-004","lineIndex":4,"speaker":"","original":"Raketen, ein Schiff gestrandet am Riff","sourceLineIndex":4,"ipa":"/rˈɑkətən aɪn ʃˈɪf ɡəʃtɾˈandət am rˈɪf/","en":"Missiles, a ship stranded on the reef","zh":"警报！有艘船搁浅在海滩","note":""},{"id":"rebecca-das-musical-23-005","lineIndex":5,"speaker":"","original":"Da drüben der Bug, ein Licht.","sourceLineIndex":5,"ipa":"/dɑː dɾˈyːbən dɛɾ bˈuːk aɪn lˈɪçt/","en":"Over there the bow, a light.","zh":"船首上灯火闪烁。","note":""},{"id":"rebecca-das-musical-23-006","lineIndex":6,"speaker":"","original":"Sie haben die Bucht mit dem Hafen verwechselt","sourceLineIndex":6,"ipa":"/ziː hˌɑːbən diː bˈʊxt mɪt deːm hˈɑːfən fɛɾvˈɛksəlt/","en":"You confused the bay with the harbor","zh":"他们把海湾 错认成港口","note":""},{"id":"rebecca-das-musical-23-007","lineIndex":7,"speaker":"","original":"Der Nebel war wieder sehr dicht","sourceLineIndex":7,"ipa":"/dɛɾ nˈeːbəl vɑːɾ vˈiːdɜ zˈeːɾ dˈɪçt/","en":"The fog was very thick again","zh":"海面上浓雾漫漫。","note":""},{"id":"rebecca-das-musical-23-008","lineIndex":8,"speaker":"","original":"Der Flagge nach, ein französisches Schiff","sourceLineIndex":8,"ipa":"/dɛɾ flˈaɡə nˈɑːx aɪn frantsˈøːzɪʃəs ʃˈɪf/","en":"According to the flag, a French ship","zh":"遇难船只挂着法国旗帜","note":""},{"id":"rebecca-das-musical-23-009","lineIndex":9,"speaker":"","original":"Sitzt fest und kommt nicht mehr weg","sourceLineIndex":9,"ipa":"/zˈɪtst fˈɛst ʊnt kˈɔmt nˈɪçt mˌeːɾ vˈɛk/","en":"Sits tight and can't get away","zh":"困在礁石间动弹不得","note":""},{"id":"rebecca-das-musical-23-010","lineIndex":10,"speaker":"","original":"Der Rumpf ist geborsten und Bald wird es sinken das Wasser läuft schon übers Deck!","sourceLineIndex":10,"ipa":"/dɛɾ rˈʊmpf ɪst ɡəbˈoːɾstən ʊnt bˈalt vˌɪɾt ɛs zˈɪŋkən das vˈasɜ lˈɔøft ʃˌoːn ˌyːbɜs dˈɛk/","en":"The hull has burst and soon it will sink the water is already running over the deck!","zh":"船身破裂，倾覆在即水已漫上了甲板！","note":""},{"id":"rebecca-das-musical-23-012","lineIndex":11,"speaker":"","original":"Maxim!","sourceLineIndex":12,"ipa":"/mˈaksiːm/","en":"Max!","zh":"马克西姆！","note":""},{"id":"rebecca-das-musical-23-013","lineIndex":12,"speaker":"","original":"Hey ho, verteilt Euch der Preis ist es wert","sourceLineIndex":13,"ipa":"/hˈaɪ hˈoː fɛɾtˈaɪlt ɔøç dɛɾ pɾˈaɪs ɪst ɛs vˈɛɾt/","en":"Hey ho, spread it out, the price is worth it","zh":"嘿嚄，好运来了！剥下的救生衣","note":""},{"id":"rebecca-das-musical-23-014","lineIndex":13,"speaker":"","original":"Die Schwimmwesten übergestreift.","sourceLineIndex":14,"ipa":"/diː ʃvˈɪmvəstən ˌyːbɜɡəʃtɾˈaɪft/","en":"Put on the life jackets.","zh":"价钱可不便宜！","note":""},{"id":"rebecca-das-musical-23-015","lineIndex":14,"speaker":"","original":"Hey ho, beeilt Euch das Strandgut gehört","sourceLineIndex":15,"ipa":"/hˈaɪ hˈoː bəˈaɪlt ɔøç das ʃtɾˈandɡuːt ɡəhˈœɾt/","en":"Hey ho, hurry up the flotsam belongs","zh":"嘿嚄，赶快上啊！冲上岸的东西","note":""},{"id":"rebecca-das-musical-23-016","lineIndex":15,"speaker":"","original":"Dem der zuerst danach greift.","sourceLineIndex":16,"ipa":"/deːm dɛɾ tsuːˈeːɾst danˈax ɡɾˈaɪft/","en":"Whoever grabs it first.","zh":"谁捡到就归谁！","note":""},{"id":"rebecca-das-musical-23-017","lineIndex":16,"speaker":"","original":"Frank! Wo ist Maxim?","sourceLineIndex":17,"ipa":"/frˈaŋk vˌoː ɪst mˈaksiːm/","en":"Frank! Where is Maxim?","zh":"弗兰克！马克西姆在哪儿？","note":""},{"id":"rebecca-das-musical-23-018","lineIndex":17,"speaker":"","original":"Sicher mit einem der Boote hinausgefahren!","sourceLineIndex":18,"ipa":"/zˈɪçɜ mɪt ˌaɪnəm dɛɾ bˈoːtə hɪnˈaʊsɡəfˌɑːrən/","en":"Went out safely on one of the boats!","zh":"一定是在那些小船上！","note":""},{"id":"rebecca-das-musical-23-019","lineIndex":18,"speaker":"","original":"Er ist immer unter den ersten, wenn Not am Mann ist!","sourceLineIndex":19,"ipa":"/ɛɾ ɪst ˈɪmɜ ˌʊntɜ deːn ˈeːɾstən vˌɛn nˈoːt am mˈan ɪst/","en":"He is always among the first when there is a need!","zh":"别人有难时，他总是第一个伸出援助之手！","note":""},{"id":"rebecca-das-musical-23-020","lineIndex":19,"speaker":"","original":"Hey ho, ans Ruder ein Schiff ist in Not","sourceLineIndex":20,"ipa":"/hˈaɪ hˈoː ans rˈuːdɜ aɪn ʃˈɪf ɪst ɪn nˈoːt/","en":"Hey ho, at the helm a ship is in distress","zh":"嘿嚄，用力划船！有船遇难","note":""},{"id":"rebecca-das-musical-23-021","lineIndex":20,"speaker":"","original":"Rettet was treibt in der Flut!","sourceLineIndex":21,"ipa":"/rˈɛtət vˈas tɾˈaɪpt ɪn dɛɾ flˈuːt/","en":"Save what is floating in the flood!","zh":"快抢救落水财物！","note":""},{"id":"rebecca-das-musical-23-022","lineIndex":21,"speaker":"","original":"Wenn ihm nur nichts zustößt!!","sourceLineIndex":22,"ipa":"/vˌɛn iːm nˈuːɾ nˈɪçts tsuːʃtˈœst/","en":"If only nothing happens to him!!","zh":"他可别出什么意外！","note":""},{"id":"rebecca-das-musical-23-023","lineIndex":22,"speaker":"","original":"Kein Sorge! Das Meer ist hier kaum tiefer als ein Ententeich!","sourceLineIndex":23,"ipa":"/kˈaɪn zˈɔɾɡə das mˈeːɾ ɪst hˈiːɾ kˈaʊm tˈiːfɜ als aɪn ˈɛntəntˌaɪç/","en":"Don't worry! The sea here is hardly deeper than a duck pond!","zh":"不用担心！这边的海水不会比养鸭塘更深！","note":""},{"id":"rebecca-das-musical-23-024","lineIndex":23,"speaker":"","original":"Mr. Favell.","sourceLineIndex":24,"ipa":"/ˌɛmˈɛɾ favˈɛl/","en":"Mr Favell.","zh":"法维尔先生？","note":""},{"id":"rebecca-das-musical-23-025","lineIndex":24,"speaker":"","original":"Freut mich, dass Sie sich an mich erinnern Mrs. De Winter!","sourceLineIndex":25,"ipa":"/frˈɔøt mɪç das ziː zɪç an mɪç ɛɾˈɪnɜn ˌɛmˌɛrˈɛs dˈeː vˈɪntɜ/","en":"I'm glad you remember me, Mrs. De Winter!","zh":"我很荣幸，您还记得我，德温特夫人！","note":""},{"id":"rebecca-das-musical-23-026","lineIndex":25,"speaker":"","original":"Was machen Sie hier?","sourceLineIndex":26,"ipa":"/vˈas mˈaxən ziː hˈiːɾ/","en":"What are you doing here?","zh":"您在这里做什么？","note":""},{"id":"rebecca-das-musical-23-027","lineIndex":26,"speaker":"","original":"Ich liebe Katastrophen.","sourceLineIndex":27,"ipa":"/ɪç lˈiːbə kˈɑtastɾˌoːfən/","en":"I love disasters.","zh":"我喜爱灾难。","note":""},{"id":"rebecca-das-musical-23-028","lineIndex":27,"speaker":"","original":"Es macht mir Spaß dem Unglück von anderen zuzuschauen!","sourceLineIndex":28,"ipa":"/ɛs mˈaxt miːɾ ʃpˈɑːs deːm ˈʊnɡlˌʏk fɔn ˈandərən tsuːtsuːʃˈaʊən/","en":"I enjoy watching other people's misfortune!","zh":"看他人遭遇不幸别有一番乐趣！","note":""},{"id":"rebecca-das-musical-23-029","lineIndex":28,"speaker":"","original":"Hey ho, ihr Leute, dass keiner sich schont","sourceLineIndex":29,"ipa":"/hˈaɪ hˈoː iːɾ lˈɔøtə das kˈaɪnɜ zɪç ʃˈɔnt/","en":"Hey ho, you people, no one spares themselves","zh":"嘿嚄，伙计们！遇到今早的好事","note":""},{"id":"rebecca-das-musical-23-030","lineIndex":29,"speaker":"","original":"An einem Morgen wie heut","sourceLineIndex":30,"ipa":"/an ˌaɪnəm mˈɔɾɡən viː hˈɔøt/","en":"On a morning like today","zh":"任谁都会奋不顾身！","note":""},{"id":"rebecca-das-musical-23-031","lineIndex":30,"speaker":"","original":"Hey ho, macht Beute das Strandgut belohnt","sourceLineIndex":31,"ipa":"/hˈaɪ hˈoː mˈaxt bˈɔøtə das ʃtɾˈandɡuːt bəlˈoːnt/","en":"Hey ho, loot rewards flotsam and jetsam","zh":"嘿嚄，战利品！只要全力以赴","note":""},{"id":"rebecca-das-musical-23-032","lineIndex":31,"speaker":"","original":"Den der die Mühe nicht scheut","sourceLineIndex":32,"ipa":"/deːn dɛɾ diː mˈyːə nˈɪçt ʃˈɔøt/","en":"The one who doesn't shy away from the effort","zh":"就不会白忙一场！","note":""},{"id":"rebecca-das-musical-23-033","lineIndex":32,"speaker":"","original":"Die Beamten vom Wachboot sind draußen am Schiff","sourceLineIndex":33,"ipa":"/diː bəˈamtən fɔm vˈaxboːt zɪnt dɾˈaʊsən am ʃˈɪf/","en":"The officers from the guard boat are outside the ship","zh":"巡逻艇的警官们到了船上","note":""},{"id":"rebecca-das-musical-23-034","lineIndex":33,"speaker":"","original":"Und ein Taucher prüft grade das Leck.","sourceLineIndex":34,"ipa":"/ʊnt aɪn tˈaʊxɜ pɾˈyːft ɡɾˈɑːdə das lˈɛk/","en":"And a diver is currently checking the leak.","zh":"派人潜水下去检查裂缝。","note":""},{"id":"rebecca-das-musical-23-035","lineIndex":34,"speaker":"","original":"So ist es Recht tausend Jahre lang schon","sourceLineIndex":35,"ipa":"/zoː ɪst ɛs rˈɛçt tˈaʊzənt jˈɑːrə lˈaŋ ʃˈoːn/","en":"It's been that way for almost a thousand years","zh":"千百年来这都是不变的真理","note":""},{"id":"rebecca-das-musical-23-036","lineIndex":35,"speaker":"","original":"Strandgut ist Handgut und frei!","sourceLineIndex":36,"ipa":"/ʃtɾˈandɡuːt ɪst hˈantɡˌuːt ʊnt frˈaɪ/","en":"Flotsam and jetsam is hand-held and free!","zh":"谁先捡到就归谁！","note":""},{"id":"rebecca-das-musical-23-037","lineIndex":36,"speaker":"","original":"Bedaure, wieder nur ich!","sourceLineIndex":37,"ipa":"/bədˈaʊrə vˈiːdɜ nˈuːɾ ɪç/","en":"Sorry, just me again!","zh":"很遗憾，又是我！","note":""},{"id":"rebecca-das-musical-23-038","lineIndex":37,"speaker":"","original":"Aber ich bringe Neuigkeiten!","sourceLineIndex":38,"ipa":"/ˌɑːbɜ ɪç bɾˈɪŋə nˈɔøɪçkˌaɪtən/","en":"But I bring news!","zh":"不过我带来了有趣的消息！","note":""},{"id":"rebecca-das-musical-23-039","lineIndex":38,"speaker":"","original":"Der Bericht des Tauchers liegt vor.","sourceLineIndex":39,"ipa":"/dɛɾ bərˈɪçt dɛs tˈaʊxɜs lˈiːkt fˈɔɾ/","en":"The diver's report is available.","zh":"潜水员的报告已经出来了。","note":""},{"id":"rebecca-das-musical-23-040","lineIndex":39,"speaker":"","original":"Ich suche meinen Mann.","sourceLineIndex":40,"ipa":"/ɪç zˈuːxə mˌaɪnən mˈan/","en":"I'm looking for my husband.","zh":"我在找我的丈夫。","note":""},{"id":"rebecca-das-musical-23-041","lineIndex":40,"speaker":"","original":"Der Bericht des Tauchers interessiert mich nicht!","sourceLineIndex":41,"ipa":"/dɛɾ bərˈɪçt dɛs tˈaʊxɜs ˌɪntərɛsˈiːɾt mɪç nˈɪçt/","en":"I'm not interested in the diver's report!","zh":"我对潜水员的报告没兴趣！","note":""},{"id":"rebecca-das-musical-23-042","lineIndex":41,"speaker":"","original":"Das sollte er aber!","sourceLineIndex":42,"ipa":"/das zˌɔltə ɛɾ ˈɑːbɜ/","en":"But he should!","zh":"您应该感兴趣的！","note":""},{"id":"rebecca-das-musical-23-043","lineIndex":42,"speaker":"","original":"Als der Mann da unten den Kiel untersuchte entdeckte er ein Wrack am Meeresboden.","sourceLineIndex":43,"ipa":"/als dɛɾ mˈan dɑː ˈʊntən deːn kˈiːl ˌʊntɜzˈuːxtə ɛntdˈɛktə ɛɾ aɪn vrˈak am mˈeːrɛsbˌoːdən/","en":"When the man down there examined the keel he discovered a wreck on the seabed.","zh":"那个人在水下检查船的龙骨时，发现海底有一艘沉船","note":""},{"id":"rebecca-das-musical-23-044","lineIndex":43,"speaker":"","original":"Das Segelboot von Rebecca.—","sourceLineIndex":44,"ipa":"/das zˈeːɡəlbˌoːt fɔn reːbˈɛkɑː/","en":"Rebecca's sailboat.—","zh":"丽贝卡的帆船","note":""},{"id":"rebecca-das-musical-23-045","lineIndex":44,"speaker":"","original":"Oh Gott.","sourceLineIndex":45,"ipa":"/ˈoː ɡˈɔt/","en":"Oh god.","zh":"上帝啊！","note":""},{"id":"rebecca-das-musical-23-046","lineIndex":45,"speaker":"","original":"Ich muss Maxim finden bevor er davon hört!","sourceLineIndex":46,"ipa":"/ɪç mˈʊs mˈaksiːm fˈɪndən bəfˈoːɾ ɛɾ dɑːfˈɔn hˈœɾt/","en":"I have to find Maxim before he hears about this!","zh":"我必须赶在马克西姆得知这消息之前找到他！","note":""},{"id":"rebecca-das-musical-23-047","lineIndex":46,"speaker":"","original":"Warten Sie, das ist noch nicht alles!","sourceLineIndex":47,"ipa":"/vˈaɾtən ziː das ɪst nˈɔx nˈɪçt ˈaləs/","en":"Wait, that's not all!","zh":"先别急，我还没讲完！","note":""},{"id":"rebecca-das-musical-23-048","lineIndex":47,"speaker":"","original":"Auf dem Kabinenboden liegt eine Leiche.","sourceLineIndex":48,"ipa":"/aʊf deːm kˈɑbiːnˌɛnboːdən lˈiːkt ˌaɪnə lˈaɪçə/","en":"There is a body on the cabin floor.","zh":"船舱里面躺着一具尸体……","note":""},{"id":"rebecca-das-musical-23-049","lineIndex":48,"speaker":"","original":"Eine Leiche?","sourceLineIndex":49,"ipa":"/ˌaɪnə lˈaɪçə/","en":"A corpse?","zh":"一具尸体？","note":""},{"id":"rebecca-das-musical-23-050","lineIndex":49,"speaker":"","original":"Ja. Gruselig, was?","sourceLineIndex":50,"ipa":"/jˈɑː ɡɾˈuːzeːlˌɪç vˈas/","en":"Yes. Creepy, huh?","zh":"没错。毛骨悚然，不是吗？","note":""},{"id":"rebecca-das-musical-23-051","lineIndex":50,"speaker":"","original":"Hey ho, verteilt Euch, das Schiff ist zerstört, (Jemand kriegt jetzt einigen Ärger, )","sourceLineIndex":51,"ipa":"/hˈaɪ hˈoː fɛɾtˈaɪlt ˈɔøç das ʃˈɪf ɪst tsɛɾʃtˈœɾt jˈeːmant kɾˈiːkt jˌɛtst ˈaɪnɪɡən ˈɛɾɡɜ/","en":"Hey ho, spread out, the ship is destroyed (Someone's going to get in some trouble now)","zh":"嘿嚄，好运来了！有船遇难，（这下子有人碰到麻烦了，）","note":""},{"id":"rebecca-das-musical-23-052","lineIndex":51,"speaker":"","original":"Es hat einen Felsen gestreift, (Schicksal nimm deinen Lauf.)","sourceLineIndex":52,"ipa":"/ɛs hat ˌaɪnən fˈɛlzən ɡəʃtɾˈaɪft ʃˈɪkzɑːl nˈɪm dˌaɪnən lˈaʊf/","en":"It hit a rock, (Fate takes its course.)","zh":"碰上了海中礁石，（冥冥之中自有天道！）","note":""},{"id":"rebecca-das-musical-23-053","lineIndex":52,"speaker":"","original":"Hey ho beeilt Euch, das Strandgut gehört, (Für ihn wird es jetzt unangenehm.)","sourceLineIndex":53,"ipa":"/hˈaɪ hˈoː bəˈaɪlt ˈɔøç das ʃtɾˈandɡuːt ɡəhˈœɾt fyːɾ iːn vˌɪɾt ɛs jˌɛtst ˈʊnanɡənˌeːm/","en":"Hey ho, hurry up, the flotsam belongs (It's getting uncomfortable for him now.)","zh":"嘿嚄，赶快上啊！冲上岸的东西，（他痛苦折磨的开始，）","note":""},{"id":"rebecca-das-musical-23-054","lineIndex":53,"speaker":"","original":"Dem der zuerst danach greift. (Ich aber freu mich drauf.)","sourceLineIndex":54,"ipa":"/deːm dɛɾ tsuːˈeːɾst danˈax ɡɾˈaɪft ɪç ˌɑːbɜ frˈɔø mɪç dɾˈaʊf/","en":"Whoever grabs it first. (But I'm looking forward to it.)","zh":"谁捡到就归谁！（却是我的好运来到！）","note":""},{"id":"rebecca-das-musical-23-055","lineIndex":54,"speaker":"","original":"Strandgut ist Handgut, holt es ein","sourceLineIndex":55,"ipa":"/ʃtɾˈandɡuːt ɪst hˈantɡˌuːt hˈɔlt ɛs ˈaɪn/","en":"Flotsam is flotsam, collect it","zh":"谁先捡到就归谁，别犹豫！","note":""},{"id":"rebecca-das-musical-23-056","lineIndex":55,"speaker":"","original":"Strandgut ist Handgut, bringt es rein","sourceLineIndex":56,"ipa":"/ʃtɾˈandɡuːt ɪst hˈantɡˌuːt bɾˈɪŋt ɛs rˈaɪn/","en":"Flotsam is handicap, bring it in","zh":"谁先捡到就归谁，揣进兜！","note":""},{"id":"rebecca-das-musical-23-057","lineIndex":56,"speaker":"","original":"Strandgut ist Handgut, tragt es Heim","sourceLineIndex":57,"ipa":"/ʃtɾˈandɡuːt ɪst hˈantɡˌuːt tɾˈɑːkt ɛs hˈaɪm/","en":"Flotsam is handicap, carry it home","zh":"谁先捡到就归谁，带回家！","note":""},{"id":"rebecca-das-musical-23-058","lineIndex":57,"speaker":"","original":"Strandgut ist Handgut","sourceLineIndex":58,"ipa":"/ʃtɾˈandɡuːt ɪst hˈantɡˌuːt/","en":"Flotsam and jetsam is handicraft","zh":"谁先捡到就归谁！","note":""},{"id":"rebecca-das-musical-23-059","lineIndex":58,"speaker":"","original":"Strandgut ist Handgut, holt es ein","sourceLineIndex":59,"ipa":"/ʃtɾˈandɡuːt ɪst hˈantɡˌuːt hˈɔlt ɛs ˈaɪn/","en":"Flotsam is flotsam, collect it","zh":"谁先捡到就归谁，别犹豫！","note":""},{"id":"rebecca-das-musical-23-060","lineIndex":59,"speaker":"","original":"Strandgut ist Handgut, bringt es rein","sourceLineIndex":60,"ipa":"/ʃtɾˈandɡuːt ɪst hˈantɡˌuːt bɾˈɪŋt ɛs rˈaɪn/","en":"Flotsam is handicap, bring it in","zh":"谁先捡到就归谁，揣进兜！","note":""},{"id":"rebecca-das-musical-23-061","lineIndex":60,"speaker":"","original":"Strandgut ist Handgut, tragt es Heim","sourceLineIndex":61,"ipa":"/ʃtɾˈandɡuːt ɪst hˈantɡˌuːt tɾˈɑːkt ɛs hˈaɪm/","en":"Flotsam is handicap, carry it home","zh":"谁先捡到就归谁，带回家！","note":""},{"id":"rebecca-das-musical-23-062","lineIndex":61,"speaker":"","original":"Strandgut ist Handgut","sourceLineIndex":62,"ipa":"/ʃtɾˈandɡuːt ɪst hˈantɡˌuːt/","en":"Flotsam and jetsam is handicraft","zh":"谁先捡到就归谁！","note":""},{"id":"rebecca-das-musical-23-063","lineIndex":62,"speaker":"","original":"Strandgut ist Handgut!","sourceLineIndex":63,"ipa":"/ʃtɾˈandɡuːt ɪst hˈantɡˌuːt/","en":"Flotsam is flotsam and jetsam!","zh":"谁先捡到就归谁！","note":""},{"id":"rebecca-das-musical-23-064","lineIndex":63,"speaker":"","original":"Strandgut ist Handgut!","sourceLineIndex":64,"ipa":"/ʃtɾˈandɡuːt ɪst hˈantɡˌuːt/","en":"Flotsam is flotsam and jetsam!","zh":"谁先捡到就归谁！","note":""}],"sourceOrder":23,"displayOrder":12},{"order":24,"id":"24-du-liebst-sie-zu-sehr","title":"Du liebst sie zu sehr","titleZh":"你太爱她了","lines":[{"id":"rebecca-das-musical-24-001","lineIndex":1,"speaker":"","original":"Ich weiß, Maxim","sourceLineIndex":1,"ipa":"/ɪç vˈaɪs mˈaksiːm/","en":"I know, Maxim","zh":"我知道，马克西姆","note":""},{"id":"rebecca-das-musical-24-002","lineIndex":2,"speaker":"","original":"Gegen Rebecca komme ich nicht an","sourceLineIndex":2,"ipa":"/ɡˌeːɡən reːbˈɛkɑː kˈɔmə ɪç nˈɪçt ˈan/","en":"I can't compete with Rebecca","zh":"我怎能比得上丽贝卡呢","note":""},{"id":"rebecca-das-musical-24-003","lineIndex":3,"speaker":"","original":"Sie ist zurückgekehrt","sourceLineIndex":3,"ipa":"/ziː ɪst tsuːrˈʏkɡəkˌeːɾt/","en":"She has returned","zh":"她回来了","note":""},{"id":"rebecca-das-musical-24-004","lineIndex":4,"speaker":"","original":"Mehr denn je sehnst du dich nach Rebecca","sourceLineIndex":4,"ipa":"/mˈeːɾ dɛn jeː zˈeːnst duː dɪç nɑːx reːbˈɛkɑː/","en":"You long for Rebecca more than ever","zh":"你怀念她更胜从前","note":""},{"id":"rebecca-das-musical-24-005","lineIndex":5,"speaker":"","original":"Niemand kann sie dir ersetzen","sourceLineIndex":5,"ipa":"/nˈiːmant kˌan ziː diːɾ ɛɾzˈɛtsən/","en":"Nobody can replace her for you","zh":"无人能将她代替","note":""},{"id":"rebecca-das-musical-24-006","lineIndex":6,"speaker":"","original":"Du wirst immer um sie trauern","sourceLineIndex":6,"ipa":"/duː vˌɪɾst ˈɪmɜ ʊm ziː tɾˈaʊɜn/","en":"You will always mourn her","zh":"你将永远为她哀伤","note":""},{"id":"rebecca-das-musical-24-007","lineIndex":7,"speaker":"","original":"Darum wirst du mir nie gehören","sourceLineIndex":7,"ipa":"/dɑːrˈʊm vˌɪɾst duː miːɾ nˈiː ɡəhˈøːrən/","en":"That's why you'll never be mine","zh":"因此你永远也无法属于我一人","note":""},{"id":"rebecca-das-musical-24-008","lineIndex":8,"speaker":"","original":"Ich werf es dir nicht vor","sourceLineIndex":8,"ipa":"/ɪç vˈɛɾf ɛs diːɾ nˈɪçt fˈɔɾ/","en":"I don't blame you","zh":"我不是在指责你","note":""},{"id":"rebecca-das-musical-24-009","lineIndex":9,"speaker":"","original":"Und ich will dich nicht trennen von Rebecca","sourceLineIndex":9,"ipa":"/ʊnt ɪç vɪl dɪç nˈɪçt tɾˈɛnən fɔn reːbˈɛkɑː/","en":"And I don't want to separate you from Rebecca","zh":"也没要求你忘记丽贝卡","note":""},{"id":"rebecca-das-musical-24-010","lineIndex":10,"speaker":"","original":"Du musst mich gar nicht lieben","sourceLineIndex":10,"ipa":"/duː mˈʊst mɪç ɡˌɑːɾnˈɪçt lˈiːbən/","en":"You don't have to love me at all","zh":"你根本不必爱我","note":""},{"id":"rebecca-das-musical-24-011","lineIndex":11,"speaker":"","original":"Wenn ich nur bei dir sein kann","sourceLineIndex":11,"ipa":"/vˌɛn ɪç nˈuːɾ baɪ diːɾ zaɪn kˌan/","en":"If only I can be with you","zh":"我只求陪在你身边","note":""},{"id":"rebecca-das-musical-24-012","lineIndex":12,"speaker":"","original":"Um dir Liebe und Trost zu geben","sourceLineIndex":12,"ipa":"/ʊm diːɾ lˈiːbə ʊnt tɾˈoːst tsuː ɡˈeːbən/","en":"To give you love and comfort","zh":"给你爱与慰藉","note":""},{"id":"rebecca-das-musical-24-013","lineIndex":13,"speaker":"","original":"Ich weiß sie lässt dich niemals los","sourceLineIndex":13,"ipa":"/ɪç vˈaɪs ziː lˈɛst dɪç nˈiːmɑːls lˈoːs/","en":"I know she will never let you go","zh":"我知道，她永远在你心头萦绕","note":""},{"id":"rebecca-das-musical-24-014","lineIndex":14,"speaker":"","original":"Du liebst sie zu sehr...","sourceLineIndex":14,"ipa":"/duː lˈiːpst ziː tsuː zˈeːɾ/","en":"You love her too much...","zh":"你是如此地爱她……","note":""},{"id":"rebecca-das-musical-24-015","lineIndex":15,"speaker":"","original":"Zu sehr? Rebecca?","sourceLineIndex":15,"ipa":"/tsuː zˈeːɾ reːbˈɛkɑː/","en":"Too much? Rebecca?","zh":"爱她？丽贝卡？","note":""}],"sourceOrder":24,"displayOrder":13},{"order":33,"id":"33-ich-hab-getraumt-von-manderley-live","title":"Ich hab geträumt von Manderley","titleZh":"我梦见曼德利","lines":[{"id":"rebecca-das-musical-33-001","lineIndex":1,"speaker":"","original":"Ich hab geträumt von Manderley...","sourceLineIndex":1,"ipa":"/ɪç hˈɑːp ɡətɾˈɔømt fɔn mˈandɜlˌaɪ/","en":"I dreamed of Manderley...","zh":"我再一次梦游曼德雷……","note":""},{"id":"rebecca-das-musical-33-002","lineIndex":2,"speaker":"","original":"Modernde Steine und schwarze Fassade So geisterhaft und unnahbar.","sourceLineIndex":2,"ipa":"/mˈoːdɛɾndə ʃtˈaɪnə ʊnt ʃvˈaɾtsə fˈasɑːdə zoː ɡˈaɪstɜhˌaft ʊnt ˈʊnnˌɑːbɑːɾ/","en":"Crumbling stones and a black façade so ghostly and unapproachable.","zh":"石砖精巧，外墙乌黑如幽灵难以接近","note":""},{"id":"rebecca-das-musical-33-004","lineIndex":3,"speaker":"","original":"Schatten der Nacht Vor denen wir flohn Raunen von dem, was war.","sourceLineIndex":4,"ipa":"/ʃˈatən dɛɾ nˈaxt fˌɔɾ deːnən viːɾ flˈoːn rˈaʊnən fɔn deːm vˈas vɑːɾ/","en":"Shadows of the night from which we fled whispering of what once was.","zh":"夜之阴影我们从中逃离幽魂低语仍萦绕耳边","note":""},{"id":"rebecca-das-musical-33-007","lineIndex":4,"speaker":"","original":"Und der Mond scheint hell Und der Fliederduft Ist so süß und sehnsuchtschwer.","sourceLineIndex":7,"ipa":"/ʊnt dɛɾ mˈoːnt ʃˈaɪnt hˈɛl ʊnt dɛɾ flˈiːdɜdˌʊft ɪst zoː zˈyːs ʊnt zˈeːnzuːxtʃvˌeːɾ/","en":"And the moon shines bright and the scent of lilac is so sweet and heavy with longing.","zh":"月光皎洁丁香盛开一切都甜蜜醉人","note":""},{"id":"rebecca-das-musical-33-010","lineIndex":5,"speaker":"","original":"Und wie damals liegt Unheil in der Luft Doch heut schreckt es mich nicht mehr","sourceLineIndex":10,"ipa":"/ʊnt viː dˈɑmɑːls lˈiːkt ˈʊnhˌaɪl ɪn dɛɾ lˈʊft dɔx hˈɔøt ʃrˈɛkt ɛs mɪç nˌɪçt mˈeːɾ/","en":"And as then, there is foreboding in the air but today it no longer frightens me.","zh":"那时灾难笼罩但我如今再也不怕","note":""},{"id":"rebecca-das-musical-33-012","lineIndex":6,"speaker":"","original":"Ich hab geträumt von Manderley Und der vergangenen Zeit.","sourceLineIndex":12,"ipa":"/ɪç hˈɑːp ɡətɾˈɔømt fɔn mˈandɜlˌaɪ ʊnt dɛɾ fɛɾɡˈaŋənən tsˈaɪt/","en":"I dreamed of Manderley and of times long past.","zh":"我再一次梦见曼德雷和过去的时光","note":""},{"id":"rebecca-das-musical-33-014","lineIndex":7,"speaker":"","original":"Von Sehnsucht, Schuld und Dunkelheit Und von Liebe, die befreit.","sourceLineIndex":14,"ipa":"/fɔn zˈeːnzuːxt ʃˈʊlt ʊnt dˈʊnkəlhˌaɪt ʊnt fɔn lˈiːbə diː bəfrˈaɪt/","en":"Of longing, guilt and darkness and of love that sets free.","zh":"欲望，罪恶和黑暗以及拯救我们的爱","note":""},{"id":"rebecca-das-musical-33-016","lineIndex":8,"speaker":"","original":"Und Rebeccas Geist Schwebte unsichtbar Durch das Haus und kam mir nah.","sourceLineIndex":16,"ipa":"/ʊnt rˈeːbɛkˌɑːs ɡˈaɪst ʃvˈeːptə ˈʊnzˌɪçtbɑːɾ dʊɐç das hˈaʊs ʊnt kˌɑːm miːɾ nˈɑː/","en":"And Rebecca's spirit hovered unseen through the house and drew near to me.","zh":"Rebecca的阴魂徘徊无定穿梁越宇，纠缠不放","note":""},{"id":"rebecca-das-musical-33-019","lineIndex":9,"speaker":"","original":"Und da war mir klar","sourceLineIndex":19,"ipa":"/ʊnt dɑː vɑːɾ miːɾ klˈɑːɾ/","en":"And then I understood:","zh":"而我清楚","note":""},{"id":"rebecca-das-musical-33-020","lineIndex":10,"speaker":"","original":"Ich entgeh ihr nur Wenn ich weiß, was hier geschah","sourceLineIndex":20,"ipa":"/ɪç ɛntɡˈeː iːɾ nˈuːɾ vˌɛn ɪç vˈaɪs vˈas hˈiːɾ ɡəʃˈɑː/","en":"I can only escape her if I know what happened here.","zh":"想要逃离她只有了解一切的真相","note":""},{"id":"rebecca-das-musical-33-022","lineIndex":11,"speaker":"","original":"Wir finden Stärke in Gefahr Und Hoffnung in schwerer Zeit.","sourceLineIndex":22,"ipa":"/viːɾ fˈɪndən ʃtˈɛɾkə ɪn ɡəfˈɑːɾ ʊnt hˈɔfnʊŋ ɪn ʃvˈeːrɜ tsˈaɪt/","en":"We find strength in danger and hope in troubled times.","zh":"在危险中，我们找到了力量在逆境中，我们看见了希望","note":""},{"id":"rebecca-das-musical-33-024","lineIndex":12,"speaker":"","original":"Ich hab geträumt von Manderley","sourceLineIndex":24,"ipa":"/ɪç hˈɑːp ɡətɾˈɔømt fɔn mˈandɜlˌaɪ/","en":"I dreamed of Manderley","zh":"我再次梦见曼德雷","note":""},{"id":"rebecca-das-musical-33-025","lineIndex":13,"speaker":"","original":"Und von Liebe, die befreit","sourceLineIndex":25,"ipa":"/ʊnt fɔn lˈiːbə diː bəfrˈaɪt/","en":"and of love that sets free","zh":"以及拯救我们的爱","note":""},{"id":"rebecca-das-musical-33-026","lineIndex":14,"speaker":"","original":"Alles fing in Frankreich an Damals im April 1926.","sourceLineIndex":26,"ipa":"/ˈaləs fˈɪŋ ɪn frˈaŋkɾaɪç an dˈɑmɑːls ɪm apɾˈiːl ˈaɪn tˈaʊzənt nˈɔønhˈʊndɜt zˈɛks ʊnttsvˈantsɪç/","en":"It all began in France back in April 1926.","zh":"这一切都始于法国1926年4月","note":""},{"id":"rebecca-das-musical-33-028","lineIndex":15,"speaker":"","original":"In der Eingangslounge Eines Grandhotels In Monte Carlo...","sourceLineIndex":28,"ipa":"/ɪn dɛɾ ˈaɪnɡˌaŋsluːŋə ˌaɪnəs ɡɾˈanthoːtəls ɪn mˈɔntə kˈaɾloː/","en":"In the entrance lounge of a grand hotel in Monte Carlo...","zh":"一家旅馆的休息室里在蒙特卡洛","note":""}],"sourceOrder":33,"displayOrder":14},{"order":34,"id":"34-rebecca-reprise-i-live","title":"Rebecca - Reprise I","titleZh":"瑞贝卡（重唱 I）","lines":[{"id":"rebecca-das-musical-34-001","lineIndex":1,"speaker":"","original":"Nachts in dem Haus am Meer","sourceLineIndex":1,"ipa":"/nˈaxts ɪn deːm hˈaʊs am mˈeːɾ/","en":"At night in the house by the sea","zh":"晚上在海边的房子里","note":""},{"id":"rebecca-das-musical-34-002","lineIndex":2,"speaker":"","original":"Seufzen die Schatten","sourceLineIndex":2,"ipa":"/zˈɔøftsən diː ʃˈatən/","en":"The shadows sigh","zh":"阴影在叹息","note":""},{"id":"rebecca-das-musical-34-003","lineIndex":3,"speaker":"","original":"Hüte dich, fürchte dich","sourceLineIndex":3,"ipa":"/hˈyːtə dˈɪç fˈʏɾçtə dˈɪç/","en":"Beware, fear","zh":"小心，害怕","note":""},{"id":"rebecca-das-musical-34-004","lineIndex":4,"speaker":"","original":"Denn alle Tür'n sind verboten","sourceLineIndex":4,"ipa":"/dɛn ˈalə tˈyːɾn zɪnt fɛɾbˈoːtən/","en":"Because all doors are forbidden","zh":"因为所有的门都禁止入内","note":""},{"id":"rebecca-das-musical-34-005","lineIndex":5,"speaker":"","original":"Versperrt und bewacht","sourceLineIndex":5,"ipa":"/fɛɾʃpˈɛɾt ʊnt bəvˈaxt/","en":"Locked and guarded","zh":"都上了锁","note":""},{"id":"rebecca-das-musical-34-006","lineIndex":6,"speaker":"","original":"Und wer hier eindringt soll verflucht sein","sourceLineIndex":6,"ipa":"/ʊnt vˈeːɾ hˈiːɾ ˈaɪndɾˌɪŋt zˌɔl fɛɾflˈʊxt zaɪn/","en":"And whoever enters here will be cursed","zh":"进入这里的人都将受到诅咒","note":""},{"id":"rebecca-das-musical-34-007","lineIndex":7,"speaker":"","original":"Und verloren","sourceLineIndex":7,"ipa":"/ʊnt fɛɾlˈoːrən/","en":"And lost","zh":"迷失方向","note":""},{"id":"rebecca-das-musical-34-008","lineIndex":8,"speaker":"","original":"Jeder Raum in diesem Haus atmet Melancholie","sourceLineIndex":8,"ipa":"/jˈeːdɜ rˈaʊm ɪn dˌiːzəm hˈaʊs ˈatmət mˌeːlançoːlˈiː/","en":"Every room in this house breathes melancholy","zh":"这房子里的每个房间都散发着忧郁的气息","note":""},{"id":"rebecca-das-musical-34-009","lineIndex":9,"speaker":"","original":"Alle Dinge hier warten auf sie:","sourceLineIndex":9,"ipa":"/ˈalə dˈɪŋə hˈiːɾ vˈaɾtən aʊf ziː/","en":"All things here are waiting for her:","zh":"这里的一切都在等着她","note":""},{"id":"rebecca-das-musical-34-010","lineIndex":10,"speaker":"","original":"Rebecca, wo du auch immer bist","sourceLineIndex":10,"ipa":"/reːbˈɛkɑː vˌoː duː ˌaʊx ˈɪmɜ bɪst/","en":"Rebecca, wherever you are","zh":"丽贝卡，无论你在哪里","note":""},{"id":"rebecca-das-musical-34-011","lineIndex":11,"speaker":"","original":"Dein Herz ist ruhlos","sourceLineIndex":11,"ipa":"/daɪn hˈɛɾts ɪst rˈuːloːs/","en":"Your heart is restless","zh":"你的心自由不羁","note":""},{"id":"rebecca-das-musical-34-012","lineIndex":12,"speaker":"","original":"Wie die wilde, freie See","sourceLineIndex":12,"ipa":"/viː diː vˈɪldə frˈaɪə zˈeː/","en":"Like the wild, free sea","zh":"就像狂野的大海","note":""},{"id":"rebecca-das-musical-34-013","lineIndex":13,"speaker":"","original":"Wenn der Abend beginnt singt der Wind","sourceLineIndex":13,"ipa":"/vˌɛn dɛɾ ˈɑːbənt bəɡˈɪnt zˈɪŋt dɛɾ vˈɪnt/","en":"When the evening begins the wind sings","zh":"当夜幕降临，狂风呼啸","note":""},{"id":"rebecca-das-musical-34-014","lineIndex":14,"speaker":"","original":"Rebecca, komm heim Rebecca","sourceLineIndex":14,"ipa":"/reːbˈɛkɑː kˈɔm hˈaɪm reːbˈɛkɑː/","en":"Rebecca, come home Rebecca","zh":"丽贝卡，回家吧，丽贝卡","note":""},{"id":"rebecca-das-musical-34-015","lineIndex":15,"speaker":"","original":"Aus dem Nebelreich zurück nach Manderley","sourceLineIndex":15,"ipa":"/ˌaʊs deːm nˈeːbəlrˌaɪç tsuːrˈʏk nɑːx mˈandɜlˌaɪ/","en":"From the Misty Realm back to Manderley","zh":"从迷雾中回到曼德雷","note":""},{"id":"rebecca-das-musical-34-016","lineIndex":16,"speaker":"","original":"Nichts was ihr sagt und tut","sourceLineIndex":16,"ipa":"/nˈɪçts vˈas iːɾ zˈɑːɡt ʊnt tˈuːt/","en":"Nothing you say or do","zh":"你的一言一行","note":""},{"id":"rebecca-das-musical-34-017","lineIndex":17,"speaker":"","original":"Bleibt ihr verborgen","sourceLineIndex":17,"ipa":"/blˈaɪpt iːɾ fɛɾbˈɔɾɡən/","en":"She remains hidden","zh":"都无法对她隐瞒","note":""},{"id":"rebecca-das-musical-34-018","lineIndex":18,"speaker":"","original":"Hüte dich, fürchte dich","sourceLineIndex":18,"ipa":"/hˈyːtə dˈɪç fˈʏɾçtə dˈɪç/","en":"Beware, fear","zh":"当心，害怕","note":""},{"id":"rebecca-das-musical-34-019","lineIndex":19,"speaker":"","original":"Sie lässt sich nicht bestehlen","sourceLineIndex":19,"ipa":"/ziː lˈɛst zɪç nˈɪçt bəʃtˈeːlən/","en":"She won't let herself be stolen from","zh":"她不会被抢走","note":""},{"id":"rebecca-das-musical-34-020","lineIndex":20,"speaker":"","original":"Und rächt den Verrat","sourceLineIndex":20,"ipa":"/ʊnt rˈɛçt deːn fɛɾrˈɑːt/","en":"And avenge the betrayal","zh":"报复背叛","note":""},{"id":"rebecca-das-musical-34-021","lineIndex":21,"speaker":"","original":"Wer sie beleidigt wird es eines Tages büßen","sourceLineIndex":21,"ipa":"/vˈeːɾ ziː bəlˈaɪdɪçt vˌɪɾt ɛs ˌaɪnəs tˈɑːɡəs bˈyːsən/","en":"Anyone who insults her will pay for it one day","zh":"冒犯她的人总有一天会付出代价","note":""},{"id":"rebecca-das-musical-34-022","lineIndex":22,"speaker":"","original":"Dieses Haus ist ihr zu Haus","sourceLineIndex":22,"ipa":"/dˌiːzəs hˈaʊs ɪst iːɾ tsuː hˈaʊs/","en":"This house is her home","zh":"这房子就是她的家","note":""},{"id":"rebecca-das-musical-34-023","lineIndex":23,"speaker":"","original":"Alles wartet auf sie","sourceLineIndex":23,"ipa":"/ˈaləs vˈaɾtət aʊf ziː/","en":"Everything is waiting for her","zh":"一切都在等着她","note":""},{"id":"rebecca-das-musical-34-024","lineIndex":24,"speaker":"","original":"Die sie liebten vergessen sie nie:","sourceLineIndex":24,"ipa":"/diː ziː lˈiːptən fɛɾɡˈɛsən ziː nˈiː/","en":"Those who loved her never forget her.","zh":"爱她的人永远不会忘记她","note":""},{"id":"rebecca-das-musical-34-025","lineIndex":25,"speaker":"","original":"Rebecca, wo du auch immer bist","sourceLineIndex":25,"ipa":"/reːbˈɛkɑː vˌoː duː ˌaʊx ˈɪmɜ bɪst/","en":"Rebecca, wherever you are","zh":"丽贝卡，无论你身在何处","note":""},{"id":"rebecca-das-musical-34-026","lineIndex":26,"speaker":"","original":"Dein Herz ist ruhlos","sourceLineIndex":26,"ipa":"/daɪn hˈɛɾts ɪst rˈuːloːs/","en":"Your heart is restless","zh":"你的心自由不羁","note":""},{"id":"rebecca-das-musical-34-027","lineIndex":27,"speaker":"","original":"Wie die wilde, freie See","sourceLineIndex":27,"ipa":"/viː diː vˈɪldə frˈaɪə zˈeː/","en":"Like the wild, free sea","zh":"就像狂野的大海","note":""},{"id":"rebecca-das-musical-34-028","lineIndex":28,"speaker":"","original":"Wenn der Abend beginnt singt der Wind","sourceLineIndex":28,"ipa":"/vˌɛn dɛɾ ˈɑːbənt bəɡˈɪnt zˈɪŋt dɛɾ vˈɪnt/","en":"When the evening begins the wind sings","zh":"当夜幕降临，狂风呼啸","note":""},{"id":"rebecca-das-musical-34-029","lineIndex":29,"speaker":"","original":"Rebecca, komm heim Rebecca","sourceLineIndex":29,"ipa":"/reːbˈɛkɑː kˈɔm hˈaɪm reːbˈɛkɑː/","en":"Rebecca, come home Rebecca","zh":"丽贝卡，回家吧，丽贝卡","note":""},{"id":"rebecca-das-musical-34-030","lineIndex":30,"speaker":"","original":"Aus dem Nebelreich zurück nach Manderley","sourceLineIndex":30,"ipa":"/ˌaʊs deːm nˈeːbəlrˌaɪç tsuːrˈʏk nɑːx mˈandɜlˌaɪ/","en":"From the Misty Realm back to Manderley","zh":"从迷雾中回到曼德雷","note":""},{"id":"rebecca-das-musical-34-031","lineIndex":31,"speaker":"","original":"Tu nicht was sie empört","sourceLineIndex":31,"ipa":"/tˈuː nˈɪçt vˈas ziː ɛmpˈœɾt/","en":"Don't do what upsets her","zh":"不要激怒她","note":""},{"id":"rebecca-das-musical-34-032","lineIndex":32,"speaker":"","original":"Oh nein!","sourceLineIndex":32,"ipa":"/ˈoː nˈaɪn/","en":"Oh no!","zh":"哦，不","note":""},{"id":"rebecca-das-musical-34-033","lineIndex":33,"speaker":"","original":"Nimm nicht was ihr gehört","sourceLineIndex":33,"ipa":"/nˈɪm nˈɪçt vˈas iːɾ ɡəhˈœɾt/","en":"Don't take what's hers","zh":"不要拿走属于她的东西","note":""},{"id":"rebecca-das-musical-34-034","lineIndex":34,"speaker":"","original":"Wer sie stört, wird zerstört!","sourceLineIndex":34,"ipa":"/vˈeːɾ ziː ʃtˈœɾt vˌɪɾt tsɛɾʃtˈœɾt/","en":"Anyone who disturbs her will be destroyed!","zh":"打扰她的人将被摧毁","note":""},{"id":"rebecca-das-musical-34-035","lineIndex":35,"speaker":"","original":"Nein!","sourceLineIndex":35,"ipa":"/nˈaɪn/","en":"No!","zh":"不！","note":""},{"id":"rebecca-das-musical-34-036","lineIndex":36,"speaker":"","original":"Rebecca!","sourceLineIndex":36,"ipa":"/reːbˈɛkɑː/","en":"Rebecca!","zh":"丽贝卡！","note":""},{"id":"rebecca-das-musical-34-037","lineIndex":37,"speaker":"","original":"Sie ist fort!","sourceLineIndex":37,"ipa":"/ziː ɪst fˈɔɾt/","en":"She's gone!","zh":"她不见了","note":""},{"id":"rebecca-das-musical-34-038","lineIndex":38,"speaker":"","original":"Wo du auch immer bist","sourceLineIndex":38,"ipa":"/vˌoː duː ˌaʊx ˈɪmɜ bɪst/","en":"Wherever you are","zh":"无论你在哪儿","note":""},{"id":"rebecca-das-musical-34-039","lineIndex":39,"speaker":"","original":"Weit fort","sourceLineIndex":39,"ipa":"/vˈaɪt fˈɔɾt/","en":"Far away","zh":"在远处","note":""},{"id":"rebecca-das-musical-34-040","lineIndex":40,"speaker":"","original":"Komm heim!","sourceLineIndex":40,"ipa":"/kˈɔm hˈaɪm/","en":"Come home!","zh":"快回家","note":""},{"id":"rebecca-das-musical-34-041","lineIndex":41,"speaker":"","original":"Dein Herz bleibt ruhlos","sourceLineIndex":41,"ipa":"/daɪn hˈɛɾts blˈaɪpt rˈuːloːs/","en":"Your heart remains restless","zh":"你的心自由不羁","note":""},{"id":"rebecca-das-musical-34-042","lineIndex":42,"speaker":"","original":"Wie die wilde, freie See","sourceLineIndex":42,"ipa":"/viː diː vˈɪldə frˈaɪə zˈeː/","en":"Like the wild, free sea","zh":"就像狂野的大海","note":""},{"id":"rebecca-das-musical-34-043","lineIndex":43,"speaker":"","original":"Wer tot ist kehrt nicht mehr zurück","sourceLineIndex":43,"ipa":"/vˈeːɾ tˈoːt ɪst kˈeːɾt nˈɪçt mˌeːɾ tsuːrˈʏk/","en":"Anyone who is dead never returns","zh":"死去之人不会复生","note":""},{"id":"rebecca-das-musical-34-044","lineIndex":44,"speaker":"","original":"Wenn der Abend beginnt, singt der Wind","sourceLineIndex":44,"ipa":"/vˌɛn dɛɾ ˈɑːbənt bəɡˈɪnt zˈɪŋt dɛɾ vˈɪnt/","en":"When the evening begins, the wind sings","zh":"当夜幕降临，狂风呼啸","note":""},{"id":"rebecca-das-musical-34-045","lineIndex":45,"speaker":"","original":"Rebecca","sourceLineIndex":45,"ipa":"/reːbˈɛkɑː/","en":"Rebecca","zh":"丽贝卡","note":""},{"id":"rebecca-das-musical-34-046","lineIndex":46,"speaker":"","original":"Rebecca","sourceLineIndex":46,"ipa":"/reːbˈɛkɑː/","en":"Rebecca","zh":"丽贝卡","note":""},{"id":"rebecca-das-musical-34-047","lineIndex":47,"speaker":"","original":"Was war ist vorbei","sourceLineIndex":47,"ipa":"/vˈas vɑːɾ ɪst foːɾbˈaɪ/","en":"What was is over","zh":"都结束了","note":""},{"id":"rebecca-das-musical-34-048","lineIndex":48,"speaker":"","original":"Komm heim Rebecca","sourceLineIndex":48,"ipa":"/kˈɔm hˈaɪm reːbˈɛkɑː/","en":"Come home Rebecca","zh":"回家吧 Rebecca","note":""},{"id":"rebecca-das-musical-34-049","lineIndex":49,"speaker":"","original":"Warum dann habe ich Angst vor...?","sourceLineIndex":49,"ipa":"/vɑːrˈʊm dan hɑːbə ɪç ˈaŋst fˈɔɾ/","en":"Then why am I afraid of...?","zh":"但我为什么会害怕？","note":""},{"id":"rebecca-das-musical-34-050","lineIndex":50,"speaker":"","original":"Aus dem Nebelreich zurück nach Manderley!","sourceLineIndex":50,"ipa":"/ˌaʊs deːm nˈeːbəlrˌaɪç tsuːrˈʏk nɑːx mˈandɜlˌaɪ/","en":"From the Misty Realm back to Manderley!","zh":"从虚无缥缈的世界回到曼德雷","note":""},{"id":"rebecca-das-musical-34-051","lineIndex":51,"speaker":"","original":"Rebecca!","sourceLineIndex":51,"ipa":"/reːbˈɛkɑː/","en":"Rebecca!","zh":"丽贝卡！","note":""}],"sourceOrder":34,"displayOrder":15},{"order":35,"id":"35-rebecca-reprise-ii-live","title":"Rebecca - Reprise II","titleZh":"瑞贝卡（重唱 II）","lines":[{"id":"rebecca-das-musical-35-001","lineIndex":1,"speaker":"","original":"Ich war ihr nah, wie niemand sonst.","sourceLineIndex":1,"ipa":"/ɪç vɑːɾ iːɾ nˈɑː viː nˈiːmant zˈɔnst/","en":"I was close to her like no one else.","zh":"我和她的关系没有其他人那么亲近。","note":""},{"id":"rebecca-das-musical-35-002","lineIndex":2,"speaker":"","original":"Doch sie verschwieg mir wie es um sie stand.","sourceLineIndex":2,"ipa":"/dɔx ziː fɛɾʃvˈiːk miːɾ viː ɛs ʊm ziː ʃtˈant/","en":"But she kept secret from me what it was like for her.","zh":"但她对我隐瞒了对她来说是什么样的。","note":""},{"id":"rebecca-das-musical-35-004","lineIndex":3,"speaker":"","original":"Mein ganzes Leben gab ich ihr. Ich liebte sie, doch sie","sourceLineIndex":4,"ipa":"/maɪn ɡˈantsəs lˈeːbən ɡˈɑːp ɪç iːɾ ɪç lˈiːptə ziː dˈɔx ziː/","en":"I gave my whole life to her. I loved her, but her","zh":"我把我的一生都给了她。我爱她，但她","note":""},{"id":"rebecca-das-musical-35-005","lineIndex":4,"speaker":"","original":"hat mich verraten.","sourceLineIndex":5,"ipa":"/hat mɪç fɛɾrˈɑːtən/","en":"betrayed me.","zh":"背叛了我。","note":""},{"id":"rebecca-das-musical-35-006","lineIndex":5,"speaker":"","original":"Rebecca","sourceLineIndex":6,"ipa":"/reːbˈɛkɑː/","en":"Rebecca","zh":"丽贝卡","note":""},{"id":"rebecca-das-musical-35-007","lineIndex":6,"speaker":"","original":"jetzt bist du nicht mehr hier.","sourceLineIndex":7,"ipa":"/jˌɛtst bɪst duː nˈɪçt mˌeːɾ hˈiːɾ/","en":"now you are no longer here.","zh":"现在你已经不在这里了。","note":""},{"id":"rebecca-das-musical-35-008","lineIndex":7,"speaker":"","original":"Worauf noch warten wenn ich dich nie wieder sehen?","sourceLineIndex":8,"ipa":"/voːrˈaʊf nɔx vˈaɾtən vˌɛn ɪç dɪç nˈiː vˈiːdɜ zˈeːən/","en":"What are you waiting for What if I never see you again?","zh":"你还在等什么如果我再也见不到你怎么办？","note":""},{"id":"rebecca-das-musical-35-010","lineIndex":8,"speaker":"","original":"Sinnlos ist dieses Haus, sowie ich!","sourceLineIndex":10,"ipa":"/zˈɪnloːs ɪst dˌiːzəs hˈaʊs zoːvˈiː ɪç/","en":"This house, like me, is pointless!","zh":"这房子和我一样，毫无意义！","note":""},{"id":"rebecca-das-musical-35-011","lineIndex":9,"speaker":"","original":"Rebecca","sourceLineIndex":11,"ipa":"/reːbˈɛkɑː/","en":"Rebecca","zh":"丽贝卡","note":""},{"id":"rebecca-das-musical-35-012","lineIndex":10,"speaker":"","original":"nach dir, Rebecca","sourceLineIndex":12,"ipa":"/nɑːx dˈiːɾ reːbˈɛkɑː/","en":"after you, Rebecca","zh":"在你之后，丽贝卡","note":""},{"id":"rebecca-das-musical-35-013","lineIndex":11,"speaker":"","original":"Soll nichts bleiben wie es war in Manderley.","sourceLineIndex":13,"ipa":"/zˌɔl nˈɪçts blˈaɪbən viː ɛs vɑːɾ ɪn mˈandɜlˌaɪ/","en":"Nothing should remain as it was in Manderley.","zh":"曼德利的一切都不应该保留。","note":""}],"sourceOrder":35,"displayOrder":16},{"order":36,"id":"36-manderley-in-flammen-live","title":"Manderley in Flammen","titleZh":"曼德利着火","lines":[{"id":"rebecca-das-musical-36-001","lineIndex":1,"speaker":"","original":"(Das ist nicht die Sonne. Das ist Manderley!)","sourceLineIndex":1,"ipa":"/das ɪst nˈɪçt diː zˈɔnə das ɪst mˈandɜlˌaɪ/","en":"(That's not the sun. That's Manderley!)","zh":"（那不是太阳。那是曼德利！）","note":""},{"id":"rebecca-das-musical-36-002","lineIndex":2,"speaker":"","original":"Feuer! Feuer!","sourceLineIndex":2,"ipa":"/fˈɔøɜ fˈɔøɜ/","en":"Fire! Fire!","zh":"火火火！火火火！","note":""},{"id":"rebecca-das-musical-36-003","lineIndex":3,"speaker":"","original":"Manderley in Flammen!","sourceLineIndex":3,"ipa":"/mˈandɜlˌaɪ ɪn flˈamən/","en":"Manderley on fire!","zh":"曼德雷被没于火焰","note":""},{"id":"rebecca-das-musical-36-004","lineIndex":4,"speaker":"","original":"Hierher alle, löscht den Brand","sourceLineIndex":4,"ipa":"/hˈiːɾhɜ ˈalə lˈœʃt deːn bɾˈant/","en":"Everyone here, put out the fire","zh":"在这里，所有的一切都讲付之一炬","note":""},{"id":"rebecca-das-musical-36-005","lineIndex":5,"speaker":"","original":"Schnell, wir brauchen Wasser!","sourceLineIndex":5,"ipa":"/ʃnˈɛl viːɾ bɾˈaʊxən vˈasɜ/","en":"Quick, we need water!","zh":"快快快！我们需要消防水！","note":""},{"id":"rebecca-das-musical-36-006","lineIndex":6,"speaker":"","original":"Feuer! Feuer!","sourceLineIndex":6,"ipa":"/fˈɔøɜ fˈɔøɜ/","en":"Fire! Fire!","zh":"火灾！火灾！","note":""},{"id":"rebecca-das-musical-36-007","lineIndex":7,"speaker":"","original":"Manderley in Flammen!","sourceLineIndex":7,"ipa":"/mˈandɜlˌaɪ ɪn flˈamən/","en":"Manderley on fire!","zh":"曼德雷已经被火焰吞噬","note":""},{"id":"rebecca-das-musical-36-008","lineIndex":8,"speaker":"","original":"Eimer her, von Hand zu Hand","sourceLineIndex":8,"ipa":"/ˈaɪmɜ hˈeːɾ fɔn hˈant tsuː hˈant/","en":"Bucket over, hand to hand","zh":"所有人，手传手，传水救火！","note":""},{"id":"rebecca-das-musical-36-009","lineIndex":9,"speaker":"","original":"Schneller, schneller, schneller!","sourceLineIndex":9,"ipa":"/ʃnˈɛlɜ ʃnˈɛlɜ ʃnˈɛlɜ/","en":"Faster, faster, faster!","zh":"快快快！快快快！","note":""},{"id":"rebecca-das-musical-36-010","lineIndex":10,"speaker":"","original":"Feuer! Feuer!","sourceLineIndex":10,"ipa":"/fˈɔøɜ fˈɔøɜ/","en":"Fire! Fire!","zh":"到处都是火焰！","note":""},{"id":"rebecca-das-musical-36-011","lineIndex":11,"speaker":"","original":"Manderley ist sonst verlor'n!","sourceLineIndex":11,"ipa":"/mˈandɜlˌaɪ ɪst zˈɔnst fɛɾlˈoːɾn/","en":"Otherwise Manderley will be lost!","zh":"曼德雷将要毁于一旦！","note":""},{"id":"rebecca-das-musical-36-012","lineIndex":12,"speaker":"","original":"(Jeder verlässt das Haus. Rettet Euer Leben!)","sourceLineIndex":12,"ipa":"/jˈeːdɜ fɛɾlˈɛst das hˈaʊs rˈɛtət ˈɔøɜ lˈeːbən/","en":"(Everyone leave the house. Save your lives!)","zh":"（所有人都逃出了房子，人人难自救。）","note":""},{"id":"rebecca-das-musical-36-013","lineIndex":13,"speaker":"","original":"Feuer! (Vorsicht!) Feuer! (Rennt hier!)","sourceLineIndex":13,"ipa":"/fˈɔøɜ fˈoːɾzˌɪçt fˈɔøɜ rˈɛnt hˈiːɾ/","en":"Fire! (Caution!) Fire! (Run here!)","zh":"火！（小心！）火（快逃！）","note":""},{"id":"rebecca-das-musical-36-014","lineIndex":14,"speaker":"","original":"Manderley in Flammen! (Rasch!)","sourceLineIndex":14,"ipa":"/mˈandɜlˌaɪ ɪn flˈamən rˈaʃ/","en":"Manderley on fire! (Quickly!)","zh":"曼德雷在火海之中（逃！）","note":""},{"id":"rebecca-das-musical-36-015","lineIndex":15,"speaker":"","original":"Wo kein Wasser ist nehmt Sand","sourceLineIndex":15,"ipa":"/vˌoː kˈaɪn vˈasɜ ɪst nˈeːmt zˈant/","en":"Where there is no water, use sand","zh":"沙滩之上竟然无水可用","note":""},{"id":"rebecca-das-musical-36-016","lineIndex":16,"speaker":"","original":"Hierher mit der Leiter! (Los!)","sourceLineIndex":16,"ipa":"/hˈiːɾhɜ mɪt dɛɾ lˈaɪtɜ lˈoːs/","en":"Here with the ladder! (Go!)","zh":"空有灭火水管！（快跑！）","note":""},{"id":"rebecca-das-musical-36-017","lineIndex":17,"speaker":"","original":"Feuer! (Höher!) Feuer! (Weiter!)","sourceLineIndex":17,"ipa":"/fˈɔøɜ hˈøːɜ fˈɔøɜ vˈaɪtɜ/","en":"Fire! (Higher!) Fire! (Continue!)","zh":"火蛇！（更高！）火龙（更大！）","note":""},{"id":"rebecca-das-musical-36-018","lineIndex":18,"speaker":"","original":"Manderley in Flammen (Lauft!)","sourceLineIndex":18,"ipa":"/mˈandɜlˌaɪ ɪn flˈamən lˈaʊft/","en":"Manderley on fire (Run!)","zh":"曼德雷在火海之中（快跑！）","note":""},{"id":"rebecca-das-musical-36-019","lineIndex":19,"speaker":"","original":"Rettet was ihr tragen könnt","sourceLineIndex":19,"ipa":"/rˈɛtət vˈas iːɾ tɾˈɑːɡən kˌœnt/","en":"Save what you can carry","zh":"带上一切可以带上的东西","note":""},{"id":"rebecca-das-musical-36-020","lineIndex":20,"speaker":"","original":"Schneller, schneller, schneller!","sourceLineIndex":20,"ipa":"/ʃnˈɛlɜ ʃnˈɛlɜ ʃnˈɛlɜ/","en":"Faster, faster, faster!","zh":"快走，快跑，快逃！","note":""},{"id":"rebecca-das-musical-36-021","lineIndex":21,"speaker":"","original":"Das stolze Manderley, Kohle und Asche...","sourceLineIndex":21,"ipa":"/das ʃtˈɔltsə mˈandɜlˌaɪ kˈoːlə ʊnt ˈaʃə/","en":"Proud Manderley, coal and ash...","zh":"曼德雷的骄傲，一炬化为尘与灰","note":""},{"id":"rebecca-das-musical-36-022","lineIndex":22,"speaker":"","original":"Welch ein tragischer Schicksalsschlag!","sourceLineIndex":22,"ipa":"/vˈɛlç aɪn tɾˈɑɡɪʃɜ ʃˈɪkzalsçlˌɑːk/","en":"What a tragic stroke of fate!","zh":"多么戏剧性的结果啊","note":""},{"id":"rebecca-das-musical-36-023","lineIndex":23,"speaker":"","original":"Wertvolle Möbel und Bücher und Bilder:","sourceLineIndex":23,"ipa":"/vˈɛɾtfɔlə mˈøːbəl ʊnt bˈyːçɜ ʊnt bˈɪldɜ/","en":"Valuable furniture and books and pictures:","zh":"价值连城的雕塑，藏书，和字画","note":""},{"id":"rebecca-das-musical-36-024","lineIndex":24,"speaker":"","original":"Alles verbennt, Manderley ist verlor'n!","sourceLineIndex":24,"ipa":"/ˈaləs fɛɾbˈɛnt mˈandɜlˌaɪ ɪst fɛɾlˈoːɾn/","en":"Everything is burned, Manderley is lost!","zh":"统统化为灰烬，曼德雷已经不复存在了","note":""},{"id":"rebecca-das-musical-36-025","lineIndex":25,"speaker":"","original":"Ich schwöre, im Haus war jedes Feuer ausgemacht.","sourceLineIndex":25,"ipa":"/ɪç ʃvˈøːrə ɪm hˈaʊs vɑːɾ jˈeːdəs fˈɔøɜ ˈaʊsɡəmˌaxt/","en":"I swear every fire in the house was turned off.","zh":"我敢说，火龙已经遍临房子的每一个角落了","note":""},{"id":"rebecca-das-musical-36-026","lineIndex":26,"speaker":"","original":"Ich sah nur im Gang noch Mrs. Danvers nach Mitternacht.","sourceLineIndex":26,"ipa":"/ɪç zˈɑː nˈuːɾ ɪm ɡˈaŋ nɔx ˌɛmˌɛrˈɛs dˈanfɜs nɑːx mˈɪtɜnˌaxt/","en":"I only saw Mrs. Danvers in the hallway after midnight.","zh":"我只看见午夜之后，丹佛斯夫人独自一人进入了房子","note":""},{"id":"rebecca-das-musical-36-027","lineIndex":27,"speaker":"","original":"Als ich rief, hat sie nur laut gelacht.","sourceLineIndex":27,"ipa":"/als ɪç rˈiːf hat ziː nˈuːɾ lˈaʊt ɡəlˈaxt/","en":"When I called out, she just laughed out loud.","zh":"当我叫她的时候，她只是在大笑","note":""},{"id":"rebecca-das-musical-36-028","lineIndex":28,"speaker":"","original":"Bald wird Schutt und Asche sein","sourceLineIndex":28,"ipa":"/bˈalt vˌɪɾt ʃˈʊt ʊnt ˈaʃə zaɪn/","en":"Soon there will be rubble and ashes","zh":"这里的一切很快就会化为灰烬","note":""},{"id":"rebecca-das-musical-36-029","lineIndex":29,"speaker":"","original":"Was mir mein stolzer Vater hinterliess","sourceLineIndex":29,"ipa":"/vˈas miːɾ maɪn ʃtˈɔltsɜ fˈɑːtɜ hˌɪntɜlˈiːs/","en":"What my proud father left me","zh":"我那骄傲的父亲liu留下来的房子啊","note":""},{"id":"rebecca-das-musical-36-030","lineIndex":30,"speaker":"","original":"Es war mal mein Zuhaus","sourceLineIndex":30,"ipa":"/ɛs vɑːɾ mˈɑːl maɪn tsuːhˈaʊs/","en":"It used to be my home","zh":"属于我的房子啊","note":""},{"id":"rebecca-das-musical-36-031","lineIndex":31,"speaker":"","original":"Jedoch das Böse nahm Besitz davon","sourceLineIndex":31,"ipa":"/jˈeːdɔx das bˈøːzə nˈɑːm bəzˈɪts dɑːfˈɔn/","en":"However, evil took possession of it","zh":"尽管承载了太多的罪恶","note":""},{"id":"rebecca-das-musical-36-032","lineIndex":32,"speaker":"","original":"So wurde daraus mein Gefängnis","sourceLineIndex":32,"ipa":"/zoː vˌʊɐdə dɑːrˈaʊs maɪn ɡəfˈɛŋnɪs/","en":"So it became my prison","zh":"成为了我的专属牢房","note":""},{"id":"rebecca-das-musical-36-033","lineIndex":33,"speaker":"","original":"Nein, weiss Gott, ich wollte nicht, dass Flammen es zerstör'n!","sourceLineIndex":33,"ipa":"/nˈaɪn vˈaɪs ɡˈɔt ɪç vɔltə nˈɪçt das flˈamən ɛs tsɛɾʃtˈøːɾn/","en":"No, God knows, I didn't want flames to destroy it!","zh":"不，我的上帝啊！请不要让火焰把一切毁灭啊。","note":""},{"id":"rebecca-das-musical-36-034","lineIndex":34,"speaker":"","original":"Doch mit dem Haus verbrennt die Angst","sourceLineIndex":34,"ipa":"/dɔx mɪt deːm hˈaʊs fɛɾbɾˈɛnt diː ˈaŋst/","en":"But fear burns down with the house","zh":"但请我的不安和恐惧，也随火焰燃烧吧","note":""},{"id":"rebecca-das-musical-36-035","lineIndex":35,"speaker":"","original":"Von den dunklen Schatten bleibt nur Rauch!","sourceLineIndex":35,"ipa":"/fɔn deːn dˈʊŋklən ʃˈatən blˈaɪpt nˈuːɾ rˈaʊx/","en":"Only smoke remains from the dark shadows!","zh":"将所有的黑暗，付诸于烈火吧！","note":""}],"sourceOrder":36,"displayOrder":17},{"order":37,"id":"37-prolog-ich-hab-getraumt-von-manderley-ich-schatten","title":"Prolog - Ich hab geträumt von Manderley","titleZh":"序幕：我梦见曼德利","lines":[{"id":"rebecca-das-musical-37-001","lineIndex":1,"speaker":"","original":"Ich hab geträumt von Manderley","sourceLineIndex":1,"ipa":"/ɪç hˈɑːp ɡətɾˈɔømt fɔn mˈandɜlˌaɪ/","en":"I dreamed of Manderley","zh":"我又梦见了曼德雷！","note":""},{"id":"rebecca-das-musical-37-002","lineIndex":2,"speaker":"","original":"Modernde Steine und schwarze Fassaden","sourceLineIndex":2,"ipa":"/mˈoːdɛɾndə ʃtˈaɪnə ʊnt ʃvˈaɾtsə fˈasɑːdən/","en":"Rotting stones and black facades","zh":"精巧的砖石，乌黑的墙壁","note":""},{"id":"rebecca-das-musical-37-003","lineIndex":3,"speaker":"","original":"so geisterhaft und unnahbar","sourceLineIndex":3,"ipa":"/zoː ɡˈaɪstɜhˌaft ʊnt ˈʊnnˌɑːbɑːɾ/","en":"so ghostly and aloof","zh":"像幻影般难以捉摸","note":""},{"id":"rebecca-das-musical-37-004","lineIndex":4,"speaker":"","original":"Schatten der Nacht, vor denen wir flohn","sourceLineIndex":4,"ipa":"/ʃˈatən dɛɾ nˈaxt fˌɔɾ deːnən viːɾ flˈoːn/","en":"Shadows of the night from which we fled","zh":"夜之幽灵，纠缠不休","note":""},{"id":"rebecca-das-musical-37-005","lineIndex":5,"speaker":"","original":"grauend von dem was war","sourceLineIndex":5,"ipa":"/ɡɾˈaʊənt fɔn deːm vˈas vɑːɾ/","en":"horror of what was","zh":"喃喃低语，沉吟至今","note":""},{"id":"rebecca-das-musical-37-006","lineIndex":6,"speaker":"","original":"Und der Mond scheint hell","sourceLineIndex":6,"ipa":"/ʊnt dɛɾ mˈoːnt ʃˈaɪnt hˈɛl/","en":"And the moon shines bright","zh":"那时的月光清澈如水","note":""},{"id":"rebecca-das-musical-37-007","lineIndex":7,"speaker":"","original":"und er Fliederduft","sourceLineIndex":7,"ipa":"/ʊnt ɛɾ flˈiːdɜdˌʊft/","en":"and the scent of lilacs","zh":"丁香馥郁芬芳","note":""},{"id":"rebecca-das-musical-37-008","lineIndex":8,"speaker":"","original":"ist so süss und sehnsuchtsschwer","sourceLineIndex":8,"ipa":"/ɪst zoː zˈʏs ʊnt zˈeːnzuːxtsçvɜ/","en":"is so sweet and longing","zh":"多么甜美醉人","note":""},{"id":"rebecca-das-musical-37-009","lineIndex":9,"speaker":"","original":"und wie damals liegt","sourceLineIndex":9,"ipa":"/ʊnt viː dˈɑmɑːls lˈiːkt/","en":"and as it was back then","zh":"而巨大的不幸","note":""},{"id":"rebecca-das-musical-37-010","lineIndex":10,"speaker":"","original":"Unheil in der Luft doch heut schreckt es mich nicht mehr","sourceLineIndex":10,"ipa":"/ˈʊnhˌaɪl ɪn dɛɾ lˈʊft dɔx hˈɔøt ʃrˈɛkt ɛs mɪç nˌɪçt mˈeːɾ/","en":"Mischief in the air but today it doesn't scare me anymore","zh":"却笼罩在空中如今的我已不再害怕！","note":""},{"id":"rebecca-das-musical-37-012","lineIndex":11,"speaker":"","original":"Ich hab geträumt von Manderley","sourceLineIndex":12,"ipa":"/ɪç hˈɑːp ɡətɾˈɔømt fɔn mˈandɜlˌaɪ/","en":"I dreamed of Manderley","zh":"我又梦见了曼德雷！","note":""},{"id":"rebecca-das-musical-37-013","lineIndex":12,"speaker":"","original":"und der vergangen Zeit","sourceLineIndex":13,"ipa":"/ʊnt dɛɾ fɛɾɡˈaŋən tsˈaɪt/","en":"and the past time","zh":"梦见了那些尘封的往事","note":""},{"id":"rebecca-das-musical-37-014","lineIndex":13,"speaker":"","original":"von Sehnsucht, Schuld und Dunkelheit","sourceLineIndex":14,"ipa":"/fɔn zˈeːnzuːxt ʃˈʊlt ʊnt dˈʊnkəlhˌaɪt/","en":"of longing, guilt and darkness","zh":"渴望，罪恶和黑暗","note":""},{"id":"rebecca-das-musical-37-015","lineIndex":14,"speaker":"","original":"und von Liebe die befreit","sourceLineIndex":15,"ipa":"/ʊnt fɔn lˈiːbə diː bəfrˈaɪt/","en":"and of love that liberates","zh":"以及拯救了我们的爱","note":""},{"id":"rebecca-das-musical-37-016","lineIndex":15,"speaker":"","original":"und Rebeccas Geist schwebte unsichtbar","sourceLineIndex":16,"ipa":"/ʊnt rˈeːbɛkˌɑːs ɡˈaɪst ʃvˈeːptə ˈʊnzˌɪçtbɑːɾ/","en":"and Rebecca's spirit floated invisibly","zh":"丽贝卡的阴魂四处游荡","note":""},{"id":"rebecca-das-musical-37-017","lineIndex":16,"speaker":"","original":"durch das Haus und kam mir nah","sourceLineIndex":17,"ipa":"/dʊɐç das hˈaʊs ʊnt kˌɑːm miːɾ nˈɑː/","en":"through the house and came close to me","zh":"徘徊不去，令我心惊","note":""},{"id":"rebecca-das-musical-37-018","lineIndex":17,"speaker":"","original":"und da war mir klar, ich entgeh ihr nur","sourceLineIndex":18,"ipa":"/ʊnt dɑː vɑːɾ miːɾ klˈɑːɾ ɪç ɛntɡˈeː iːɾ nˈuːɾ/","en":"and then I realized I was just avoiding her","zh":"只有去了解事实和真相","note":""},{"id":"rebecca-das-musical-37-019","lineIndex":18,"speaker":"","original":"wenn ich weiss, was hier geschah","sourceLineIndex":19,"ipa":"/vˌɛn ɪç vˈaɪs vˈas hˈiːɾ ɡəʃˈɑː/","en":"if I know what happened here","zh":"才能摆脱她的纠缠！","note":""},{"id":"rebecca-das-musical-37-020","lineIndex":19,"speaker":"","original":"Wir finden Starke in Gefahr","sourceLineIndex":20,"ipa":"/viːɾ fˈɪndən ʃtˈaɾkə ɪn ɡəfˈɑːɾ/","en":"We find strong people in danger","zh":"我们在危急关头获得了力量","note":""},{"id":"rebecca-das-musical-37-021","lineIndex":20,"speaker":"","original":"und Hoffnung in schwerer Zeit","sourceLineIndex":21,"ipa":"/ʊnt hˈɔfnʊŋ ɪn ʃvˈeːrɜ tsˈaɪt/","en":"and hope in difficult times","zh":"在困难的时刻看到了希望","note":""},{"id":"rebecca-das-musical-37-022","lineIndex":21,"speaker":"","original":"Ich hab getraumt von Manderley","sourceLineIndex":22,"ipa":"/ɪç hˈɑːp ɡətɾˈaʊmt fɔn mˈandɜlˌaɪ/","en":"I dreamed of Manderley","zh":"我又梦见了曼德雷","note":""},{"id":"rebecca-das-musical-37-023","lineIndex":22,"speaker":"","original":"und von Liebe die befreit","sourceLineIndex":23,"ipa":"/ʊnt fɔn lˈiːbə diː bəfrˈaɪt/","en":"and of love that liberates","zh":"和拯救了我们的爱","note":""},{"id":"rebecca-das-musical-37-024","lineIndex":23,"speaker":"","original":"Alles fing in Frankreich an","sourceLineIndex":24,"ipa":"/ˈaləs fˈɪŋ ɪn frˈaŋkɾaɪç ˈan/","en":"It all started in France","zh":"故事开始于法国","note":""},{"id":"rebecca-das-musical-37-025","lineIndex":24,"speaker":"","original":"damals im April 1926","sourceLineIndex":25,"ipa":"/dˈɑmɑːls ɪm apɾˈiːl ˈaɪn tˈaʊzənt nˈɔønhˈʊndɜt zˈɛks ʊnttsvˈantsɪç/","en":"back in April 1926","zh":"1926年的四月","note":""},{"id":"rebecca-das-musical-37-026","lineIndex":25,"speaker":"","original":"In der Eingangslounge eines Grand Hotels in Monte Carlo","sourceLineIndex":26,"ipa":"/ɪn dɛɾ ˈaɪnɡˌaŋsluːŋə ˌaɪnəs ɡɾˈant hˈoːtəls ɪn mˈɔntə kˈaɾloː/","en":"In the entrance lounge of a grand hotel in Monte Carlo","zh":"一家宾馆的休息大厅在蒙特卡罗！","note":""}],"sourceOrder":37,"displayOrder":18},{"order":39,"id":"39-zeit-in-einer-flasche-ich","title":"Zeit in einer Flasche","titleZh":"序曲/瓶中时光","lines":[{"id":"rebecca-das-musical-39-001","lineIndex":1,"speaker":"","original":"Wir reisen morgen ab","sourceLineIndex":1,"ipa":"/viːɾ rˈaɪzən mˈɔɾɡən ˈap/","en":"We're leaving tomorrow","zh":"我们明天就启程","note":""},{"id":"rebecca-das-musical-39-002","lineIndex":2,"speaker":"","original":"Dieses alte Europa macht mich krank.","sourceLineIndex":2,"ipa":"/dˌiːzəs ˈaltə ɔørˈoːpɑː mˈaxt mɪç kɾˈaŋk/","en":"This old Europe makes me sick.","zh":"老旧的欧洲真让我受够了","note":""},{"id":"rebecca-das-musical-39-003","lineIndex":3,"speaker":"","original":"Ich muss wieder zurueck nach New York.","sourceLineIndex":3,"ipa":"/ɪç mˈʊs vˈiːdɜ tsuːrˈuːɛk nɑːx njˈuː jˈɔɾk/","en":"I have to go back to New York.","zh":"我必须回纽约去","note":""},{"id":"rebecca-das-musical-39-004","lineIndex":4,"speaker":"","original":"Schon morgen?","sourceLineIndex":4,"ipa":"/ʃˌoːn mˈɔɾɡən/","en":"Already tomorrow?","zh":"明天就走","note":""},{"id":"rebecca-das-musical-39-005","lineIndex":5,"speaker":"","original":"Ich wer’ nicht Schlau aus dir, Kind.","sourceLineIndex":5,"ipa":"/ɪç vˈeːɾ nˈɪçt ʃlˈaʊ ˌaʊs dˈiːɾ kˈɪnt/","en":"I can't understand you, child.","zh":"我可搞不懂你，孩子","note":""},{"id":"rebecca-das-musical-39-006","lineIndex":6,"speaker":"","original":"Ich dachte, du machst dir nicht aus Monte.","sourceLineIndex":6,"ipa":"/ɪç dˈaxtə duː mˈaxst diːɾ nˈɪçt ˌaʊs mˈɔntə/","en":"I thought you didn't care about Monte.","zh":"我还以为你不喜欢蒙特卡罗","note":""},{"id":"rebecca-das-musical-39-007","lineIndex":7,"speaker":"","original":"Ich hab mich dran gewoehnt.","sourceLineIndex":7,"ipa":"/ɪç hˈɑːp mɪç dɾˈɑːn ɡəvˈœhnt/","en":"I got used to it.","zh":"我已经习惯这里了","note":""},{"id":"rebecca-das-musical-39-008","lineIndex":8,"speaker":"","original":"Worauf wartest du?","sourceLineIndex":8,"ipa":"/voːrˈaʊf vˈaɾtəst duː/","en":"What are you waiting for?","zh":"还等什么","note":""},{"id":"rebecca-das-musical-39-009","lineIndex":9,"speaker":"","original":"Fang an zu Packen!","sourceLineIndex":9,"ipa":"/fˈaŋ an tsuː pˈakən/","en":"Start packing!","zh":"快去整理行李","note":""},{"id":"rebecca-das-musical-39-010","lineIndex":10,"speaker":"","original":"Aber, Mrs. van Hopper...","sourceLineIndex":10,"ipa":"/ˈɑːbɜ ˌɛmˌɛrˈɛs vˈɑːn hˈɔpɜ/","en":"But, Mrs. van Hopper...","zh":"可是凡霍珀夫人……","note":""},{"id":"rebecca-das-musical-39-011","lineIndex":11,"speaker":"","original":"Hallo…Rezeption?","sourceLineIndex":11,"ipa":"/hˈaloː rˌeːtsɛptsjˈoːn/","en":"Hello…reception?","zh":"您好……前台吗","note":""},{"id":"rebecca-das-musical-39-012","lineIndex":12,"speaker":"","original":"Verbinden Sie mich mit Mr. de Winters Zimmer.","sourceLineIndex":12,"ipa":"/fɛɾbˈɪndən ziː mɪç mɪt ˌɛmˈɛɾ dˈeː vˈɪntɜs tsˈɪmɜ/","en":"Direct me to Mr. de Winter's room.","zh":"请为我接通德温特先生","note":""},{"id":"rebecca-das-musical-39-013","lineIndex":13,"speaker":"","original":"Sind Sie sicher?","sourceLineIndex":13,"ipa":"/zɪnt ziː zˈɪçɜ/","en":"Are you sure?","zh":"您确定吗","note":""},{"id":"rebecca-das-musical-39-014","lineIndex":14,"speaker":"","original":"Merci beaucoup, Monsieur.","sourceLineIndex":14,"ipa":"/mˈɛɾkiː bəˈaʊkuːp mˌɔnziːˈuːɾ/","en":"Merci beaucoup, monsieur.","zh":"非常感谢，先生","note":""},{"id":"rebecca-das-musical-39-015","lineIndex":15,"speaker":"","original":"Lieber Gott! Ich moechte ihn noch einmal sehen.","sourceLineIndex":15,"ipa":"/lˈiːbɜ ɡˈɔt ɪç mˈœçtə iːn nɔx ˈaɪnmˌɑːl zˈeːən/","en":"Dear God! I would like to see him again.","zh":"上帝啊！我想再见他一次","note":""},{"id":"rebecca-das-musical-39-016","lineIndex":16,"speaker":"","original":"Nein, ich weine nicht.","sourceLineIndex":16,"ipa":"/nˈaɪn ɪç vˈaɪnə nˈɪçt/","en":"No, I'm not crying.","zh":"不，我不能哭","note":""},{"id":"rebecca-das-musical-39-017","lineIndex":17,"speaker":"","original":"Statt mich selber zu bedauern möchte ich dankbar sein, für das was war.","sourceLineIndex":17,"ipa":"/ʃtˈat mɪç zˈɛlbɜ tsuː bədˈaʊɜn mˈœçtə ɪç dˈaŋkbɑːɾ zaɪn fyːɾ das vˈas vɑːɾ/","en":"Instead of feeling sorry for myself I want to be grateful for what was.","zh":"我不能自怨自艾我对过去心怀感激","note":""},{"id":"rebecca-das-musical-39-019","lineIndex":18,"speaker":"","original":"Mir bleibt ja die Erinnerung.","sourceLineIndex":19,"ipa":"/miːɾ blˈaɪpt jˈɑː diː ɛɾˈɪnərˌʊŋ/","en":"I still have the memory.","zh":"小心珍藏着","note":""},{"id":"rebecca-das-musical-39-020","lineIndex":19,"speaker":"","original":"Etwa an den Tag","sourceLineIndex":20,"ipa":"/ˌɛtvɑː an deːn tˈɑːk/","en":"About the day","zh":"在海边度过的","note":""},{"id":"rebecca-das-musical-39-021","lineIndex":20,"speaker":"","original":"Über der Küste","sourceLineIndex":21,"ipa":"/ˌyːbɜ dɛɾ kˈʏstə/","en":"Over the coast","zh":"那一天","note":""},{"id":"rebecca-das-musical-39-022","lineIndex":21,"speaker":"","original":"Du sahst wie gebannt hinab aufs Meer.","sourceLineIndex":22,"ipa":"/duː zˈɑːst viː ɡəbˈant hɪnˈap aʊfs mˈeːɾ/","en":"You looked down at the sea as if spellbound.","zh":"那时你痴痴地凝视着大海","note":""},{"id":"rebecca-das-musical-39-023","lineIndex":22,"speaker":"","original":"Weil mir kalt und schwindlig war Wollte ich zurück zum Wagen gehn.","sourceLineIndex":23,"ipa":"/vˌaɪl miːɾ kˈalt ʊnt ʃvˈɪndlɪç vɑːɾ vɔltə ɪç tsuːrˈʏk tsʊm vˈɑːɡən ɡˈeːn/","en":"Because I was cold and dizzy I wanted to go back to the car.","zh":"而我觉得冷 有些头晕想回到车里","note":""},{"id":"rebecca-das-musical-39-025","lineIndex":23,"speaker":"","original":"Da hielt deine Hand mich fest","sourceLineIndex":25,"ipa":"/dɑː hˈiːlt dˌaɪnə hˈant mɪç fˈɛst/","en":"Your hand held me tight","zh":"你紧紧握住我的手","note":""},{"id":"rebecca-das-musical-39-026","lineIndex":24,"speaker":"","original":"Du hast mich angesehn","sourceLineIndex":26,"ipa":"/duː hast mɪç ˈanɡəzˌeːn/","en":"You looked at me","zh":"深深地把我凝视","note":""},{"id":"rebecca-das-musical-39-027","lineIndex":25,"speaker":"","original":"Und sanft mein Haar berührt.","sourceLineIndex":27,"ipa":"/ʊnt zˈanft maɪn hˈɑːɾ bərˈyːɾt/","en":"And gently touched my hair.","zh":"轻柔的抚摸我的头发","note":""},{"id":"rebecca-das-musical-39-028","lineIndex":26,"speaker":"","original":"Ich wünsch mir ich würde wissen","sourceLineIndex":28,"ipa":"/ɪç vˈʏnʃ miːɾ ɪç vˈʏɾdə vˈɪsən/","en":"I wish I knew","zh":"我多想找个方法","note":""},{"id":"rebecca-das-musical-39-029","lineIndex":27,"speaker":"","original":"Wie Erinnerung lebendig bleibt.","sourceLineIndex":29,"ipa":"/viː ɛɾˈɪnərˌʊŋ leːbˈɛndɪç blˈaɪpt/","en":"How memories stay alive.","zh":"能让回忆鲜活如昔","note":""},{"id":"rebecca-das-musical-39-030","lineIndex":28,"speaker":"","original":"Wie man den Augenblick","sourceLineIndex":30,"ipa":"/viː man deːn ˈaʊɡənblˌɪk/","en":"How to capture the moment","zh":"能让这包含千言万语的眼神","note":""},{"id":"rebecca-das-musical-39-031","lineIndex":29,"speaker":"","original":"In dem das Schweigen sang","sourceLineIndex":31,"ipa":"/ɪn deːm das ʃvˈaɪɡən zˈaŋ/","en":"in which the silence sang","zh":"在这一刻","note":""},{"id":"rebecca-das-musical-39-032","lineIndex":30,"speaker":"","original":"Vor dem Vergehn bewahrt.","sourceLineIndex":32,"ipa":"/fˌɔɾ deːm fɛɾɡˈeːn bəvˈɑːɾt/","en":"Protected from offense.","zh":"凝成永恒","note":""},{"id":"rebecca-das-musical-39-033","lineIndex":31,"speaker":"","original":"Ich wollte ich wüsst","sourceLineIndex":33,"ipa":"/ɪç vɔltə ɪç vˈʏst/","en":"I wish I knew","zh":"我多想能够","note":""},{"id":"rebecca-das-musical-39-034","lineIndex":32,"speaker":"","original":"Wie man Zeit in eine Flasche füllt.","sourceLineIndex":34,"ipa":"/viː man tsˈaɪt ɪn ˌaɪnə flˈaʃə fˈʏlt/","en":"How to put time in a bottle.","zh":"把时间装进瓶子里","note":""},{"id":"rebecca-das-musical-39-035","lineIndex":33,"speaker":"","original":"Dann müsst ich sie nur öffnen und schon","sourceLineIndex":35,"ipa":"/dan mˈʏst ɪç ziː nˈuːɾ ˈœfnən ʊnt ʃˈoːn/","en":"Then I just have to open it and that's it","zh":"只需拧开瓶盖","note":""},{"id":"rebecca-das-musical-39-036","lineIndex":34,"speaker":"","original":"Wäre alles wieder so wie es war.","sourceLineIndex":36,"ipa":"/vˈɛːrə ˈaləs vˈiːdɜ zoː viː ɛs vɑːɾ/","en":"Everything would be the way it was again.","zh":"一切便又能回到从前","note":""},{"id":"rebecca-das-musical-39-037","lineIndex":35,"speaker":"","original":"Ich sah ins Blau mit dem Fahrtwind in den Haaren","sourceLineIndex":37,"ipa":"/ɪç zˈɑː ɪns blˈaʊ mɪt deːm fˈɑːɾtvɪnt ɪn deːn hˈɑːrən/","en":"I looked into the blue with the wind in my hair","zh":"我望着蓝天 任风吹起我的长发","note":""},{"id":"rebecca-das-musical-39-038","lineIndex":36,"speaker":"","original":"Und hab mir ausgemalt, wie schön es wär","sourceLineIndex":38,"ipa":"/ʊnt hˈɑːp miːɾ ˈaʊsɡəmˌɑːllt viː ʃˈøːn ɛs vˈɛːɾ/","en":"And I imagined how nice it would be","zh":"沉溺于自己的幻想之中 希望自己","note":""},{"id":"rebecca-das-musical-39-039","lineIndex":37,"speaker":"","original":"Könnt ich dir geben was dir fehlt.","sourceLineIndex":39,"ipa":"/kˌœnt ɪç diːɾ ɡˈeːbən vˈas diːɾ fˈeːlt/","en":"Can I give you what you're missing?","zh":"变成那个配得上你的女人","note":""},{"id":"rebecca-das-musical-39-040","lineIndex":38,"speaker":"","original":"Und du hast wohl geahnt, woran ich denke.","sourceLineIndex":40,"ipa":"/ʊnt duː hast vˈoːl ɡəˈɑːnt voːrˈan ɪç dˈɛŋkə/","en":"And you probably guessed what I was thinking about.","zh":"你一定是看出了我的心思","note":""},{"id":"rebecca-das-musical-39-041","lineIndex":39,"speaker":"","original":"Du hast gesagt? Ich mag dich wie du bist?","sourceLineIndex":41,"ipa":"/duː hast ɡəzˈɑːkt ɪç mˈɑːk dɪç viː duː bɪst/","en":"You said? I like you the way you are?","zh":"你还记得你说过“我就喜欢你现在的样子”","note":""},{"id":"rebecca-das-musical-39-042","lineIndex":40,"speaker":"","original":"Barfuß gingen wir am Strand","sourceLineIndex":42,"ipa":"/bˈaɾfuːs ɡˈɪŋən viːɾ am ʃtɾˈant/","en":"We walked barefoot on the beach","zh":"我们赤脚走在沙滩上","note":""},{"id":"rebecca-das-musical-39-043","lineIndex":41,"speaker":"","original":"Sonnenstrahlen tanzten auf dem Meer","sourceLineIndex":43,"ipa":"/zˈɔnənstɾˌɑːlən tˈantstən aʊf deːm mˈeːɾ/","en":"Rays of sunshine danced on the sea","zh":"阳光在海面上舞蹈","note":""},{"id":"rebecca-das-musical-39-044","lineIndex":42,"speaker":"","original":"Und du hast mich angesehn","sourceLineIndex":44,"ipa":"/ʊnt duː hast mɪç ˈanɡəzˌeːn/","en":"And you looked at me","zh":"你望向我","note":""},{"id":"rebecca-das-musical-39-045","lineIndex":43,"speaker":"","original":"Als ob du Hilfe brauchst","sourceLineIndex":45,"ipa":"/als ˌɔp duː hˈɪlfə bɾˈaʊxst/","en":"As if you need help","zh":"眼神似是在向我求救","note":""},{"id":"rebecca-das-musical-39-046","lineIndex":44,"speaker":"","original":"Dann hast du mich geküsst.","sourceLineIndex":46,"ipa":"/dan hast duː mɪç ɡəkˈʏst/","en":"Then you kissed me.","zh":"然后你亲吻了我","note":""},{"id":"rebecca-das-musical-39-047","lineIndex":45,"speaker":"","original":"Ich wünsch mir ich würde wissen","sourceLineIndex":47,"ipa":"/ɪç vˈʏnʃ miːɾ ɪç vˈʏɾdə vˈɪsən/","en":"I wish I knew","zh":"我多想找个方法","note":""},{"id":"rebecca-das-musical-39-048","lineIndex":46,"speaker":"","original":"Wie man festhält was nicht greifbar ist.","sourceLineIndex":48,"ipa":"/viː man fˈɛsthˌɛlt vˈas nˈɪçt ɡɾˈaɪfbɑːɾ ɪst/","en":"How to capture what is intangible.","zh":"能让时间永不消逝","note":""},{"id":"rebecca-das-musical-39-049","lineIndex":47,"speaker":"","original":"Den Zauber eines Blicks","sourceLineIndex":49,"ipa":"/deːn tsˈaʊbɜ ˌaɪnəs blˈɪks/","en":"The magic of a glance","zh":"那充满魔力的眼神","note":""},{"id":"rebecca-das-musical-39-050","lineIndex":48,"speaker":"","original":"Die Wahrheit eines Traums.","sourceLineIndex":50,"ipa":"/diː vˈɑːɾhaɪt ˌaɪnəs tɾˈaʊms/","en":"The truth of a dream.","zh":"那恍若真实的梦幻","note":""},{"id":"rebecca-das-musical-39-051","lineIndex":49,"speaker":"","original":"Das Wunder des Verstehns.","sourceLineIndex":51,"ipa":"/das vˈʊndɜ dɛs fɛɾʃtˈeːns/","en":"The miracle of understanding.","zh":"那理解的奇迹","note":""},{"id":"rebecca-das-musical-39-052","lineIndex":50,"speaker":"","original":"Denn würd ich wissen","sourceLineIndex":52,"ipa":"/dɛn vˈʏɾt ɪç vˈɪsən/","en":"Because I would know","zh":"我多想能够","note":""},{"id":"rebecca-das-musical-39-053","lineIndex":51,"speaker":"","original":"Wie man Glück in eine Flasche füllt","sourceLineIndex":53,"ipa":"/viː man ɡlˈʏk ɪn ˌaɪnə flˈaʃə fˈʏlt/","en":"How to put happiness in a bottle","zh":"把幸福装进瓶子里","note":""},{"id":"rebecca-das-musical-39-054","lineIndex":52,"speaker":"","original":"Müsst ich sie nur öffnen und schon","sourceLineIndex":54,"ipa":"/mˈʏst ɪç ziː nˈuːɾ ˈœfnən ʊnt ʃˈoːn/","en":"I just have to open it and that's it","zh":"只需拧开瓶盖","note":""},{"id":"rebecca-das-musical-39-055","lineIndex":53,"speaker":"","original":"Wäre jeder Moment wieder wahr.","sourceLineIndex":55,"ipa":"/vˈɛːrə jˈeːdɜ moːmˈɛnt vˈiːdɜ vˈɑːɾ/","en":"Every moment would be true again.","zh":"旧时光又回到从前","note":""},{"id":"rebecca-das-musical-39-056","lineIndex":54,"speaker":"","original":"Mir war ja von Anfang klar, dass es nicht dauern kann","sourceLineIndex":56,"ipa":"/miːɾ vɑːɾ jˈɑː fɔn ˈanfˌaŋ klˈɑːɾ das ɛs nˈɪçt dˈaʊɜn kˌan/","en":"It was clear to me from the start that it couldn't last","zh":"一开始我就明白幸福的时光不会长久","note":""},{"id":"rebecca-das-musical-39-057","lineIndex":55,"speaker":"","original":"Und doch gibt es nichts zu bereuen.","sourceLineIndex":57,"ipa":"/ʊnt dɔx ɡˈiːpt ɛs nˈɪçts tsuː bərˈɔøən/","en":"And yet there is nothing to regret.","zh":"但我依旧无怨无悔","note":""},{"id":"rebecca-das-musical-39-058","lineIndex":56,"speaker":"","original":"Jedes Bild, jedes Wort lebt in mir fort.","sourceLineIndex":58,"ipa":"/jˈeːdəs bˈɪlt jˈeːdəs vˈɔɾt lˈeːpt ɪn miːɾ fˈɔɾt/","en":"Every image, every word lives on in me.","zh":"每个画面每句话均已铭记在心","note":""},{"id":"rebecca-das-musical-39-059","lineIndex":57,"speaker":"","original":"Ich wünsch mir ich würde wissen","sourceLineIndex":59,"ipa":"/ɪç vˈʏnʃ miːɾ ɪç vˈʏɾdə vˈɪsən/","en":"I wish I knew","zh":"我多想找个方法","note":""},{"id":"rebecca-das-musical-39-060","lineIndex":58,"speaker":"","original":"Wie Erinnerung lebendig bleibt.","sourceLineIndex":60,"ipa":"/viː ɛɾˈɪnərˌʊŋ leːbˈɛndɪç blˈaɪpt/","en":"How memories stay alive.","zh":"能让回忆鲜活如昔","note":""},{"id":"rebecca-das-musical-39-061","lineIndex":59,"speaker":"","original":"Wie man den Augenblick","sourceLineIndex":61,"ipa":"/viː man deːn ˈaʊɡənblˌɪk/","en":"How to capture the moment","zh":"能让这包含千言万语的眼神","note":""},{"id":"rebecca-das-musical-39-062","lineIndex":60,"speaker":"","original":"In dem die Sehnsucht starb","sourceLineIndex":62,"ipa":"/ɪn deːm diː zˈeːnzuːxt ʃtˈaɾp/","en":"In which the longing died","zh":"在这一刻","note":""},{"id":"rebecca-das-musical-39-063","lineIndex":61,"speaker":"","original":"Vor dem Vergehn bewahrt.","sourceLineIndex":63,"ipa":"/fˌɔɾ deːm fɛɾɡˈeːn bəvˈɑːɾt/","en":"Protected from offense.","zh":"凝成永恒","note":""},{"id":"rebecca-das-musical-39-064","lineIndex":62,"speaker":"","original":"Und dass ich dich verlier","sourceLineIndex":64,"ipa":"/ʊnt das ɪç dɪç fɛɾlˈiːɾ/","en":"And that I lose you","zh":"这样就算我失去了你","note":""},{"id":"rebecca-das-musical-39-065","lineIndex":63,"speaker":"","original":"Fiele mir nicht ganz so schwer","sourceLineIndex":65,"ipa":"/fˈiːlə miːɾ nˈɪçt ɡˌants zoː ʃvˈeːɾ/","en":"It wasn't that difficult for me","zh":"我也不用伤心欲绝","note":""},{"id":"rebecca-das-musical-39-066","lineIndex":64,"speaker":"","original":"Bliebe mir die Zeit in einer Flasche","sourceLineIndex":66,"ipa":"/blˈiːbə miːɾ diː tsˈaɪt ɪn ˌaɪnɜ flˈaʃə/","en":"I have time left in a bottle","zh":"因为我还有那瓶子里的时光","note":""},{"id":"rebecca-das-musical-39-067","lineIndex":65,"speaker":"","original":"Die Zeit die ich hatte mit dir.","sourceLineIndex":67,"ipa":"/diː tsˈaɪt diː ɪç hˌatə mɪt dˈiːɾ/","en":"The time I had with you.","zh":"那些我还拥有你的时光","note":""},{"id":"rebecca-das-musical-39-068","lineIndex":66,"speaker":"","original":"Lass die Flasche Lieber zu.","sourceLineIndex":68,"ipa":"/lˈas diː flˈaʃə lˈiːbɜ tsˈuː/","en":"Better leave the bottle closed.","zh":"最好别把瓶子打开","note":""},{"id":"rebecca-das-musical-39-069","lineIndex":67,"speaker":"","original":"Manchmal steckt ein Daemon drin.","sourceLineIndex":69,"ipa":"/mˈançmɑːl ʃtˈɛkt aɪn dˈɛːmoːn dɾˈiːn/","en":"Sometimes there is a daemon inside.","zh":"有时候瓶子里面装着妖怪","note":""},{"id":"rebecca-das-musical-39-070","lineIndex":68,"speaker":"","original":"Maxim!","sourceLineIndex":70,"ipa":"/mˈaksiːm/","en":"Max!","zh":"马克西姆","note":""},{"id":"rebecca-das-musical-39-071","lineIndex":69,"speaker":"","original":"Wie gut, dich noch einmal zu sehen.","sourceLineIndex":71,"ipa":"/viː ɡˈuːt dɪç nɔx ˈaɪnmˌɑːl tsuː zˈeːən/","en":"How good to see you again.","zh":"真好，我还能见你一面","note":""},{"id":"rebecca-das-musical-39-072","lineIndex":70,"speaker":"","original":"Mrs. Van Hopper will abreisen.","sourceLineIndex":72,"ipa":"/ˌɛmˌɛrˈɛs vˈɑːn hˈɔpɜ vɪl ˈapɾˌaɪzən/","en":"Mrs. Van Hopper wants to leave.","zh":"凡霍珀夫人要走了","note":""},{"id":"rebecca-das-musical-39-073","lineIndex":71,"speaker":"","original":"Wir fahren nach New York.","sourceLineIndex":73,"ipa":"/viːɾ fˈɑːrən nɑːx njˈuː jˈɔɾk/","en":"We're going to New York.","zh":"我们要去纽约","note":""},{"id":"rebecca-das-musical-39-074","lineIndex":72,"speaker":"","original":"Und du begleitest sie?","sourceLineIndex":74,"ipa":"/ʊnt duː bəɡlˈaɪtəst ziː/","en":"And you accompany her?","zh":"你要陪着她去","note":""},{"id":"rebecca-das-musical-39-075","lineIndex":73,"speaker":"","original":"Ich muss.","sourceLineIndex":75,"ipa":"/ɪç mˈʊs/","en":"I have to.","zh":"我不能不去","note":""},{"id":"rebecca-das-musical-39-076","lineIndex":74,"speaker":"","original":"Du weiss, ich bin ihre Angestellte.","sourceLineIndex":76,"ipa":"/duː vˈaɪs ɪç bɪn ˌiːrə ˈanɡəʃtˌɛltə/","en":"You know I'm her employee.","zh":"你知道，我是她雇来的","note":""},{"id":"rebecca-das-musical-39-077","lineIndex":75,"speaker":"","original":"Ich kann es mir nicht leisten, waehlerisch zu sein.","sourceLineIndex":77,"ipa":"/ɪç kˌan ɛs miːɾ nˈɪçt lˈaɪstən vˈɛhlərˌɪʃ tsuː zaɪn/","en":"I can't afford to be picky.","zh":"我没有立场对她说不","note":""},{"id":"rebecca-das-musical-39-078","lineIndex":76,"speaker":"","original":"Na gut.","sourceLineIndex":78,"ipa":"/nˈɑː ɡˈuːt/","en":"All right.","zh":"好吧","note":""},{"id":"rebecca-das-musical-39-079","lineIndex":77,"speaker":"","original":"Mrs. Van Hopper will also wieder heim.","sourceLineIndex":79,"ipa":"/ˌɛmˌɛrˈɛs vˈɑːn hˈɔpɜ vɪl ˈalzoː vˈiːdɜ hˈaɪm/","en":"So Mrs. Van Hopper wants to go home.","zh":"凡霍珀夫人要回家了","note":""},{"id":"rebecca-das-musical-39-080","lineIndex":78,"speaker":"","original":"Ich auch.","sourceLineIndex":80,"ipa":"/ɪç ˈaʊx/","en":"Me too.","zh":"我也是","note":""},{"id":"rebecca-das-musical-39-081","lineIndex":79,"speaker":"","original":"Sie faehrt nach New York, und ich nach Manderley.","sourceLineIndex":81,"ipa":"/ziː fˈɛhɾt nɑːx njˈuː jˈɔɾk ʊnt ɪç nɑːx mˈandɜlˌaɪ/","en":"She's going to New York and I'm going to Manderley.","zh":"她去纽约，我回曼德雷","note":""},{"id":"rebecca-das-musical-39-082","lineIndex":80,"speaker":"","original":"Wo moechtest du hin?","sourceLineIndex":82,"ipa":"/vˌoː mˈœçtəst duː hˈɪn/","en":"Where do you want to go?","zh":"你选哪边","note":""},{"id":"rebecca-das-musical-39-083","lineIndex":81,"speaker":"","original":"Du kannst waehlen.","sourceLineIndex":83,"ipa":"/duː kˌanst vˈɛhlən/","en":"You can choose.","zh":"自己做主","note":""},{"id":"rebecca-das-musical-39-084","lineIndex":82,"speaker":"","original":"Bitte, Maxim!","sourceLineIndex":84,"ipa":"/bˈɪtə mˈaksiːm/","en":"Please, Maxim!","zh":"别这样，马克西姆","note":""},{"id":"rebecca-das-musical-39-085","lineIndex":83,"speaker":"","original":"Lass die Scherze.","sourceLineIndex":85,"ipa":"/lˈas diː ʃˈɛɾtsə/","en":"Stop the jokes.","zh":"别开玩笑","note":""},{"id":"rebecca-das-musical-39-086","lineIndex":84,"speaker":"","original":"Mach es mir nicht noch schwerer.","sourceLineIndex":86,"ipa":"/mˈax ɛs miːɾ nˈɪçt nɔx ʃvˈeːrɜ/","en":"Don't make it any harder for me.","zh":"别让我更伤心了","note":""},{"id":"rebecca-das-musical-39-087","lineIndex":85,"speaker":"","original":"Vor dem Fruehstueck mache ich nie Scherze.","sourceLineIndex":87,"ipa":"/fˌɔɾ deːm frˈuːeːstˌuːɛk mˈaxə ɪç nˈiː ʃˈɛɾtsə/","en":"I never joke before breakfast.","zh":"早餐之前我从不看玩笑","note":""},{"id":"rebecca-das-musical-39-088","lineIndex":86,"speaker":"","original":"Entscheide dich","sourceLineIndex":88,"ipa":"/ɛntʃˈaɪdə dˈɪç/","en":"Make up your mind","zh":"你做决定吧","note":""},{"id":"rebecca-das-musical-39-089","lineIndex":87,"speaker":"","original":"New York oder Manderley.","sourceLineIndex":89,"ipa":"/njˈuː jˈɔɾk ˌoːdɜ mˈandɜlˌaɪ/","en":"New York or Manderley.","zh":"纽约还是曼德雷","note":""},{"id":"rebecca-das-musical-39-090","lineIndex":88,"speaker":"","original":"Soll das heissen, du bietest mir eine Stellung an…","sourceLineIndex":90,"ipa":"/zˌɔl das hˈaɪsən duː bˈiːtəst miːɾ ˌaɪnə ʃtˈɛlʊŋ ˈan/","en":"Does that mean you're offering me a position...","zh":"你的意思是，你要给我一份工作……","note":""},{"id":"rebecca-das-musical-39-091","lineIndex":89,"speaker":"","original":"Als deine Sekretaerin oder so?","sourceLineIndex":91,"ipa":"/als dˌaɪnə zˈɛkɾeːtˌɛːrɪn ˌoːdɜ zˈoː/","en":"As your secretary or something?","zh":"做你的秘书还是什么？","note":""},{"id":"rebecca-das-musical-39-092","lineIndex":90,"speaker":"","original":"Aber nein","sourceLineIndex":92,"ipa":"/ˌɑːbɜ nˈaɪn/","en":"But no","zh":"不","note":""},{"id":"rebecca-das-musical-39-093","lineIndex":91,"speaker":"","original":"Ich frag dich, ob du mich heiraten willst.","sourceLineIndex":93,"ipa":"/ɪç frˈɑːk dˈɪç ˌɔp duː mɪç haɪrˈɑːtən vɪlst/","en":"I'm asking you if you want to marry me.","zh":"我再问你，你愿意嫁给我吗？","note":""},{"id":"rebecca-das-musical-39-094","lineIndex":92,"speaker":"","original":"…was?……","sourceLineIndex":94,"ipa":"/vˈas/","en":"…what?……","zh":"什么","note":""},{"id":"rebecca-das-musical-39-095","lineIndex":93,"speaker":"","original":"Ich will, dass du meine Frau wirst.","sourceLineIndex":95,"ipa":"/ˈɪç vɪl das duː mˌaɪnə frˈaʊ vˌɪɾst/","en":"I want you to be my wife.","zh":"我想要你成为我的妻子","note":""},{"id":"rebecca-das-musical-39-096","lineIndex":94,"speaker":"","original":"Was haelst du davon?","sourceLineIndex":96,"ipa":"/vˈas hˈɑːɛlst duː dɑːfˈɔn/","en":"What do you make of it?","zh":"意下如何","note":""},{"id":"rebecca-das-musical-39-097","lineIndex":95,"speaker":"","original":"Ich weiss nicht.","sourceLineIndex":97,"ipa":"/ɪç vˈaɪs nˈɪçt/","en":"I don't know.","zh":"我不知道","note":""},{"id":"rebecca-das-musical-39-098","lineIndex":96,"speaker":"","original":"Ich gehoer doch nicht in deine Welt.","sourceLineIndex":98,"ipa":"/ɪç ɡəhˈøːɾ dɔx nˈɪçt ɪn dˌaɪnə vˈɛlt/","en":"I don't belong in your world.","zh":"我跟你不属于一个世界","note":""},{"id":"rebecca-das-musical-39-099","lineIndex":97,"speaker":"","original":"Also nein.","sourceLineIndex":99,"ipa":"/ˈalzoː nˈaɪn/","en":"So no.","zh":"原来如此","note":""},{"id":"rebecca-das-musical-39-100","lineIndex":98,"speaker":"","original":"Und ich dachte, du liebst mich.","sourceLineIndex":100,"ipa":"/ʊnt ɪç dˈaxtə duː lˈiːpst mɪç/","en":"And I thought you loved me.","zh":"我还以为你爱我呢","note":""},{"id":"rebecca-das-musical-39-101","lineIndex":99,"speaker":"","original":"Aber das tu ich ja!","sourceLineIndex":101,"ipa":"/ˌɑːbɜ das tˈuː ɪç jˈɑː/","en":"But I do!","zh":"我的确爱你","note":""},{"id":"rebecca-das-musical-39-102","lineIndex":100,"speaker":"","original":"Ich liebe dich. Mehr als alles auf der Welt!","sourceLineIndex":102,"ipa":"/ɪç lˈiːbə dˈɪç mˈeːɾ als ˈaləs aʊf dɛɾ vˈɛlt/","en":"I love you. More than anything in the world!","zh":"我爱你胜过世上的一切","note":""},{"id":"rebecca-das-musical-39-103","lineIndex":101,"speaker":"","original":"Und Manderley wird dir gefallen.","sourceLineIndex":103,"ipa":"/ʊnt mˈandɜlˌaɪ vˌɪɾt diːɾ ɡəfˈalən/","en":"And you will like Manderley.","zh":"你一定会喜欢曼德雷的","note":""},{"id":"rebecca-das-musical-39-104","lineIndex":102,"speaker":"","original":"Bist du soweit?","sourceLineIndex":104,"ipa":"/bɪst duː zoːvˈaɪt/","en":"Are you ready?","zh":"你准备好了吗","note":""},{"id":"rebecca-das-musical-39-105","lineIndex":103,"speaker":"","original":"Wir muessen noch die…","sourceLineIndex":105,"ipa":"/viːɾ mˈuːɛsən nɔx diː/","en":"We still have to...","zh":"我们还得……","note":""},{"id":"rebecca-das-musical-39-106","lineIndex":104,"speaker":"","original":"Oooooh, Mr. de Winter!","sourceLineIndex":106,"ipa":"/ˈoːoːˌoː ˌɛmˈɛɾ dˈeː vˈɪntɜ/","en":"Oooooh, Mr. de Winter!","zh":"哦—德温特先生","note":""},{"id":"rebecca-das-musical-39-107","lineIndex":105,"speaker":"","original":"Was suer eine unerwartete Freude!","sourceLineIndex":107,"ipa":"/vˈas zˈuːɜ ˌaɪnə ˈʊnɛɾvˌaɾtətə frˈɔødə/","en":"What an unexpected joy!","zh":"真是个意外的惊喜","note":""},{"id":"rebecca-das-musical-39-108","lineIndex":106,"speaker":"","original":"Sie sind gekommen nun mir Adieu zu sagen?","sourceLineIndex":108,"ipa":"/ziː zɪnt ɡəkˈɔmən nˈuːn miːɾ ˈɑdiːˌuː tsuː zˈɑːɡən/","en":"Have you come to say goodbye to me?","zh":"您来跟我道别吗","note":""},{"id":"rebecca-das-musical-39-109","lineIndex":107,"speaker":"","original":"Wie nett von Ihnen.","sourceLineIndex":109,"ipa":"/viː nˈɛt fɔn ˈiːnən/","en":"How kind of you.","zh":"您对我真是太好了","note":""},{"id":"rebecca-das-musical-39-110","lineIndex":108,"speaker":"","original":"Um ehrlich zu sein, wollte ich Ihnen nur mitteilen…(Ja, ja)","sourceLineIndex":110,"ipa":"/ʊm ˈeːɾlɪç tsuː zaɪn vɔltə ɪç ˌiːnən nˈuːɾ mˈɪttaɪlən jˈɑː jˈɑː/","en":"To be honest, I just wanted to let you know... (Yes, yes)","zh":"我是来为了告诉您……","note":""},{"id":"rebecca-das-musical-39-111","lineIndex":109,"speaker":"","original":"Ihre Gesellschafterin wird Sie nicht nach New York begleiten koennen.","sourceLineIndex":111,"ipa":"/ˌiːrə ɡəzˈɛlʃaftərˌɪn vˌɪɾt ziː nˈɪçt nɑːx njˈuː jˈɔɾk bəɡlˈaɪtən kˈœnən/","en":"Your partner will not be able to accompany you to New York.","zh":"您的女伴不能陪您回纽约了","note":""},{"id":"rebecca-das-musical-39-112","lineIndex":110,"speaker":"","original":"Wieso das?","sourceLineIndex":112,"ipa":"/vˈiːzoː das/","en":"How come?","zh":"为什么","note":""},{"id":"rebecca-das-musical-39-113","lineIndex":111,"speaker":"","original":"Wir heiraten.","sourceLineIndex":113,"ipa":"/viːɾ haɪrˈɑːtən/","en":"We are going to marry.","zh":"我们要结婚了","note":""},{"id":"rebecca-das-musical-39-114","lineIndex":112,"speaker":"","original":"Ah, ja…WAS??!","sourceLineIndex":114,"ipa":"/ˈɑː jˈɑː vˈas/","en":"Ah, yes…WHAT??!","zh":"啊，是的……什么？","note":""},{"id":"rebecca-das-musical-39-115","lineIndex":113,"speaker":"","original":"Wie bitte…?","sourceLineIndex":115,"ipa":"/viː bˈɪtə/","en":"I'm sorry, what…?","zh":"您说……什么","note":""},{"id":"rebecca-das-musical-39-116","lineIndex":114,"speaker":"","original":"Ich wuensche Ihnen eine hute Reise.","sourceLineIndex":116,"ipa":"/ɪç vˈuːɛnʃə ˌiːnən ˌaɪnə hˈuːtə rˈaɪzə/","en":"I wish you a safe journey.","zh":"祝您一路顺风","note":""},{"id":"rebecca-das-musical-39-117","lineIndex":115,"speaker":"","original":"Gruessen Sie New York von uns.","sourceLineIndex":117,"ipa":"/ɡɾˈuːɛsən ziː njˈuː jˈɔɾk fɔn ˈʊns/","en":"Say hello to New York from us.","zh":"代我们向纽约问好","note":""},{"id":"rebecca-das-musical-39-118","lineIndex":116,"speaker":"","original":"Ich hasse inzwischen dein Gpaeck auf meine Suite bringen.","sourceLineIndex":118,"ipa":"/ɪç hˈasə ɪntsvˈɪʃən daɪn ɡˈeːpˈɛk aʊf mˌaɪnə swˈiːt bɾˈɪŋən/","en":"I now hate bringing your luggage to my suite.","zh":"我这就把你的行李拿到我的套房去","note":""},{"id":"rebecca-das-musical-39-119","lineIndex":117,"speaker":"","original":"Offenbar hab ich dich unterschaetzt.","sourceLineIndex":119,"ipa":"/ˈɔfənbˌɑːɾ hˈɑːp ɪç dɪç ˌʊntɜʃˈɛtst/","en":"Apparently I underestimated you.","zh":"看来我真是小瞧了你","note":""},{"id":"rebecca-das-musical-39-120","lineIndex":118,"speaker":"","original":"Weiss Gott, stille Wasser sind tief.","sourceLineIndex":120,"ipa":"/vˈaɪs ɡˈɔt ʃtˈɪlə vˈasɜ zɪnt tˈiːf/","en":"God knows, still waters run deep.","zh":"不鸣则已，鸣惊人啊","note":""},{"id":"rebecca-das-musical-39-121","lineIndex":119,"speaker":"","original":"Tennisstunden, das ich nicht lache!","sourceLineIndex":121,"ipa":"/tˈɛnɪsʃtˌʊndən das ɪç nˈɪçt lˈaːxə/","en":"Tennis lessons that I don't laugh about!","zh":"你也要去打网球，简直笑死人了","note":""},{"id":"rebecca-das-musical-39-122","lineIndex":120,"speaker":"","original":"Du hast mich hintergangen.","sourceLineIndex":122,"ipa":"/duː hast mɪç hˌɪntɜɡˈaŋən/","en":"You betrayed me.","zh":"居然把我蒙在鼓里","note":""},{"id":"rebecca-das-musical-39-123","lineIndex":121,"speaker":"","original":"Dass Sie das danken, Mrs. van Hopper","sourceLineIndex":123,"ipa":"/das ziː das dˈaŋkən ˌɛmˌɛrˈɛs vˈɑːn hˈɔpɜ/","en":"Thank you for that, Mrs. van Hopper","zh":"您要是这么想，凡霍珀夫人","note":""},{"id":"rebecca-das-musical-39-124","lineIndex":122,"speaker":"","original":"Tut mir leid.","sourceLineIndex":124,"ipa":"/tˈuːt miːɾ lˈaɪt/","en":"I'm sorry.","zh":"我很遗憾","note":""},{"id":"rebecca-das-musical-39-125","lineIndex":123,"speaker":"","original":"Du sollstest dir selbst leid tun.","sourceLineIndex":125,"ipa":"/duː zˌɔlstəst diːɾ zˈɛlpst lˈaɪt tˈuːn/","en":"You should feel sorry for yourself.","zh":"有空还是为你自己感到遗憾吧","note":""},{"id":"rebecca-das-musical-39-126","lineIndex":124,"speaker":"","original":"Was glaubst du den, was dich dazu befaehigt, Herrin von Manderley zu warden?","sourceLineIndex":126,"ipa":"/vˈas ɡlˈaʊpst duː deːn vˈas dɪç dɑːtsˈuː bəfˈɛːhɪçt hˈɛrɪn fɔn mˈandɜlˌaɪ tsuː vˈaɾdən/","en":"What do you think enables you to become Mistress of Manderley?","zh":"你觉得你有那个能耐做曼德雷的女主人","note":""},{"id":"rebecca-das-musical-39-127","lineIndex":125,"speaker":"","original":"Ich liebe ihn.","sourceLineIndex":127,"ipa":"/ɪç lˈiːbə ˈiːn/","en":"I love him.","zh":"我爱他","note":""},{"id":"rebecca-das-musical-39-128","lineIndex":126,"speaker":"","original":"Rebecca de Winter war eine Dame von Welt.","sourceLineIndex":128,"ipa":"/reːbˈɛkɑː dˈeː vˈɪntɜ vɑːɾ ˌaɪnə dˈɑːmə fɔn vˈɛlt/","en":"Rebecca de Winter was a lady of the world.","zh":"丽贝卡·德温特曾一度闻名于世","note":""},{"id":"rebecca-das-musical-39-129","lineIndex":127,"speaker":"","original":"Von ihren Gesellschaften spracht ganz England.","sourceLineIndex":129,"ipa":"/fɔn ˌiːrən ɡəzˈɛlʃaftən ʃpɾˈɑːxt ɡˌants ˈɛŋlant/","en":"All of England spoke about their societies.","zh":"全英格兰都讨论着她的社交圈","note":""},{"id":"rebecca-das-musical-39-130","lineIndex":128,"speaker":"","original":"Ich werde ihn nicht enttaeuschen.","sourceLineIndex":130,"ipa":"/ɪç vˌɛɾdə iːn nˈɪçt ɛnttˈɛːʊʃən/","en":"I won't disappoint him.","zh":"我不会让他失望的","note":""},{"id":"rebecca-das-musical-39-131","lineIndex":129,"speaker":"","original":"Mach dich nicht laecherlich!","sourceLineIndex":131,"ipa":"/mˈax dɪç nˈɪçt lˈɛçɜlˌɪç/","en":"Don't be ridiculous!","zh":"别让我发笑了","note":""},{"id":"rebecca-das-musical-39-132","lineIndex":130,"speaker":"","original":"Lady de Winter, ha!","sourceLineIndex":132,"ipa":"/lˈeɪdi dˈeː vˈɪntɜ hˈɑː/","en":"Lady de Winter, ha!","zh":"德温特夫人，哈","note":""}],"sourceOrder":39,"displayOrder":19},{"order":40,"id":"40-die-neue-mrs-de-winter-ensemble-mrs-danvers-crawley","title":"Die neue Mrs. de Winter","titleZh":"新的德温特夫人","lines":[{"id":"rebecca-das-musical-40-001","lineIndex":1,"speaker":"","original":"Wiener und wisch","sourceLineIndex":1,"ipa":"/vˈiːnɜ ʊnt vˈɪʃ/","en":"Viennese and wipe","zh":"维也纳和擦拭","note":""},{"id":"rebecca-das-musical-40-002","lineIndex":2,"speaker":"","original":"Tisch für Tisch","sourceLineIndex":2,"ipa":"/tˈɪʃ fyːɾ tˈɪʃ/","en":"Table by table","zh":"桌桌椅椅","note":""},{"id":"rebecca-das-musical-40-003","lineIndex":3,"speaker":"","original":"Schrank um Schrank das Holz muss glänzen!","sourceLineIndex":3,"ipa":"/ʃrˈaŋk ʊm ʃrˈaŋk das hˈɔlts mˈʊs ɡlˈɛntsən/","en":"Closet after closet the wood has to shine!","zh":"擦擦拭拭木头必须闪闪发亮","note":""},{"id":"rebecca-das-musical-40-005","lineIndex":4,"speaker":"","original":"Putz und polier","sourceLineIndex":5,"ipa":"/pˈʊts ʊnt poːlˈiːɾ/","en":"Clean and polish","zh":"仔仔细细","note":""},{"id":"rebecca-das-musical-40-006","lineIndex":5,"speaker":"","original":"da und hier","sourceLineIndex":6,"ipa":"/dɑː ʊnt hˈiːɾ/","en":"here and here","zh":"搓搓洗洗","note":""},{"id":"rebecca-das-musical-40-007","lineIndex":6,"speaker":"","original":"Stück für Stück heut kommen sie zurück!","sourceLineIndex":7,"ipa":"/ʃtˈʏk fyːɾ ʃtˈʏk hˈɔøt kˈɔmən ziː tsuːrˈʏk/","en":"Little by little They're coming back today!","zh":"脚步不停他们今天要回来了！","note":""},{"id":"rebecca-das-musical-40-009","lineIndex":7,"speaker":"","original":"Fein und reinsoll es sein für den Herrn von Manderley und die vollkommen neue Mrs. de Winter!","sourceLineIndex":9,"ipa":"/fˈaɪn ʊnt rˈaɪnzɔl ɛs zaɪn fyːɾ deːn hˈɛɾn fɔn mˈandɜlˌaɪ ʊnt diː fɔlkˈɔmən nˈɔøə ˌɛmˌɛrˈɛs dˈeː vˈɪntɜ/","en":"It should be fine and pure for the Lord of Manderley and the all-new Mrs. de Winter!","zh":"一切都得井井有条为了迎接曼德雷的主人以及新一任的德温特夫人","note":""},{"id":"rebecca-das-musical-40-012","lineIndex":8,"speaker":"","original":"Gleich wird man sehn was und wen unser Herr aus Frankreich mitbringt.","sourceLineIndex":12,"ipa":"/ɡlˈaɪç vˌɪɾt man zˈeːn vˈas ʊnt vˈeːn ˌʊnzɜ hˈɛɾ ˌaʊs frˈaŋkɾaɪç mˈɪtbɾˌɪŋt/","en":"You'll see soon what and whom our Lord brings with him from France.","zh":"马上就要揭晓我们的主人从法国带回来的到底是何方神圣","note":""},{"id":"rebecca-das-musical-40-015","lineIndex":9,"speaker":"","original":"Wir glaubten schon dass er immer Witwer bleibt aber wir kriegen hier eine neue Mrs. de Winter.","sourceLineIndex":15,"ipa":"/viːɾ ɡlˈaʊptən ʃˌoːn das ɛɾ ˈɪmɜ vˈɪtvɜ blˈaɪpt ˌɑːbɜ viːɾ kɾˈiːɡən hˈiːɾ ˌaɪnə nˈɔøə ˌɛmˌɛrˈɛs dˈeː vˈɪntɜ/","en":"We believed so that he will always remain a widower but we're getting a new Mrs. de Winter here.","zh":"我们本以为他会孤老终生可现在我们又有了一个德温特夫人","note":""},{"id":"rebecca-das-musical-40-018","lineIndex":10,"speaker":"","original":"Selbst wenn sie eine Fürstin wär","sourceLineIndex":18,"ipa":"/zˈɛlpst vˌɛn ziː ˌaɪnə fˈʏɾstɪn vˈɛːɾ/","en":"Even if she were a princess","zh":"哪怕是个公爵夫人","note":""},{"id":"rebecca-das-musical-40-019","lineIndex":11,"speaker":"","original":"was will sie hier in Manderley","sourceLineIndex":19,"ipa":"/vˈas vɪl ziː hˈiːɾ ɪn mˈandɜlˌaɪ/","en":"what does she want here in Manderley","zh":"也别妄想在曼德雷立足","note":""},{"id":"rebecca-das-musical-40-020","lineIndex":12,"speaker":"","original":"für mich gibt es auf dieser Welt","sourceLineIndex":20,"ipa":"/fyːɾ mɪç ɡˈiːpt ɛs aʊf dˌiːzɜ vˈɛlt/","en":"for me there is in this world","zh":"对我而言这世界上只有","note":""},{"id":"rebecca-das-musical-40-021","lineIndex":13,"speaker":"","original":"nur eine Mrs. de Winter","sourceLineIndex":21,"ipa":"/nˈuːɾ ˌaɪnə ˌɛmˌɛrˈɛs dˈeː vˈɪntɜ/","en":"just a Mrs. de Winter","zh":"一位德温特夫人","note":""},{"id":"rebecca-das-musical-40-022","lineIndex":14,"speaker":"","original":"denn ruht dein Körper auch im Grab","sourceLineIndex":22,"ipa":"/dɛn rˈuːt daɪn kˈœɾpɜ ˌaʊx ɪm ɡɾˈɑːp/","en":"because your body also rests in the grave","zh":"即使你的身体憩息在墓园","note":""},{"id":"rebecca-das-musical-40-023","lineIndex":15,"speaker":"","original":"dein Geist ist noch in Manderley","sourceLineIndex":23,"ipa":"/daɪn ɡˈaɪst ɪst nɔx ɪn mˈandɜlˌaɪ/","en":"your spirit is still in Manderley","zh":"你的灵魂依然留在曼德雷","note":""},{"id":"rebecca-das-musical-40-024","lineIndex":16,"speaker":"","original":"und keine nimmt dir deinen Platz","sourceLineIndex":24,"ipa":"/ʊnt kˈaɪnə nˈɪmt diːɾ dˌaɪnən plˈats/","en":"and no one will take your place","zh":"没人能取代你的位置","note":""},{"id":"rebecca-das-musical-40-025","lineIndex":17,"speaker":"","original":"Niemals!","sourceLineIndex":25,"ipa":"/nˈiːmɑːls/","en":"Never!","zh":"永远没有！","note":""},{"id":"rebecca-das-musical-40-026","lineIndex":18,"speaker":"","original":"Sie kommen an, irgendwann zwischen fünf und sechs vermutlich.","sourceLineIndex":26,"ipa":"/ziː kˈɔmən ˈan ˈɪɾɡəndvˌan tsvˈɪʃən fˈʏnf ʊnt zˈɛks fɛɾmˈuːtlɪç/","en":"They arrive, sometime between five and six probably.","zh":"他们随时可能到达大概五点到六点之间","note":""},{"id":"rebecca-das-musical-40-028","lineIndex":19,"speaker":"","original":"Dinner um Acht?","sourceLineIndex":28,"ipa":"/dˈɪnɜ ʊm ˈaxt/","en":"Dinner at eight?","zh":"晚餐在八点？","note":""},{"id":"rebecca-das-musical-40-029","lineIndex":20,"speaker":"","original":"Früher geht es nicht.","sourceLineIndex":29,"ipa":"/frˈyːɜ ɡˈeːt ɛs nˈɪçt/","en":"It can't be done earlier.","zh":"没法提前","note":""},{"id":"rebecca-das-musical-40-030","lineIndex":21,"speaker":"","original":"Das ist zu spät!","sourceLineIndex":30,"ipa":"/das ɪst tsuː ʃpˈɛːt/","en":"That's too late!","zh":"太晚了！","note":""},{"id":"rebecca-das-musical-40-031","lineIndex":22,"speaker":"","original":"Das Appartement?","sourceLineIndex":31,"ipa":"/das ˌapaɾteːmˈɛnt/","en":"The apartment?","zh":"房间布置好了？","note":""},{"id":"rebecca-das-musical-40-032","lineIndex":23,"speaker":"","original":"Blumen stehn, Lüster strahlen, im Kamin das Feuer brennt","sourceLineIndex":32,"ipa":"/blˈʊmən ʃtˈeːn lˈʏstɜ ʃtɾˈɑːlən ɪm kamˈiːn das fˈɔøɜ bɾˈɛnt/","en":"Flowers are standing, chandeliers are shining, the fire is burning in the fireplace","zh":"摆上了鲜花，吊灯闪闪亮，壁炉里炭火暖洋洋","note":""},{"id":"rebecca-das-musical-40-033","lineIndex":24,"speaker":"","original":"Für die neue Mrs. de Winter","sourceLineIndex":33,"ipa":"/fyːɾ diː nˈɔøə ˌɛmˌɛrˈɛs dˈeː vˈɪntɜ/","en":"For the new Mrs. de Winter","zh":"为了我们新的德温特夫人","note":""},{"id":"rebecca-das-musical-40-034","lineIndex":25,"speaker":"","original":"Wie wird sie sein, Kühl und fein oder hart und überheblich","sourceLineIndex":34,"ipa":"/viː vˈɪɾt ziː zaɪn kˈyːl ʊnt fˈaɪn ˌoːdɜ hˈaɾt ʊnt ˌyːbɜhˈeːplɪç/","en":"What will she be like, cool and refined or hard and arrogant","zh":"她会是什么样？文静高雅？还是骄傲自负？","note":""},{"id":"rebecca-das-musical-40-035","lineIndex":26,"speaker":"","original":"mischt sie sich ein oder hält sie sich zurück","sourceLineIndex":35,"ipa":"/mˈɪʃt ziː zɪç aɪn ˌoːdɜ hˈɛlt ziː zɪç tsuːrˈʏk/","en":"does she get involved or does she hold back","zh":"她喜欢指手画脚还是不管不问？","note":""},{"id":"rebecca-das-musical-40-036","lineIndex":27,"speaker":"","original":"sicher ist nur sie wird unsere neue Mrs. de Winter","sourceLineIndex":36,"ipa":"/zˈɪçɜ ɪst nˈuːɾ ziː vˌɪɾt ˌʊnzrə nˈɔøə ˌɛmˌɛrˈɛs dˈeː vˈɪntɜ/","en":"One thing is certain: she will be our new Mrs. de Winter","zh":"不论如何，她将是我们新的德温特夫人","note":""},{"id":"rebecca-das-musical-40-037","lineIndex":28,"speaker":"","original":"Potter rief an sie passierten das Tor im Cabrio grad als es anfing zu regnen.","sourceLineIndex":37,"ipa":"/pˈɔtɜ rˈiːf an ziː pasˈiːɾtən das tˈoːɾ ɪm kˈabɾɪˌoː ɡɾˈɑːt als ɛs ˈanfˌɪŋ tsuː rˈɛɡnən/","en":"Potter called and they passed the gate in the convertible just as it started to rain.","zh":"波特打电话说他们的敞篷汽车通过大门时开始下雨了。","note":""},{"id":"rebecca-das-musical-40-038","lineIndex":29,"speaker":"","original":"Ankunft bei Regen das bringt sicher Unglück.","sourceLineIndex":38,"ipa":"/ˈankˌʊnft baɪ rˈeːɡən das bɾˈɪŋt zˈɪçɜ ˈʊnɡlˌʏk/","en":"Arriving in the rain will definitely bring bad luck.","zh":"下雨天回家可不是好兆头","note":""},{"id":"rebecca-das-musical-40-039","lineIndex":30,"speaker":"","original":"Jetzt kommt der Wagen herraus aus dem Wald","sourceLineIndex":39,"ipa":"/jˌɛtst kˈɔmt dɛɾ vˈɑːɡən hˈɛraʊs ˌaʊs deːm vˈalt/","en":"Now the car comes out of the forest","zh":"车正从树林里开出来","note":""},{"id":"rebecca-das-musical-40-040","lineIndex":31,"speaker":"","original":"das Verdeck ist noch offen, obwohl es doch regnet","sourceLineIndex":40,"ipa":"/das fɛɾdˈɛk ɪst nɔx ˈɔfən ɔpvˈoːl ɛs dɔx rˈɛɡnət/","en":"The top is still open even though it is raining","zh":"虽然外面下着雨，车篷却还敞开着！","note":""},{"id":"rebecca-das-musical-40-041","lineIndex":32,"speaker":"","original":"Angetreten zum Empfang in Reih und Glied!!!","sourceLineIndex":41,"ipa":"/ˈanɡətɾˌeːtən tsʊm ɛmpfˈaŋ ɪn rˈaɪ ʊnt ɡlˈiːt/","en":"Line up for the reception!!!","zh":"全体注意，列队迎接！","note":""},{"id":"rebecca-das-musical-40-042","lineIndex":33,"speaker":"","original":"Ach, du lieber Himmel, Frith! Die ganze Belegschaft!","sourceLineIndex":42,"ipa":"/ˈax duː lˈiːbɜ hˈɪməl frˈɪt diː ɡˈantsə bəlˈeːɡʃaft/","en":"MAXIM (quietly): Oh dear heavens, Frith! The entire staff!","zh":"啊，我的上帝，弗里茨！怎么都在这里！","note":""},{"id":"rebecca-das-musical-40-043","lineIndex":34,"speaker":"","original":"Anweisung von Mrs. Danvers, Sir.","sourceLineIndex":43,"ipa":"/ˈanvˌaɪzʊŋ fɔn ˌɛmˌɛrˈɛs dˈanfɜs zˈiːɾ/","en":"Instructions from Mrs. Danvers, sir.","zh":"丹弗斯夫人的命令，先生","note":""},{"id":"rebecca-das-musical-40-044","lineIndex":35,"speaker":"MAXIM (ZU \"Ich\")","original":"Keine Sorge. Dauert nicht lang.","sourceLineIndex":44,"ipa":"/kˈaɪnə zˈɔɾɡə dˈaʊɜt nˈɪçt lˈaŋ/","en":"Don't worry. Doesn't take long.","zh":"别担心，不会很久","note":""},{"id":"rebecca-das-musical-40-045","lineIndex":36,"speaker":"MAXIM (ZU \"Ich\")","original":"Willkommen, Maxim.","sourceLineIndex":45,"ipa":"/vɪlkˈɔmən mˈaksiːm/","en":"Welcome, Maxim.","zh":"欢迎回家，马克西姆","note":""},{"id":"rebecca-das-musical-40-046","lineIndex":37,"speaker":"MAXIM (ZU \"Ich\")","original":"Frank! Das ist Frank Crawley. Der Verwalter von Manderley, und mein bester Freund.","sourceLineIndex":46,"ipa":"/frˈaŋk das ɪst frˈaŋk kɾˈavlaɪ dɛɾ fɛɾvˈaltɜ fɔn mˈandɜlˌaɪ ʊnt maɪn bˈɛstɜ frˈɔønt/","en":"Frank! This is Frank Crawley. The steward of Manderley, and my best friend.","zh":"弗兰克！这是弗兰克·克劳利。曼德雷的总管事，也是我最好的朋友。","note":""},{"id":"rebecca-das-musical-40-047","lineIndex":38,"speaker":"MAXIM (ZU \"Ich\")","original":"Guten Abend, Mrs. de Winter.","sourceLineIndex":47,"ipa":"/ɡˈuːtən ˈɑːbənt ˌɛmˌɛrˈɛs dˈeː vˈɪntɜ/","en":"Good evening, Mrs. de Winter.","zh":"晚上好，德温特夫人。","note":""},{"id":"rebecca-das-musical-40-048","lineIndex":39,"speaker":"MAXIM (ZU \"Ich\")","original":"Wenn Sie Fragen haben, wenden Sie sich an mich.","sourceLineIndex":48,"ipa":"/vˌɛn ziː frˈɑːɡən hˈɑːbən vˈɛndən ziː zɪç an mɪç/","en":"If you have any questions, contact me.","zh":"如果有什么问题的话，尽管找我。","note":""},{"id":"rebecca-das-musical-40-049","lineIndex":40,"speaker":"MAXIM (ZU \"Ich\")","original":"Freut mich, Mr. Crawley... Frank.","sourceLineIndex":49,"ipa":"/frˈɔøt mɪç ˌɛmˈɛɾ kɾˈavlaɪ frˈaŋk/","en":"My pleasure, Mr. Crawley... Frank.","zh":"非常荣幸，克劳利先生……弗兰克。","note":""},{"id":"rebecca-das-musical-40-050","lineIndex":41,"speaker":"MAXIM (ZU \"Ich\")","original":"Guten Abend. (Pause.) Sie sind neu, nicht wahr? (Pause.)","sourceLineIndex":50,"ipa":"/ɡˈuːtən ˈɑːbənt pˈaʊzə ziː zɪnt nˈɔø nˈɪçt vˈɑːɾ pˈaʊzə/","en":"Good evening. (Pause.) You're new, aren't you? (Pause.)","zh":"晚上好。您是新来的，对吧？","note":""},{"id":"rebecca-das-musical-40-051","lineIndex":42,"speaker":"MAXIM (ZU \"Ich\")","original":"Ah, Mrs. Rutherford, wie geht es Ihnen?","sourceLineIndex":51,"ipa":"/ˈɑː ˌɛmˌɛrˈɛs rˈʊtɜfˌɔɾt viː ɡˈeːt ɛs ˈiːnən/","en":"Ah, Mrs. Rutherford, how are you?","zh":"啊，罗德福特夫人，您还好吗？","note":""},{"id":"rebecca-das-musical-40-052","lineIndex":43,"speaker":"MAXIM (ZU \"Ich\")","original":"Danke, gut Sir. Schön dass Sie wieder da sind.","sourceLineIndex":52,"ipa":"/dˈaŋkə ɡˈuːt zˈiːɾ ʃˈøːn das ziː vˈiːdɜ dɑː zɪnt/","en":"Thank you, good sir. Nice to have you back.","zh":"谢谢，我很好，先生。您回来了真好。","note":""},{"id":"rebecca-das-musical-40-053","lineIndex":44,"speaker":"MAXIM (ZU \"Ich\")","original":"Das ist meine Frau, Mrs. de Winter. Schön, Sie alle wiederzusehen.","sourceLineIndex":53,"ipa":"/das ɪst mˌaɪnə frˈaʊ ˌɛmˌɛrˈɛs dˈeː vˈɪntɜ ʃˈøːn ziː ˈalə viːdɜtsuːzˈeːən/","en":"This is my wife, Mrs. de Winter. Nice to see you all again.","zh":"这是我的妻子，德温特夫人。又见到你们大家了，我很高兴。","note":""},{"id":"rebecca-das-musical-40-054","lineIndex":45,"speaker":"MAXIM (ZU \"Ich\")","original":"Willkommen zuhause, Mr. de Winter.","sourceLineIndex":54,"ipa":"/vɪlkˈɔmən tsuːhˈaʊzə ˌɛmˈɛɾ dˈeː vˈɪntɜ/","en":"Welcome home, Mr. de Winter.","zh":"欢迎回家，德温特先生。","note":""},{"id":"rebecca-das-musical-40-055","lineIndex":46,"speaker":"MAXIM (ZU \"Ich\")","original":"Danke Robert. Das ist unsere Haushälterin, Mrs. Danvers.","sourceLineIndex":55,"ipa":"/dˈaŋkə rˈoːbɜt das ɪst ˌʊnzrə hˈaʊshˌɛltərˌɪn ˌɛmˌɛrˈɛs dˈanfɜs/","en":"Thanks Robert. This is our housekeeper, Mrs. Danvers.","zh":"谢谢，罗伯特。这是我们的管家，丹弗斯夫人。","note":""},{"id":"rebecca-das-musical-40-056-a","lineIndex":47,"speaker":"MAXIM (ZU \"Ich\")","original":"MRS. DANVERS (mustert \"Ich\"): Ich werde Clarice bitten","sourceLineIndex":56,"ipa":"/ˌɛmˌɛrˈɛs dˈanfɜs mˈʊstɜt ɪç ɪç vˌɛɾdə klˈɑriːkə bˈɪtən ˌiːnən tsuːɾ hˈant tsuː ɡˈeːən zˈoːlaŋə iːɾ mˈɛːdçən nˈɔx nˈɪçt dɑː ɪst/","en":"MRS.","zh":"我会派克拉丽丝供您差遣","note":""},{"id":"rebecca-das-musical-40-056-b","lineIndex":48,"speaker":"MAXIM (ZU \"Ich\")","original":"Ihnen zur Hand zu gehen, solange Ihr Mädchen noch nicht da ist.","sourceLineIndex":56,"ipa":"/ˌɛmˌɛrˈɛs dˈanfɜs mˈʊstɜt ɪç ɪç vˌɛɾdə klˈɑriːkə bˈɪtən ˌiːnən tsuːɾ hˈant tsuː ɡˈeːən zˈoːlaŋə iːɾ mˈɛːdçən nˈɔx nˈɪçt dɑː ɪst/","en":"DANVERS (looks at \"I\"): I'll ask Clarice to give you a hand while your girl isn't here yet.","zh":"既然您的贴身女仆不在身边。","note":""},{"id":"rebecca-das-musical-40-057","lineIndex":49,"speaker":"MAXIM (ZU \"Ich\")","original":"Ich... ich habe kein Mädchen.","sourceLineIndex":57,"ipa":"/ˈɪç ɪç hɑːbə kˈaɪn mˈɛːdçən/","en":"I... I don't have a girl.","zh":"我……我没有贴身女仆。","note":""},{"id":"rebecca-das-musical-40-058","lineIndex":50,"speaker":"MAXIM (ZU \"Ich\")","original":"SO?","sourceLineIndex":58,"ipa":"/zˈoː/","en":"SO?","zh":"真的？","note":""},{"id":"rebecca-das-musical-40-059","lineIndex":51,"speaker":"MAXIM (ZU \"Ich\")","original":"Mrs. de Winter ist müde. Ist ihr Zimmer hergerichtet?","sourceLineIndex":59,"ipa":"/ˌɛmˌɛrˈɛs dˈeː vˈɪntɜ ɪst mˈyːdə ɪst iːɾ tsˈɪmɜ hˈɛɾɡeːrˌɪçtət/","en":"Mrs. en Winter is tired. Is your room prepared?","zh":"德温特夫人累了，她的房间准备好了吗？","note":""},{"id":"rebecca-das-musical-40-060","lineIndex":52,"speaker":"MAXIM (ZU \"Ich\")","original":"Jawohl, Mr. de Winter. Wie von Ihnen gewünscht.","sourceLineIndex":60,"ipa":"/jˈɑvoːl ˌɛmˈɛɾ dˈeː vˈɪntɜ viː fɔn ˌiːnən ɡəvˈʏnʃt/","en":"Yes, Mr. de Winter. As requested by you.","zh":"是的，德温特先生。如您所愿。","note":""},{"id":"rebecca-das-musical-40-061","lineIndex":53,"speaker":"MAXIM (ZU \"Ich\")","original":"Die Gästesuite im Ostflügel wurde renoviert.","sourceLineIndex":61,"ipa":"/diː ɡˌɛsteːzuːˈiːtə ɪm ˈɔstflyːɡəl vˌʊɐdə rˌeːnoːvˈiːɾt/","en":"The guest suite in the east wing has been renovated.","zh":"东翼的客房套房已经翻新了。","note":""},{"id":"rebecca-das-musical-40-062","lineIndex":54,"speaker":"MAXIM (ZU \"Ich\")","original":"Die Räume über dem Rosengarten.","sourceLineIndex":62,"ipa":"/diː rˈɔømə ˌyːbɜ deːm rˈoːzənɡˌaɾtən/","en":"The rooms above the rose garden.","zh":"玫瑰园上方的那些房间。","note":""},{"id":"rebecca-das-musical-40-063","lineIndex":55,"speaker":"MAXIM (ZU \"Ich\")","original":"Jeweils ein Schlaf- und Ankleidezimmer für Sie und die gnädige Frau.","sourceLineIndex":63,"ipa":"/jˈeːvaɪls aɪn ʃlˈɑːf ʊnt ˈanklˌaɪdeːtsˌɪmɜ fyːɾ ziː ʊnt diː ɡənˈɛːdɪɡə frˈaʊ/","en":"There is a bedroom and dressing room for you and your lady.","zh":"东厢的那套客房已经重新装修，玫瑰园上面的几间，还有一个睡房和更衣室，已经为您和仁慈的夫人准备好。","note":""},{"id":"rebecca-das-musical-40-064","lineIndex":56,"speaker":"MAXIM (ZU \"Ich\")","original":"Nun, dann führen Sie sie hinauf. Wir sehn uns beim Abendessen, Frank.","sourceLineIndex":64,"ipa":"/nˈuːn dan fˈyːrən ziː ziː hɪnˈaʊf viːɾ zˈeːn ʊns baɪm ˈɑːbəndˌɛsən frˈaŋk/","en":"Well, then lead her up. See you at dinner, Frank.","zh":"那么现在您带她上去。我们晚餐时见，亲爱的。","note":""},{"id":"rebecca-das-musical-40-065","lineIndex":57,"speaker":"MAXIM (ZU \"Ich\")","original":"Madam.","sourceLineIndex":65,"ipa":"/mˈɑdɑːm/","en":"Madam.","zh":"夫人。","note":""},{"id":"rebecca-das-musical-40-066","lineIndex":58,"speaker":"MAXIM (ZU \"Ich\")","original":"Sehr intressant! Allerhand!","sourceLineIndex":66,"ipa":"/zˈeːɾ ˌɪntɾɛsˈant ˈalɜhˌant/","en":"Very interesting! All sorts of things!","zh":"真有意思！难以置信！","note":""},{"id":"rebecca-das-musical-40-067","lineIndex":59,"speaker":"MAXIM (ZU \"Ich\")","original":"Wer von uns hätt das erwartet?","sourceLineIndex":67,"ipa":"/vˈeːɾ fɔn ʊns hˈɛt das ɛɾvˈaɾtət/","en":"Who among us would have expected that?","zh":"谁料到事实竟是这样？","note":""},{"id":"rebecca-das-musical-40-068","lineIndex":60,"speaker":"MAXIM (ZU \"Ich\")","original":"So haben wir uns die Frau nicht vorgestellt!","sourceLineIndex":68,"ipa":"/zoː hˌɑːbən viːɾ ʊns diː frˈaʊ nˈɪçt fˈoːɾɡəʃtˌɛlt/","en":"This is not how we imagined the woman!","zh":"没想到新夫人居然是这副模样！","note":""},{"id":"rebecca-das-musical-40-069","lineIndex":61,"speaker":"MAXIM (ZU \"Ich\")","original":"Doch gleich wie","sourceLineIndex":69,"ipa":"/dɔx ɡlˈaɪç viː/","en":"But no matter how","zh":"不过无论如何","note":""},{"id":"rebecca-das-musical-40-070","lineIndex":62,"speaker":"MAXIM (ZU \"Ich\")","original":"jetzt ist sie unsre neue Mrs. de Winter","sourceLineIndex":70,"ipa":"/jˌɛtst ɪst ziː ˌʊnzrə nˈɔøə ˌɛmˌɛrˈɛs dˈeː vˈɪntɜ/","en":"now she is our new Mrs. de Winter","zh":"她今后就是我们新的德温特夫人","note":""},{"id":"rebecca-das-musical-40-071","lineIndex":63,"speaker":"MAXIM (ZU \"Ich\")","original":"Und man muss sie nehmen wie sie ist","sourceLineIndex":71,"ipa":"/ʊnt man mˈʊs ziː nˈeːmən viː ziː ɪst/","en":"And you have to take it as it is","zh":"我们必须照单全收！","note":""},{"id":"rebecca-das-musical-40-072","lineIndex":64,"speaker":"MAXIM (ZU \"Ich\")","original":"denn in ihr haben wir hier...","sourceLineIndex":72,"ipa":"/dɛn ɪn iːɾ hˌɑːbən viːɾ hˈiːɾ/","en":"because in her we have here...","zh":"因为她今后就是","note":""},{"id":"rebecca-das-musical-40-073","lineIndex":65,"speaker":"MAXIM (ZU \"Ich\")","original":"Unsre neue Mrs. de Winter!","sourceLineIndex":73,"ipa":"/ˌʊnzrə nˈɔøə ˌɛmˌɛrˈɛs dˈeː vˈɪntɜ/","en":"Our new Mrs. de Winter!","zh":"我们新的德温特夫人！","note":""}],"sourceOrder":40,"displayOrder":20},{"order":41,"id":"41-sie-ergibt-sich-nicht-mrs-danvers","title":"Sie ergibt sich nicht","titleZh":"她不会屈服","lines":[{"id":"rebecca-das-musical-41-001","lineIndex":1,"speaker":"","original":"Orchideen sind ganz besondere Blumen manchmal sehen sie aus, als wären sie tot.","sourceLineIndex":1,"ipa":"/ˌɔɾçiːdˈeːən zɪnt ɡˌants bəzˈɔndərə blˈʊmən mˈançmɑːl zˈeːən ziː ˈaʊs als vˈɛːrən ziː tˈoːt/","en":"Orchids are very special flowers sometimes they look like they are dead.","zh":"兰花是一种奇异的花卉有时它们看上去仿佛已完全枯萎","note":""},{"id":"rebecca-das-musical-41-003","lineIndex":2,"speaker":"","original":"Aber irgendwann, ganz unerwartet blühen sie wieder wei? und dunkelrot.","sourceLineIndex":3,"ipa":"/ˌɑːbɜ ˈɪɾɡəndvˌan ɡˌants ˈʊnɛɾvˌaɾtət blˈyːən ziː vˈiːdɜ vˈaɪ ʊnt dˈʊnkəlrˌoːt/","en":"But at some point, completely unexpectedly Are they blooming white again? and dark red.","zh":"但在某时某刻，完全出人意料会再次绽放出纯白和暗红的花蕊","note":""},{"id":"rebecca-das-musical-41-005","lineIndex":3,"speaker":"","original":"Sie starb, sagt man und glaubt daran doch ich wei? es besser.","sourceLineIndex":5,"ipa":"/ziː ʃtˈaɾp zˈɑːkt man ʊnt ɡlˈaʊpt dɑːrˈan dɔx ɪç vˈaɪ ɛs bˈɛsɜ/","en":"She died, they say and believe it but I know? it better.","zh":"人们都以为她已死去没人像我这般了解","note":""},{"id":"rebecca-das-musical-41-007","lineIndex":4,"speaker":"","original":"Sie ergibt sich nicht man besiegt sie nicht sie ist stark, der Macht des Todes unterliegt sie nicht.","sourceLineIndex":7,"ipa":"/ziː ɛɾɡˈiːpt zɪç nˈɪçt man bəzˈiːkt ziː nˈɪçt ziː ɪst ʃtˈaɾk dɛɾ mˈaxt dɛs tˈoːdəs ˌʊntɜlˈiːkt ziː nˈɪçt/","en":"She doesn't surrender you don't defeat her She is strong, she is not subject to the power of death.","zh":"她从不屈服没人能将她征服她是强者，死亡也在她面前却步","note":""},{"id":"rebecca-das-musical-41-010","lineIndex":5,"speaker":"","original":"Nein, man sieht sie nicht","sourceLineIndex":10,"ipa":"/nˈaɪn man zˈiːt ziː nˈɪçt/","en":"No, you don't see her","zh":"不，没人能看得见她","note":""},{"id":"rebecca-das-musical-41-011","lineIndex":6,"speaker":"","original":"doch ich spür, sie ist hier und lebt noch","sourceLineIndex":11,"ipa":"/dɔx ɪç ʃpˈyːɾ ziː ɪst hˈiːɾ ʊnt lˈeːpt nɔx/","en":"but I feel she is here and still alive","zh":"只有我能感到，她依然活在我们身边","note":""},{"id":"rebecca-das-musical-41-012","lineIndex":7,"speaker":"","original":"sie hört uns, sie sieht uns.","sourceLineIndex":12,"ipa":"/ziː hˈœɾt ˈʊns ziː zˈiːt ˈʊns/","en":"she hears us, she sees us.","zh":"她在倾听我们，在注视我们","note":""},{"id":"rebecca-das-musical-41-013","lineIndex":8,"speaker":"","original":"Sie ergibt sich nicht.","sourceLineIndex":13,"ipa":"/ziː ɛɾɡˈiːpt zɪç nˈɪçt/","en":"She doesn't surrender.","zh":"她从不屈服","note":""},{"id":"rebecca-das-musical-41-014","lineIndex":9,"speaker":"","original":"Orchideen waren ihre Lieblingsblumen","sourceLineIndex":14,"ipa":"/ˌɔɾçiːdˈeːən vɑːrən ˌiːrə lˈiːblɪŋsblˌʊmən/","en":"Orchids were her favorite flowers","zh":"兰花是她最爱的花卉","note":""},{"id":"rebecca-das-musical-41-015","lineIndex":10,"speaker":"","original":"rätselhaft wie sie und fremdartig schön","sourceLineIndex":15,"ipa":"/rˈɛtzəlhˌaft viː ziː ʊnt frˈɛmdaɾtˌɪç ʃˈøːn/","en":"enigmatic like her and strangely beautiful","zh":"像她般神秘莫测，仪态万千","note":""},{"id":"rebecca-das-musical-41-016","lineIndex":11,"speaker":"","original":"und auch die verblühten und verdorrten","sourceLineIndex":16,"ipa":"/ʊnt ˌaʊx diː fɛɾblˈyːtən ʊnt fɛɾdˈɔɾtən/","en":"and also those that withered and withered","zh":"她总将它们摆在窗前","note":""},{"id":"rebecca-das-musical-41-017","lineIndex":12,"speaker":"","original":"lie? sie immer hier am Fenster stehn","sourceLineIndex":17,"ipa":"/lˈiː ziː ˈɪmɜ hˈiːɾ am fˈɛnstɜ ʃtˈeːn/","en":"lie? she always stands here at the window","zh":"任其生生灭灭，盛放与枯萎","note":""},{"id":"rebecca-das-musical-41-018","lineIndex":13,"speaker":"","original":"sie starb, sagt man und läge im Grab","sourceLineIndex":18,"ipa":"/ziː ʃtˈaɾp zˈɑːkt man ʊnt lˈɛːɡə ɪm ɡɾˈɑːp/","en":"She died, they say, and lies in the grave","zh":"人们都说她已死去，归于尘土","note":""},{"id":"rebecca-das-musical-41-019","lineIndex":14,"speaker":"","original":"doch ich wei? es besser.","sourceLineIndex":19,"ipa":"/dɔx ɪç vˈaɪ ɛs bˈɛsɜ/","en":"but I know? it better.","zh":"没人像我这般了解","note":""},{"id":"rebecca-das-musical-41-020","lineIndex":15,"speaker":"","original":"Sie ergibt sich nicht man besiegt sie nicht sie ist stark der Macht des Todes unterliegt sie nicht.","sourceLineIndex":20,"ipa":"/ziː ɛɾɡˈiːpt zɪç nˈɪçt man bəzˈiːkt ziː nˈɪçt ziː ɪst ʃtˈaɾk dɛɾ mˈaxt dɛs tˈoːdəs ˌʊntɜlˈiːkt ziː nˈɪçt/","en":"She doesn't surrender you don't defeat her she is strong She is not subject to the power of death.","zh":"她从不屈服没人能将她征服她是强者死亡也在她面前却步","note":""},{"id":"rebecca-das-musical-41-024","lineIndex":16,"speaker":"","original":"Nein, man sieht sie nicht","sourceLineIndex":24,"ipa":"/nˈaɪn man zˈiːt ziː nˈɪçt/","en":"No, you don't see her","zh":"不，没人能看得见她","note":""},{"id":"rebecca-das-musical-41-025","lineIndex":17,"speaker":"","original":"doch ich spür, sie ist hier und lebt noch","sourceLineIndex":25,"ipa":"/dɔx ɪç ʃpˈyːɾ ziː ɪst hˈiːɾ ʊnt lˈeːpt nɔx/","en":"but I feel she is here and still alive","zh":"只有我能感到，她依然活在我们身边","note":""},{"id":"rebecca-das-musical-41-026","lineIndex":18,"speaker":"","original":"sie hört uns, sie sieht uns.","sourceLineIndex":26,"ipa":"/ziː hˈœɾt ˈʊns ziː zˈiːt ˈʊns/","en":"she hears us, she sees us.","zh":"她在倾听我们，在注视我们","note":""},{"id":"rebecca-das-musical-41-027","lineIndex":19,"speaker":"","original":"Sie klagt und spricht mit mir","sourceLineIndex":27,"ipa":"/ziː klˈɑːkt ʊnt ʃpɾˈɪçt mɪt mˈiːɾ/","en":"She complains and talks to me","zh":"她在我耳边诉说着：","note":""},{"id":"rebecca-das-musical-41-028","lineIndex":20,"speaker":"","original":"Kein Mann dieser Welt war ihr je genug sie war stolz und frei sie war selbstbewusst und klug.","sourceLineIndex":28,"ipa":"/kˈaɪn mˈan dˌiːzɜ vˈɛlt vɑːɾ iːɾ jeː ɡənˈuːk ziː vɑːɾ ʃtˈɔlts ʊnt frˈaɪ ziː vɑːɾ zˈɛlpstbəvˌʊst ʊnt klˈuːk/","en":"No man in this world was ever enough for her she was proud and free she was confident and smart.","zh":"她从来未曾需要过任何一个男人她骄傲而自由她自信而聪慧","note":""},{"id":"rebecca-das-musical-41-031","lineIndex":21,"speaker":"","original":"Kein Mann konnte für sie je wichtig sein diese Art von Liebe gab ihr nichts.","sourceLineIndex":31,"ipa":"/kˈaɪn mˈan kˈɔntə fyːɾ ziː jeː vˈɪçtɪç zaɪn dˌiːzə ˈɑːɾt fɔn lˈiːbə ɡˈɑːp iːɾ nˈɪçts/","en":"No man could ever be important to her that kind of love gave her nothing.","zh":"她从来未曾看重过任何一个男人这种爱对她毫无意义","note":""},{"id":"rebecca-das-musical-41-033","lineIndex":22,"speaker":"","original":"Sie ergibt sich nicht man besiegt sie nicht sie ist stark der Macht des Todes unterliegt sie nicht.","sourceLineIndex":33,"ipa":"/ziː ɛɾɡˈiːpt zɪç nˈɪçt man bəzˈiːkt ziː nˈɪçt ziː ɪst ʃtˈaɾk dɛɾ mˈaxt dɛs tˈoːdəs ˌʊntɜlˈiːkt ziː nˈɪçt/","en":"She doesn't surrender you don't defeat her she is strong She is not subject to the power of death.","zh":"她从不屈服没人能将她征服她是强者死亡也在她面前却步","note":""},{"id":"rebecca-das-musical-41-037","lineIndex":23,"speaker":"","original":"Nein, man sieht sie nicht","sourceLineIndex":37,"ipa":"/nˈaɪn man zˈiːt ziː nˈɪçt/","en":"No, you don't see her","zh":"不，没人能看得见她","note":""},{"id":"rebecca-das-musical-41-038","lineIndex":24,"speaker":"","original":"doch ich spür, sie ist hier und lebt noch","sourceLineIndex":38,"ipa":"/dɔx ɪç ʃpˈyːɾ ziː ɪst hˈiːɾ ʊnt lˈeːpt nɔx/","en":"but I feel she is here and still alive","zh":"只有我能感到，她依然活在我们身边","note":""},{"id":"rebecca-das-musical-41-039","lineIndex":25,"speaker":"","original":"sie hört uns, sie sieht uns.","sourceLineIndex":39,"ipa":"/ziː hˈœɾt ˈʊns ziː zˈiːt ˈʊns/","en":"she hears us, she sees us.","zh":"她在倾听我们，在注视我们","note":""},{"id":"rebecca-das-musical-41-040","lineIndex":26,"speaker":"","original":"Sie ergibt sich nicht.","sourceLineIndex":40,"ipa":"/ziː ɛɾɡˈiːpt zɪç nˈɪçt/","en":"She doesn't surrender.","zh":"她从不屈服","note":""},{"id":"rebecca-das-musical-41-041","lineIndex":27,"speaker":"","original":"man besiegt sie nicht","sourceLineIndex":41,"ipa":"/man bəzˈiːkt ziː nˈɪçt/","en":"you don't defeat her","zh":"没人能将她征服","note":""},{"id":"rebecca-das-musical-41-042","lineIndex":28,"speaker":"","original":"Sie ergibt sich nicht.","sourceLineIndex":42,"ipa":"/ziː ɛɾɡˈiːpt zɪç nˈɪçt/","en":"She doesn't surrender.","zh":"她从不屈服","note":""},{"id":"rebecca-das-musical-41-043","lineIndex":29,"speaker":"","original":"Sie ergibt sich nicht.","sourceLineIndex":43,"ipa":"/ziː ɛɾɡˈiːpt zɪç nˈɪçt/","en":"She doesn't surrender.","zh":"她从不屈服","note":""},{"id":"rebecca-das-musical-41-044","lineIndex":30,"speaker":"","original":"Kann ich etwas für Sie tun?","sourceLineIndex":44,"ipa":"/kˌan ɪç ˈɛtvɑːs fyːɾ ziː tˈuːn/","en":"Can I do something for you?","zh":"有什么我能为您效劳的吗？","note":""},{"id":"rebecca-das-musical-41-045","lineIndex":31,"speaker":"“我”","original":"Nein, danke. Mein Mann ist sehr beschäftigt","sourceLineIndex":45,"ipa":"/nˈaɪn dˈaŋkə maɪn mˈan ɪst zˈeːɾ bəʃˈɛftɪçt/","en":"No, thank you. My husband is very busy","zh":"不用，谢谢。我的丈夫很忙","note":""},{"id":"rebecca-das-musical-41-046","lineIndex":32,"speaker":"","original":"deshalb schau' ich mich allein ein wenig um","sourceLineIndex":46,"ipa":"/dɛshˈalp ʃˈaʊ ɪç mɪç alˈaɪn aɪn vˈeːnɪç ˈʊm/","en":"That's why I'm just looking around a little","zh":"所以我一个人在这里四处走走","note":""},{"id":"rebecca-das-musical-41-047","lineIndex":33,"speaker":"","original":"damit ich die Räume einigermaßen kennenlerne.","sourceLineIndex":47,"ipa":"/dɑːmˈɪt ɪç diː rˈɔømə ˈaɪnɪɡɜmˌɑːsən kˈɛnənlɜnə/","en":"so that I can get to know the rooms somewhat.","zh":"这样我可以熟悉一下这里的房间。","note":""},{"id":"rebecca-das-musical-41-048","lineIndex":34,"speaker":"","original":"Das ist das Morgenzimmer. Hier hat Mrs.","sourceLineIndex":48,"ipa":"/das ɪst das mˈɔɾɡəntsˌɪmɜ hˈiːɾ hat ˌɛmˌɛrˈɛs/","en":"This is the morning room. This is where Mrs.","zh":"这是一件晨室。","note":""},{"id":"rebecca-das-musical-41-049","lineIndex":35,"speaker":"","original":"de Winter nach dem Frühstück ihre Korrespondenz und ihre Telefonate erledigt.","sourceLineIndex":49,"ipa":"/dˈeː vˈɪntɜ nɑːx deːm frˈyːʃtʏk ˌiːrə kˌɔrɛspɔndˈɛnts ʊnt ˌiːrə tˌeːleːfoːnˈɑːtə ɛɾlˈeːdɪçt/","en":"de Winter completed her correspondence and phone calls after breakfast.","zh":"早餐后德温特夫人习惯在这里处理她的信件和来电","note":""},{"id":"rebecca-das-musical-41-050","lineIndex":36,"speaker":"","original":"Das ist ihr Sekretär. Das Gästebuch. Ihr Briefpapier.","sourceLineIndex":50,"ipa":"/das ɪst iːɾ zˌɛkɾeːtˈɛːɾ das ɡˈɛsteːbˌʊx iːɾ bɾˌiːfpapˈiːɾ/","en":"This is your secretary. The guest book. Your stationery.","zh":"这是她的写字台，她的客人登记册，她的信件。","note":""},{"id":"rebecca-das-musical-41-051","lineIndex":37,"speaker":"","original":"Und in der Schublade hier - ihr Telefonbuch, ihre Visitenkarten und ihr Kalender.","sourceLineIndex":51,"ipa":"/ʊnt ɪn dɛɾ ʃˈʊblɑːdə hˈiːɾ iːɾ tˌeːleːfˈɔnbʊx ˌiːrə vˈiːziːtˌɛnkaɾtən ʊnt iːɾ kalˈɛndɜ/","en":"And in the drawer here - her phone book, her business cards and her calendar.","zh":"这里的抽屉里还有她的电话本名片还有日历。","note":""},{"id":"rebecca-das-musical-41-053","lineIndex":38,"speaker":"“我”","original":"Ich (liest): Rebecca de Winter.","sourceLineIndex":53,"ipa":"/ɪç lˈiːst reːbˈɛkɑː dˈeː vˈɪntɜ/","en":"Me (reading): Rebecca de Winter.","zh":"丽贝卡·德温特","note":""},{"id":"rebecca-das-musical-41-054","lineIndex":39,"speaker":"","original":"Und das ist ihr Amor. Der Gott der Liebe.","sourceLineIndex":54,"ipa":"/ʊnt das ɪst iːɾ ˈɑmoːɾ dɛɾ ɡˈɔt dɛɾ lˈiːbə/","en":"And that's her cupid. The God of love.","zh":"这是她的爱神。","note":""},{"id":"rebecca-das-musical-41-055","lineIndex":40,"speaker":"","original":"Mrs. de Winter mochte die kleine Skulptur sehr gern.","sourceLineIndex":55,"ipa":"/ˌɛmˌɛrˈɛs dˈeː vˈɪntɜ mˈɔxtə diː klˈaɪnə skʊlptˈuːɾ zˈeːɾ ɡˈɛɾn/","en":"Mrs. de Winter really liked the little sculpture.","zh":"德温特夫人非常喜欢这个小塑像。","note":""},{"id":"rebecca-das-musical-41-056","lineIndex":41,"speaker":"“我”","original":"Sie sind wohl schon sehr lange auf Manderley.","sourceLineIndex":56,"ipa":"/ziː zɪnt vˈoːl ʃˌoːn zˈeːɾ lˈaŋə aʊf mˈandɜlˌaɪ/","en":"You've probably been at Manderley for a long time.","zh":"您在曼德雷一定已经很久了。","note":""},{"id":"rebecca-das-musical-41-057","lineIndex":42,"speaker":"","original":"Ich kam mit Mrs. de Winter hierher, als sie heiratete.","sourceLineIndex":57,"ipa":"/ɪç kˌɑːm mɪt ˌɛmˌɛrˈɛs dˈeː vˈɪntɜ hˈiːɾhɜ als ziː hˈaɪratətə/","en":"I came here with Mrs. de Winter when she got married.","zh":"我是和德温特夫人一起来的，在她结婚的时候。","note":""},{"id":"rebecca-das-musical-41-058","lineIndex":43,"speaker":"","original":"Ich war immer für sie da. Seit ihrer Kindheit.","sourceLineIndex":58,"ipa":"/ɪç vɑːɾ ˈɪmɜ fyːɾ ziː dˈɑː zaɪt ˌiːrɜ kˈɪnthaɪt/","en":"I was always there for her. Since childhood.","zh":"我一直陪着她，从小时候起。","note":""},{"id":"rebecca-das-musical-41-059","lineIndex":44,"speaker":"“我”","original":"Die Vorbereitung meiner Ankunft hat Ihnen sicher viel Arbeit gemacht.","sourceLineIndex":59,"ipa":"/diː fˈoːɾbərˌaɪtʊŋ mˌaɪnɜ ˈankˌʊnft hat ˌiːnən zˈɪçɜ fˈiːl ˈaɾbaɪt ɡəmˈaxt/","en":"Preparing for my arrival must have been a lot of work for you.","zh":"为了迎接我您一定操了不少心。","note":""},{"id":"rebecca-das-musical-41-060","lineIndex":45,"speaker":"","original":"Ich habe lediglich Mr. de Winters Anweisungen ausgeführt.","sourceLineIndex":60,"ipa":"/ɪç hɑːbə lˈeːdɪɡlˌɪç ˌɛmˈɛɾ dˈeː vˈɪntɜs ˈanvˌaɪzʊŋən ˈaʊsɡəfˌyːɾt/","en":"I was merely following Mr. de Winter's instructions.","zh":"我只是按照德温特先生的指示来做事。","note":""},{"id":"rebecca-das-musical-41-061","lineIndex":46,"speaker":"“我”","original":"Ich hoffe, wir werden Freunde und was den Haushalt angeht","sourceLineIndex":61,"ipa":"/ɪç hˈɔfə viːɾ vˌɛɾdən frˈɔøndə ʊnt vˈas deːn hˈaʊshˌalt ˈanɡˌeːt/","en":"I hope we become friends and as for the household","zh":"我希望我们能成为朋友。","note":""},{"id":"rebecca-das-musical-41-062","lineIndex":47,"speaker":"","original":"so überlasse ich alles Ihnen. Machen Sie alles wie bisher.","sourceLineIndex":62,"ipa":"/zoː ˌyːbɜlˈasə ɪç ˈaləs ˈiːnən mˈaxən ziː ˈaləs viː bɪshˈeːɾ/","en":"so I leave everything to you. Do everything as before.","zh":"家政的事就全部委托给您了。请您继续保持原来的做法吧。","note":""},{"id":"rebecca-das-musical-41-063","lineIndex":48,"speaker":"","original":"Wie Sie wünschen, Madam. Falls Sie noch etwas brauchen","sourceLineIndex":63,"ipa":"/viː ziː vˈʏnʃən mˈɑdɑːm fˈals ziː nɔx ˈɛtvɑːs bɾˈaʊxən/","en":"As you wish, madam. If you need anything else","zh":"如您所愿，夫人。","note":""},{"id":"rebecca-das-musical-41-064","lineIndex":49,"speaker":"","original":"das ist das Haustelefon. Ich nehme an","sourceLineIndex":64,"ipa":"/das ɪst das hˈaʊstˌeːleːfˌoːn ɪç nˈeːmə ˈan/","en":"this is the house telephone. I assume","zh":"如果您还需要什么，这是家里的内线电话。","note":""},{"id":"rebecca-das-musical-41-065","lineIndex":50,"speaker":"","original":"Sie wollen jetzt Ihre Briefe schreiben.","sourceLineIndex":65,"ipa":"/ziː vɔlən jˌɛtst ˌiːrə bɾˈiːfə ʃrˈaɪbən/","en":"You want to write your letters now.","zh":"我想，您现在是要写信了。","note":""},{"id":"rebecca-das-musical-41-066","lineIndex":51,"speaker":"“我”","original":"Meine Briefe?","sourceLineIndex":66,"ipa":"/mˌaɪnə bɾˈiːfə/","en":"My letters?","zh":"写信？","note":""}],"sourceOrder":41,"displayOrder":21},{"order":42,"id":"42-die-lieben-verwandten-beatrice-ich-giles","title":"Die lieben Verwandten","titleZh":"亲爱的亲戚们","lines":[{"id":"rebecca-das-musical-42-001","lineIndex":1,"speaker":"","original":"Ist mein Bruder nicht da?","sourceLineIndex":1,"ipa":"/ɪst maɪn bɾˈuːdɜ nˈɪçt dˈɑː/","en":"Isn't my brother there?","zh":"我的弟弟在这儿吗？","note":""},{"id":"rebecca-das-musical-42-002","lineIndex":2,"speaker":"","original":"Es ist im Buero von Mr. Crawley, Madam.","sourceLineIndex":2,"ipa":"/ɛsɪst ɪm buːˈeːroː fɔn ˌɛmˈɛɾ kɾˈavlaɪ mˈɑdɑːm/","en":"It's in Mr. Crawley's office, madam.","zh":"他在克劳利先生的办公室，夫人","note":""},{"id":"rebecca-das-musical-42-003","lineIndex":3,"speaker":"","original":"Und meine neue Schwaegerin?","sourceLineIndex":3,"ipa":"/ʊnt mˌaɪnə nˈɔøə ʃvˈɛːɡərˌɪn/","en":"And my new sister-in-law?","zh":"我的弟媳呢？","note":""},{"id":"rebecca-das-musical-42-004","lineIndex":4,"speaker":"","original":"Ja, die woll’n wir sehn!","sourceLineIndex":4,"ipa":"/jˈɑː diː vˈɔln viːɾ zˈeːn/","en":"Yes, we want to see her!","zh":"对，我们要见见她！","note":""},{"id":"rebecca-das-musical-42-005","lineIndex":5,"speaker":"","original":"Im Morgenzimmer, Madam.","sourceLineIndex":5,"ipa":"/ɪm mˈɔɾɡəntsˌɪmɜ mˈɑdɑːm/","en":"In the morning room, madam.","zh":"在晨室，夫人","note":""},{"id":"rebecca-das-musical-42-006","lineIndex":6,"speaker":"","original":"Hallo...!?","sourceLineIndex":6,"ipa":"/hˈaloː/","en":"Hello...!?","zh":"你好","note":""},{"id":"rebecca-das-musical-42-007","lineIndex":7,"speaker":"","original":"Eine Madame aus Frankreich.","sourceLineIndex":7,"ipa":"/ˌaɪnə mˈɑdɑːmə ˌaʊs frˈaŋkɾaɪç/","en":"A madame from France.","zh":"一个法国女人","note":""},{"id":"rebecca-das-musical-42-008","lineIndex":8,"speaker":"","original":"Sie kommt aus Yorkshire, Giles","sourceLineIndex":8,"ipa":"/ziː kˈɔmt ˌaʊs jˈɔɾkshiːrə ɡˈiːləs/","en":"She comes from Yorkshire, Giles","zh":"她来自约克郡，吉尔斯","note":""},{"id":"rebecca-das-musical-42-009","lineIndex":9,"speaker":"","original":"Naja, Immerhin hat er sie in Frankreich kennen gelernt.","sourceLineIndex":9,"ipa":"/nˈɑjɑː ˈɪmɜhˌɪn hat ɛɾ ziː ɪn frˈaŋkɾaɪç kˈɛnən ɡəlˈɛɾnt/","en":"Well, at least he met her in France.","zh":"好吧，不论怎样他们是在法国认识的","note":""},{"id":"rebecca-das-musical-42-010","lineIndex":10,"speaker":"","original":"Vermutlich eine mondaene Schöenheit.","sourceLineIndex":10,"ipa":"/fɛɾmˈuːtlɪç ˌaɪnə mˈɔndɛːnə ʃˈøːənhˌaɪt/","en":"Probably a sophisticated beauty.","zh":"八成是个漂亮的交际花","note":""},{"id":"rebecca-das-musical-42-011","lineIndex":11,"speaker":"","original":"Woher willst du das wissen, Giles?","sourceLineIndex":11,"ipa":"/voːhˈeːɾ vɪlst duː das vˈɪsən ɡˈiːləs/","en":"How do you know that, Giles?","zh":"你从哪儿知道的，吉尔斯？","note":""},{"id":"rebecca-das-musical-42-012","lineIndex":12,"speaker":"","original":"Ich hoffe nur, sie macht keine naechtlichen Segeltouren.","sourceLineIndex":12,"ipa":"/ɪç hˈɔfə nˈuːɾ ziː mˈaxt kˈaɪnə nˈɛçtlɪçən zˈeːɡəltˌuːrən/","en":"I just hope she doesn't do any night sailing trips.","zh":"我只盼望着她不喜欢半夜坐船出海","note":""},{"id":"rebecca-das-musical-42-013","lineIndex":13,"speaker":"","original":"Hallo","sourceLineIndex":13,"ipa":"/hˈaloː/","en":"Hello","zh":"你们好","note":""},{"id":"rebecca-das-musical-42-014","lineIndex":14,"speaker":"","original":"Da sind Sie ja...","sourceLineIndex":14,"ipa":"/dɑː zɪnt ziː jˈɑː/","en":"There you are...","zh":"您在这儿啊……","note":""},{"id":"rebecca-das-musical-42-015","lineIndex":15,"speaker":"","original":"Ich meine natüerlich, du bist...","sourceLineIndex":15,"ipa":"/ɪç mˌaɪnə nˈɑtyːɜlˌɪç dˈuː bɪst/","en":"I mean, of course, you are...","zh":"呃，当然我的意思是，你是……","note":""},{"id":"rebecca-das-musical-42-016","lineIndex":16,"speaker":"","original":"Ach entschuldige, dass wir so einfach eindringen.","sourceLineIndex":16,"ipa":"/ˈax ɛntʃˈʊldɪɡə das viːɾ zoː ˈaɪnfˌax ˈaɪndɾˌɪŋən/","en":"Oh, sorry for intruding so easily.","zh":"抱歉，我们就这么贸然闯进来","note":""},{"id":"rebecca-das-musical-42-017","lineIndex":17,"speaker":"","original":"Ich bin Maxims Schwester Beatrice.","sourceLineIndex":17,"ipa":"/ɪç bɪn mˈaksiːms ʃvˈɛstɜ bəˈatɾiːkə/","en":"I am Maxim's sister Beatrice.","zh":"我是马克西姆的姐姐贝亚特丽丝","note":""},{"id":"rebecca-das-musical-42-018","lineIndex":18,"speaker":"","original":"Das ist Giles, mein Mann.","sourceLineIndex":18,"ipa":"/das ɪst ɡˈiːləs maɪn mˈan/","en":"This is Giles, my husband.","zh":"这是吉尔斯，我的丈夫","note":""},{"id":"rebecca-das-musical-42-019","lineIndex":19,"speaker":"","original":"Herzlich Willkommen auf Manderley.","sourceLineIndex":19,"ipa":"/hˈɛɾtslɪç vɪlkˈɔmən aʊf mˈandɜlˌaɪ/","en":"Welcome to Manderley.","zh":"欢迎你来到曼德雷","note":""},{"id":"rebecca-das-musical-42-020","lineIndex":20,"speaker":"","original":"Guten tag!","sourceLineIndex":20,"ipa":"/ɡˈuːtən tˈɑːk/","en":"Good day!","zh":"你好！","note":""},{"id":"rebecca-das-musical-42-021","lineIndex":21,"speaker":"","original":"Nenn mich einfach Bee.","sourceLineIndex":21,"ipa":"/nˈɛn mɪç ˈaɪnfˌax bəˈeː/","en":"Just call me Bee.","zh":"叫我“比”就好","note":""},{"id":"rebecca-das-musical-42-022","lineIndex":22,"speaker":"","original":"Haben Sie etwas gehört was ich eben...?","sourceLineIndex":22,"ipa":"/hˌɑːbən ziː ˈɛtvɑːs ɡəhˈœɾt vˈas ɪç ˈeːbən/","en":"Did you hear something I just...?","zh":"你听到我说的话了吗？","note":""},{"id":"rebecca-das-musical-42-023","lineIndex":23,"speaker":"","original":"Lasst doch die Foermlichkeit weg. Wir sind jetzt doch verwandt.","sourceLineIndex":23,"ipa":"/lˈast dɔx diː fˈœɾmlɪçkˌaɪt vˈɛk viːɾ zɪnt jˌɛtst dɔx fɛɾvˈant/","en":"Leave out the formality. We're related now.","zh":"别再扯这些繁文缛节了。我们现在可是亲戚了。","note":""},{"id":"rebecca-das-musical-42-024","lineIndex":24,"speaker":"","original":"Wenn zwei sich finden suchen sie nur Zweisamkeit und Harmonie.","sourceLineIndex":24,"ipa":"/vˌɛn tsvˈaɪ zɪç fˈɪndən zˈuːxən ziː nˈuːɾ tsvˈaɪzɑːmkˌaɪt ʊnt hˌaɾmoːnˈiː/","en":"When two find each other they search just togetherness and harmony.","zh":"两人若是情投意合自然渴望终身相伴","note":""},{"id":"rebecca-das-musical-42-026","lineIndex":25,"speaker":"","original":"Sie traun sich, darum lassen sie sich traum.","sourceLineIndex":26,"ipa":"/ziː tɾˈaʊn zɪç dɑːrˈʊm lˈasən ziː zɪç tɾˈaʊm/","en":"You dare, so you let yourself dream.","zh":"他们许下誓言，结为夫妇","note":""},{"id":"rebecca-das-musical-42-027","lineIndex":26,"speaker":"","original":"Es gibt nichts, was sie trennen kann.","sourceLineIndex":27,"ipa":"/ɛs ɡˈiːpt nˈɪçts vˈas ziː tɾˈɛnən kˌan/","en":"There is nothing that can separate them.","zh":"没什么能将他们分开","note":""},{"id":"rebecca-das-musical-42-028","lineIndex":27,"speaker":"","original":"Doch kaum hast du traeumend ja gesagt","sourceLineIndex":28,"ipa":"/dɔx kˈaʊm hast duː tɾˈɛːʊmənt jˈɑː ɡəzˈɑːkt/","en":"But as soon as you said yes while dreaming","zh":"可你忘了发另一个誓","note":""},{"id":"rebecca-das-musical-42-029","lineIndex":28,"speaker":"","original":"umschlingen dich gratis und ungefragt","sourceLineIndex":29,"ipa":"/ˈʊmʃlˌɪŋən dɪç ɡɾˈɑtɪs ʊnt ˈʊnɡəfrˌɑːkt/","en":"embrace you free of charge and without asking","zh":"对那些无怨无悔无诉无求","note":""},{"id":"rebecca-das-musical-42-030","lineIndex":29,"speaker":"","original":"Familienbanden, der ganze Clan von deinem Mann.","sourceLineIndex":30,"ipa":"/famˈiːlɪənbˌandən dɛɾ ɡˈantsə klˈɑːn fɔn dˌaɪnəm mˈan/","en":"Family ties, your husband's whole clan.","zh":"陪在你身边的你丈夫的一大家子","note":""},{"id":"rebecca-das-musical-42-031","lineIndex":30,"speaker":"","original":"Man heiratet auch die Verwandten mit kriegt gratis die Onkel und Tanen mit.","sourceLineIndex":31,"ipa":"/man haɪrˈɑːtət ˌaʊx diː fɛɾvˈantən mɪt kɾˈiːkt ɡɾˈɑtɪs diː ˈɔnkəl ʊnt tˈɑːnən mˈɪt/","en":"You also marry your relatives get the uncles and parents along for free.","zh":"结婚可不是两个人的事还免费附赠叔叔和婶婶","note":""},{"id":"rebecca-das-musical-42-033","lineIndex":31,"speaker":"","original":"Ob Ostern, ob Weihnacht, ob Herbst oder Mai die lieben Verwandten sind immer dabei!","sourceLineIndex":33,"ipa":"/ˌɔp ˈoːstɜn ˌɔp vˈaɪhnaxt ˌɔp hˈɛɾbst ˌoːdɜ mˈaɪ diː lˈiːbən fɛɾvˈantən zɪnt ˈɪmɜ dɑːbˈaɪ/","en":"Whether Easter, Christmas, autumn or May the dear relatives are always there!","zh":"无论复活节、圣诞节，无论春夏秋冬可爱的亲戚们总是和你一起","note":""},{"id":"rebecca-das-musical-42-035","lineIndex":32,"speaker":"","original":"Dein Schwager macht manch derben Scherz","sourceLineIndex":35,"ipa":"/daɪn ʃvˈɑːɡɜ mˈaxt mˈanç dˈɛɾbən ʃˈɛɾts/","en":"Your brother-in-law makes many a rude joke","zh":"你的姐夫爱开粗俗的玩笑","note":""},{"id":"rebecca-das-musical-42-036","lineIndex":33,"speaker":"","original":"Jedoch er hat ein goldenes Herz!","sourceLineIndex":36,"ipa":"/jˈeːdɔx ɛɾ hat aɪn ɡˈɔldənəs hˈɛɾts/","en":"However, he has a heart of gold!","zh":"但是他有一颗金子般的心","note":""},{"id":"rebecca-das-musical-42-037","lineIndex":34,"speaker":"","original":"Familienbanden fordern oft viel Geduld!","sourceLineIndex":37,"ipa":"/famˈiːlɪənbˌandən fˈɔɾdɜn ˈɔft fˈiːl ɡədˈʊlt/","en":"Family ties often require a lot of patience!","zh":"与亲戚们相处常常得有相当的耐心","note":""},{"id":"rebecca-das-musical-42-038","lineIndex":35,"speaker":"","original":"Ich hab nun mal einen besond'ren Humor.","sourceLineIndex":38,"ipa":"/ɪç hˈɑːp nˈuːn mˈɑːl ˌaɪnən bəzˈɔndɾən huːmˈoːɾ/","en":"I have a special sense of humor.","zh":"我的幽默感总是无人理解","note":""},{"id":"rebecca-das-musical-42-039","lineIndex":36,"speaker":"","original":"Das kommt leider in den besten Familien vor.","sourceLineIndex":39,"ipa":"/das kˈɔmt lˈaɪdɜ ɪn deːn bˈɛstən famˈiːlɪən fˈɔɾ/","en":"Unfortunately, this happens in the best families.","zh":"即使在最优秀的家庭里也不例外","note":""},{"id":"rebecca-das-musical-42-040","lineIndex":37,"speaker":"","original":"Ich wollte immer eine Schwester wie dich.","sourceLineIndex":40,"ipa":"/ɪç vɔltə ˈɪmɜ ˌaɪnə ʃvˈɛstɜ viː dˈɪç/","en":"I always wanted a sister like you.","zh":"我一直想有一个你这样的姐姐","note":""},{"id":"rebecca-das-musical-42-041","lineIndex":38,"speaker":"","original":"Dass du jetzt da bist ist ein grosses Glueck fuer mich.","sourceLineIndex":41,"ipa":"/das duː jˌɛtst dɑː bɪst ɪst aɪn ɡɾˈɔsəs ɡlˈuːɛk fyːɾ mɪç/","en":"That you are here now is a great blessing for me.","zh":"你在这里就是我最大的幸福","note":""},{"id":"rebecca-das-musical-42-043","lineIndex":39,"speaker":"","original":"Auch mich!","sourceLineIndex":43,"ipa":"/ˈaʊx mɪç/","en":"Me too!","zh":"也是我的","note":""},{"id":"rebecca-das-musical-42-044","lineIndex":40,"speaker":"","original":"Und mich!","sourceLineIndex":44,"ipa":"/ˈʊnt mɪç/","en":"And me!","zh":"还是我的","note":""},{"id":"rebecca-das-musical-42-045","lineIndex":41,"speaker":"","original":"Verwandte bekommt man umsonst dazu man kuesst und umarmt sich und ist per du.","sourceLineIndex":45,"ipa":"/fɛɾvˈantə bəkˈɔmt man ˈʊmzˌɔnst dɑːtsˈuː man kˈuːɛst ʊnt ˈʊmˌaɾmt zɪç ʊnt ɪst pɛɾ duː/","en":"You get relatives for free You kiss and hug and are on a first-name basis.","zh":"亲戚们总是不计得失他们彼此拥抱亲切相称","note":""},{"id":"rebecca-das-musical-42-047","lineIndex":42,"speaker":"","original":"Fuer liebe Verwandte gilt kein Tabu.","sourceLineIndex":47,"ipa":"/fyːɾ lˈiːbə fɛɾvˈantə ɡˈɪlt kˈaɪn tˈɑbuː/","en":"There is no taboo for dear relatives.","zh":"亲爱的亲戚间百无禁忌","note":""},{"id":"rebecca-das-musical-42-048","lineIndex":43,"speaker":"","original":"Und war'n wir bisher auch gar nicht bekannt jetzt bindet uns ber Familienstand.","sourceLineIndex":48,"ipa":"/ʊnt vˈɑɾn viːɾ bɪshˈeːɾ ˌaʊx ɡˌɑːɾnˈɪçt bəkˈant jˌɛtst bˈɪndət ʊns bˈeːɾ famˈiːlɪənstˌant/","en":"And we weren't even known before now we are bound by marital status.","zh":"今天之前我们还是陌路人但现在家庭纽带将我们连在一起","note":""},{"id":"rebecca-das-musical-42-050","lineIndex":44,"speaker":"","original":"Wir sind, was auch sei verwandt und stets da-bei!","sourceLineIndex":50,"ipa":"/vˈiːɾ zɪnt vˈas ˌaʊx zˈaɪ fɛɾvˈant ʊnt ʃtˈeːts dɑːbˈaɪ/","en":"We are, no matter what related and always there!","zh":"无论发生什么亲戚永远在一起","note":""},{"id":"rebecca-das-musical-42-052","lineIndex":45,"speaker":"","original":"Da-bei!","sourceLineIndex":52,"ipa":"/dɑːbˈaɪ/","en":"Included!","zh":"包括！","note":""}],"sourceOrder":42,"displayOrder":22},{"order":43,"id":"43-hilf-mir-durch-die-nacht-ich-maxim","title":"Hilf mir durch die Nacht","titleZh":"助我度过沉沉黑夜","lines":[{"id":"rebecca-das-musical-43-001","lineIndex":1,"speaker":"","original":"Vor'm Fensterkreuz, der Vorhand der im Wind weht","sourceLineIndex":1,"ipa":"/vˈoːɾm fˈɛnstɜkɾˌɔøts dɛɾ fˈoːɾhˌant dɛɾ ɪm vˈɪnt vˈeːt/","en":"In front of the window cross, the forehand blowing in the wind","zh":"窗前的窗帘随风飘扬","note":""},{"id":"rebecca-das-musical-43-002","lineIndex":2,"speaker":"","original":"das Mondlicht, das die Schatten tanzen lässt","sourceLineIndex":2,"ipa":"/das mˈɔndlɪçt das diː ʃˈatən tˈantsən lˈɛst/","en":"the moonlight that makes the shadows dance","zh":"影子正随月光起舞","note":""},{"id":"rebecca-das-musical-43-003","lineIndex":3,"speaker":"","original":"Und die Geräusche in dem großem fremden Haus","sourceLineIndex":3,"ipa":"/ʊnt diː ɡərˈɔøʃə ɪn deːm ɡɾˈoːsəm frˈɛmdən hˈaʊs/","en":"And the noises in the big strange house","zh":"而在这空旷陌生的房内流淌的声音","note":""},{"id":"rebecca-das-musical-43-004","lineIndex":4,"speaker":"","original":"wie leise Stimmen huschender Gespenstern","sourceLineIndex":4,"ipa":"/viː lˈaɪzə ʃtˈɪmən hˈʊʃəndɜ ɡəʃpˈɛnstɜn/","en":"like quiet voices of scurrying ghosts","zh":"似是鬼魂的低语","note":""},{"id":"rebecca-das-musical-43-005","lineIndex":5,"speaker":"","original":"Es ist schon spät","sourceLineIndex":5,"ipa":"/ɛsɪst ʃˌoːn ʃpˈɛːt/","en":"It's already late","zh":"天色已晚","note":""},{"id":"rebecca-das-musical-43-006","lineIndex":6,"speaker":"","original":"doch ich komm nicht zur Ruh","sourceLineIndex":6,"ipa":"/dɔx ɪç kˈɔm nˈɪçt tsuːɾ rˈuː/","en":"but I can't calm down","zh":"我却难以入眠","note":""},{"id":"rebecca-das-musical-43-007","lineIndex":7,"speaker":"","original":"In mir tausend Fragen","sourceLineIndex":7,"ipa":"/ɪn miːɾ tˈaʊzənt frˈɑːɡən/","en":"A thousand questions in my mind","zh":"内心在反复询问","note":""},{"id":"rebecca-das-musical-43-008","lineIndex":8,"speaker":"","original":"Wie kann ich schlafen, wenn du nicht da bist?","sourceLineIndex":8,"ipa":"/viː kˌan ɪç ʃlˈɑːfən vˌɛn duː nˈɪçt dɑː bɪst/","en":"How can I sleep when you're not there?","zh":"没有你在身边，我该如何入睡？","note":""},{"id":"rebecca-das-musical-43-009","lineIndex":9,"speaker":"","original":"Hilf mir durch die Nacht","sourceLineIndex":9,"ipa":"/hˈɪlf miːɾ dʊɐç diː nˈaxt/","en":"Help me through the night","zh":"助我度过漫漫长夜","note":""},{"id":"rebecca-das-musical-43-010","lineIndex":10,"speaker":"","original":"Gib auf mich Acht","sourceLineIndex":10,"ipa":"/ɡˈiːp aʊf mɪç ˈaxt/","en":"Take care of me","zh":"陪伴我","note":""},{"id":"rebecca-das-musical-43-011","lineIndex":11,"speaker":"","original":"Lass mich nicht den Mut verliern","sourceLineIndex":11,"ipa":"/lˈas mɪç nˈɪçt deːn mˈuːt fɛɾlˈiːɾn/","en":"Don't let me lose heart","zh":"让我保有坚持的勇气","note":""},{"id":"rebecca-das-musical-43-012","lineIndex":12,"speaker":"","original":"Halt mich ganz fest","sourceLineIndex":12,"ipa":"/hˈalt mɪç ɡˌants fˈɛst/","en":"Hold me tight","zh":"抱紧我","note":""},{"id":"rebecca-das-musical-43-013","lineIndex":13,"speaker":"","original":"wenn mir kalt ist im Dunkeln","sourceLineIndex":13,"ipa":"/vˌɛn miːɾ kˈalt ɪst ɪm dˈʊnkəln/","en":"when I'm cold in the dark","zh":"让我免受冰冷黑暗的侵袭","note":""},{"id":"rebecca-das-musical-43-014","lineIndex":14,"speaker":"","original":"Und hast du die Zweifel mir fort geküsst-","sourceLineIndex":14,"ipa":"/ʊnt hast duː diː tsvˈaɪfəl miːɾ fˈɔɾt ɡəkˈʏst/","en":"And did you kiss away my doubts?","zh":"用亲吻打消我的疑虑","note":""},{"id":"rebecca-das-musical-43-015","lineIndex":15,"speaker":"","original":"zeig mir was Liebe ist","sourceLineIndex":15,"ipa":"/tsˈaɪk miːɾ vˈas lˈiːbə ɪst/","en":"show me what love is","zh":"告诉我，什么是爱","note":""},{"id":"rebecca-das-musical-43-016","lineIndex":16,"speaker":"","original":"Ich dachte ich kann ganz von vorn beginnen","sourceLineIndex":16,"ipa":"/ɪç dˈaxtə ɪç kˌan ɡˌants fɔn fˈɔɾn bəɡˈɪnən/","en":"I thought I could start from the beginning","zh":"我本以为我能重新开始","note":""},{"id":"rebecca-das-musical-43-017","lineIndex":17,"speaker":"","original":"doch wie gibt die Vergangenheit mich frei","sourceLineIndex":17,"ipa":"/dɔx viː ɡˈiːpt diː fɛɾɡˈaŋənhˌaɪt mɪç frˈaɪ/","en":"but how the past releases me","zh":"但过去却将我紧追不放","note":""},{"id":"rebecca-das-musical-43-018","lineIndex":18,"speaker":"","original":"Wie konnte ich nur glauben dass ich sie vergessen kann?","sourceLineIndex":18,"ipa":"/viː kˈɔntə ɪç nˈuːɾ ɡlˈaʊbən das ɪç ziː fɛɾɡˈɛsən kˌan/","en":"How could I possibly believe that I could forget her?","zh":"我怎能单纯到以为自己可以忘记她？","note":""},{"id":"rebecca-das-musical-43-019","lineIndex":19,"speaker":"","original":"Ich schleiß die Augen und sehe nur Rebecca","sourceLineIndex":19,"ipa":"/ɪç ʃlˈaɪs diː ˈaʊɡən ʊnt zˈeːə nˈuːɾ reːbˈɛkɑː/","en":"I close my eyes and only see Rebecca","zh":"我一闭上双眼，眼前就只剩Rebecca的身影","note":""},{"id":"rebecca-das-musical-43-020","lineIndex":20,"speaker":"","original":"Die Wahrheit ist ich weiß nicht, wer ich bin Ich habe mich verloren!","sourceLineIndex":20,"ipa":"/diː vˈɑːɾhaɪt ɪst ɪç vˈaɪs nˈɪçt vˈeːɾ ɪç bɪn ɪç hɑːbə mɪç fɛɾlˈoːrən/","en":"The truth is I don't know who I am I'm lost!","zh":"看看现在，我连自己是谁都不知道了我已经迷失了自我！","note":""},{"id":"rebecca-das-musical-43-022","lineIndex":21,"speaker":"","original":"Nirgendwo Hoffnung-","sourceLineIndex":22,"ipa":"/nɪɾɡˈɛndvoː hˈɔfnʊŋ/","en":"Nowhere Hope-","zh":"希望全无","note":""},{"id":"rebecca-das-musical-43-023","lineIndex":22,"speaker":"","original":"Überall Lüge!","sourceLineIndex":23,"ipa":"/ˌyːbɜˈal lˈyːɡə/","en":"Lies everywhere!","zh":"谎言遍布！","note":""},{"id":"rebecca-das-musical-43-024","lineIndex":23,"speaker":"","original":"Hilf mir durch die Nacht","sourceLineIndex":24,"ipa":"/hˈɪlf miːɾ dʊɐç diː nˈaxt/","en":"Help me through the night","zh":"助我度过漫漫长夜","note":""},{"id":"rebecca-das-musical-43-025","lineIndex":24,"speaker":"","original":"gib mir die Kraft","sourceLineIndex":25,"ipa":"/ɡˈiːp miːɾ diː kɾˈaft/","en":"give me the strength","zh":"给我力量","note":""},{"id":"rebecca-das-musical-43-026","lineIndex":25,"speaker":"","original":"durch die Dunkelheit zu gehn","sourceLineIndex":26,"ipa":"/dʊɐç diː dˈʊnkəlhˌaɪt tsuː ɡˈeːn/","en":"to walk through the darkness","zh":"好越过这无穷的黑暗","note":""},{"id":"rebecca-das-musical-43-027","lineIndex":26,"speaker":"","original":"Halt mich ganz fest","sourceLineIndex":27,"ipa":"/hˈalt mɪç ɡˌants fˈɛst/","en":"Hold me tight","zh":"将我抱紧","note":""},{"id":"rebecca-das-musical-43-028","lineIndex":27,"speaker":"","original":"wenn das Gestern mir Angst macht","sourceLineIndex":28,"ipa":"/vˌɛn das ɡˈɛstɜn miːɾ ˈaŋst mˈaxt/","en":"if yesterday scares me","zh":"好远离过去的纠缠","note":""},{"id":"rebecca-das-musical-43-029","lineIndex":28,"speaker":"","original":"Und wenn ich gelernt hab","sourceLineIndex":29,"ipa":"/ʊnt vˌɛn ɪç ɡəlˈɛɾnt hˈɑːp/","en":"And when I've learned","zh":"当我学会","note":""},{"id":"rebecca-das-musical-43-030","lineIndex":29,"speaker":"","original":"wie man vergisst-","sourceLineIndex":30,"ipa":"/viː man fɛɾɡˈɪst/","en":"how to forget-","zh":"如何将过去遗忘","note":""},{"id":"rebecca-das-musical-43-031","lineIndex":30,"speaker":"","original":"zeig mir was Liebe ist","sourceLineIndex":31,"ipa":"/tsˈaɪk miːɾ vˈas lˈiːbə ɪst/","en":"show me what love is","zh":"告诉我，什么是爱","note":""},{"id":"rebecca-das-musical-43-032","lineIndex":31,"speaker":"","original":"Hilf mir durch die Nacht","sourceLineIndex":32,"ipa":"/hˈɪlf miːɾ dʊɐç diː nˈaxt/","en":"Help me through the night","zh":"助我度过漫漫长夜","note":""},{"id":"rebecca-das-musical-43-033","lineIndex":32,"speaker":"","original":"gib mir die Kraft","sourceLineIndex":33,"ipa":"/ɡˈiːp miːɾ diː kɾˈaft/","en":"give me the strength","zh":"给我力量","note":""},{"id":"rebecca-das-musical-43-034","lineIndex":33,"speaker":"","original":"durch die Dunkelheit zu gehn","sourceLineIndex":34,"ipa":"/dʊɐç diː dˈʊnkəlhˌaɪt tsuː ɡˈeːn/","en":"to walk through the darkness","zh":"越过无穷的黑暗","note":""},{"id":"rebecca-das-musical-43-035","lineIndex":34,"speaker":"","original":"Halt mich ganz fest","sourceLineIndex":35,"ipa":"/hˈalt mɪç ɡˌants fˈɛst/","en":"Hold me tight","zh":"将我抱紧","note":""},{"id":"rebecca-das-musical-43-036","lineIndex":35,"speaker":"","original":"wenn das Gestern mir Angst macht","sourceLineIndex":36,"ipa":"/vˌɛn das ɡˈɛstɜn miːɾ ˈaŋst mˈaxt/","en":"if yesterday scares me","zh":"摆脱对过去的恐惧","note":""},{"id":"rebecca-das-musical-43-037","lineIndex":36,"speaker":"","original":"Und wenn ich gelernt hab wie man vergisst:","sourceLineIndex":37,"ipa":"/ʊnt vˌɛn ɪç ɡəlˈɛɾnt hˈɑːp viː man fɛɾɡˈɪst/","en":"And when I learned how to forget:","zh":"当我学会如何遗忘过去","note":""},{"id":"rebecca-das-musical-43-038","lineIndex":37,"speaker":"","original":"Zeig mir was Liebe ist","sourceLineIndex":38,"ipa":"/tsˈaɪk miːɾ vˈas lˈiːbə ɪst/","en":"Show me what love is","zh":"告诉我，什么是爱","note":""}],"sourceOrder":43,"displayOrder":23},{"order":44,"id":"44-was-ist-nur-los-mit-ihm-beatrice","title":"Was ist nur los mit ihm?","titleZh":"他究竟怎么了？","lines":[{"id":"rebecca-das-musical-44-001","lineIndex":1,"speaker":"","original":"Du wirst sehen wenn er aus London zurückkommt ist er wieder ganz der Alte.","sourceLineIndex":1,"ipa":"/duː vˌɪɾst zˈeːən vˌɛn ɛɾ ˌaʊs lˈɔndoːn tsuːrˈʏkkˌɔmt ɪst ɛɾ vˈiːdɜ ɡˌants dɛɾ ˈaltə/","en":"You will see when he returns from London he's his old self again.","zh":"你会知道的当他从伦敦回来时他又回到了以前的自己。","note":""},{"id":"rebecca-das-musical-44-004","lineIndex":2,"speaker":"","original":"Ruf mich wieder an ja","sourceLineIndex":4,"ipa":"/rˈuːf mɪç vˈiːdɜ an jˈɑː/","en":"Call me again yeah","zh":"再给我打电话是的","note":""},{"id":"rebecca-das-musical-44-005","lineIndex":3,"speaker":"","original":"Kopf hoch!","sourceLineIndex":5,"ipa":"/kˈɔpf hˈoːx/","en":"Head up!","zh":"振作起来！","note":""},{"id":"rebecca-das-musical-44-006","lineIndex":4,"speaker":"","original":"Adieu.","sourceLineIndex":6,"ipa":"/ˈɑdiːˌuː/","en":"Adieu.","zh":"再见。","note":""},{"id":"rebecca-das-musical-44-007","lineIndex":5,"speaker":"","original":"Was ist nur los mit ihm?","sourceLineIndex":7,"ipa":"/vˈas ɪst nˈuːɾ lˈoːs mɪt ˈiːm/","en":"What's wrong with him?","zh":"他怎么了？","note":""},{"id":"rebecca-das-musical-44-008","lineIndex":6,"speaker":"","original":"Ich kann ihn nicht versteh'n.","sourceLineIndex":8,"ipa":"/ɪç kˌan iːn nˈɪçt fɛɾʃtˈeːn/","en":"I can't understand him.","zh":"我无法理解他。","note":""},{"id":"rebecca-das-musical-44-009","lineIndex":7,"speaker":"","original":"Irgendwas ist gescheh'n worüber er nicht spricht.","sourceLineIndex":9,"ipa":"/ˈɪɾɡəndvˌɑːs ɪst ɡəʃˈeːn vˈoːryːbɜ ɛɾ nˈɪçt ʃpɾˈɪçt/","en":"Something has happened what he doesn't talk about.","zh":"发生了一些事情他不说。","note":""},{"id":"rebecca-das-musical-44-011","lineIndex":8,"speaker":"","original":"Er wird geliebt wie je.","sourceLineIndex":11,"ipa":"/ɛɾ vˌɪɾt ɡəlˈiːpt viː jeː/","en":"He is loved as ever.","zh":"他一如既往地受到爱戴。","note":""},{"id":"rebecca-das-musical-44-012","lineIndex":9,"speaker":"","original":"Er hat sein Manderley doch glücklich ist er nicht.","sourceLineIndex":12,"ipa":"/ɛɾ hat zaɪn mˈandɜlˌaɪ dɔx ɡlˈʏklɪç ɪst ɛɾ nˈɪçt/","en":"He has his Manderley but he is not happy.","zh":"他有他的曼德雷但他不开心。","note":""},{"id":"rebecca-das-musical-44-014","lineIndex":10,"speaker":"","original":"Obwohl ich meinen Bruder kenn' seh' ich doch nicht in ihn hinein.","sourceLineIndex":14,"ipa":"/ɔpvˈoːl ɪç mˌaɪnən bɾˈuːdɜ kˈɛn zˈeː ɪç dɔx nˈɪçt ɪn iːn hɪnˈaɪn/","en":"Even though I know my brother I don't see into him.","zh":"虽然我认识我的弟弟但我看不透他。","note":""},{"id":"rebecca-das-musical-44-016","lineIndex":11,"speaker":"","original":"Doch ist er kalt und ungerecht dann muss er sehr verzweifelt sein.","sourceLineIndex":16,"ipa":"/dɔx ɪst ɛɾ kˈalt ʊnt ˈʊnɡərˌɛçt dan mˈʊs ɛɾ zˈeːɾ fɛɾtsvˈaɪfəlt zaɪn/","en":"But he is cold and unjust then he must be very desperate.","zh":"他冷酷不公那么他一定很绝望。","note":""},{"id":"rebecca-das-musical-44-018","lineIndex":12,"speaker":"","original":"Als unser Vater starb hielt er ihn stumm die Hand.","sourceLineIndex":18,"ipa":"/als ˌʊnzɜ fˈɑːtɜ ʃtˈaɾp hˈiːlt ɛɾ iːn ʃtˈʊm diː hˈant/","en":"When our father died he held his hand silently.","zh":"当我们的父亲去世时他默默地握着他的手。","note":""},{"id":"rebecca-das-musical-44-020","lineIndex":13,"speaker":"","original":"Und dass er ihn verstand sagte mir sein Gesieht.","sourceLineIndex":20,"ipa":"/ʊnt das ɛɾ iːn fɛɾʃtˈant zˈɑːɡtə miːɾ zaɪn ɡəzˈiːt/","en":"And that he understood him his face told me.","zh":"他理解他告诉我他的异象。","note":""},{"id":"rebecca-das-musical-44-022","lineIndex":14,"speaker":"","original":"Und alle wussten gut was immer Maxim tut er hält, was er verspricht.","sourceLineIndex":22,"ipa":"/ʊnt ˈalə vˈʊstən ɡˈuːt vˈas ˈɪmɜ mˈaksiːm tˈuːt ɛɾ hˈɛlt vˈas ɛɾ fɛɾʃpɾˈɪçt/","en":"And everyone knew well whatever Maxim does he keeps what he promises.","zh":"每个人都很清楚无论马克西姆做什么他做到了他的承诺。","note":""},{"id":"rebecca-das-musical-44-025","lineIndex":15,"speaker":"","original":"Ehre und Ruf von Manderley würde er schützen vor Gefahr'n.","sourceLineIndex":25,"ipa":"/ˈeːrə ʊnt rˈuːf fɔn mˈandɜlˌaɪ vˈʏɾdə ɛɾ ʃˈʏtsən fˌɔɾ ɡəfˈɑːɾn/","en":"Honor and reputation of Manderley he would protect from danger.","zh":"曼德雷的荣誉和声誉他会保护它免受危险。","note":""},{"id":"rebecca-das-musical-44-027","lineIndex":16,"speaker":"","original":"Er schwor den Namen und das Haus","sourceLineIndex":27,"ipa":"/ɛɾ ʃvˈoːɾ deːn nˈɑːmən ʊnt das hˈaʊs/","en":"He swore the name and the house","zh":"他发誓姓氏和房子","note":""},{"id":"rebecca-das-musical-44-028","lineIndex":17,"speaker":"","original":"Vor jedem Makel zu Bewahr'n.","sourceLineIndex":28,"ipa":"/fˌɔɾ jˈeːdəm mˈɑkəl tsuː bəvˈɑːɾn/","en":"To protect from every flaw.","zh":"保护免受任何瑕疵的侵害。","note":""},{"id":"rebecca-das-musical-44-029","lineIndex":18,"speaker":"","original":"Und das ist schwer für ihn oft folgt er blindings den Gefühlen.","sourceLineIndex":29,"ipa":"/ʊnt das ɪst ʃvˈeːɾ fyːɾ iːn ˈɔft fˈɔlkt ɛɾ blˈɪndɪŋs deːn ɡəfˈyːlən/","en":"And that's hard for him he often blindly follows his feelings.","zh":"这对他来说很难他常常盲目地追随感情。","note":""},{"id":"rebecca-das-musical-44-031","lineIndex":19,"speaker":"","original":"Er liebt und hasst ganz unbeherrscht.","sourceLineIndex":31,"ipa":"/ɛɾ lˈiːpt ʊnt hˈast ɡˌants ˈʊnbəhˌɛɾʃt/","en":"He loves and hates completely without control.","zh":"他完全无法控制地爱恨交加。","note":""},{"id":"rebecca-das-musical-44-032","lineIndex":20,"speaker":"","original":"Dann ist er oft sein eigner Feind.","sourceLineIndex":32,"ipa":"/dan ɪst ɛɾ ˈɔft zaɪn ˈaɪɡnɜ fˈaɪnt/","en":"Then he is often his own enemy.","zh":"那么他往往是自己的敌人。","note":""},{"id":"rebecca-das-musical-44-033","lineIndex":21,"speaker":"","original":"Und wer mit meinem Bruder lebt.","sourceLineIndex":33,"ipa":"/ʊnt vˈeːɾ mɪt mˌaɪnəm bɾˈuːdɜ lˈeːpt/","en":"And who lives with my brother.","zh":"谁和我弟弟住在一起。","note":""},{"id":"rebecca-das-musical-44-034","lineIndex":22,"speaker":"","original":"Bleibt oft mit seinem Schmerz allein.","sourceLineIndex":34,"ipa":"/blˈaɪpt ˈɔft mɪt zˌaɪnəm ʃmˈɛɾts alˈaɪn/","en":"Often remains alone with his pain.","zh":"经常独自面对他的痛苦。","note":""},{"id":"rebecca-das-musical-44-035","lineIndex":23,"speaker":"","original":"Doch ist er kalt und ungerecht dann muss er sehr verzweifelt sein.","sourceLineIndex":35,"ipa":"/dɔx ɪst ɛɾ kˈalt ʊnt ˈʊnɡərˌɛçt dan mˈʊs ɛɾ zˈeːɾ fɛɾtsvˈaɪfəlt zaɪn/","en":"But he is cold and unjust then he must be very desperate.","zh":"但他冷酷不公那么他一定非常绝望。","note":""}],"sourceOrder":44,"displayOrder":24},{"order":46,"id":"46-rebecca-mrs-danvers-favell","title":"Rebecca","titleZh":"瑞贝卡","lines":[{"id":"rebecca-das-musical-46-001","lineIndex":1,"speaker":"","original":"Rebecca - Susan Rigvava-Dumas","sourceLineIndex":1,"ipa":"/reːbˈɛkɑː zuːzˈɑːn rˈɪɡvavˌɑːdˈuːmɑːs/","en":"Rebecca - Susan Rigvava-Dumas","zh":"丽贝卡 - 苏珊·里格瓦瓦-杜马斯","note":""},{"id":"rebecca-das-musical-46-002","lineIndex":2,"speaker":"","original":"Rebecca...","sourceLineIndex":2,"ipa":"/reːbˈɛkɑː/","en":"Rebecca...","zh":"丽贝卡","note":""},{"id":"rebecca-das-musical-46-003","lineIndex":3,"speaker":"","original":"Rebecca...","sourceLineIndex":3,"ipa":"/reːbˈɛkɑː/","en":"Rebecca...","zh":"丽贝卡","note":""},{"id":"rebecca-das-musical-46-004","lineIndex":4,"speaker":"","original":"Das ist ihr Bett.","sourceLineIndex":4,"ipa":"/das ɪst iːɾ bˈɛt/","en":"This is her bed.","zh":"她睡过的床","note":""},{"id":"rebecca-das-musical-46-005","lineIndex":5,"speaker":"","original":"Und hier -","sourceLineIndex":5,"ipa":"/ʊnt hˈiːɾ/","en":"And here -","zh":"这里—","note":""},{"id":"rebecca-das-musical-46-006","lineIndex":6,"speaker":"","original":"Das ist ihr Nachthemd.","sourceLineIndex":6,"ipa":"/das ɪst iːɾ nˈaxtɛmt/","en":"This is her nightgown.","zh":"有她的睡衣","note":""},{"id":"rebecca-das-musical-46-007","lineIndex":7,"speaker":"","original":"Wunderschön, sehn sie nur.","sourceLineIndex":7,"ipa":"/vˈʊndɜʃˌøːn zˈeːn ziː nˈuːɾ/","en":"Beautiful, just look at it.","zh":"您看看，多么美","note":""},{"id":"rebecca-das-musical-46-008","lineIndex":8,"speaker":"","original":"Leicht wie ein Windhauch","sourceLineIndex":8,"ipa":"/lˈaɪçt viː aɪn vˈɪnthaʊx/","en":"Light as a breeze","zh":"轻得就像一阵风","note":""},{"id":"rebecca-das-musical-46-009","lineIndex":9,"speaker":"","original":"So seidig, ein schmeichelndes nichts.","sourceLineIndex":9,"ipa":"/zoː zˈaɪdɪç aɪn ʃmˈaɪçəlndəs nˈɪçts/","en":"So silky, a flattering nothing.","zh":"柔软丝滑，薄如蝉翼","note":""},{"id":"rebecca-das-musical-46-010","lineIndex":10,"speaker":"","original":"Und jede faser, atmet noch heut den Duft ihrer Haut.","sourceLineIndex":10,"ipa":"/ʊnt jˈeːdə fˈɑːzɜ ˈatmət nɔx hˈɔøt deːn dˈʊft ˌiːrɜ hˈaʊt/","en":"And every fiber still breathes the scent of your skin.","zh":"每缕丝线至今残留她的体香","note":""},{"id":"rebecca-das-musical-46-011","lineIndex":11,"speaker":"","original":"Auch wenn sie hier nicht mehr schläft","sourceLineIndex":11,"ipa":"/ˌaʊx vˌɛn ziː hˈiːɾ nˈɪçt mˌeːɾ ʃlˈɛft/","en":"Even if she doesn't sleep here anymore","zh":"虽然她已不睡在这里","note":""},{"id":"rebecca-das-musical-46-012","lineIndex":12,"speaker":"","original":"Auch wenn sie keiner sieht -","sourceLineIndex":12,"ipa":"/ˌaʊx vˌɛn ziː kˈaɪnɜ zˈiːt/","en":"Even if no one sees her -","zh":"即使没有人看见她","note":""},{"id":"rebecca-das-musical-46-013","lineIndex":13,"speaker":"","original":"Seit sie ging, singt die Brandung ihr Lied:","sourceLineIndex":13,"ipa":"/zaɪt ziː ɡˈɪŋ zˈɪŋt diː bɾˈandʊŋ iːɾ lˈiːt/","en":"Since she left, the surf has been singing her song:","zh":"波涛却依旧唱着属于她的歌：","note":""},{"id":"rebecca-das-musical-46-014","lineIndex":14,"speaker":"","original":"Rebecca~~","sourceLineIndex":14,"ipa":"/reːbˈɛkɑː tˈɪldətˌɪldə/","en":"Rebecca~~","zh":"丽贝卡","note":""},{"id":"rebecca-das-musical-46-015","lineIndex":15,"speaker":"","original":"Wo du auch immer bist dein Herz ist ruhlos wie die wilde, freie See.","sourceLineIndex":15,"ipa":"/vˌoː duː ˌaʊx ˈɪmɜ bɪst daɪn hˈɛɾts ɪst rˈuːloːs viː diː vˈɪldə frˈaɪə zˈeː/","en":"Wherever you are your heart is restless like the wild, free sea.","zh":"无论你身在何方你的心澎湃汹涌，就如这片放荡不羁的海","note":""},{"id":"rebecca-das-musical-46-017","lineIndex":16,"speaker":"","original":"Wenn der Abend beginnt, singt der Wind","sourceLineIndex":17,"ipa":"/vˌɛn dɛɾ ˈɑːbənt bəɡˈɪnt zˈɪŋt dɛɾ vˈɪnt/","en":"When the evening begins, the wind sings","zh":"每当夜晚到来，风就开始吟唱：","note":""},{"id":"rebecca-das-musical-46-018","lineIndex":17,"speaker":"","original":"Rebecca","sourceLineIndex":18,"ipa":"/reːbˈɛkɑː/","en":"Rebecca","zh":"丽贝卡","note":""},{"id":"rebecca-das-musical-46-019","lineIndex":18,"speaker":"","original":"Komm heim, Rebecca!","sourceLineIndex":19,"ipa":"/kˈɔm hˈaɪm reːbˈɛkɑː/","en":"Come home, Rebecca!","zh":"回来吧，丽贝卡！","note":""},{"id":"rebecca-das-musical-46-020","lineIndex":19,"speaker":"","original":"Aus dem Nebelreich zurück nach Manderley.","sourceLineIndex":20,"ipa":"/ˌaʊs deːm nˈeːbəlrˌaɪç tsuːrˈuːk nɑːx mˈandɜlˌaɪ/","en":"From the Misty Realm back to Manderley.","zh":"从那雾的国度再次回到曼德雷","note":""},{"id":"rebecca-das-musical-46-021","lineIndex":20,"speaker":"","original":"Ihr Harr war dicht und weich.","sourceLineIndex":21,"ipa":"/iːɾ hˈaɾ vɑːɾ dˈɪçt ʊnt vˈaɪç/","en":"Her hair was thick and soft.","zh":"她的秀发丰美而柔软","note":""},{"id":"rebecca-das-musical-46-022","lineIndex":21,"speaker":"","original":"Ich kämmte es genau wie′s ihr Gefiel.","sourceLineIndex":22,"ipa":"/ɪç kˈɛmtə ɛs ɡənˈaʊ vˈiːs iːɾ ɡəfˈiːl/","en":"I combed it exactly as she liked.","zh":"我忠实地按照她的愿望梳理","note":""},{"id":"rebecca-das-musical-46-023","lineIndex":22,"speaker":"","original":"Tag und Nacht sah sie wie eine Königin aus.","sourceLineIndex":23,"ipa":"/tˈɑːk ʊnt nˈaxt zˈɑː ziː viː ˌaɪnə kˈøːnɪɡˌɪn ˈaʊs/","en":"Day and night she looked like a queen.","zh":"每时每刻，她都像女王般令人赞叹","note":""},{"id":"rebecca-das-musical-46-024","lineIndex":23,"speaker":"","original":"Was sie auch machte, sie hatte Haltung, hatte Stil.","sourceLineIndex":24,"ipa":"/vˈas ziː ˌaʊx mˈaxtə ziː hˌatə hˈaltʊŋ hˌatə ʃtˈiːl/","en":"Whatever she did, she had attitude, had style.","zh":"无论做什么她都风格独到，气度不凡","note":""},{"id":"rebecca-das-musical-46-025","lineIndex":24,"speaker":"","original":"Manches hat sich verändert hier, seit sie ging letztes Jahr","sourceLineIndex":25,"ipa":"/mˈançəs hat zɪç fɛɾˈɛndɜt hˈiːɾ zaɪt ziː ɡˈɪŋ lˈɛtstəs jˈɑːɾ/","en":"A lot has changed here since she left last year","zh":"自从去年她辞世之后，这里的陈设有些改变","note":""},{"id":"rebecca-das-musical-46-026","lineIndex":25,"speaker":"","original":"Doch ihr Zauber ist immer noch wahr.","sourceLineIndex":26,"ipa":"/dɔx iːɾ tsˈaʊbɜ ɪst ˈɪmɜ nɔx vˈɑːɾ/","en":"But her magic is still true.","zh":"可她的魔力萦绕不去","note":""},{"id":"rebecca-das-musical-46-027","lineIndex":26,"speaker":"","original":"Rebecca~~","sourceLineIndex":27,"ipa":"/reːbˈɛkɑː tˈɪldətˌɪldə/","en":"Rebecca~~","zh":"丽贝卡","note":""},{"id":"rebecca-das-musical-46-028","lineIndex":27,"speaker":"","original":"Wo du auch immer bist dein Herz ist ruhlos wie die wilde, freie See.","sourceLineIndex":28,"ipa":"/vˌoː duː ˌaʊx ˈɪmɜ bɪst daɪn hˈɛɾts ɪst rˈuːloːs viː diː vˈɪldə frˈaɪə zˈeː/","en":"Wherever you are your heart is restless like the wild, free sea.","zh":"无论你身在何方你的心澎湃汹涌，就如这片放荡不羁的海","note":""},{"id":"rebecca-das-musical-46-030","lineIndex":28,"speaker":"","original":"Wenn der Abend beginnt, singt der Wind:","sourceLineIndex":30,"ipa":"/vˌɛn dɛɾ ˈɑːbənt bəɡˈɪnt zˈɪŋt dɛɾ vˈɪnt/","en":"When the evening begins, the wind sings:","zh":"每当夜晚到来，风就开始吟唱：","note":""},{"id":"rebecca-das-musical-46-031","lineIndex":29,"speaker":"","original":"Rebecca","sourceLineIndex":31,"ipa":"/reːbˈɛkɑː/","en":"Rebecca","zh":"丽贝卡","note":""},{"id":"rebecca-das-musical-46-032","lineIndex":30,"speaker":"","original":"Komm heim, Rebecca!","sourceLineIndex":32,"ipa":"/kˈɔm hˈaɪm reːbˈɛkɑː/","en":"Come home, Rebecca!","zh":"回来吧，丽贝卡！","note":""},{"id":"rebecca-das-musical-46-033","lineIndex":31,"speaker":"","original":"Aus dem Nebelreich zurück nach Manderley.","sourceLineIndex":33,"ipa":"/ˌaʊs deːm nˈeːbəlrˌaɪç tsuːrˈuːk nɑːx mˈandɜlˌaɪ/","en":"From the Misty Realm back to Manderley.","zh":"从那雾的国度再次回到曼德雷","note":""}],"sourceOrder":46,"displayOrder":25},{"order":47,"id":"47-sie-s-fort-ben","title":"Sie's fort","titleZh":"她已经走了","lines":[{"id":"rebecca-das-musical-47-001","lineIndex":1,"speaker":"","original":"Sie's fort.","sourceLineIndex":1,"ipa":"/zˈiːs fˈɔɾt/","en":"It's gone.","zh":"她走了","note":""},{"id":"rebecca-das-musical-47-002","lineIndex":2,"speaker":"","original":"Sie's fort jetz'.","sourceLineIndex":2,"ipa":"/zˈiːs fˈɔɾt jˈɛts/","en":"Let's go now.","zh":"她已经离开","note":""},{"id":"rebecca-das-musical-47-003","lineIndex":3,"speaker":"","original":"Kommt nimmermehr","sourceLineIndex":3,"ipa":"/kˈɔmt nˈɪmɜmˌeːɾ/","en":"Never comes again","zh":"再也不会回来","note":""},{"id":"rebecca-das-musical-47-004","lineIndex":4,"speaker":"","original":"Liegt draussen im Meer drunten","sourceLineIndex":4,"ipa":"/lˈiːkt dɾˈaʊsən ɪm mˈeːɾ dɾˈʊntən/","en":"Lies out in the sea","zh":"在遥远的大海下面","note":""},{"id":"rebecca-das-musical-47-005","lineIndex":5,"speaker":"","original":"und kann nie mehr zurück","sourceLineIndex":5,"ipa":"/ʊnt kˌan nˈiː mˈeːɾ tsuːrˈʏk/","en":"and can never go back","zh":"再也回不来了","note":""},{"id":"rebecca-das-musical-47-006","lineIndex":6,"speaker":"","original":"Versunken, ertrunken!","sourceLineIndex":6,"ipa":"/fɛɾzˈʊŋkən ɛɾtɾˈʊŋkən/","en":"Sunk, drowned!","zh":"沉下去了，淹死了！","note":""},{"id":"rebecca-das-musical-47-007","lineIndex":7,"speaker":"","original":"Ben nicht gemacht, Ben nicht gesehen.","sourceLineIndex":7,"ipa":"/bˈeːn nˈɪçt ɡəmˈaxt bˈeːn nˈɪçt ɡəzˈeːən/","en":"Not done Ben, not seen Ben.","zh":"本什么也没做！本什么都没看见！","note":""},{"id":"rebecca-das-musical-47-008","lineIndex":8,"speaker":"","original":"Guten Tag. Ich bin Mrs. de Winter.","sourceLineIndex":8,"ipa":"/ɡˈuːtən tˈɑːk ɪç bɪn ˌɛmˌɛrˈɛs dˈeː vˈɪntɜ/","en":"Good day. I'm Mrs. de Winter.","zh":"你好，我是德温特夫人","note":""},{"id":"rebecca-das-musical-47-009","lineIndex":9,"speaker":"","original":"Mrs. kommt nimmermehr.","sourceLineIndex":9,"ipa":"/ˌɛmˌɛrˈɛs kˈɔmt nˈɪmɜmˌeːɾ/","en":"Mrs. is never coming.","zh":"夫人不会再来了","note":""},{"id":"rebecca-das-musical-47-010","lineIndex":10,"speaker":"","original":"Ich bin Mr. de Winters neue Frau.","sourceLineIndex":10,"ipa":"/ɪç bɪn ˌɛmˈɛɾ dˈeː vˈɪntɜs nˈɔøə frˈaʊ/","en":"I am Mr. de Winter's new wife.","zh":"我是德温特先生新一任的妻子","note":""},{"id":"rebecca-das-musical-47-011","lineIndex":11,"speaker":"","original":"Und wer sind Sie?","sourceLineIndex":11,"ipa":"/ʊnt vˈeːɾ zɪnt ziː/","en":"And who are you?","zh":"你是谁？","note":""},{"id":"rebecca-das-musical-47-012","lineIndex":12,"speaker":"","original":"Ben nichts getan. Ben brav.","sourceLineIndex":12,"ipa":"/bˈeːn nˈɪçts ɡətˈɑːn bˈeːn bɾˈɑːf/","en":"Ben did nothing. Ben good.","zh":"本什么也没做，本很老实的","note":""},{"id":"rebecca-das-musical-47-013","lineIndex":13,"speaker":"","original":"Ist ja schon gut, Ben. Ich schau mich ein wenig um.","sourceLineIndex":13,"ipa":"/ɪst jˈɑː ʃˌoːn ɡˈuːt bˈeːn ɪç ʃˈaʊ mɪç aɪn vˈeːnɪç ˈʊm/","en":"It's okay, Ben. I'll look around a little.","zh":"别怕，我只是来这里看看","note":""},{"id":"rebecca-das-musical-47-014","lineIndex":14,"speaker":"","original":"Wohnst du in dem Bootshuas?","sourceLineIndex":14,"ipa":"/vˈoːnst duː ɪn deːm bˈoːtshuːˌɑːs/","en":"Do you live in the Bootshuas?","zh":"你住在船屋里吗？","note":""},{"id":"rebecca-das-musical-47-015","lineIndex":15,"speaker":"","original":"Nein, nein. Ben darf da nicht rein.","sourceLineIndex":15,"ipa":"/nˈaɪn nˈaɪn bˈeːn dˈaɾf dɑː nˈɪçt rˈaɪn/","en":"No no. Ben isn't allowed in there.","zh":"不不，本不能进去","note":""},{"id":"rebecca-das-musical-47-016","lineIndex":16,"speaker":"","original":"Ist ja ganz gemütlich da drinnen.","sourceLineIndex":16,"ipa":"/ɪst jˈɑː ɡˌants ɡəmˈyːtlɪç dɑː dɾˈɪnən/","en":"It's really cozy in there.","zh":"这里面还挺舒适","note":""},{"id":"rebecca-das-musical-47-017","lineIndex":17,"speaker":"","original":"Sie kann nie mehr zurück, oder?","sourceLineIndex":17,"ipa":"/ziː kˌan nˈiː mˈeːɾ tsuːrˈʏk ˈoːdɜ/","en":"She can never go back, can she?","zh":"她再也回不来了，对吧？","note":""},{"id":"rebecca-das-musical-47-018","lineIndex":18,"speaker":"","original":"Nein, Ben. Sie ist tot.","sourceLineIndex":18,"ipa":"/nˈaɪn bˈeːn ziː ɪst tˈoːt/","en":"No, Ben. She's dead.","zh":"不会的，她死了。","note":""},{"id":"rebecca-das-musical-47-019","lineIndex":19,"speaker":"","original":"Ben nicht gesehen. Ben nicht gemacht.","sourceLineIndex":19,"ipa":"/bˈeːn nˈɪçt ɡəzˈeːən bˈeːn nˈɪçt ɡəmˈaxt/","en":"Didn't see Ben. Ben didn't do it.","zh":"本什么都没看见，本什么都没做！","note":""},{"id":"rebecca-das-musical-47-020","lineIndex":20,"speaker":"","original":"Bitte nicht ins Heim.","sourceLineIndex":20,"ipa":"/bˈɪtə nˈɪçt ɪns hˈaɪm/","en":"Please don't go to the home.","zh":"不要把本送去疯人院","note":""},{"id":"rebecca-das-musical-47-021","lineIndex":21,"speaker":"","original":"Beruhige dich, Ben! Niemand will dich in ein Heim schicken.","sourceLineIndex":21,"ipa":"/bərˈuːɪɡə dˈɪç bˈeːn nˈiːmant vɪl dɪç ɪn aɪn hˈaɪm ʃˈɪkən/","en":"Calm down, Ben! Nobody wants to send you to a home.","zh":"本冷静点！没人要把你送进疯人院","note":""},{"id":"rebecca-das-musical-47-022","lineIndex":22,"speaker":"","original":"Doch, Sie.","sourceLineIndex":22,"ipa":"/dˈɔx zˈiː/","en":"Yes, you.","zh":"有的，她会","note":""},{"id":"rebecca-das-musical-47-023","lineIndex":23,"speaker":"","original":"Aber kann Ben nicht mehr tun.","sourceLineIndex":23,"ipa":"/ˌɑːbɜ kˌan bˈeːn nˈɪçt mˌeːɾ tˈuːn/","en":"But Ben can't do that anymore.","zh":"但是她再也不能把本如何了","note":""},{"id":"rebecca-das-musical-47-024","lineIndex":24,"speaker":"","original":"Sie's fort.","sourceLineIndex":24,"ipa":"/zˈiːs fˈɔɾt/","en":"It's gone.","zh":"她走了","note":""},{"id":"rebecca-das-musical-47-025","lineIndex":25,"speaker":"","original":"Sie's fort jetz'.","sourceLineIndex":25,"ipa":"/zˈiːs fˈɔɾt jˈɛts/","en":"Let's go now.","zh":"她已经离开","note":""},{"id":"rebecca-das-musical-47-026","lineIndex":26,"speaker":"","original":"Kommt nimmermehr.","sourceLineIndex":26,"ipa":"/kˈɔmt nˈɪmɜmˌeːɾ/","en":"Never comes again.","zh":"再也不会回来","note":""},{"id":"rebecca-das-musical-47-027","lineIndex":27,"speaker":"","original":"Liegt draussen im Meer drunten","sourceLineIndex":27,"ipa":"/lˈiːkt dɾˈaʊsən ɪm mˈeːɾ dɾˈʊntən/","en":"Lies out in the sea","zh":"在遥远的大海下面","note":""},{"id":"rebecca-das-musical-47-028","lineIndex":28,"speaker":"","original":"und kann nie mehr zurück","sourceLineIndex":28,"ipa":"/ʊnt kˌan nˈiː mˈeːɾ tsuːrˈʏk/","en":"and can never go back","zh":"再也回不来了","note":""},{"id":"rebecca-das-musical-47-029","lineIndex":29,"speaker":"","original":"Versunken, ertrunken!","sourceLineIndex":29,"ipa":"/fɛɾzˈʊŋkən ɛɾtɾˈʊŋkən/","en":"Sunk, drowned!","zh":"沉下去了，淹死了！","note":""},{"id":"rebecca-das-musical-47-030","lineIndex":30,"speaker":"","original":"Was für schöne Muscheln du hast.","sourceLineIndex":30,"ipa":"/vˈas fyːɾ ʃˈøːnə mˈʊʃəln duː hast/","en":"What beautiful shells you have.","zh":"你的贝壳真漂亮","note":""},{"id":"rebecca-das-musical-47-031","lineIndex":31,"speaker":"","original":"Alles selbst gesammelt?","sourceLineIndex":31,"ipa":"/ˈaləs zˈɛlpst ɡəzˈaməlt/","en":"Collected everything yourself?","zh":"都是你自己收集的吗？","note":""},{"id":"rebecca-das-musical-47-032","lineIndex":32,"speaker":"","original":"Ja. Viele Farben. Ben gesammelt.","sourceLineIndex":32,"ipa":"/jˈɑː fˈiːlə fˈaɾbən bˈeːn ɡəzˈaməlt/","en":"Yes. Many colors. Ben collected.","zh":"对，各种颜色，都是本收集的","note":""},{"id":"rebecca-das-musical-47-033","lineIndex":33,"speaker":"","original":"Lass mal sehn. Ja, wirklich, sehr schön.","sourceLineIndex":33,"ipa":"/lˈas mˈɑːl zˈeːn jˈɑː vˈɪɾklɪç zˈeːɾ ʃˈøːn/","en":"Let's see. Yes, really, very nice.","zh":"让我看看，真的很漂亮","note":""},{"id":"rebecca-das-musical-47-034","lineIndex":34,"speaker":"","original":"Bitte nicht ins Heim!","sourceLineIndex":34,"ipa":"/bˈɪtə nˈɪçt ɪns hˈaɪm/","en":"Please don't go home!","zh":"求你，不去疯人院！","note":""},{"id":"rebecca-das-musical-47-035","lineIndex":35,"speaker":"","original":"Nein Ben, kein Heim.","sourceLineIndex":35,"ipa":"/nˈaɪn bˈeːn kˈaɪn hˈaɪm/","en":"No Ben, no home.","zh":"不会的，不去疯人院","note":""},{"id":"rebecca-das-musical-47-036","lineIndex":36,"speaker":"","original":"das versprech' ich dir.","sourceLineIndex":36,"ipa":"/das fɛɾʃpɾˈɛç ɪç dˈiːɾ/","en":"I promise you that.","zh":"我向你保证","note":""},{"id":"rebecca-das-musical-47-037","lineIndex":37,"speaker":"","original":"Du bist nicht wie die die war immer bös du bist gut.","sourceLineIndex":37,"ipa":"/duː bɪst nˈɪçt viː diː diː vɑːɾ ˈɪmɜ bˈøːs duː bɪst ɡˈuːt/","en":"You're not like her she was always bad you are good.","zh":"你和她不一样她很坏你很好","note":""},{"id":"rebecca-das-musical-47-040","lineIndex":38,"speaker":"","original":"Muss ein Engel sein siehst wie einer aus und du schaust wie nur Engel schaun.","sourceLineIndex":40,"ipa":"/mˈʊs aɪn ˈɛŋəl zaɪn zˈiːst viː ˌaɪnɜ ˌaʊs ʊnt duː ʃˈaʊst viː nˈuːɾ ˈɛŋəl ʃˈaʊn/","en":"Must be an angel you look like one and you look as only angels look.","zh":"你一定是天使你看起来就是天使你的眼神就像天使那样","note":""},{"id":"rebecca-das-musical-47-044","lineIndex":39,"speaker":"","original":"Du bist zu niemand bös tust keinen nicht hast gutes Herz.","sourceLineIndex":44,"ipa":"/duː bɪst tsuː nˈiːmant bˈøːs tˈʊst kˈaɪnən nˈɪçt hast ɡˈuːtəs hˈɛɾts/","en":"You're not angry with anyone don't do anyone you have good heart.","zh":"你对谁都很好从来不作恶心地善良","note":""},{"id":"rebecca-das-musical-47-047","lineIndex":40,"speaker":"","original":"Bleib da!","sourceLineIndex":47,"ipa":"/blˈaɪp dˈɑː/","en":"Stay there!","zh":"留在这！","note":""},{"id":"rebecca-das-musical-47-048","lineIndex":41,"speaker":"","original":"Bleib da jetz!","sourceLineIndex":48,"ipa":"/blˈaɪp dɑː jˈɛts/","en":"Stay there now!","zh":"留在这吧！","note":""},{"id":"rebecca-das-musical-47-049","lineIndex":42,"speaker":"","original":"Geh' nimmer mehr.","sourceLineIndex":49,"ipa":"/ɡˈeː nˈɪmɜ mˈeːɾ/","en":"Don't ever go again.","zh":"永远不要走","note":""},{"id":"rebecca-das-musical-47-050","lineIndex":43,"speaker":"","original":"Die and're im Meer drunten die kann dir gar nicht tun.","sourceLineIndex":50,"ipa":"/diː ˈandɾə ɪm mˈeːɾ dɾˈʊntən diː kˌan diːɾ ɡˌɑːɾnˈɪçt tˈuːn/","en":"The others in the sea below it can't do anything to you.","zh":"那个人在海底下她不能把你怎样","note":""},{"id":"rebecca-das-musical-47-052","lineIndex":44,"speaker":"","original":"Bist stärker! Bist besser!","sourceLineIndex":52,"ipa":"/bɪst ʃtˈɛɾkɜ bɪst bˈɛsɜ/","en":"You are stronger! You're better!","zh":"你更强大！你更优秀！","note":""},{"id":"rebecca-das-musical-47-053","lineIndex":45,"speaker":"","original":"Hallo! wo steckst du?","sourceLineIndex":53,"ipa":"/hˈaloː vˌoː ʃtˈɛkst duː/","en":"Hello! where are you?","zh":"喂！你在哪儿？","note":""},{"id":"rebecca-das-musical-47-054","lineIndex":46,"speaker":"","original":"Bitte, Mrs.","sourceLineIndex":54,"ipa":"/bˈɪtə ˌɛmˌɛrˈɛs/","en":"Please, Mrs.","zh":"求你了，夫人","note":""},{"id":"rebecca-das-musical-47-055","lineIndex":47,"speaker":"","original":"He, ich bin zurück!","sourceLineIndex":55,"ipa":"/hˈeː ɪç bɪn tsuːrˈʏk/","en":"Hey, I'm back!","zh":"嘿，我回来了！","note":""},{"id":"rebecca-das-musical-47-056","lineIndex":48,"speaker":"","original":"Nicht sagen. Ben nichts gemacht.","sourceLineIndex":56,"ipa":"/nˈɪçt zˈɑːɡən bˈeːn nˈɪçts ɡəmˈaxt/","en":"Don't say. Ben didn't do anything.","zh":"什么也没说，本什么也没做","note":""},{"id":"rebecca-das-musical-47-057","lineIndex":49,"speaker":"","original":"Maxim?","sourceLineIndex":57,"ipa":"/mˈaksiːm/","en":"Maxim?","zh":"马克西姆？","note":""}],"sourceOrder":47,"displayOrder":26},{"order":48,"id":"48-gott-warum-maxim","title":"Gott, warum?","titleZh":"上天，为什么","lines":[{"id":"rebecca-das-musical-48-001","lineIndex":1,"speaker":"","original":"Wo bist du denn?","sourceLineIndex":1,"ipa":"/vˌoː bɪst duː dˈɛn/","en":"Where are you then?","zh":"你到底在哪？","note":""},{"id":"rebecca-das-musical-48-002","lineIndex":2,"speaker":"","original":"Hier unten, Maxim! Beim Bootshaus...","sourceLineIndex":2,"ipa":"/hˈiːɾ ˈʊntən mˈaksiːm baɪm bˈoːtshaʊs/","en":"Down here, Maxim! At the boathouse...","zh":"在下面，马克西姆！船屋这边……","note":""},{"id":"rebecca-das-musical-48-003","lineIndex":3,"speaker":"","original":"Was zum Teufel machst du hier?","sourceLineIndex":3,"ipa":"/vˈas tsʊm tˈɔøfəl mˈaxst duː hˈiːɾ/","en":"What the hell are you doing here?","zh":"你在这里做什么？","note":""},{"id":"rebecca-das-musical-48-004","lineIndex":4,"speaker":"","original":"Ich hab mich ein wenig umgesehen. Gehört die ganze Bucht zu Manderley?","sourceLineIndex":4,"ipa":"/ɪç hˈɑːp mɪç aɪn vˈeːnɪç ˈʊmɡəzˌeːən ɡəhˈœɾt diː ɡˈantsə bˈʊxt tsuː mˈandɜlˌaɪ/","en":"I looked around a little. Does the whole bay belong to Manderley?","zh":"我在这里转了一圈。这整个海湾都属于曼德雷吗？","note":""},{"id":"rebecca-das-musical-48-005","lineIndex":5,"speaker":"","original":"Warst du im Bootshaus?","sourceLineIndex":5,"ipa":"/vɑːɾst duː ɪm bˈoːtshaʊs/","en":"Have you been to the boathouse?","zh":"你进船屋了吗？","note":""},{"id":"rebecca-das-musical-48-006","lineIndex":6,"speaker":"","original":"Nein, warum?","sourceLineIndex":6,"ipa":"/nˈaɪn vɑːrˈʊm/","en":"No, why?","zh":"没有，为什么这么问？","note":""},{"id":"rebecca-das-musical-48-007","lineIndex":7,"speaker":"","original":"Niemand geht da rein, ist das klar.","sourceLineIndex":7,"ipa":"/nˈiːmant ɡˈeːt dɑː rˈaɪn ɪst das klˈɑːɾ/","en":"Nobody goes in there, that's for sure.","zh":"任何人都不许进去，你明白的吧。","note":""},{"id":"rebecca-das-musical-48-008","lineIndex":8,"speaker":"","original":"Ich war nicht drin, Maxim.","sourceLineIndex":8,"ipa":"/ɪç vɑːɾ nˈɪçt dɾˈiːn mˈaksiːm/","en":"I wasn't there, Maxim.","zh":"我没有进去，马克西姆。","note":""},{"id":"rebecca-das-musical-48-009-a","lineIndex":9,"speaker":"","original":"Und ich will auch nicht, dass du hier herunter kommst.","sourceLineIndex":9,"ipa":"/ʊnt ɪç vɪl ˌaʊx nˈɪçt das duː hˈiːɾ hɛrˈʊntɜ kˈɔmst ɪç hˈasə dˌiːzəs dɾˈɛkɪɡə bˈoːtshaʊs ɛs mˈaxt mɪç kɾˈaŋk dɪç hˈiːɾ tsuː zˈeːən/","en":"And I don't want you to come down here either.","zh":"我也不愿意你到下面来。","note":""},{"id":"rebecca-das-musical-48-009-b","lineIndex":10,"speaker":"","original":"Ich hasse dieses dreckige Bootshaus.","sourceLineIndex":9,"ipa":"/ʊnt ɪç vɪl ˌaʊx nˈɪçt das duː hˈiːɾ hɛrˈʊntɜ kˈɔmst ɪç hˈasə dˌiːzəs dɾˈɛkɪɡə bˈoːtshaʊs ɛs mˈaxt mɪç kɾˈaŋk dɪç hˈiːɾ tsuː zˈeːən/","en":"I hate this dirty boathouse.","zh":"我讨厌这间肮脏的屋子。","note":""},{"id":"rebecca-das-musical-48-009-c","lineIndex":11,"speaker":"","original":"Es macht mich krank, dich hier zu sehen.","sourceLineIndex":9,"ipa":"/ʊnt ɪç vɪl ˌaʊx nˈɪçt das duː hˈiːɾ hɛrˈʊntɜ kˈɔmst ɪç hˈasə dˌiːzəs dɾˈɛkɪɡə bˈoːtshaʊs ɛs mˈaxt mɪç kɾˈaŋk dɪç hˈiːɾ tsuː zˈeːən/","en":"It makes me sick to see you here.","zh":"看到你在这里真让我受不了。","note":""},{"id":"rebecca-das-musical-48-010","lineIndex":12,"speaker":"","original":"Ist das da draußen eine Boje?","sourceLineIndex":10,"ipa":"/ɪst das dɑː dɾˈaʊsən ˌaɪnə bˈoːjə/","en":"Is that a buoy out there?","zh":"那边是有个浮标吗？","note":""},{"id":"rebecca-das-musical-48-011","lineIndex":13,"speaker":"","original":"Warum interessiert dich das? Was geht dich diese gottverdammte Boje an?","sourceLineIndex":11,"ipa":"/vɑːrˈʊm ˌɪntərɛsˈiːɾt dɪç das vˈas ɡˈeːt dɪç dˌiːzə ɡˈɔtfɜdˌamtə bˈoːjə ˈan/","en":"Why do you care? What's this goddamn buoy to you?","zh":"为什么你会对这个感兴趣？这该死的浮标和你有什么关系？","note":""},{"id":"rebecca-das-musical-48-012","lineIndex":14,"speaker":"","original":"Maxim, bitte!","sourceLineIndex":12,"ipa":"/mˈaksiːm bˈɪtə/","en":"Maxim, please!","zh":"马克西姆，别这样！","note":""},{"id":"rebecca-das-musical-48-013","lineIndex":15,"speaker":"","original":"Was, bitte? Was!","sourceLineIndex":13,"ipa":"/vˈas bˈɪtə vˈas/","en":"What, please? What!","zh":"怎么了！","note":""},{"id":"rebecca-das-musical-48-014","lineIndex":16,"speaker":"","original":"Bitte, Maxim! Du machst mir Angst.","sourceLineIndex":14,"ipa":"/bˈɪtə mˈaksiːm duː mˈaxst miːɾ ˈaŋst/","en":"Please, Maxim! You're scaring me.","zh":"别这样，马克西姆，你让我感到害怕。","note":""},{"id":"rebecca-das-musical-48-015","lineIndex":17,"speaker":"","original":"Hab ich denn den Verstand verlorn?","sourceLineIndex":15,"ipa":"/hˈɑːp ɪç dɛn deːn fɛɾʃtˈant fɛɾlˈɔɾn/","en":"Have I lost my mind?","zh":"莫非我已丧失了理智？","note":""},{"id":"rebecca-das-musical-48-016","lineIndex":18,"speaker":"","original":"Warum ist soviel Angst und Zorn in mir?","sourceLineIndex":16,"ipa":"/vɑːrˈʊm ɪst zˈoːviːl ˈaŋst ʊnt tsˈɔɾn ɪn mˈiːɾ/","en":"Why is there so much fear and anger in me?","zh":"为何会如此狂暴易怒？","note":""},{"id":"rebecca-das-musical-48-017","lineIndex":19,"speaker":"","original":"Ich hass mich selbst dafür.","sourceLineIndex":17,"ipa":"/ɪç hˈas mɪç zˈɛlpst dɑːfˈyːɾ/","en":"I hate myself for it.","zh":"连我也恨自己","note":""},{"id":"rebecca-das-musical-48-018","lineIndex":20,"speaker":"","original":"Was zog mich bloß an diesen Unglücksort?","sourceLineIndex":18,"ipa":"/vˈas tsˈoːk mɪç blˈoːs an dˌiːzən ˈʊnɡlˌʏksɔɾt/","en":"What drew me to this unfortunate place?","zh":"到底是什么驱使我回到这个不幸之地？","note":""},{"id":"rebecca-das-musical-48-019","lineIndex":21,"speaker":"","original":"Ich fühl, dass er verflucht, verflucht ist","sourceLineIndex":19,"ipa":"/ɪç fˈyːl das ɛɾ fɛɾflˈʊxt fɛɾflˈʊxt ɪst/","en":"I feel that he is cursed, cursed","zh":"这个地方遭到了诅咒，遭到了诅咒！","note":""},{"id":"rebecca-das-musical-48-020","lineIndex":22,"speaker":"","original":"Gott, warum","sourceLineIndex":20,"ipa":"/ɡˈɔt vɑːrˈʊm/","en":"God, why","zh":"上帝啊，为什么","note":""},{"id":"rebecca-das-musical-48-021","lineIndex":23,"speaker":"","original":"Warum kam ich zurück nach Manderley?","sourceLineIndex":21,"ipa":"/vɑːrˈʊm kˌɑːm ɪç tsuːrˈʏk nɑːx mˈandɜlˌaɪ/","en":"Why did I come back to Manderley?","zh":"为什么我回到了曼德雷？","note":""},{"id":"rebecca-das-musical-48-022","lineIndex":24,"speaker":"","original":"Als ich ein kleiner Junge war","sourceLineIndex":22,"ipa":"/als ɪç aɪn klˈaɪnɜ jˈʊŋə vɑːɾ/","en":"When I was a little boy","zh":"当我还是个懵懂少年","note":""},{"id":"rebecca-das-musical-48-023","lineIndex":25,"speaker":"","original":"Sang mich das Lied der Brandung in den Schlaf","sourceLineIndex":23,"ipa":"/zˈaŋ mɪç das lˈiːt dɛɾ bɾˈandʊŋ ɪn deːn ʃlˈɑːf/","en":"The song of the surf sang me to sleep","zh":"波涛与浪花用歌声催我入眠","note":""},{"id":"rebecca-das-musical-48-024","lineIndex":26,"speaker":"","original":"Und trug mich über's Meer","sourceLineIndex":24,"ipa":"/ʊnt tɾˈuːk mɪç ˈyːbeːɾs mˈeːɾ/","en":"And carried me across the sea","zh":"送我扬帆出海","note":""},{"id":"rebecca-das-musical-48-025","lineIndex":27,"speaker":"","original":"Jetzt klingt das Lied der Brandung geisterhaft","sourceLineIndex":25,"ipa":"/jˌɛtst klˈɪŋt das lˈiːt dɛɾ bɾˈandʊŋ ɡˈaɪstɜhˌaft/","en":"Now the song of the surf sounds ghostly","zh":"而如今波涛却像鬼魂般哀鸣","note":""},{"id":"rebecca-das-musical-48-026","lineIndex":28,"speaker":"","original":"Ich weiß, dass ich verflucht, verflucht bin Gott, warum kam ich zurück?","sourceLineIndex":26,"ipa":"/ɪç vˈaɪs das ɪç fɛɾflˈʊxt fɛɾflˈʊxt bɪn ɡˈɔt vɑːrˈʊm kˌɑːm ɪç tsuːrˈʏk/","en":"I know that I am cursed, cursed God, why did I come back?","zh":"我知道，我遭到了诅咒，遭到了诅咒！上帝啊，我为什么回来？","note":""},{"id":"rebecca-das-musical-48-028","lineIndex":29,"speaker":"","original":"Was bin ich für ein Narr","sourceLineIndex":28,"ipa":"/vˈas bɪn ɪç fyːɾ aɪn nˈaɾ/","en":"What a fool I am","zh":"我简直愚蠢透顶！","note":""},{"id":"rebecca-das-musical-48-029","lineIndex":30,"speaker":"","original":"Hier lebt die Vergangenheit","sourceLineIndex":29,"ipa":"/hˈiːɾ lˈeːpt diː fɛɾɡˈaŋənhˌaɪt/","en":"The past lives here","zh":"该过去从未过去","note":""},{"id":"rebecca-das-musical-48-030","lineIndex":31,"speaker":"","original":"Hier hat sie gewartet all die Zeit","sourceLineIndex":30,"ipa":"/hˈiːɾ hat ziː ɡəvˈaɾtət ˈal diː tsˈaɪt/","en":"She's been waiting here all this time","zh":"她的阴魂徘徊不去","note":""},{"id":"rebecca-das-musical-48-031","lineIndex":32,"speaker":"","original":"Etwas in mir glaubt daran","sourceLineIndex":31,"ipa":"/ˈɛtvɑːs ɪn miːɾ ɡlˈaʊpt dɑːrˈan/","en":"Something in me believes","zh":"心底有个声音对我说","note":""},{"id":"rebecca-das-musical-48-032","lineIndex":33,"speaker":"","original":"Dass ihre Liebe mich befrei'n kann","sourceLineIndex":32,"ipa":"/das ˌiːrə lˈiːbə mɪç bəfrˈaɪn kˌan/","en":"That her love can set me free","zh":"她的爱会让我重获新生","note":""},{"id":"rebecca-das-musical-48-033","lineIndex":34,"speaker":"","original":"Von den Bildern die mich quälen","sourceLineIndex":33,"ipa":"/fɔn deːn bˈɪldɜn diː mɪç kvˈɛːlən/","en":"Of the images that torment me","zh":"当我闭起双眼","note":""},{"id":"rebecca-das-musical-48-034","lineIndex":35,"speaker":"","original":"Wenn ich die Augen schließe","sourceLineIndex":34,"ipa":"/vˌɛn ɪç diː ˈaʊɡən ʃlˈiːsə/","en":"When I close my eyes","zh":"那些画面不会再来将我折磨","note":""},{"id":"rebecca-das-musical-48-035","lineIndex":36,"speaker":"","original":"Doch wenn ich mit ihr flieh von hier","sourceLineIndex":35,"ipa":"/dɔx vˌɛn ɪç mɪt iːɾ flˈiː fɔn hˈiːɾ/","en":"But if I flee from here with her","zh":"但我要是带她逃离此处","note":""},{"id":"rebecca-das-musical-48-036","lineIndex":37,"speaker":"","original":"dann holt uns irgendwann das Gestern ein","sourceLineIndex":36,"ipa":"/dan hˈɔlt ʊns ˈɪɾɡəndvˌan das ɡˈɛstɜn ˈaɪn/","en":"then at some point yesterday catches up with us","zh":"昨日的回忆总有一天会尾随而至","note":""},{"id":"rebecca-das-musical-48-037","lineIndex":38,"speaker":"","original":"ich käme nie zur Ruh.","sourceLineIndex":37,"ipa":"/ɪç kˈɛːmə nˈiː tsuːɾ rˈuː/","en":"I would never be able to relax.","zh":"我终将永无宁日","note":""},{"id":"rebecca-das-musical-48-038","lineIndex":39,"speaker":"","original":"Nein ich bleib da!","sourceLineIndex":38,"ipa":"/nˈaɪn ɪç blˈaɪp dˈɑː/","en":"No, I'll stay there!","zh":"不，我不走！","note":""},{"id":"rebecca-das-musical-48-039","lineIndex":40,"speaker":"","original":"Und stell mich dem was war","sourceLineIndex":39,"ipa":"/ʊnt ʃtˈɛl mɪç deːm vˈas vɑːɾ/","en":"And face what was","zh":"我要面对这一切","note":""},{"id":"rebecca-das-musical-48-040","lineIndex":41,"speaker":"","original":"Bis ich, nicht mehr verflucht","sourceLineIndex":40,"ipa":"/bˈɪs ɪç nˈɪçt mˌeːɾ fɛɾflˈʊxt/","en":"Until I, no longer cursed","zh":"直至从诅咒","note":""},{"id":"rebecca-das-musical-48-041","lineIndex":42,"speaker":"","original":"verflucht bin","sourceLineIndex":41,"ipa":"/fɛɾflˈʊxt bɪn/","en":"am cursed","zh":"从诅咒中解脱出来","note":""},{"id":"rebecca-das-musical-48-042","lineIndex":43,"speaker":"","original":"Ja, darum","sourceLineIndex":42,"ipa":"/jˈɑː dɑːrˈʊm/","en":"Yes, that's why","zh":"没错，就是为了这个","note":""},{"id":"rebecca-das-musical-48-043","lineIndex":44,"speaker":"","original":"Darum kam ich zurück nach Manderley","sourceLineIndex":43,"ipa":"/dɑːrˈʊm kˌɑːm ɪç tsuːrˈʏk nɑːx mˈandɜlˌaɪ/","en":"That's why I came back to Manderley","zh":"为了这个我才回到曼德雷！","note":""},{"id":"rebecca-das-musical-48-044","lineIndex":45,"speaker":"","original":"Und ich werde stärker sein Stärker als die Schatten und die Nacht!","sourceLineIndex":44,"ipa":"/ʊnt ɪç vˌɛɾdə ʃtˈɛɾkɜ zaɪn ʃtˈɛɾkɜ als diː ʃˈatən ʊnt diː nˈaxt/","en":"And I will be stronger Stronger than the shadows and the night!","zh":"我要变得更强让幽灵与黑夜统统退却！","note":""}],"sourceOrder":48,"displayOrder":27},{"order":49,"id":"49-heut-nacht-verzauber-ich-die-welt-ich","title":"Heut' Nacht verzauber' ich die Welt","titleZh":"今晚我将让世界着迷","lines":[{"id":"rebecca-das-musical-49-001","lineIndex":1,"speaker":"","original":"Sternenstaub im Haar","sourceLineIndex":1,"ipa":"/ʃtˈɛɾnənstˌaʊp ɪm hˈɑːɾ/","en":"Stardust in your hair","zh":"星尘在发间闪耀","note":""},{"id":"rebecca-das-musical-49-002","lineIndex":2,"speaker":"","original":"Märchen oder wahr","sourceLineIndex":2,"ipa":"/mˈɛːɾçən ˌoːdɜ vˈɑːɾ/","en":"Fairy tale or true","zh":"是童话还是现实","note":""},{"id":"rebecca-das-musical-49-003","lineIndex":3,"speaker":"","original":"Ich seh mich an und kanns","sourceLineIndex":3,"ipa":"/ɪç zˈeː mɪç an ʊnt kˈans/","en":"I look at myself and can do it","zh":"我看着自己","note":""},{"id":"rebecca-das-musical-49-004","lineIndex":4,"speaker":"","original":"Kaum glauben","sourceLineIndex":4,"ipa":"/kˈaʊm ɡlˈaʊbən/","en":"Hard to believe","zh":"无法相信","note":""},{"id":"rebecca-das-musical-49-005","lineIndex":5,"speaker":"","original":"Diese Frau im Spiegel","sourceLineIndex":5,"ipa":"/dˌiːzə frˈaʊ ɪm ʃpˈiːɡəl/","en":"That woman in the mirror","zh":"镜子里的这个女人","note":""},{"id":"rebecca-das-musical-49-006","lineIndex":6,"speaker":"","original":"Bin das wirklich ich?","sourceLineIndex":6,"ipa":"/bɪn das vˈɪɾklɪç ɪç/","en":"Is that really me?","zh":"真的是我吗","note":""},{"id":"rebecca-das-musical-49-007","lineIndex":7,"speaker":"","original":"Alle werden nach mir sehn","sourceLineIndex":7,"ipa":"/ˈalə vˌɛɾdən nɑːx miːɾ zˈeːn/","en":"Everyone will look for me","zh":"所有人都会看向我","note":""},{"id":"rebecca-das-musical-49-008","lineIndex":8,"speaker":"","original":"Geheimnisvoll und schön","sourceLineIndex":8,"ipa":"/ɡəhˈaɪmnɪsfˌɔl ʊnt ʃˈøːn/","en":"Mysterious and beautiful","zh":"神秘又美丽","note":""},{"id":"rebecca-das-musical-49-009","lineIndex":9,"speaker":"","original":"Werd ich strahlend in den Ballsaal gehn","sourceLineIndex":9,"ipa":"/vˈeːɾt ɪç ʃtɾˈɑːlənt ɪn deːn balzˈɑːl ɡˈeːn/","en":"I'll walk into the ballroom beaming","zh":"我会在舞会里万众瞩目","note":""},{"id":"rebecca-das-musical-49-010","lineIndex":10,"speaker":"","original":"Seht nur da kommt","sourceLineIndex":10,"ipa":"/zˈeːt nˈuːɾ dɑː kˈɔmt/","en":"Just look here it comes","zh":"看那里","note":""},{"id":"rebecca-das-musical-49-011","lineIndex":11,"speaker":"","original":"Die Dame in weiß","sourceLineIndex":11,"ipa":"/diː dˈɑːmə ɪn vˈaɪs/","en":"The lady in white","zh":"走来了身穿白衣的女人","note":""},{"id":"rebecca-das-musical-49-012","lineIndex":12,"speaker":"","original":"Und ich schweb' auf Musik","sourceLineIndex":12,"ipa":"/ʊnt ɪç ʃvˈeːp aʊf muːzˈiːk/","en":"And I'm into music","zh":"我随着音乐起舞","note":""},{"id":"rebecca-das-musical-49-013","lineIndex":13,"speaker":"","original":"Und ich sehe mich in jedem Blick","sourceLineIndex":13,"ipa":"/ʊnt ɪç zˈeːə mɪç ɪn jˈeːdəm blˈɪk/","en":"And I see myself in every look","zh":"所有人都在看着我","note":""},{"id":"rebecca-das-musical-49-014","lineIndex":14,"speaker":"","original":"Es gibt keinen der mich nicht bewundert","sourceLineIndex":14,"ipa":"/ɛs ɡˈiːpt kˈaɪnən dɛɾ mɪç nˈɪçt bəvˈʊndɜt/","en":"There is no one who doesn't admire me","zh":"没有人不为我惊叹","note":""},{"id":"rebecca-das-musical-49-015","lineIndex":15,"speaker":"","original":"Und nichts was mich hält","sourceLineIndex":15,"ipa":"/ʊnt nˈɪçts vˈas mɪç hˈɛlt/","en":"And nothing to hold me","zh":"没有人能阻挡我","note":""},{"id":"rebecca-das-musical-49-016","lineIndex":16,"speaker":"","original":"Ich bin so wie ich sein will","sourceLineIndex":16,"ipa":"/ɪç bɪn zoː viː ɪç zaɪn vˈɪl/","en":"I am what I want to be","zh":"我变成了我想变成的样子","note":""},{"id":"rebecca-das-musical-49-017","lineIndex":17,"speaker":"","original":"Und tu was mir gefällt","sourceLineIndex":17,"ipa":"/ʊnt tˈuː vˈas miːɾ ɡəfˈɛlt/","en":"And do what I like","zh":"做我想做的事","note":""},{"id":"rebecca-das-musical-49-018","lineIndex":18,"speaker":"","original":"Heut' Nacht verzauber' ich die Welt","sourceLineIndex":18,"ipa":"/hˈɔøt nˈaxt fɛɾtsˈaʊbɜ ɪç diː vˈɛlt/","en":"Tonight I'm enchanting the world","zh":"今晚全世界都会为我着迷","note":""},{"id":"rebecca-das-musical-49-019","lineIndex":19,"speaker":"","original":"Heut' glaub ich dass mich jeder mag","sourceLineIndex":19,"ipa":"/hˈɔøt ɡlˈaʊp ɪç das mɪç jˈeːdɜ mˈɑːk/","en":"Today I think everyone likes me","zh":"我确信今天每个人都会喜欢我","note":""},{"id":"rebecca-das-musical-49-020","lineIndex":20,"speaker":"","original":"Ganz egal was ich auch tu und sag","sourceLineIndex":20,"ipa":"/ɡˌants eːɡˈɑːl vˈas ɪç ˌaʊx tˈuː ʊnt zˈɑːk/","en":"No matter what I do and say","zh":"我可以随便做什么说什么","note":""},{"id":"rebecca-das-musical-49-021","lineIndex":21,"speaker":"","original":"Dies ist mein Tag ein Traum","sourceLineIndex":21,"ipa":"/diːs ɪst maɪn tˈɑːk aɪn tɾˈaʊm/","en":"This is my day a dream","zh":"今天对我来说就像一个梦","note":""},{"id":"rebecca-das-musical-49-022","lineIndex":22,"speaker":"","original":"Wird heute wahr!","sourceLineIndex":22,"ipa":"/vˌɪɾt hˈɔøtə vˈɑːɾ/","en":"Comes true today!","zh":"变成了现实","note":""},{"id":"rebecca-das-musical-49-023","lineIndex":23,"speaker":"","original":"Denn ich schweb' auf Musik","sourceLineIndex":23,"ipa":"/dɛn ɪç ʃvˈeːp aʊf muːzˈiːk/","en":"Because I'm into music","zh":"我随着音乐起舞","note":""},{"id":"rebecca-das-musical-49-024","lineIndex":24,"speaker":"","original":"Und ich sehe mich in jedem Blick","sourceLineIndex":24,"ipa":"/ʊnt ɪç zˈeːə mɪç ɪn jˈeːdəm blˈɪk/","en":"And I see myself in every look","zh":"所有人都在看着我","note":""},{"id":"rebecca-das-musical-49-025","lineIndex":25,"speaker":"","original":"Es gibt keinen der mich nicht bewundert","sourceLineIndex":25,"ipa":"/ɛs ɡˈiːpt kˈaɪnən dɛɾ mɪç nˈɪçt bəvˈʊndɜt/","en":"There is no one who doesn't admire me","zh":"没有人不为我惊叹","note":""},{"id":"rebecca-das-musical-49-026","lineIndex":26,"speaker":"","original":"Und nichts was mich hält","sourceLineIndex":26,"ipa":"/ʊnt nˈɪçts vˈas mɪç hˈɛlt/","en":"And nothing to hold me","zh":"没有人能阻挡我","note":""},{"id":"rebecca-das-musical-49-027","lineIndex":27,"speaker":"","original":"Einmal im Leben","sourceLineIndex":27,"ipa":"/ˈaɪnmˌɑːl ɪm lˈeːbən/","en":"Once in a lifetime","zh":"在生命中仅有这一次","note":""},{"id":"rebecca-das-musical-49-028","lineIndex":28,"speaker":"","original":"Bin ich wies mir gefällt","sourceLineIndex":28,"ipa":"/bɪn ɪç vˈiːs miːɾ ɡəfˈɛlt/","en":"I am as I like it","zh":"我对自己很满意","note":""},{"id":"rebecca-das-musical-49-029","lineIndex":29,"speaker":"","original":"Heut' Nacht verzauber' ich die Welt","sourceLineIndex":29,"ipa":"/hˈɔøt nˈaxt fɛɾtsˈaʊbɜ ɪç diː vˈɛlt/","en":"Tonight I'm enchanting the world","zh":"今晚全世界都会为我着迷","note":""}],"sourceOrder":49,"displayOrder":28},{"order":50,"id":"50-finale-erster-akt-mrs-danvers-ensemble","title":"Finale - Erster Akt","titleZh":"第一幕终曲","lines":[{"id":"rebecca-das-musical-50-001","lineIndex":1,"speaker":"","original":"Rebecca, es geht nicht ohne dich!","sourceLineIndex":1,"ipa":"/reːbˈɛkɑː ɛs ɡˈeːt nˈɪçt ˈoːnə dˈɪç/","en":"Rebecca, it doesn't work without you!","zh":"丽贝卡，这里怎么能没有你","note":""},{"id":"rebecca-das-musical-50-002","lineIndex":2,"speaker":"","original":"Wenn tausend Lichter strahlen fehlst du mehr denn je!","sourceLineIndex":2,"ipa":"/vˌɛn tˈaʊzənt lˈɪçtɜ ʃtɾˈɑːlən fˈeːlst duː mˈeːɾ dɛn jeː/","en":"When a thousand lights shine I miss you more than ever!","zh":"万千光芒聚焦的地方更不能少了你","note":""},{"id":"rebecca-das-musical-50-004","lineIndex":3,"speaker":"","original":"Alle Gäste hier warten auf dich!","sourceLineIndex":4,"ipa":"/ˈalə ɡˈɛstə hˈiːɾ vˈaɾtən aʊf dˈɪç/","en":"All guests here are waiting for you!","zh":"所有客人都在等着你","note":""},{"id":"rebecca-das-musical-50-005","lineIndex":4,"speaker":"","original":"Rebecca, komm heim Rebecca!","sourceLineIndex":5,"ipa":"/reːbˈɛkɑː kˈɔm hˈaɪm reːbˈɛkɑː/","en":"Rebecca, come home Rebecca!","zh":"丽贝卡，回家吧丽贝卡","note":""},{"id":"rebecca-das-musical-50-006","lineIndex":5,"speaker":"","original":"Aus dem Schattenreich zurück nach Manderley!","sourceLineIndex":6,"ipa":"/ˌaʊs deːm ʃˈatənrˌaɪç tsuːrˈʏk nɑːx mˈandɜlˌaɪ/","en":"From the Shadow Realm back to Manderley!","zh":"从死亡中回到曼德雷吧","note":""}],"sourceOrder":50,"displayOrder":29},{"order":52,"id":"52-und-das-und-das-und-das-ich","title":"Und das und das und das","titleZh":"还有这个、还有那个、还有这个","lines":[{"id":"rebecca-das-musical-52-001","lineIndex":1,"speaker":"","original":"Ich hatte doch keine Ah nung.","sourceLineIndex":1,"ipa":"/ɪç hˌatə dɔx kˈaɪnə ˈɑː nˈʊŋ/","en":"I had no idea.","zh":"我不知道。","note":""},{"id":"rebecca-das-musical-52-002","lineIndex":2,"speaker":"","original":"das ich dasselbe Kleidtrug wie Rebecca","sourceLineIndex":2,"ipa":"/das ɪç daszˈɛlbə klˈaɪtɾuːk viː reːbˈɛkɑː/","en":"that I was wearing the same dress as Rebecca","zh":"我和丽贝卡穿了同样的衣服","note":""},{"id":"rebecca-das-musical-52-003","lineIndex":3,"speaker":"","original":"Ich wolt' du konntest vergessen","sourceLineIndex":3,"ipa":"/ɪç vˈɔlt duː kɔntˈɛst fɛɾɡˈɛsən/","en":"I wish you could forget","zh":"我希望你能忘记","note":""},{"id":"rebecca-das-musical-52-004","lineIndex":4,"speaker":"","original":"doch du lebst noch mit Rebecca","sourceLineIndex":4,"ipa":"/dɔx duː lˈeːpst nɔx mɪt reːbˈɛkɑː/","en":"but you still live with Rebecca","zh":"但你心里仍然有着丽贝卡","note":""},{"id":"rebecca-das-musical-52-005","lineIndex":5,"speaker":"","original":"denn du liebst sie, liebst sie noch immer","sourceLineIndex":5,"ipa":"/dɛn duː lˈiːpst ziː lˈiːpst ziː nɔx ˈɪmɜ/","en":"because you love her, still love her","zh":"因为你爱她，仍然爱她","note":""},{"id":"rebecca-das-musical-52-006","lineIndex":6,"speaker":"","original":"Ich hab' es langst bemerkt","sourceLineIndex":6,"ipa":"/ɪç hˈɑːp ɛs lˈaŋst bəmˈɛɾkt/","en":"I noticed it a long time ago","zh":"我很久以前就注意到了","note":""},{"id":"rebecca-das-musical-52-007","lineIndex":7,"speaker":"","original":"wenn wir uns kiissen, denkst du an Rebecca","sourceLineIndex":7,"ipa":"/vˌɛn viːɾ ʊns kˈiːɪsən dˈɛŋkst duː an reːbˈɛkɑː/","en":"When we kiss, you think of Rebecca","zh":"当我们吻时，你会想起丽贝卡","note":""},{"id":"rebecca-das-musical-52-008","lineIndex":8,"speaker":"","original":"Und kommt sie auch nie mehr wieder.","sourceLineIndex":8,"ipa":"/ʊnt kˈɔmt ziː ˌaʊx nˈiː mˈeːɾ vˈiːdɜ/","en":"And she'll never come back again.","zh":"哪怕她再也不会回来了","note":""},{"id":"rebecca-das-musical-52-009","lineIndex":9,"speaker":"","original":"du wirst ewig auf sie warten","sourceLineIndex":9,"ipa":"/duː vˌɪɾst ˈeːvɪç aʊf ziː vˈaɾtən/","en":"you will wait for her forever","zh":"你也会永远等她","note":""},{"id":"rebecca-das-musical-52-010","lineIndex":10,"speaker":"","original":"Was auch immer ich dir bedeute","sourceLineIndex":10,"ipa":"/vˈas ˌaʊx ˈɪmɜ ɪç diːɾ bədˈɔøtə/","en":"Whatever I mean to you","zh":"无论我对你意味着什么","note":""},{"id":"rebecca-das-musical-52-011","lineIndex":11,"speaker":"","original":"Und wenn du mich ansiehst vergleichst du mich mit Rebecca","sourceLineIndex":11,"ipa":"/ʊnt vˌɛn duː mɪç ˈanzˌiːst fɛɾɡlˈaɪçst duː mɪç mɪt reːbˈɛkɑː/","en":"And when you look at me are you comparing me to Rebecca?","zh":"当你看着我时你在将我与丽贝卡进行比较吗","note":""},{"id":"rebecca-das-musical-52-013","lineIndex":12,"speaker":"","original":"Und wenn du durch das Haus gehst","sourceLineIndex":13,"ipa":"/ʊnt vˌɛn duː dʊɐç das hˈaʊs ɡˈeːst/","en":"And when you walk through the house","zh":"当你在房子里行走时","note":""},{"id":"rebecca-das-musical-52-014","lineIndex":13,"speaker":"","original":"spricht jeder Gegenstand von Rebecca","sourceLineIndex":14,"ipa":"/ʃpɾˈɪçt jˈeːdɜ ɡˈeːɡənʃtˌant fɔn reːbˈɛkɑː/","en":"every item speaks of Rebecca","zh":"每个物体都在讲述丽贝卡","note":""},{"id":"rebecca-das-musical-52-015","lineIndex":14,"speaker":"","original":"Wo immer wir gehn und stehn.","sourceLineIndex":15,"ipa":"/vˌoː ˈɪmɜ viːɾ ɡˈeːn ʊnt ʃtˈeːn/","en":"Wherever we walk and stand.","zh":"无论我们走到哪里、站在哪里。","note":""},{"id":"rebecca-das-musical-52-016","lineIndex":15,"speaker":"","original":"sie folgt dir nach wie ein Schatten","sourceLineIndex":16,"ipa":"/ziː fˈɔlkt diːɾ nɑːx viː aɪn ʃˈatən/","en":"she follows you like a shadow","zh":"她像影子一样跟着你","note":""},{"id":"rebecca-das-musical-52-017","lineIndex":16,"speaker":"","original":"Was auch immer wir tun","sourceLineIndex":17,"ipa":"/vˈas ˌaʊx ˈɪmɜ viːɾ tˈuːn/","en":"Whatever we do","zh":"无论我们做什么","note":""},{"id":"rebecca-das-musical-52-018","lineIndex":17,"speaker":"","original":"du denkst jedesmal das tat ich auch mit Rebecca","sourceLineIndex":18,"ipa":"/duː dˈɛŋkst jˈeːdɛsmˌɑːl das tˈɑːt ɪç ˌaʊx mɪt reːbˈɛkɑː/","en":"you think every time I did that too with Rebecca","zh":"无论我们做什么","note":""},{"id":"rebecca-das-musical-52-019","lineIndex":18,"speaker":"","original":"und auch das tat ich mit Rebecca","sourceLineIndex":19,"ipa":"/ʊnt ˌaʊx das tˈɑːt ɪç mɪt reːbˈɛkɑː/","en":"and I did that too with Rebecca","zh":"你都会觉得丽贝卡就是这么做的","note":""},{"id":"rebecca-das-musical-52-020","lineIndex":19,"speaker":"","original":"und das und das und das und das!","sourceLineIndex":20,"ipa":"/ʊnt das ʊnt das ʊnt das ˈʊnt das/","en":"and this and this and this and this!","zh":"还有那个那个那个","note":""},{"id":"rebecca-das-musical-52-021","lineIndex":20,"speaker":"","original":"Was ich auch tu, ist falsch","sourceLineIndex":21,"ipa":"/vˈas ɪç ˌaʊx tˈuː ɪst fˈalʃ/","en":"Whatever I do is wrong","zh":"无论我做什么都是错的","note":""},{"id":"rebecca-das-musical-52-022","lineIndex":21,"speaker":"","original":"Immer wieder steht zwischen uns Rebecca","sourceLineIndex":22,"ipa":"/ˈɪmɜ vˈiːdɜ ʃtˈeːt tsvˈɪʃən ʊns reːbˈɛkɑː/","en":"Rebecca always stands between us","zh":"丽贝卡总是站在我们之间","note":""},{"id":"rebecca-das-musical-52-023","lineIndex":22,"speaker":"","original":"Sie lebt in deinen Gedanken Nie wirst du mir ganz gehoren","sourceLineIndex":23,"ipa":"/ziː lˈeːpt ɪn dˌaɪnən ɡədˈaŋkən nˈiː vˌɪɾst duː miːɾ ɡˌants ɡəhˈoːrən/","en":"She lives in your thoughts. You will never be completely mine","zh":"她活在你的思想里。你永远不会完全属于我","note":""},{"id":"rebecca-das-musical-52-024","lineIndex":23,"speaker":"","original":"Immer fallt auf mich ihr Schatten..","sourceLineIndex":24,"ipa":"/ˈɪmɜ fˈalt aʊf mɪç iːɾ ʃˈatən/","en":"Her shadow always falls on me...","zh":"她的影子总是落在我身上……","note":""}],"sourceOrder":52,"displayOrder":30},{"order":53,"id":"53-rebecca-reprise-mrs-danvers-ich-schatten","title":"Rebecca - Reprise","titleZh":"瑞贝卡（重唱）","lines":[{"id":"rebecca-das-musical-53-001","lineIndex":1,"speaker":"","original":"Nachts in dem Haus am Meer seufzen die Schatten.","sourceLineIndex":1,"ipa":"/nˈaxts ɪn deːm hˈaʊs am mˈeːɾ zˈɔøftsən diː ʃˈatən/","en":"At night in the house by the sea sigh the shadows.","zh":"海边的这幢房子里，每夜都有幽魂嗟叹","note":""},{"id":"rebecca-das-musical-53-003","lineIndex":2,"speaker":"","original":"Hüte dich, fürchte dich.","sourceLineIndex":3,"ipa":"/hˈyːtə dˈɪç fˈʏɾçtə dˈɪç/","en":"Beware, fear.","zh":"记得提防，记得畏惧","note":""},{"id":"rebecca-das-musical-53-004","lineIndex":3,"speaker":"","original":"Denn alle Türn sind verboten versperrt und bewacht und wer hier eindringt wird verflucht sein und verloren.","sourceLineIndex":4,"ipa":"/dɛn ˈalə tˈʏɾn zɪnt fɛɾbˈoːtən fɛɾʃpˈɛɾt ʊnt bəvˈaxt ʊnt vˈeːɾ hˈiːɾ ˈaɪndɾˌɪŋt vˌɪɾt fɛɾflˈʊxt zaɪn ʊnt fɛɾlˈoːrən/","en":"Because all doors are forbidden locked and guarded and whoever enters here will be cursed and lost.","zh":"因为所有的塔楼都禁止入内大门紧锁，严加看管擅自闯入者必受诅咒，放逐不归","note":""},{"id":"rebecca-das-musical-53-007","lineIndex":4,"speaker":"","original":"Jeder Raum in diesem Haus atmet Melancholie alle Dinge hier warten auf sie.","sourceLineIndex":7,"ipa":"/jˈeːdɜ rˈaʊm ɪn dˌiːzəm hˈaʊs ˈatmət mˌeːlançoːlˈiː ˈalə dˈɪŋə hˈiːɾ vˈaɾtən aʊf ziː/","en":"Every room in this house breathes melancholy all things here are waiting for her.","zh":"这幢房子的每一间屋子里都充满着愁绪这里的一切都在等待着她","note":""},{"id":"rebecca-das-musical-53-009","lineIndex":5,"speaker":"","original":"REBECCA wo du auch immer bist dein Herz ist ruhlos wie die wilde freie See.","sourceLineIndex":9,"ipa":"/reːbˈɛkɑː vˌoː duː ˌaʊx ˈɪmɜ bɪst daɪn hˈɛɾts ɪst rˈuːloːs viː diː vˈɪldə frˈaɪə zˈeː/","en":"REBECCA wherever you are your heart is restless like the wild open sea.","zh":"丽贝卡无论你在哪里你的心总是澎湃不安就像这片狂野自由的大海","note":""},{"id":"rebecca-das-musical-53-012","lineIndex":6,"speaker":"","original":"Wenn der Abend beginnt singt der Wind:","sourceLineIndex":12,"ipa":"/vˌɛn dɛɾ ˈɑːbənt bəɡˈɪnt zˈɪŋt dɛɾ vˈɪnt/","en":"When the evening begins the wind sings:","zh":"每当夜幕降临，晚风开始颂唱","note":""},{"id":"rebecca-das-musical-53-013","lineIndex":7,"speaker":"","original":"REBECCA komm heim REBECCA aus dem Nebelreich zurück nach Manderley.","sourceLineIndex":13,"ipa":"/reːbˈɛkɑː kˈɔm hˈaɪm reːbˈɛkɑː ˌaʊs deːm nˈeːbəlrˌaɪç tsuːrˈʏk nɑːx mˈandɜlˌaɪ/","en":"REBECCA come home REBECCA from the Misty Realm back to Manderley.","zh":"丽贝卡，归来吧，丽贝卡！从那雾之国度回到曼德雷","note":""},{"id":"rebecca-das-musical-53-015","lineIndex":8,"speaker":"","original":"Nichts was ihr sagt und tut","sourceLineIndex":15,"ipa":"/nˈɪçts vˈas iːɾ zˈɑːɡt ʊnt tˈuːt/","en":"Nothing you say or do","zh":"无论你们做了什么，说了什么","note":""},{"id":"rebecca-das-musical-53-016","lineIndex":9,"speaker":"","original":"bleibt ihr verborgen","sourceLineIndex":16,"ipa":"/blˈaɪpt iːɾ fɛɾbˈɔɾɡən/","en":"remains hidden from her","zh":"你们都无法隐瞒","note":""},{"id":"rebecca-das-musical-53-017","lineIndex":10,"speaker":"","original":"Hüte dich, fürchte dich.","sourceLineIndex":17,"ipa":"/hˈyːtə dˈɪç fˈʏɾçtə dˈɪç/","en":"Beware, fear.","zh":"记得提防，记得畏惧","note":""},{"id":"rebecca-das-musical-53-018","lineIndex":11,"speaker":"","original":"Sie lässt sich nicht bestehlen und rächt den Verrat.","sourceLineIndex":18,"ipa":"/ziː lˈɛst zɪç nˈɪçt bəʃtˈeːlən ʊnt rˈɛçt deːn fɛɾrˈɑːt/","en":"She won't let herself be robbed and avenges the betrayal.","zh":"她对窃贼从不宽饶对叛徒从不留情","note":""},{"id":"rebecca-das-musical-53-020","lineIndex":12,"speaker":"","original":"Wer sie beleidigt wird es eines Tages büßen.","sourceLineIndex":20,"ipa":"/vˈeːɾ ziː bəlˈaɪdɪçt vˌɪɾt ɛs ˌaɪnəs tˈɑːɡəs bˈyːsən/","en":"Anyone who insults her will pay for it one day.","zh":"冒犯者总有一天将会接受惩罚","note":""},{"id":"rebecca-das-musical-53-021","lineIndex":13,"speaker":"","original":"Dieses Haus ist ihr zu Haus","sourceLineIndex":21,"ipa":"/dˌiːzəs hˈaʊs ɪst iːɾ tsuː hˈaʊs/","en":"This house is her home","zh":"这座房子仍是她的居所","note":""},{"id":"rebecca-das-musical-53-022","lineIndex":14,"speaker":"","original":"alles wartet auf sie","sourceLineIndex":22,"ipa":"/ˈaləs vˈaɾtət aʊf ziː/","en":"everything is waiting for you","zh":"一切都在等待着她","note":""},{"id":"rebecca-das-musical-53-023","lineIndex":15,"speaker":"","original":"Die sie liebten vergessen sie nie.","sourceLineIndex":23,"ipa":"/diː ziː lˈiːptən fɛɾɡˈɛsən ziː nˈiː/","en":"Those who loved her never forget her.","zh":"爱她的人永远都不会将她忘记","note":""},{"id":"rebecca-das-musical-53-024","lineIndex":16,"speaker":"","original":"REBECCA wo du auch immer bist dein Herz bleibt ruhlos wie die wilde freie See.","sourceLineIndex":24,"ipa":"/reːbˈɛkɑː vˌoː duː ˌaʊx ˈɪmɜ bɪst daɪn hˈɛɾts blˈaɪpt rˈuːloːs viː diː vˈɪldə frˈaɪə zˈeː/","en":"REBECCA wherever you are your heart remains restless like the wild open sea.","zh":"丽贝卡无论你在哪里你的心总是澎湃不安就像这片狂野自由的大海","note":""},{"id":"rebecca-das-musical-53-027","lineIndex":17,"speaker":"","original":"Wenn der Abend beginnt singt der Wind:","sourceLineIndex":27,"ipa":"/vˌɛn dɛɾ ˈɑːbənt bəɡˈɪnt zˈɪŋt dɛɾ vˈɪnt/","en":"When the evening begins the wind sings:","zh":"每当夜幕降临，晚风开始颂唱","note":""},{"id":"rebecca-das-musical-53-028","lineIndex":18,"speaker":"","original":"REBECCA komm heim REBECCA aus dem Nebelreich zurück nach Manderley.","sourceLineIndex":28,"ipa":"/reːbˈɛkɑː kˈɔm hˈaɪm reːbˈɛkɑː ˌaʊs deːm nˈeːbəlrˌaɪç tsuːrˈʏk nɑːx mˈandɜlˌaɪ/","en":"REBECCA come home REBECCA from the Misty Realm back to Manderley.","zh":"丽贝卡，归来吧，丽贝卡！从那雾之国度回到曼德雷","note":""},{"id":"rebecca-das-musical-53-030","lineIndex":19,"speaker":"","original":"Mrs. Danvers & Schatten: Tu nicht was sie empört! (Oh nein!)","sourceLineIndex":30,"ipa":"/ˌɛmˌɛrˈɛs dˈanfɜs ˈʊnt ʃˈatən tˈuː nˈɪçt vˈas ziː ɛmpˈœɾt ˈoː nˈaɪn/","en":"Mrs. Danvers & Shadow: Don't do what outrages her! (Oh no!)","zh":"不要做惹怒她的事！噢，不！","note":""},{"id":"rebecca-das-musical-53-031","lineIndex":20,"speaker":"","original":"Mrs. Danvers & Schatten: Nimm nicht was ihr gehört","sourceLineIndex":31,"ipa":"/ˌɛmˌɛrˈɛs dˈanfɜs ˈʊnt ʃˈatən nˈɪm nˈɪçt vˈas iːɾ ɡəhˈœɾt/","en":"Mrs. Danvers & Shadow: Don't take what's hers","zh":"不要碰属于她的东西！","note":""},{"id":"rebecca-das-musical-53-032","lineIndex":21,"speaker":"","original":"wer sie stört, wird zerstört! (Nein!)","sourceLineIndex":32,"ipa":"/vˈeːɾ ziː ʃtˈœɾt vˌɪɾt tsɛɾʃtˈœɾt nˈaɪn/","en":"Anyone who disturbs her will be destroyed! (No!)","zh":"惊扰之人，必将毁灭！不！","note":""},{"id":"rebecca-das-musical-53-033","lineIndex":22,"speaker":"","original":"REBECCA! (Sie ist fort!)","sourceLineIndex":33,"ipa":"/reːbˈɛkɑː ziː ɪst fˈɔɾt/","en":"REBECCA! (She's gone!)","zh":"丽贝卡！她早已离去！","note":""},{"id":"rebecca-das-musical-53-034","lineIndex":23,"speaker":"","original":"Wo du auch immer bist (Weit fort)","sourceLineIndex":34,"ipa":"/vˌoː duː ˌaʊx ˈɪmɜ bɪst vˈaɪt fˈɔɾt/","en":"Wherever you are (Far away)","zh":"无论你身在何方远远离去！","note":""},{"id":"rebecca-das-musical-53-035","lineIndex":24,"speaker":"","original":"Komm heim!","sourceLineIndex":35,"ipa":"/kˈɔm hˈaɪm/","en":"Come home!","zh":"归来吧！","note":""},{"id":"rebecca-das-musical-53-036","lineIndex":25,"speaker":"","original":"Dein Herz bleibt ruhlos, wie die wilde, freie See","sourceLineIndex":36,"ipa":"/daɪn hˈɛɾts blˈaɪpt rˈuːloːs viː diː vˈɪldə frˈaɪə zˈeː/","en":"Your heart remains restless, like the wild, free sea","zh":"你的心依然不安，就像狂野、自由的大海","note":""},{"id":"rebecca-das-musical-53-037","lineIndex":26,"speaker":"","original":"\"Ich\": Wer tot ist kehrt nicht mehr zurück","sourceLineIndex":37,"ipa":"/ˈɪç vˈeːɾ tˈoːt ɪst kˈeːɾt nˈɪçt mˌeːɾ tsuːrˈʏk/","en":"\"I\": He who is dead never returns","zh":"“我”：死者不会再回来","note":""},{"id":"rebecca-das-musical-53-038","lineIndex":27,"speaker":"","original":"Mrs. Danvers＆Schatten: Wenn der Abend beginnt, singt der Wind (Was war ist vorbei)","sourceLineIndex":38,"ipa":"/ˌɛmˌɛrˈɛs dˈanfɜs ʃˈatən vˌɛn dɛɾ ˈɑːbənt bəɡˈɪnt zˈɪŋt dɛɾ vˈɪnt vˈas vɑːɾ ɪst foːɾbˈaɪ/","en":"Mrs. Danvers＆Shadow: When the evening begins, the wind sings (What was is over)","zh":"每当夜幕降临，晚风开始颂唱这些都已成为过去","note":""},{"id":"rebecca-das-musical-53-039","lineIndex":28,"speaker":"","original":"Mrs. Danvers & Schatten: REBECCA Komm heim REBECCA (Warum dann hab ich Angst vor...)","sourceLineIndex":39,"ipa":"/ˌɛmˌɛrˈɛs dˈanfɜs ˈʊnt ʃˈatən reːbˈɛkɑː kˈɔm hˈaɪm reːbˈɛkɑː vɑːrˈʊm dan hˈɑːp ɪç ˈaŋst fˈɔɾ/","en":"Mrs. Danvers & Shadow: REBECCA Come home REBECCA (Then why am I afraid of...)","zh":"丽贝卡，归来吧，丽贝卡！我为什么会恐惧……","note":""},{"id":"rebecca-das-musical-53-040","lineIndex":29,"speaker":"","original":"Aus dem Nebelreich zurück nach Manderley","sourceLineIndex":40,"ipa":"/ˌaʊs deːm nˈeːbəlrˌaɪç tsuːrˈʏk nɑːx mˈandɜlˌaɪ/","en":"From the Misty Realm back to Manderley","zh":"从那雾之国度回到曼德雷","note":""},{"id":"rebecca-das-musical-53-041","lineIndex":30,"speaker":"","original":"REBECCA","sourceLineIndex":41,"ipa":"/reːbˈɛkɑː/","en":"REBECCA","zh":"丽贝卡！","note":""}],"sourceOrder":53,"displayOrder":31},{"order":54,"id":"54-kein-lacheln-war-je-so-kalt-maxim","title":"Kein Lächeln war je so kalt","titleZh":"她的笑容从未如此冰冷","lines":[{"id":"rebecca-das-musical-54-001","lineIndex":1,"speaker":"","original":"(Maxim) Ich habe sie nich geliebt.","sourceLineIndex":1,"ipa":"/mˈaksiːm ɪç hɑːbə ziː nˈɪç ɡəlˈiːpt/","en":"(Maxim) I didn't love her.","zh":"（马克西姆）我不爱她","note":""},{"id":"rebecca-das-musical-54-002","lineIndex":2,"speaker":"","original":"(Ich) Was?","sourceLineIndex":2,"ipa":"/ɪç vˈas/","en":"(I) What?","zh":"（我）什么？","note":""},{"id":"rebecca-das-musical-54-003","lineIndex":3,"speaker":"","original":"(Maxim) Ich habe Rebecca gehasst!","sourceLineIndex":3,"ipa":"/mˈaksiːm ɪç hɑːbə reːbˈɛkɑː ɡəhˈast/","en":"(Maxim) I hated Rebecca!","zh":"（马克西姆）我恨黎贝卡","note":""},{"id":"rebecca-das-musical-54-004","lineIndex":4,"speaker":"","original":"Sie war bösartig, gemein und durch und durch verdorben.","sourceLineIndex":4,"ipa":"/ziː vɑːɾ bˈøːzaɾtˌɪç ɡəmˈaɪn ʊnt dʊɐç ʊnt dʊɐç fɛɾdˈɔɾbən/","en":"She was vicious, vile and corrupt to the core.","zh":"她恶毒，肮脏，令人作呕","note":""},{"id":"rebecca-das-musical-54-005","lineIndex":5,"speaker":"","original":"Zu Liebe war sie gar nicht fähig.","sourceLineIndex":5,"ipa":"/tsuː lˈiːbə vɑːɾ ziː ɡˌɑːɾnˈɪçt fˈɛːɪç/","en":"She wasn't capable of love at all.","zh":"她从来不会真正爱一个人","note":""},{"id":"rebecca-das-musical-54-006","lineIndex":6,"speaker":"","original":"Keiner hat sie durchschaut.","sourceLineIndex":6,"ipa":"/kˈaɪnɜ hat ziː dʊɐçʃˈaʊt/","en":"Nobody saw through her.","zh":"没人能看穿她","note":""},{"id":"rebecca-das-musical-54-007","lineIndex":7,"speaker":"","original":"Jeder Mann, der sie sah","sourceLineIndex":7,"ipa":"/jˈeːdɜ mˈan dɛɾ ziː zˈɑː/","en":"Every man who saw her","zh":"每个看见她的男人","note":""},{"id":"rebecca-das-musical-54-008","lineIndex":8,"speaker":"","original":"War fasziniert, wie freundlich und charmant sie war.","sourceLineIndex":8,"ipa":"/vɑːɾ fˌastsiːnˈiːɾt viː frˈɔøntlɪç ʊnt ʃaɾmˈant ziː vɑːɾ/","en":"Was fascinated by how friendly and charming she was.","zh":"都觉得她是如此迷人，友善，让人神魂颠倒","note":""},{"id":"rebecca-das-musical-54-009","lineIndex":9,"speaker":"","original":"Alle führte sie hinters Licht.","sourceLineIndex":9,"ipa":"/ˈalə fˈyːɾtə ziː hˈɪntɜs lˈɪçt/","en":"She deceived everyone.","zh":"她都把他们蒙蔽","note":""},{"id":"rebecca-das-musical-54-010","lineIndex":10,"speaker":"","original":"Genau wie mich.","sourceLineIndex":10,"ipa":"/ɡənˈaʊ viː mɪç/","en":"Just like me.","zh":"就像我一样","note":""},{"id":"rebecca-das-musical-54-011","lineIndex":11,"speaker":"","original":"Sie lief mir nach und umschwärmten sie.","sourceLineIndex":11,"ipa":"/ziː lˈiːf miːɾ nɑːx ʊnt ˈʊmʃvˌɛɾmtən ziː/","en":"She ran after me and swarmed around them.","zh":"他们痴狂地追求她围着她团团转","note":""},{"id":"rebecca-das-musical-54-013","lineIndex":12,"speaker":"","original":"Jeder war wie von Sinnen","sourceLineIndex":13,"ipa":"/jˈeːdɜ vɑːɾ viː fɔn zˈɪnən/","en":"Everyone was out of their mind","zh":"每个人都神魂颠倒","note":""},{"id":"rebecca-das-musical-54-014","lineIndex":13,"speaker":"","original":"Genau wie ich.","sourceLineIndex":14,"ipa":"/ɡənˈaʊ viː ɪç/","en":"Just like me.","zh":"就像我一样","note":""},{"id":"rebecca-das-musical-54-015","lineIndex":14,"speaker":"","original":"Kein Lächeln war je so kalt","sourceLineIndex":15,"ipa":"/kˈaɪn lˈɛçəln vɑːɾ jeː zoː kˈalt/","en":"No smile was ever so cold","zh":"她却不挂一丝笑意，如此冷淡","note":""},{"id":"rebecca-das-musical-54-016","lineIndex":15,"speaker":"","original":"Es nahm mir den Verstand.","sourceLineIndex":16,"ipa":"/ɛs nˈɑːm miːɾ deːn fɛɾʃtˈant/","en":"It took my mind away.","zh":"她夺走了我的一切","note":""},{"id":"rebecca-das-musical-54-017","lineIndex":16,"speaker":"","original":"Vielleicht vergess ich ihr Gesicht, jedoch","sourceLineIndex":17,"ipa":"/fɪlˈaɪçt fɛɾɡˈɛs ɪç iːɾ ɡəzˈɪçt jˈeːdɔx/","en":"Maybe I'll forget her face, however","zh":"也许我能忘掉她的容颜","note":""},{"id":"rebecca-das-musical-54-018","lineIndex":17,"speaker":"","original":"Ihr Lächeln vergess ich nicht.","sourceLineIndex":18,"ipa":"/iːɾ lˈɛçəln fɛɾɡˈɛs ɪç nˈɪçt/","en":"I won't forget her smile.","zh":"但我忘不了她的微笑","note":""},{"id":"rebecca-das-musical-54-019","lineIndex":18,"speaker":"","original":"Erinn're dich an die Fahrt in die Berge mit mir.","sourceLineIndex":19,"ipa":"/ɛɾˈɪnrə dɪç an diː fˈɑːɾt ɪn diː bˈɛɾɡə mɪt mˈiːɾ/","en":"Remember the trip to the mountains with me.","zh":"记得我们一起上山的旅程","note":""},{"id":"rebecca-das-musical-54-020","lineIndex":19,"speaker":"","original":"Ich fuhr auch mit ihr auf die Höh'n von Monte Carlo.","sourceLineIndex":20,"ipa":"/ɪç fˈuːɾ ˌaʊx mɪt iːɾ aʊf diː hˈøːn fɔn mˈɔntə kˈaɾloː/","en":"I also went with her to the heights of Monte Carlo.","zh":"我也和她一起去过蒙特卡洛的高处","note":""},{"id":"rebecca-das-musical-54-021","lineIndex":20,"speaker":"","original":"Dort hat sie mir erklärt","sourceLineIndex":21,"ipa":"/dˈɔɾt hat ziː miːɾ ɛɾklˈɛɾt/","en":"There she explained to me","zh":"在那里她向我坦白","note":""},{"id":"rebecca-das-musical-54-022","lineIndex":21,"speaker":"","original":"Dass sie mich nur benutzt.","sourceLineIndex":22,"ipa":"/das ziː mɪç nˈuːɾ bənˈʊtst/","en":"That she's just using me.","zh":"她只是一直在利用我","note":""},{"id":"rebecca-das-musical-54-023","lineIndex":22,"speaker":"","original":"\"Ich schlag einen Deal vor\", sagte sie schlau","sourceLineIndex":23,"ipa":"/ɪç ʃlˈɑːk ˌaɪnən dˈiːl fˈɔɾ zˈɑːɡtə ziː ʃlˈaʊ/","en":"\"I propose a deal, \" she said slyly","zh":"“我们做个交易吧”，她说","note":""},{"id":"rebecca-das-musical-54-024","lineIndex":23,"speaker":"","original":"\"Ich betrüg dich weiter","sourceLineIndex":24,"ipa":"/ɪç bətɾˈyːk dɪç vˈaɪtɜ/","en":"\"I keep cheating on you","zh":"“我一直欺骗着你","note":""},{"id":"rebecca-das-musical-54-025","lineIndex":24,"speaker":"","original":"doch ich spiel deine Frau.\"","sourceLineIndex":25,"ipa":"/dɔx ɪç ʃpˈiːl dˌaɪnə frˈaʊ/","en":"but I play your wife.\"","zh":"但我仍可装作是你的妻子”","note":""},{"id":"rebecca-das-musical-54-026","lineIndex":25,"speaker":"","original":"Aus Angst vor dem Skandal","sourceLineIndex":26,"ipa":"/ˌaʊs ˈaŋst fˌɔɾ deːm skˈandɑːl/","en":"For fear of scandal","zh":"因为我害怕这糗事让人知晓","note":""},{"id":"rebecca-das-musical-54-027","lineIndex":26,"speaker":"","original":"Ließ ich mich ein auf den elenden Handel","sourceLineIndex":27,"ipa":"/lˈiːs ɪç mɪç aɪn aʊf deːn ˈeːlɛndən hˈandəl/","en":"If I got involved in the miserable trade","zh":"我完成了这个悲惨的交易","note":""},{"id":"rebecca-das-musical-54-028","lineIndex":27,"speaker":"","original":"Scheidung war für die de Winters tabu","sourceLineIndex":28,"ipa":"/ʃˈaɪdʊŋ vɑːɾ fyːɾ diː dˈeː vˈɪntɜs tˈɑbuː/","en":"Divorce was taboo for the de Winters","zh":"离婚是温特斯的禁忌","note":""},{"id":"rebecca-das-musical-54-029","lineIndex":28,"speaker":"","original":"Die Familienehre war mir mehr wert als mein Stolz","sourceLineIndex":29,"ipa":"/diː famˈiːlɪənˌeːrə vɑːɾ miːɾ mˈeːɾ vˈɛɾt als maɪn ʃtˈɔlts/","en":"Family honor was more valuable to me than my pride","zh":"家族的荣耀远高于我的自尊","note":""},{"id":"rebecca-das-musical-54-030","lineIndex":29,"speaker":"","original":"Das wusste sie und genoss den Triumph.","sourceLineIndex":30,"ipa":"/das vˈʊstə ziː ʊnt ɡənˈɔs deːn tɾˈiːʊmf/","en":"She knew that and enjoyed the triumph.","zh":"她知道我想的这些，为胜利沾沾自喜","note":""},{"id":"rebecca-das-musical-54-031","lineIndex":30,"speaker":"","original":"Kein Lächeln war je so kalt","sourceLineIndex":31,"ipa":"/kˈaɪn lˈɛçəln vɑːɾ jeː zoː kˈalt/","en":"No smile was ever so cold","zh":"她不挂一丝笑意，如此冷淡","note":""},{"id":"rebecca-das-musical-54-032","lineIndex":31,"speaker":"","original":"Wie gut hab ich's gekannt.","sourceLineIndex":32,"ipa":"/viː ɡˈuːt hˈɑːp ˈɪçs ɡəkˈant/","en":"How well I knew it.","zh":"我也多么清楚她的算盘","note":""},{"id":"rebecca-das-musical-54-033","lineIndex":32,"speaker":"","original":"Vielleicht vergess ich ihr Gesicht, jedoch","sourceLineIndex":33,"ipa":"/fɪlˈaɪçt fɛɾɡˈɛs ɪç iːɾ ɡəzˈɪçt jˈeːdɔx/","en":"Maybe I'll forget her face, however","zh":"也许我能忘掉她的容颜","note":""},{"id":"rebecca-das-musical-54-034","lineIndex":33,"speaker":"","original":"Ihr Lächeln vergess ich nicht.","sourceLineIndex":34,"ipa":"/iːɾ lˈɛçəln fɛɾɡˈɛs ɪç nˈɪçt/","en":"I won't forget her smile.","zh":"但我忘不了她的微笑","note":""},{"id":"rebecca-das-musical-54-035","lineIndex":34,"speaker":"","original":"Zuerst tat sie ihren Teil","sourceLineIndex":35,"ipa":"/tsuːˈeːɾst tˈɑːt ziː ˌiːrən tˈaɪl/","en":"First she did her part","zh":"起初，她扮演着这角色","note":""},{"id":"rebecca-das-musical-54-036","lineIndex":35,"speaker":"","original":"Spielte die Ehefrau","sourceLineIndex":36,"ipa":"/ʃpˈiːltə diː ˈeːɛfrˌaʊ/","en":"played the wife","zh":"假扮我的我的妻子","note":""},{"id":"rebecca-das-musical-54-037","lineIndex":36,"speaker":"","original":"Und Manderlay, so wie es heute","sourceLineIndex":37,"ipa":"/ʊnt mˈandɜlˌɛɪ zoː viː ɛs hˈɔøtə/","en":"And Manderlay, as it is today","zh":"还有曼德勒这儿，就像现在看到这样","note":""},{"id":"rebecca-das-musical-54-038","lineIndex":37,"speaker":"","original":"bewundert wird, sorgsam renoviert","sourceLineIndex":38,"ipa":"/bəvˈʊndɜt vˌɪɾt zˈɔɾɡzɑːm rˌeːnoːvˈiːɾt/","en":"is admired, carefully renovated","zh":"精心装点，令人称赞","note":""},{"id":"rebecca-das-musical-54-039","lineIndex":38,"speaker":"","original":"Ist gänzlich das Werk von Rebecca.","sourceLineIndex":39,"ipa":"/ɪst ɡˈɛntslɪç das vˈɛɾk fɔn reːbˈɛkɑː/","en":"Is entirely the work of Rebecca.","zh":"都是黎贝卡的杰作","note":""},{"id":"rebecca-das-musical-54-040","lineIndex":39,"speaker":"","original":"Doch dann lud sie ohne jede Scham Ihre Liebhaber ein Hat hier im Bootshaus die Nächte verbracht.","sourceLineIndex":40,"ipa":"/dɔx dan lˈuːt ziː ˈoːnə jˈeːdə ʃˈɑːm ˌiːrə lˈiːphɑːbɜ aɪn hat hˈiːɾ ɪm bˈoːtshaʊs diː nˈɛçtə fɛɾbɾˈaxt/","en":"But then she invited without any shame your lovers one Spent the nights here in the boathouse.","zh":"她竟毫不感到羞耻她的恋人就在这船屋里过夜","note":""},{"id":"rebecca-das-musical-54-043","lineIndex":40,"speaker":"","original":"Ich warnte sie, doch ihr Blick war voll Spott.","sourceLineIndex":43,"ipa":"/ɪç vˈaɾntə ziː dɔx iːɾ blˈɪk vɑːɾ fˈɔl ʃpˈɔt/","en":"I warned her, but her eyes were full of mockery.","zh":"我警告过她，但她目光流转，尽显嘲笑","note":""},{"id":"rebecca-das-musical-54-044","lineIndex":41,"speaker":"","original":"Kein Lächeln war je so kalt...","sourceLineIndex":44,"ipa":"/kˈaɪn lˈɛçəln vɑːɾ jeː zoː kˈalt/","en":"No smile has ever been so cold...","zh":"她不挂一丝笑意，如此冷淡","note":""},{"id":"rebecca-das-musical-54-045","lineIndex":42,"speaker":"","original":"Einer ihrer Liebhabern war ein Cousin von ihr.","sourceLineIndex":45,"ipa":"/ˌaɪnɜ ˌiːrɜ lˈiːphabɜn vɑːɾ aɪn kuːzˈiːn fɔn iːɾ/","en":"One of her lovers was a cousin of hers.","zh":"她的情人中有一个是她的表兄","note":""},{"id":"rebecca-das-musical-54-046","lineIndex":43,"speaker":"","original":"Ein windiger Bursche namens Jack Favell.","sourceLineIndex":46,"ipa":"/aɪn vˈɪndɪɡɜ bˈʊɐʃə nˈɑməns jˈak favˈɛl/","en":"A windy fellow named Jack Favell.","zh":"一个叫杰克·法维尔的年轻人","note":""},{"id":"rebecca-das-musical-54-047","lineIndex":44,"speaker":"","original":"(Ich) Ich kenne Favell.","sourceLineIndex":47,"ipa":"/ɪç ɪç kˈɛnə favˈɛl/","en":"(I) I know Favell.","zh":"（我）我认识法维尔","note":""},{"id":"rebecca-das-musical-54-048","lineIndex":45,"speaker":"","original":"Er war hier, als du in London zu tun hattest.","sourceLineIndex":48,"ipa":"/ɛɾ vɑːɾ hˈiːɾ als duː ɪn lˈɔndoːn tsuː tˈuːn hˈatəst/","en":"He was here when you were busy in London.","zh":"你在伦敦的时候，他也在这里","note":""},{"id":"rebecca-das-musical-54-049","lineIndex":46,"speaker":"","original":"(Maxim) Warum zum Teufel hast du mir das nicht erzählt?","sourceLineIndex":49,"ipa":"/mˈaksiːm vɑːrˈʊm tsʊm tˈɔøfəl hast duː miːɾ das nˈɪçt ɛɾtsˈɛːlt/","en":"(Maxim) Why the hell didn't you tell me?","zh":"（马克西姆）你为何却从未告诉我","note":""},{"id":"rebecca-das-musical-54-050","lineIndex":47,"speaker":"","original":"(Ich) Ich dachte, es würde dich wieder an Rebecca erinnern.","sourceLineIndex":50,"ipa":"/ɪç ɪç dˈaxtə ɛs vˈʏɾdə dɪç vˈiːdɜ an reːbˈɛkɑː ɛɾˈɪnɜn/","en":"(I) I thought it would remind you of Rebecca again.","zh":"（我）我想，这可能会再让你想起她","note":""},{"id":"rebecca-das-musical-54-051","lineIndex":48,"speaker":"","original":"(Maxim) Mich an Rebecca erinnern?","sourceLineIndex":51,"ipa":"/mˈaksiːm mɪç an reːbˈɛkɑː ɛɾˈɪnɜn/","en":"(Maxim) Remember Rebecca?","zh":"（马克西姆）让我再次想起她？","note":""},{"id":"rebecca-das-musical-54-052","lineIndex":49,"speaker":"","original":"Mein Gott, als ob das nötig wäre.","sourceLineIndex":52,"ipa":"/maɪn ɡˈɔt als ˌɔp das nˈøːtɪç vˈɛːrə/","en":"My God, as if that were necessary.","zh":"上帝啊，也许你是不该告诉我","note":""},{"id":"rebecca-das-musical-54-053","lineIndex":50,"speaker":"","original":"Eines Nachts kam sie heim aus London","sourceLineIndex":53,"ipa":"/ˌaɪnəs nˈaxts kˌɑːm ziː hˈaɪm ˌaʊs lˈɔndoːn/","en":"One night she came home from London","zh":"一天晚上她从伦敦回来","note":""},{"id":"rebecca-das-musical-54-054","lineIndex":51,"speaker":"","original":"Doch sie blieb nicht im Haus.","sourceLineIndex":54,"ipa":"/dɔx ziː blˈiːp nˈɪçt ɪm hˈaʊs/","en":"But she didn't stay in the house.","zh":"但她却没有在家停留","note":""},{"id":"rebecca-das-musical-54-055","lineIndex":52,"speaker":"","original":"Und als ich Licht im Bootshaus sah, war ich sicher","sourceLineIndex":55,"ipa":"/ʊnt als ɪç lˈɪçt ɪm bˈoːtshaʊs zˈɑː vɑːɾ ɪç zˈɪçɜ/","en":"And when I saw light in the boathouse I was sure","zh":"当我看到船屋里的灯光，我肯定","note":""},{"id":"rebecca-das-musical-54-056","lineIndex":53,"speaker":"","original":"Dass sie mit Favell hier unten war.","sourceLineIndex":56,"ipa":"/das ziː mɪt favˈɛl hˈiːɾ ˈʊntən vɑːɾ/","en":"That she was down here with Favell.","zh":"她和法维尔在一起","note":""},{"id":"rebecca-das-musical-54-057","lineIndex":54,"speaker":"","original":"Genug ist genug, dachte ich, und ging ins Bootshaus.","sourceLineIndex":57,"ipa":"/ɡənˈuːk ɪst ɡənˈuːk dˈaxtə ɪç ʊnt ɡˈɪŋ ɪns bˈoːtshaʊs/","en":"Enough is enough, I thought, and went into the boathouse.","zh":"够了够了，我想道，然后就进了船屋","note":""},{"id":"rebecca-das-musical-54-058","lineIndex":55,"speaker":"","original":"Doch siehe da, Rebecca war allein.","sourceLineIndex":58,"ipa":"/dɔx zˈiːə dˈɑː reːbˈɛkɑː vɑːɾ alˈaɪn/","en":"But lo and behold, Rebecca was alone.","zh":"但我看到，只有黎贝卡一个人","note":""},{"id":"rebecca-das-musical-54-059","lineIndex":56,"speaker":"","original":"Gelangweilt lag sie auf der Couch","sourceLineIndex":59,"ipa":"/ɡəlˈaŋvˌaɪlt lˈɑːk ziː aʊf dɛɾ kˈaʊtʃ/","en":"She lay bored on the couch","zh":"疲倦地躺在沙发上","note":""},{"id":"rebecca-das-musical-54-060","lineIndex":57,"speaker":"","original":"Und ihr Aschenbecher voller Kippen stand am Boden.","sourceLineIndex":60,"ipa":"/ʊnt iːɾ ˈaʃənbˌɛçɜ fˈɔlɜ kˈɪpən ʃtˈant am bˈoːdən/","en":"And her ashtray full of butts was on the floor.","zh":"她的烟灰缸翻倒在地上","note":""},{"id":"rebecca-das-musical-54-061","lineIndex":58,"speaker":"","original":"Sie war blass, schwach, doch voll Hass.","sourceLineIndex":61,"ipa":"/ziː vɑːɾ blˈas ʃvˈax dɔx fˈɔl hˈas/","en":"She was pale, weak, but full of hate.","zh":"她脸色苍白，虚弱，但充满了恨意","note":""},{"id":"rebecca-das-musical-54-062","lineIndex":59,"speaker":"","original":"Ich sagte ihr: \"Du brichst dein verdammtes Versprechen","sourceLineIndex":62,"ipa":"/ɪç zˈɑːɡtə iːɾ duː bɾˈɪkst daɪn fɛɾdˈamtəs fɛɾʃpɾˈɛçən/","en":"I told her, \"You're breaking your damn promise","zh":"我对她说：“你打破了你那该死的承诺","note":""},{"id":"rebecca-das-musical-54-063","lineIndex":60,"speaker":"","original":"Du bist schamlos","sourceLineIndex":63,"ipa":"/duː bɪst ʃˈamloːs/","en":"You are shameless","zh":"你真是无耻","note":""},{"id":"rebecca-das-musical-54-064","lineIndex":61,"speaker":"","original":"Du treibst es in meinem Haus, so als ob's ein Bordell wär.\"","sourceLineIndex":64,"ipa":"/duː tɾˈaɪpst ɛs ɪn mˌaɪnəm hˈaʊs zoː als ˈoːbs aɪn bɔɾdˈɛl vˈɛːɾ/","en":"You're doing it in my house like it's a brothel.\"","zh":"你在我的家里做这样的事情，就像这里就是妓院","note":""},{"id":"rebecca-das-musical-54-065","lineIndex":62,"speaker":"","original":"Da stand sie auf, warf den Kopf zurück","sourceLineIndex":65,"ipa":"/dɑː ʃtˈant ziː ˈaʊf vˈaɾf deːn kˈɔpf tsuːrˈʏk/","en":"Then she stood up, threw her head back","zh":"然后她站起身，回过头来","note":""},{"id":"rebecca-das-musical-54-066","lineIndex":63,"speaker":"","original":"Und sagte lächelnd:","sourceLineIndex":66,"ipa":"/ʊnt zˈɑːɡtə lˈɛçəlnt/","en":"And said with a smile:","zh":"微笑着说：","note":""},{"id":"rebecca-das-musical-54-067","lineIndex":64,"speaker":"","original":"\"Was machst du, wenn ich ein Kind bekomm?","sourceLineIndex":67,"ipa":"/vˈas mˈaxst duː vˌɛn ɪç aɪn kˈɪnt bəkˈɔm/","en":"\"What will you do if I have a child?","zh":"“当我有了孩子后，你会怎么认为","note":""},{"id":"rebecca-das-musical-54-068","lineIndex":65,"speaker":"","original":"Man wird denken, es wär deins.","sourceLineIndex":68,"ipa":"/man vˌɪɾt dˈɛŋkən ɛs vˈɛːɾ dˈaɪns/","en":"People will think it's yours.","zh":"你会认为，那就是你的孩子","note":""},{"id":"rebecca-das-musical-54-069","lineIndex":66,"speaker":"","original":"Auf jeden Fall ist es meins","sourceLineIndex":69,"ipa":"/aʊf jˈeːdən fˈal ɪst ɛs mˈaɪns/","en":"In any case it's mine","zh":"但无论如何，那孩子是我的","note":""},{"id":"rebecca-das-musical-54-070","lineIndex":67,"speaker":"","original":"Und einmal wird Manderlay ihm gehörn.","sourceLineIndex":70,"ipa":"/ʊnt ˈaɪnmˌɑːl vˌɪɾt mˈandɜlˌɛɪ iːm ɡəhˈœɾn/","en":"And one day Manderlay will be his.","zh":"一但这让曼德勒的人知道了","note":""},{"id":"rebecca-das-musical-54-071","lineIndex":68,"speaker":"","original":"Deine perfekte Gattin, Max, wird die perfekte Mutter sein","sourceLineIndex":71,"ipa":"/dˌaɪnə pɛɾfˈɛktə ɡˈatɪn mˈɑːks vˌɪɾt diː pɛɾfˈɛktə mˈʊtɜ zaɪn/","en":"Your perfect wife, Max, will be the perfect mother","zh":"你这完美的妻子，马克西姆，将成为完美的母亲","note":""},{"id":"rebecca-das-musical-54-072","lineIndex":69,"speaker":"","original":"Und du spielst den Papa","sourceLineIndex":72,"ipa":"/ʊnt duː ʃpˈiːlst deːn pˈɑpɑː/","en":"And you play the dad","zh":"然后你就扮演了那个父亲","note":""},{"id":"rebecca-das-musical-54-073","lineIndex":70,"speaker":"","original":"Als der perfekte Narr!\"","sourceLineIndex":73,"ipa":"/als dɛɾ pɛɾfˈɛktə nˈaɾ/","en":"As the perfect fool!\"","zh":"同时还是那个傻瓜","note":""},{"id":"rebecca-das-musical-54-074","lineIndex":71,"speaker":"","original":"Kein Lächeln war je so kalt","sourceLineIndex":74,"ipa":"/kˈaɪn lˈɛçəln vɑːɾ jeː zoː kˈalt/","en":"No smile was ever so cold","zh":"她不挂一丝笑意，如此冷淡","note":""},{"id":"rebecca-das-musical-54-075","lineIndex":72,"speaker":"","original":"So lächelte nur sie.","sourceLineIndex":75,"ipa":"/zoː lˈɛçəltə nˈuːɾ ziː/","en":"So only she smiled.","zh":"就这样，只有她一个人笑了","note":""},{"id":"rebecca-das-musical-54-076","lineIndex":73,"speaker":"","original":"Mir stieg das Blut zu Kopf.","sourceLineIndex":76,"ipa":"/miːɾ ʃtˈiːk das blˈuːt tsuː kˈɔpf/","en":"The blood rushed to my head.","zh":"血从她的脑袋上流下来","note":""},{"id":"rebecca-das-musical-54-077","lineIndex":74,"speaker":"","original":"Ich stieß sie weg, und sie stürzte und fiel","sourceLineIndex":77,"ipa":"/ɪç ʃtˈiːs ziː vˈɛk ʊnt ziː ʃtˈʏɾtstə ʊnt fˈiːl/","en":"I pushed her away and she tumbled and fell","zh":"我一把把她推开，她踉跄地跌倒了","note":""},{"id":"rebecca-das-musical-54-078","lineIndex":75,"speaker":"","original":"Ich weiß nicht wie's geschah","sourceLineIndex":78,"ipa":"/ɪç vˈaɪs nˈɪçt vˈiːs ɡəʃˈɑː/","en":"I don't know how it happened","zh":"我不知道这是怎么发生的","note":""},{"id":"rebecca-das-musical-54-079","lineIndex":76,"speaker":"","original":"Sie lag da.","sourceLineIndex":79,"ipa":"/ziː lˈɑːk dˈɑː/","en":"She lay there.","zh":"她躺在那儿","note":""},{"id":"rebecca-das-musical-54-080","lineIndex":77,"speaker":"","original":"Ich dachte, ich helf ihr auf Jedoch - sie war tot!","sourceLineIndex":80,"ipa":"/ɪç dˈaxtə ɪç hˈɛlf iːɾ aʊf jˈeːdɔx ziː vɑːɾ tˈoːt/","en":"I thought I'd help her up However - she was dead!","zh":"我以为我能帮她但—她死了","note":""},{"id":"rebecca-das-musical-54-082","lineIndex":78,"speaker":"","original":"Und lächelte noch.","sourceLineIndex":82,"ipa":"/ʊnt lˈɛçəltə nɔx/","en":"And still smiled.","zh":"仍在微笑着","note":""},{"id":"rebecca-das-musical-54-083","lineIndex":79,"speaker":"","original":"Dann trug ich sie auf ihr Boot","sourceLineIndex":83,"ipa":"/dan tɾˈuːk ɪç ziː aʊf iːɾ bˈoːt/","en":"Then I carried her onto her boat","zh":"然后我把她抬上她的船","note":""},{"id":"rebecca-das-musical-54-084","lineIndex":80,"speaker":"","original":"Und brachte sie nach unten.","sourceLineIndex":84,"ipa":"/ʊnt bɾˈaxtə ziː nɑːx ˈʊntən/","en":"And brought her downstairs.","zh":"把她藏在船底","note":""},{"id":"rebecca-das-musical-54-085","lineIndex":81,"speaker":"","original":"Dann fuhr ich das Boot hinaus","sourceLineIndex":85,"ipa":"/dan fˈuːɾ ɪç das bˈoːt hɪnˈaʊs/","en":"Then I drove the boat out","zh":"然后我把船开走了","note":""},{"id":"rebecca-das-musical-54-086","lineIndex":82,"speaker":"","original":"Und versenkte es, wo man es heute fand.","sourceLineIndex":86,"ipa":"/ʊnt fɛɾzˈɛŋktə ɛs vˌoː man ɛs hˈɔøtə fˈant/","en":"And sank it where it was found today.","zh":"把她沉在人们今天发现她的地方","note":""},{"id":"rebecca-das-musical-54-087","lineIndex":83,"speaker":"","original":"Sie hat mich besiegt","sourceLineIndex":87,"ipa":"/ziː hat mɪç bəzˈiːkt/","en":"She defeated me","zh":"她打败了我","note":""},{"id":"rebecca-das-musical-54-088","lineIndex":84,"speaker":"","original":"Sie gewinnt noch im Tod!","sourceLineIndex":88,"ipa":"/ziː ɡəvˈɪnt nɔx ɪm tˈoːt/","en":"She still wins in death!","zh":"她死了，也赢得了胜利","note":""},{"id":"rebecca-das-musical-54-089","lineIndex":85,"speaker":"","original":"Kein Lächeln war je so kalt","sourceLineIndex":89,"ipa":"/kˈaɪn lˈɛçəln vɑːɾ jeː zoː kˈalt/","en":"No smile was ever so cold","zh":"她不挂一丝笑意，如此冷淡","note":""},{"id":"rebecca-das-musical-54-090","lineIndex":86,"speaker":"","original":"Es nahm mir den Verstand.","sourceLineIndex":90,"ipa":"/ɛs nˈɑːm miːɾ deːn fɛɾʃtˈant/","en":"It took my mind away.","zh":"这一切让我心烦意乱","note":""},{"id":"rebecca-das-musical-54-091","lineIndex":87,"speaker":"","original":"Es ist ihr Lächeln, das ich vor mir seh","sourceLineIndex":91,"ipa":"/ɛsɪst iːɾ lˈɛçəln das ɪç fˌɔɾ miːɾ zˈeː/","en":"It's her smile that I see before me","zh":"这一切都是她的微笑，就像我先前所看到的","note":""},{"id":"rebecca-das-musical-54-092","lineIndex":88,"speaker":"","original":"Wohin ich auch geh.","sourceLineIndex":92,"ipa":"/voːhˈiːn ɪç ˌaʊx ɡˈeː/","en":"Wherever I go.","zh":"现在这微笑已经无处不在了","note":""},{"id":"rebecca-das-musical-54-093","lineIndex":89,"speaker":"","original":"Kein Lächeln war je","sourceLineIndex":93,"ipa":"/kˈaɪn lˈɛçəln vɑːɾ jeː/","en":"No smile ever was","zh":"没有任何微笑","note":""},{"id":"rebecca-das-musical-54-094","lineIndex":90,"speaker":"","original":"Kein Lächeln war je so kalt!","sourceLineIndex":94,"ipa":"/kˈaɪn lˈɛçəln vɑːɾ jeː zoː kˈalt/","en":"No smile has ever been so cold!","zh":"没有任何微笑像这样冷酷了","note":""}],"sourceOrder":54,"displayOrder":32},{"order":55,"id":"55-die-starke-einer-frau-beatrice-ich","title":"Die Stärke einer Frau","titleZh":"一个女人的力量","lines":[{"id":"rebecca-das-musical-55-001","lineIndex":1,"speaker":"","original":"Ich bin wirklich froh, dass er dich hat","sourceLineIndex":1,"ipa":"/ɪç bɪn vˈɪɾklɪç frˈoː das ɛɾ dˈɪç hat/","en":"I'm really glad he has you","zh":"我真高兴，他娶了你","note":""},{"id":"rebecca-das-musical-55-002","lineIndex":2,"speaker":"","original":"Du glaubst an ihn, wenn er zweifelt an sich","sourceLineIndex":2,"ipa":"/duː ɡlˈaʊbst an ˈiːn vˌɛn ɛɾ tsvˈaɪfəlt an zɪç/","en":"You believe in him when he doubts himself","zh":"他要是置疑自己，你给他信心","note":""},{"id":"rebecca-das-musical-55-003","lineIndex":3,"speaker":"","original":"Du fühlst die Angst, die er nie eingesteht","sourceLineIndex":3,"ipa":"/duː fˈyːlst diː ˈaŋst diː ɛɾ nˈiː ˈaɪnɡəʃtˌeːt/","en":"You feel the fear that he never admits","zh":"他要是感到恐惧，你感同身受","note":""},{"id":"rebecca-das-musical-55-004","lineIndex":4,"speaker":"","original":"Gibt er die Hoffnung auf, reicht dein Mut für zwei","sourceLineIndex":4,"ipa":"/ɡˈiːpt ɛɾ diː hˈɔfnʊŋ ˈaʊf rˈaɪçt daɪn mˈuːt fyːɾ tsvˈaɪ/","en":"If he gives up hope, your courage is enough for two","zh":"他要是失去信念，你给他勇气","note":""},{"id":"rebecca-das-musical-55-005","lineIndex":5,"speaker":"","original":"Du zeigst ihm einen Weg, auf dem es weitergeht","sourceLineIndex":5,"ipa":"/duː tsˈaɪkst iːm ˌaɪnən vˈeːk aʊf deːm ɛs vˈaɪtɜɡˌeːt/","en":"You show him a path to continue","zh":"你为他指明出路，引导他前行","note":""},{"id":"rebecca-das-musical-55-006","lineIndex":6,"speaker":"","original":"In dir ist die Stärke einer Frau","sourceLineIndex":6,"ipa":"/ɪn diːɾ ɪst diː ʃtˈɛɾkə ˌaɪnɜ frˈaʊ/","en":"There is a woman's strength in you","zh":"别小看一个女人的力量","note":""},{"id":"rebecca-das-musical-55-007","lineIndex":7,"speaker":"","original":"Die kämpft um den Mann, den sie liebt","sourceLineIndex":7,"ipa":"/diː kˈɛmpft ʊm deːn mˈan deːn ziː lˈiːpt/","en":"She's fighting for the man she loves","zh":"她会为自己所爱的男人而战","note":""},{"id":"rebecca-das-musical-55-008","lineIndex":8,"speaker":"","original":"Wenn sie fühlt, dass er in Gefahr ist","sourceLineIndex":8,"ipa":"/vˌɛn ziː fˈyːlt das ɛɾ ɪn ɡəfˈɑːɾ ɪst/","en":"If she feels that he is in danger","zh":"当她感到他身陷险境时","note":""},{"id":"rebecca-das-musical-55-009","lineIndex":9,"speaker":"","original":"Versetzt sie Berge und teilt das Meer","sourceLineIndex":9,"ipa":"/fɛɾzˈɛtst ziː bˈɛɾɡə ʊnt tˈaɪlt das mˈeːɾ/","en":"She moves mountains and divides the sea","zh":"移山填海她无所不能","note":""},{"id":"rebecca-das-musical-55-010","lineIndex":10,"speaker":"","original":"Mit der Stärke einer liebenden Frau","sourceLineIndex":10,"ipa":"/mɪt dɛɾ ʃtˈɛɾkə ˌaɪnɜ lˈiːbəndən frˈaʊ/","en":"With the strength of a loving woman","zh":"爱情赋予女人无穷力量","note":""},{"id":"rebecca-das-musical-55-011","lineIndex":11,"speaker":"","original":"Du holst ihn ein, wenn er sich verirrt","sourceLineIndex":11,"ipa":"/duː hˈoːlst iːn ˈaɪn vˌɛn ɛɾ zɪç fɛɾˈɪɾt/","en":"You catch up with him when he gets lost","zh":"当他迷失时，你寻他回家","note":""},{"id":"rebecca-das-musical-55-012","lineIndex":12,"speaker":"","original":"Ich bau ihn auf, wenn er müde wird","sourceLineIndex":12,"ipa":"/ɪç bˈaʊ iːn ˈaʊf vˌɛn ɛɾ mˈyːdə vˌɪɾt/","en":"I pick him up when he gets tired","zh":"当他疲惫时，我让他重新振作","note":""},{"id":"rebecca-das-musical-55-013","lineIndex":13,"speaker":"","original":"Du stellst dich vor ihn, wenn man ihn bedroht","sourceLineIndex":13,"ipa":"/duː ʃtˈɛlst dɪç fˌɔɾ ˈiːn vˌɛn man iːn bədɾˈoːt/","en":"You stand in front of him when he is threatened","zh":"他要是面临威胁，你挡在他身前","note":""},{"id":"rebecca-das-musical-55-014","lineIndex":14,"speaker":"","original":"Ich sprech für ihn, wenn er allein ist","sourceLineIndex":14,"ipa":"/ɪç ʃpɾˈɛç fyːɾ ˈiːn vˌɛn ɛɾ alˈaɪn ɪst/","en":"I speak for him when he is alone","zh":"他要是孤独无助，我会为他辩护","note":""},{"id":"rebecca-das-musical-55-015","lineIndex":15,"speaker":"","original":"Eine Frau läuft, nicht fort wenn man sie braucht","sourceLineIndex":15,"ipa":"/ˌaɪnə frˈaʊ lˈɔøft nˈɪçt fˈɔɾt vˌɛn man ziː bɾˈaʊxt/","en":"A woman doesn't run away when she's needed","zh":"当需要她时，女人不会逃离","note":""},{"id":"rebecca-das-musical-55-016","lineIndex":16,"speaker":"","original":"Was in ihr steckt, zeigt sich oft im Augenblick der Not","sourceLineIndex":16,"ipa":"/vˈas ɪn iːɾ ʃtˈɛkt tsˈaɪkt zɪç ˈɔft ɪm ˈaʊɡənblˌɪk dɛɾ nˈoːt/","en":"What's inside her often shows up in the moment of need","zh":"她内在的潜能往往在危急时刻显现","note":""},{"id":"rebecca-das-musical-55-017","lineIndex":17,"speaker":"","original":"Denn das ist die Stärke einer Frau","sourceLineIndex":17,"ipa":"/dɛn das ɪst diː ʃtˈɛɾkə ˌaɪnɜ frˈaʊ/","en":"Because that is the strength of a woman","zh":"因为这就是一个女人的力量","note":""},{"id":"rebecca-das-musical-55-018","lineIndex":18,"speaker":"","original":"Sie kämpft um den Mann, den sie liebt","sourceLineIndex":18,"ipa":"/ziː kˈɛmpft ʊm deːn mˈan deːn ziː lˈiːpt/","en":"She fights for the man she loves","zh":"她会为自己所爱的男人而战","note":""},{"id":"rebecca-das-musical-55-019","lineIndex":19,"speaker":"","original":"Wenn sie fühlt, dass er in Gefahr ist","sourceLineIndex":19,"ipa":"/vˌɛn ziː fˈyːlt das ɛɾ ɪn ɡəfˈɑːɾ ɪst/","en":"If she feels that he is in danger","zh":"当她感到他身陷险境时","note":""},{"id":"rebecca-das-musical-55-020","lineIndex":20,"speaker":"","original":"Versetzt sie Berge und teilt das Meer","sourceLineIndex":20,"ipa":"/fɛɾzˈɛtst ziː bˈɛɾɡə ʊnt tˈaɪlt das mˈeːɾ/","en":"She moves mountains and divides the sea","zh":"移山填海她无所不能","note":""},{"id":"rebecca-das-musical-55-021","lineIndex":21,"speaker":"","original":"Mit der Stärke einer liebenden Frau","sourceLineIndex":21,"ipa":"/mɪt dɛɾ ʃtˈɛɾkə ˌaɪnɜ lˈiːbəndən frˈaʊ/","en":"With the strength of a loving woman","zh":"爱情赋予女人无穷力量","note":""},{"id":"rebecca-das-musical-55-022","lineIndex":22,"speaker":"","original":"In der Dunkelheit gibt sie ihm Zeichen","sourceLineIndex":22,"ipa":"/ɪn dɛɾ dˈʊnkəlhˌaɪt ɡˈiːpt ziː iːm tsˈaɪçən/","en":"In the darkness she gives him signs","zh":"在黑暗中，她为他指引方向","note":""},{"id":"rebecca-das-musical-55-023","lineIndex":23,"speaker":"","original":"Und im Sturm der Zeit gibt sie ihm Halt","sourceLineIndex":23,"ipa":"/ʊnt ɪm ʃtˈʊɐm dɛɾ tsˈaɪt ɡˈiːpt ziː iːm hˈalt/","en":"And in the storm of time she gives him support","zh":"在时光的风暴中，她给他依靠","note":""},{"id":"rebecca-das-musical-55-024","lineIndex":24,"speaker":"","original":"In dir (mir ) ist die Stärke einer Frau","sourceLineIndex":24,"ipa":"/ɪn diːɾ miːɾ ɪst diː ʃtˈɛɾkə ˌaɪnɜ frˈaʊ/","en":"In you (me) is the strength of a woman","zh":"在你（我）身上都有一个女人的力量","note":""},{"id":"rebecca-das-musical-55-025","lineIndex":25,"speaker":"","original":"Die kämpft um den Mann, den sie liebt","sourceLineIndex":25,"ipa":"/diː kˈɛmpft ʊm deːn mˈan deːn ziː lˈiːpt/","en":"She's fighting for the man she loves","zh":"她会为自己所爱的男人而战","note":""},{"id":"rebecca-das-musical-55-026","lineIndex":26,"speaker":"","original":"Wenn sie fühlt, dass er in Gefahr ist","sourceLineIndex":26,"ipa":"/vˌɛn ziː fˈyːlt das ɛɾ ɪn ɡəfˈɑːɾ ɪst/","en":"If she feels that he is in danger","zh":"当她感到他身陷险境时","note":""},{"id":"rebecca-das-musical-55-027","lineIndex":27,"speaker":"","original":"Versetzt sie Berge und teilt das Meer","sourceLineIndex":27,"ipa":"/fɛɾzˈɛtst ziː bˈɛɾɡə ʊnt tˈaɪlt das mˈeːɾ/","en":"She moves mountains and divides the sea","zh":"移山填海她无所不能","note":""},{"id":"rebecca-das-musical-55-028","lineIndex":28,"speaker":"","original":"Mit der Stärke einer liebenden","sourceLineIndex":28,"ipa":"/mɪt dɛɾ ʃtˈɛɾkə ˌaɪnɜ lˈiːbəndən/","en":"With the strength of a loving one","zh":"爱情赋予女人","note":""},{"id":"rebecca-das-musical-55-029","lineIndex":29,"speaker":"","original":"Stärke einer liebenden","sourceLineIndex":29,"ipa":"/ʃtˈɛɾkə ˌaɪnɜ lˈiːbəndən/","en":"Strength of a loving one","zh":"爱情赋予女人","note":""},{"id":"rebecca-das-musical-55-030","lineIndex":30,"speaker":"","original":"Der Stärke einer liebenden Frau","sourceLineIndex":30,"ipa":"/dɛɾ ʃtˈɛɾkə ˌaɪnɜ lˈiːbəndən frˈaʊ/","en":"The strength of a loving woman","zh":"爱情赋予女人无穷力量","note":""}],"sourceOrder":55,"displayOrder":33},{"order":56,"id":"56-die-neue-mrs-de-winter-reprise-ensemble","title":"Die neue Mrs. de Winter - Reprise","titleZh":"新的德温特夫人（重唱）","lines":[{"id":"rebecca-das-musical-56-001","lineIndex":1,"speaker":"","original":"Schleppt, schleift und schiebt denn es gibt viel zu tun nichts bleibt wie immer!","sourceLineIndex":1,"ipa":"/ʃlˈɛpt ʃlˈaɪft ʊnt ʃˈiːpt dɛn ɛs ɡˈiːpt fˈiːl tsuː tˈuːn nˈɪçts blˈaɪpt viː ˈɪmɜ/","en":"Drags, grinds and pushes because there is a lot to do nothing stays the same!","zh":"抬来搬去有很多事情要做一夜之间天翻地覆！","note":""},{"id":"rebecca-das-musical-56-004","lineIndex":2,"speaker":"","original":"Rutscht, rollt und rückt","sourceLineIndex":4,"ipa":"/rˈʊtʃt rˈɔlt ʊnt rˈʏkt/","en":"Slips, rolls and shifts","zh":"东搬西扛","note":""},{"id":"rebecca-das-musical-56-005","lineIndex":3,"speaker":"","original":"zeiht und drückt","sourceLineIndex":5,"ipa":"/tsˈaɪht ʊnt dɾˈʏkt/","en":"pulls and pushes","zh":"又拉又拽","note":""},{"id":"rebecca-das-musical-56-006","lineIndex":4,"speaker":"","original":"Stück für Stück wird gründlich umgeräumt.","sourceLineIndex":6,"ipa":"/ʃtˈʏk fyːɾ ʃtˈʏk vˌɪɾt ɡɾˈʏntlɪç ˈʊmɡərˌɔømt/","en":"Little by little is thoroughly rearranged.","zh":"一点一点彻底重新安排。","note":""},{"id":"rebecca-das-musical-56-008","lineIndex":5,"speaker":"","original":"Nichts bleibt da wo es war von dem ganzen Inventar.","sourceLineIndex":8,"ipa":"/nˈɪçts blˈaɪpt dɑː vˌoː ɛs vɑːɾ fɔn deːm ɡˈantsən ˌɪnvəntˈɑːɾ/","en":"Nothing remains there where it was of the entire inventory.","zh":"改朝换代任何摆设都不能让人想起","note":""},{"id":"rebecca-das-musical-56-011","lineIndex":6,"speaker":"","original":"Und von uns'rer alten Mrs. de Winter!","sourceLineIndex":11,"ipa":"/ʊnt fɔn ˈʊnsrɜ ˈaltən ˌɛmˌɛrˈɛs dˈeː vˈɪntɜ/","en":"And from our old Mrs. de Winter!","zh":"我们曾经的德温特夫人！","note":""},{"id":"rebecca-das-musical-56-012","lineIndex":7,"speaker":"","original":"Schafft alles raus aus dem Haus damit nichts an sie erinnert.","sourceLineIndex":12,"ipa":"/ʃˈaft ˈaləs rˈaʊs ˌaʊs deːm hˈaʊs dɑːmˈɪt nˈɪçts an ziː ɛɾˈɪnɜt/","en":"Get it all out out of the house so that nothing reminds you of her.","zh":"属于她的器具物品全扔出去，一件不留","note":""},{"id":"rebecca-das-musical-56-015","lineIndex":8,"speaker":"","original":"Weg damit und fragt nicht weiter nach dem Grund.","sourceLineIndex":15,"ipa":"/vˈeːk dɑːmˈɪt ʊnt frˈɑːkt nˈɪçt vˈaɪtɜ nɑːx deːm ɡɾˈʊnt/","en":"Away with it and don't ask the reason any further.","zh":"只管丢掉别追问原因。","note":""},{"id":"rebecca-das-musical-56-017","lineIndex":9,"speaker":"","original":"Was geschieht ist der Wunsch uns'rer neuen Mrs. de Winter.","sourceLineIndex":17,"ipa":"/vˈas ɡəʃˈiːt ɪst dɛɾ vˈʊnʃ ˈʊnsrɜ nˈɔøən ˌɛmˌɛrˈɛs dˈeː vˈɪntɜ/","en":"What happens is the wish our new Mrs. de Winter.","zh":"我们只需按命行事服从我们的新德温特夫人。","note":""},{"id":"rebecca-das-musical-56-019","lineIndex":10,"speaker":"","original":"Füllt Wand und Fach unterm Dach mit den Bildern und den Büchern.","sourceLineIndex":19,"ipa":"/fˈʏlt vˈant ʊnt fˈax ˈʊntˌɛɾm dˈax mɪt deːn bˈɪldɜn ʊnt deːn bˈyːçɜn/","en":"Fills the wall and compartment under the roof with the pictures and the books.","zh":"橱橱柜柜，一层一格绘画和书籍","note":""},{"id":"rebecca-das-musical-56-021","lineIndex":11,"speaker":"","original":"Schlagt das Geschirr in Papier und passt auf in den Kisten ist das Glas.","sourceLineIndex":21,"ipa":"/ʃlˈɑːkt das ɡəʃˈɪɾ ɪn papˈiːɾ ʊnt pˈast aʊf ɪn deːn kˈɪstən ɪst das ɡlˈɑːs/","en":"Wrap the dishes in paper and be careful, the glass is in the boxes.","zh":"搬进搬出，盘盘碗碗小心的把玻璃在盒子里","note":""},{"id":"rebecca-das-musical-56-023","lineIndex":12,"speaker":"","original":"Alles wird neu möbliert.","sourceLineIndex":23,"ipa":"/ˈaləs vˌɪɾt nˈɔø mœblˈiːɾt/","en":"Everything will be newly furnished.","zh":"一切都在重新装修。","note":""},{"id":"rebecca-das-musical-56-024","lineIndex":13,"speaker":"","original":"Ab jetzt herrscht in Manderlay eine vollkommen and're Mrs. de Winter.","sourceLineIndex":24,"ipa":"/ap jˌɛtst hˈɛɾʃt ɪn mˈandɜlˌɛɪ ˌaɪnə fɔlkˈɔmən ˈandɾə ˌɛmˌɛrˈɛs dˈeː vˈɪntɜ/","en":"From now on there is one in Manderlay completely different Mrs. de Winter.","zh":"从现在起曼德勒只有一个完全不同的德温特夫人。","note":""},{"id":"rebecca-das-musical-56-026","lineIndex":14,"speaker":"","original":"Welch ein Verdruss warum muss sich auf einmal alles ändern?","sourceLineIndex":26,"ipa":"/vˈɛlç aɪn fɛɾdɾˈʊs vɑːrˈʊm mˈʊs zɪç aʊf ˈaɪnmˌɑːl ˈaləs ˈɛndɜn/","en":"What annoyance Why does everything have to change all of a sudden?","zh":"真烦人为什么一切都要突然改变？","note":""},{"id":"rebecca-das-musical-56-028","lineIndex":15,"speaker":"","original":"Es war doch nett","sourceLineIndex":28,"ipa":"/ɛs vɑːɾ dɔx nˈɛt/","en":"It was nice","zh":"舒适","note":""},{"id":"rebecca-das-musical-56-029","lineIndex":16,"speaker":"","original":"so adrett außerdem war es gewöhnt","sourceLineIndex":29,"ipa":"/zoː adɾˈɛt ˈaʊsɜdˌeːm vɑːɾ ɛs ɡəvˈøːnt/","en":"so neat, besides, it was used to","zh":"而且我们已经习惯了","note":""},{"id":"rebecca-das-musical-56-030","lineIndex":17,"speaker":"","original":"doch es war ja der Stil","sourceLineIndex":30,"ipa":"/dɔx ɛs vɑːɾ jˈɑː dɛɾ ʃtˈiːl/","en":"but it was the style","zh":"可那风格全都属于","note":""},{"id":"rebecca-das-musical-56-031","lineIndex":18,"speaker":"","original":"uns'rer alten Mrs. de Winter.","sourceLineIndex":31,"ipa":"/ˈʊnsrɜ ˈaltən ˌɛmˌɛrˈɛs dˈeː vˈɪntɜ/","en":"our old Mrs. de Winter.","zh":"我们曾经的德温特太太。","note":""},{"id":"rebecca-das-musical-56-032","lineIndex":19,"speaker":"","original":"Schleppt schleift und schiebt","sourceLineIndex":32,"ipa":"/ʃlˈɛpt ʃlˈaɪft ʊnt ʃˈiːpt/","en":"Drags, drags and pushes","zh":"拖、拖、推","note":""},{"id":"rebecca-das-musical-56-033","lineIndex":20,"speaker":"","original":"Tisch um Tisch","sourceLineIndex":33,"ipa":"/tˈɪʃ ʊm tˈɪʃ/","en":"Table after table","zh":"一个又一个桌子","note":""},{"id":"rebecca-das-musical-56-034","lineIndex":21,"speaker":"","original":"Schrank um Schrank nichts bleibt wie immer.","sourceLineIndex":34,"ipa":"/ʃrˈaŋk ʊm ʃrˈaŋk nˈɪçts blˈaɪpt viː ˈɪmɜ/","en":"Closet after closet nothing stays the same.","zh":"一个又一个的衣柜一夜之间天翻地覆！","note":""},{"id":"rebecca-das-musical-56-036","lineIndex":22,"speaker":"","original":"Weg damit und fragt nicht weiter nach dem Grund.","sourceLineIndex":36,"ipa":"/vˈeːk dɑːmˈɪt ʊnt frˈɑːkt nˈɪçt vˈaɪtɜ nɑːx deːm ɡɾˈʊnt/","en":"Away with it and don't ask the reason any further.","zh":"只管丢掉别再追问原因。","note":""},{"id":"rebecca-das-musical-56-038","lineIndex":23,"speaker":"","original":"Was geschieht ist der Wunsch uns'rer neuen Mrs. de Winter.","sourceLineIndex":38,"ipa":"/vˈas ɡəʃˈiːt ɪst dɛɾ vˈʊnʃ ˈʊnsrɜ nˈɔøən ˌɛmˌɛrˈɛs dˈeː vˈɪntɜ/","en":"What happens is the wish our new Mrs. de Winter.","zh":"我们只需按命行事服从的新德温特夫人。","note":""},{"id":"rebecca-das-musical-56-040","lineIndex":24,"speaker":"","original":"Mrs. de Winter!","sourceLineIndex":40,"ipa":"/ˌɛmˌɛrˈɛs dˈeː vˈɪntɜ/","en":"Mrs de Winter!","zh":"德温特夫人！","note":""}],"sourceOrder":56,"displayOrder":34},{"order":57,"id":"57-mrs-de-winter-bin-ich-ich-mrs-danvers","title":"Mrs. de Winter bin ich!","titleZh":"我就是德温特夫人！","lines":[{"id":"rebecca-das-musical-57-001","lineIndex":1,"speaker":"","original":"\"Ich\": Ich mag keine Orchideen","sourceLineIndex":1,"ipa":"/ˈɪç ɪç mˈɑːk kˈaɪnə ˌɔɾçiːdˈeːən/","en":"\"I\": I don't like orchids","zh":"我不喜欢兰花","note":""},{"id":"rebecca-das-musical-57-002","lineIndex":2,"speaker":"","original":"Ich moechte stattdessen Azaleen","sourceLineIndex":2,"ipa":"/ɪç mˈœçtə ʃtˈatdɛsən ˌɑtsalˈeːən/","en":"I would like azaleas instead","zh":"我想要摆杜鹃花","note":""},{"id":"rebecca-das-musical-57-003","lineIndex":3,"speaker":"","original":"Ich will die Toepfe hier","sourceLineIndex":3,"ipa":"/ɪç vɪl diː tˈœpfə hˈiːɾ/","en":"I want the pots here","zh":"我不想再看到这里的花盆","note":""},{"id":"rebecca-das-musical-57-004","lineIndex":4,"speaker":"","original":"morgen nicht mehr sehn","sourceLineIndex":4,"ipa":"/mˈɔɾɡən nˈɪçt mˌeːɾ zˈeːn/","en":"won't see you tomorrow","zh":"明天就把它们撤掉","note":""},{"id":"rebecca-das-musical-57-005","lineIndex":5,"speaker":"","original":"Das sind die Orchideen von Mrs. de Winter","sourceLineIndex":5,"ipa":"/das zɪnt diː ˌɔɾçiːdˈeːən fɔn ˌɛmˌɛrˈɛs dˈeː vˈɪntɜ/","en":"These are Mrs. de Winter's orchids","zh":"这些是德温特夫人的兰花！","note":""},{"id":"rebecca-das-musical-57-006","lineIndex":6,"speaker":"","original":"\"Ich\": Es riecht muffig hier","sourceLineIndex":6,"ipa":"/ˈɪç ɛs rˈiːçt mˈʊfɪç hˈiːɾ/","en":"\"I\": It smells musty here","zh":"这里闻起来有股霉味","note":""},{"id":"rebecca-das-musical-57-007","lineIndex":7,"speaker":"","original":"Drum machen sie hier ab und zu die Fenster auf!","sourceLineIndex":7,"ipa":"/dɾˈʊm mˈaxən ziː hˈiːɾ ap ʊnt tsuː diː fˈɛnstɜ ˈaʊf/","en":"That's why they're doing it here and open the windows!","zh":"嗯，这就是为什么这里有股霉味的原因！我把窗户打开了","note":""},{"id":"rebecca-das-musical-57-009","lineIndex":8,"speaker":"","original":"Mrs. de Winter will das nicht","sourceLineIndex":9,"ipa":"/ˌɛmˌɛrˈɛs dˈeː vˈɪntɜ vɪl das nˈɪçt/","en":"Mrs. de Winter doesn't want that","zh":"德温特夫人不想这样！","note":""},{"id":"rebecca-das-musical-57-010","lineIndex":9,"speaker":"","original":"\"Ich\": Sie will, Sie irren sich","sourceLineIndex":10,"ipa":"/ˈɪç zˈiː vɪl ziː ˈɪrən zɪç/","en":"\"I\": She wants you to be wrong","zh":"我想是你搞错了","note":""},{"id":"rebecca-das-musical-57-011","lineIndex":10,"speaker":"","original":"Mrs. de Winter bin ich","sourceLineIndex":11,"ipa":"/ˌɛmˌɛrˈɛs dˈeː vˈɪntɜ bɪn ɪç/","en":"I am Mrs. de Winter","zh":"我才是德温特夫人！","note":""},{"id":"rebecca-das-musical-57-012","lineIndex":11,"speaker":"","original":"Ich schreib nicht auf Briefpapier","sourceLineIndex":12,"ipa":"/ɪç ʃrˈaɪp nˈɪçt aʊf bɾˌiːfpapˈiːɾ/","en":"I don't write on stationery","zh":"我不需要这些文具","note":""},{"id":"rebecca-das-musical-57-013","lineIndex":12,"speaker":"","original":"das einer fremden toten Frau gehoert","sourceLineIndex":13,"ipa":"/das ˌaɪnɜ frˈɛmdən tˈoːtən frˈaʊ ɡəhˈœɾt/","en":"that belongs to a strange dead woman","zh":"尤其他们属于一个死去的奇怪女人","note":""},{"id":"rebecca-das-musical-57-014","lineIndex":13,"speaker":"","original":"Auf den Müll damit","sourceLineIndex":14,"ipa":"/aʊf deːn mˈʏl dɑːmˈɪt/","en":"Throw it in the trash","zh":"他们应该到垃圾桶里了","note":""},{"id":"rebecca-das-musical-57-015","lineIndex":14,"speaker":"","original":"es ist nichts mehr wert","sourceLineIndex":15,"ipa":"/ɛsɪst nˈɪçts mˈeːɾ vˈɛɾt/","en":"it is no longer worth anything","zh":"他们应该到垃圾桶里了","note":""},{"id":"rebecca-das-musical-57-016","lineIndex":15,"speaker":"","original":"Sowie das Buch mit ihren Nummern und Adressen","sourceLineIndex":16,"ipa":"/zoːvˈiː das bˈuːx mɪt ˌiːrən nˈʊmɜn ʊnt adɾˈɛsən/","en":"As well as the book with their numbers and addresses","zh":"还有这些带有号码和地址的书！","note":""},{"id":"rebecca-das-musical-57-017","lineIndex":16,"speaker":"","original":"Es liegt immer hier","sourceLineIndex":17,"ipa":"/ɛs lˈiːkt ˈɪmɜ hˈiːɾ/","en":"It's always here","zh":"它们一直都在这里","note":""},{"id":"rebecca-das-musical-57-018","lineIndex":17,"speaker":"","original":"Stets griffbereit","sourceLineIndex":18,"ipa":"/ʃtˈeːts ɡɾˈɪfbeːrˌaɪt/","en":"Always at hand","zh":"德温特夫人需要随时随地，使用这些信封和纸张","note":""},{"id":"rebecca-das-musical-57-019","lineIndex":18,"speaker":"","original":"So wie die Couverts und das Papier","sourceLineIndex":19,"ipa":"/zoː viː diː kˈuːvɜts ʊnt das papˈiːɾ/","en":"Like the envelopes and the paper","zh":"德温特夫人需要随时随地，使用这些信封和纸张","note":""},{"id":"rebecca-das-musical-57-020","lineIndex":19,"speaker":"","original":"Mrs. de Winter will das so","sourceLineIndex":20,"ipa":"/ˌɛmˌɛrˈɛs dˈeː vˈɪntɜ vɪl das zˈoː/","en":"Mrs. de Winter wants it that way","zh":"德温特夫人需要随时随地，使用这些信封和纸张","note":""},{"id":"rebecca-das-musical-57-021","lineIndex":20,"speaker":"","original":"\"Ich\": Oh nein, Sie irren sich","sourceLineIndex":21,"ipa":"/ˈɪç ˈoː nˈaɪn ziː ˈɪrən zɪç/","en":"\"I\": Oh no, you're wrong","zh":"哦不，你错了","note":""},{"id":"rebecca-das-musical-57-022","lineIndex":21,"speaker":"","original":"Mrs. de Winter bin ich","sourceLineIndex":22,"ipa":"/ˌɛmˌɛrˈɛs dˈeː vˈɪntɜ bɪn ɪç/","en":"I am Mrs. de Winter","zh":"我才是德温特夫人！","note":""},{"id":"rebecca-das-musical-57-023","lineIndex":22,"speaker":"","original":"Diese Porzellanfigur","sourceLineIndex":23,"ipa":"/dˌiːzə pˌɔɾtsəlˌanfɪɡˈuːɾ/","en":"This porcelain figurine","zh":"这瓷俑（小天使爱神像）","note":""},{"id":"rebecca-das-musical-57-024","lineIndex":23,"speaker":"","original":"fand ich schon immer kitschig (Mrs. de Winter's Lieblingsfigur)","sourceLineIndex":24,"ipa":"/fˈant ɪç ʃˌoːn ˈɪmɜ kˈɪtʃɪç ˌɛmˌɛrˈɛs dˈeː vˈɪnteːɾs lˌiːblɪŋsfɪɡˈuːɾ/","en":"I always found it cheesy (Mrs. de Winter's favorite character)","zh":"我一直都觉得它俗气德温特夫人最喜欢它了","note":""},{"id":"rebecca-das-musical-57-025","lineIndex":24,"speaker":"","original":"Sie soll mir nicht laenger","sourceLineIndex":25,"ipa":"/ziː zˌɔl miːɾ nˈɪçt lˈɛŋɜ/","en":"She shouldn't be with me any longer","zh":"它不应该一直放在这里","note":""},{"id":"rebecca-das-musical-57-026","lineIndex":25,"speaker":"","original":"den Geschmack verderben (Mrs. de Winter erwarb sie auf einer Auktion)","sourceLineIndex":26,"ipa":"/deːn ɡəʃmˈak fɛɾdˈɛɾbən ˌɛmˌɛrˈɛs dˈeː vˈɪntɜ ɛɾvˈaɾp ziː aʊf ˌaɪnɜ aʊktsjˈoːn/","en":"spoil the taste (Mrs. de Winter bought it at an auction)","zh":"影响这里的味道！德温特夫人在拍卖会上买下了它","note":""},{"id":"rebecca-das-musical-57-027","lineIndex":26,"speaker":"","original":"Ein geklebter Amor bringt kein Glück (Mrs. de Winter sagte)","sourceLineIndex":27,"ipa":"/aɪn ɡəklˈeːptɜ ˈɑmoːɾ bɾˈɪŋt kˈaɪn ɡlˈʏk ˌɛmˌɛrˈɛs dˈeː vˈɪntɜ zˈɑːɡtə/","en":"A glued Cupid brings no luck (Mrs. de Winter said)","zh":"用胶水粘起来的丘比特不会带来好运。","note":""},{"id":"rebecca-das-musical-57-028","lineIndex":27,"speaker":"","original":"Also machen wir ihn wieder zu Scherben (Nein, Nein! )","sourceLineIndex":28,"ipa":"/ˈalzoː mˈaxən viːɾ iːn vˈiːdɜ tsuː ʃˈɛɾbən nˈaɪn nˈaɪn/","en":"So we turn him into shards again (No, no!)","zh":"所以我们再把它变回原样（摔碎）不，不！","note":""},{"id":"rebecca-das-musical-57-029","lineIndex":28,"speaker":"","original":"Ich will hier zuhause sein (Sie ergibt sich nicht)","sourceLineIndex":29,"ipa":"/ɪç vɪl hˈiːɾ tsuːhˈaʊzə zaɪn ziː ɛɾɡˈiːpt zɪç nˈɪçt/","en":"I want to be at home here (she won't surrender)","zh":"我待在我自己的家中你不会成功的","note":""},{"id":"rebecca-das-musical-57-030","lineIndex":29,"speaker":"","original":"Nicht nur geduldet wie ein Gast (Man besiegt sie nicht)","sourceLineIndex":30,"ipa":"/nˈɪçt nˈuːɾ ɡədˈʊldət viː aɪn ɡˈast man bəzˈiːkt ziː nˈɪçt/","en":"Not just tolerated like a guest (you can't beat her)","zh":"不会像客人一样容忍她！你不会打败她的","note":""},{"id":"rebecca-das-musical-57-031","lineIndex":30,"speaker":"","original":"Will leben wie's mir gefaellt","sourceLineIndex":31,"ipa":"/vɪl lˈeːbən vˈiːs miːɾ ɡəfˈɛlt/","en":"I want to live as I please","zh":"我会过自己想过的生活","note":""},{"id":"rebecca-das-musical-57-032","lineIndex":31,"speaker":"","original":"Egal ob's Ihnen passt (Sie ist starkder Macht des Todes unterliegt sie nicht)","sourceLineIndex":32,"ipa":"/eːɡˈɑːl ˈoːbs ˌiːnən pˈast ziː ɪst ʃtˈaɾkdɜ mˈaxt dɛs tˈoːdəs ˌʊntɜlˈiːkt ziː nˈɪçt/","en":"No matter whether it suits you (she is strong, she is not subject to the power of death)","zh":"而它适合你她不会受到死亡的威胁","note":""},{"id":"rebecca-das-musical-57-033","lineIndex":32,"speaker":"","original":"Ich habe lang genug mich selbst verleugnet (Nein, man sieht sie nicht)","sourceLineIndex":33,"ipa":"/ɪç hɑːbə lˈaŋ ɡənˈuːk mɪç zˈɛlpst fɛɾlˈɔøɡnət nˈaɪn man zˈiːt ziː nˈɪçt/","en":"I've denied myself long enough (No, you can't see her)","zh":"我已经受够长时间地否认自己了不，你看不到她","note":""},{"id":"rebecca-das-musical-57-034","lineIndex":33,"speaker":"","original":"Das ist jetzt vorbei (Doch ich spür sie ist hier und lebt noch)","sourceLineIndex":34,"ipa":"/das ɪst jˌɛtst foːɾbˈaɪ dɔx ɪç ʃpˈyːɾ ziː ɪst hˈiːɾ ʊnt lˈeːpt nɔx/","en":"That's over now (But I feel she's here and still alive)","zh":"这里她已经是过去了但我觉得她一直都还在这里生活","note":""},{"id":"rebecca-das-musical-57-035","lineIndex":34,"speaker":"","original":"Ich war umgeben von Schatten (Sie hoert und sie sieht uns)","sourceLineIndex":35,"ipa":"/ɪç vɑːɾ ʊmɡˈeːbən fɔn ʃˈatən ziː hˈœɾt ʊnt ziː zˈiːt ˈʊns/","en":"I was surrounded by shadows (She hears and she sees us)","zh":"我一直被她的阴影所包围着她能听到，她能看到我们","note":""},{"id":"rebecca-das-musical-57-036","lineIndex":35,"speaker":"","original":"Doch jetzt sind sie fort (Sie ergibt sich nicht)","sourceLineIndex":36,"ipa":"/dɔx jˌɛtst zɪnt ziː fˈɔɾt ziː ɛɾɡˈiːpt zɪç nˈɪçt/","en":"But now they're gone (She won't surrender)","zh":"但它们现在已经全部消失了它不会出现","note":""},{"id":"rebecca-das-musical-57-037","lineIndex":36,"speaker":"","original":"In das dunkle Haus kommt Licht (Sie ist staerker)","sourceLineIndex":37,"ipa":"/ɪn das dˈʊŋklə hˈaʊs kˈɔmt lˈɪçt ziː ɪst ʃtˈɛɾkɜ/","en":"Light comes into the dark house (she is stronger)","zh":"给黑暗的房子带来光吧她更强大","note":""},{"id":"rebecca-das-musical-57-038","lineIndex":37,"speaker":"","original":"Alles, alles aendert sich (Sie ergibt sich nicht)","sourceLineIndex":38,"ipa":"/ˈaləs ˈaləs ˈɛndɜt zɪç ziː ɛɾɡˈiːpt zɪç nˈɪçt/","en":"Everything, everything changes (it doesn't surrender)","zh":"一切都已经变了不会出现","note":""},{"id":"rebecca-das-musical-57-039","lineIndex":38,"speaker":"","original":"Mrs. de Winter bin ich (Man besiegt sie nicht)","sourceLineIndex":39,"ipa":"/ˌɛmˌɛrˈɛs dˈeː vˈɪntɜ bɪn ɪç man bəzˈiːkt ziː nˈɪçt/","en":"I am Mrs. de Winter (you can't beat her)","zh":"我才是德温特夫人！你不会打败她的","note":""},{"id":"rebecca-das-musical-57-040","lineIndex":39,"speaker":"","original":"Was auch immer hier geschah (Du besiegst sie nicht)","sourceLineIndex":40,"ipa":"/vˈas ˌaʊx ˈɪmɜ hˈiːɾ ɡəʃˈɑː duː bəzˈiːkst ziː nˈɪçt/","en":"Whatever happened here (You don't beat her)","zh":"无论这里曾经发生过什么事情你不会打败她的","note":""},{"id":"rebecca-das-musical-57-041","lineIndex":40,"speaker":"","original":"Nichts mehr bleibe wie es war (Sie bleibt da!)","sourceLineIndex":41,"ipa":"/nˈɪçts mˈeːɾ blˈaɪbə viː ɛs vɑːɾ ziː blˈaɪpt dˈɑː/","en":"Nothing will stay as it was (she stays there!)","zh":"没有任何东西是可以保持不变的她就停留在那里！","note":""}],"sourceOrder":57,"displayOrder":35},{"order":58,"id":"58-eine-hand-wascht-die-andre-hand-favell","title":"Eine Hand wäscht die andre Hand","titleZh":"一只手洗另一只手","lines":[{"id":"rebecca-das-musical-58-001","lineIndex":1,"speaker":"","original":"(Favell)","sourceLineIndex":1,"ipa":"/favˈɛl/","en":"(Favell)","zh":"（法维尔）","note":""},{"id":"rebecca-das-musical-58-002","lineIndex":2,"speaker":"","original":"Was ich will?","sourceLineIndex":2,"ipa":"/vˈas ɪç vɪl/","en":"What do I want?","zh":"我想要什么？（笑）","note":""},{"id":"rebecca-das-musical-58-003","lineIndex":3,"speaker":"","original":"Was ich will ist ein Haus","sourceLineIndex":3,"ipa":"/vˈas ɪç vɪl ɪst aɪn hˈaʊs/","en":"What I want is a house","zh":"我想要一座大房子","note":""},{"id":"rebecca-das-musical-58-004","lineIndex":4,"speaker":"","original":"Kein Palast, nur eine Villa","sourceLineIndex":4,"ipa":"/kˈaɪn pˈɑlast nˈuːɾ ˌaɪnə vˈɪlɑː/","en":"Not a palace, just a villa","zh":"不要宫殿，一座别墅就好","note":""},{"id":"rebecca-das-musical-58-005","lineIndex":5,"speaker":"","original":"Vor dem Portal ein Cabrio","sourceLineIndex":5,"ipa":"/fˌɔɾ deːm pɔɾtˈɑːl aɪn kˈabɾɪˌoː/","en":"A convertible in front of the portal","zh":"门口停一辆敞篷车","note":""},{"id":"rebecca-das-musical-58-006","lineIndex":6,"speaker":"","original":"Im Keller reichlich Veuve Cliquot","sourceLineIndex":6,"ipa":"/ɪm kˈɛlɜ rˈaɪçlɪç vˈɔøvə klˈiːkvoːt/","en":"Plenty of Veuve Cliquot in the cellar","zh":"酒窖里装上高档香槟","note":""},{"id":"rebecca-das-musical-58-007","lineIndex":7,"speaker":"","original":"Bisher versuchte ich es leider","sourceLineIndex":7,"ipa":"/bɪshˈeːɾ fɛɾzˈuːxtə ɪç ɛs lˈaɪdɜ/","en":"Unfortunately, I've tried so far","zh":"很可惜，跟那些傻子一样","note":""},{"id":"rebecca-das-musical-58-008","lineIndex":8,"speaker":"","original":"Wie andre Trottel","sourceLineIndex":8,"ipa":"/viː ˈandɾə tɾˈɔtəl/","en":"Like other idiots","zh":"我曾经以为","note":""},{"id":"rebecca-das-musical-58-009","lineIndex":9,"speaker":"","original":"Mit Talent und Fleiß","sourceLineIndex":9,"ipa":"/mɪt talˈɛnt ʊnt flˈaɪs/","en":"With talent and hard work","zh":"才能和勤奋带来富贵","note":""},{"id":"rebecca-das-musical-58-010","lineIndex":10,"speaker":"","original":"Inzwischen habe ich gelernt","sourceLineIndex":10,"ipa":"/ɪntsvˈɪʃən hɑːbə ɪç ɡəlˈɛɾnt/","en":"I have now learned","zh":"现在我已经懂得了","note":""},{"id":"rebecca-das-musical-58-011","lineIndex":11,"speaker":"","original":"In dieser Welt kommt man nur weiter","sourceLineIndex":11,"ipa":"/ɪn dˌiːzɜ vˈɛlt kˈɔmt man nˈuːɾ vˈaɪtɜ/","en":"In this world you can only move forward","zh":"在这世上想要上进","note":""},{"id":"rebecca-das-musical-58-012","lineIndex":12,"speaker":"","original":"Wenn man die gold'ne Regel weiß","sourceLineIndex":12,"ipa":"/vˌɛn man diː ɡˈɔldnə rˈeːɡəl vˈaɪs/","en":"If you know the golden rule","zh":"就得明白这“黄金法则”……","note":""},{"id":"rebecca-das-musical-58-013","lineIndex":13,"speaker":"","original":"Eine Hand wäscht die and're Hand","sourceLineIndex":13,"ipa":"/ˌaɪnə hˈant vˈɛʃt diː ˈandɾə hˈant/","en":"One hand washes the other hand","zh":"做人就要互帮互助","note":""},{"id":"rebecca-das-musical-58-014","lineIndex":14,"speaker":"","original":"Ich halt das Maul und kassiere","sourceLineIndex":14,"ipa":"/ɪç hˈalt das mˈaʊl ʊnt kasˈiːrə/","en":"I keep my mouth shut and collect","zh":"我会闭紧嘴巴，收好钞票","note":""},{"id":"rebecca-das-musical-58-015","lineIndex":15,"speaker":"","original":"Geheimes Wissen ist wie ein Band","sourceLineIndex":15,"ipa":"/ɡəhˈaɪməs vˈɪsən ɪst viː aɪn bˈant/","en":"Secret knowledge is like a ribbon","zh":"不能说的事情就是纽带","note":""},{"id":"rebecca-das-musical-58-016","lineIndex":16,"speaker":"","original":"Das jeden Feind mit mir vereint","sourceLineIndex":16,"ipa":"/das jˈeːdən fˈaɪnt mɪt miːɾ fɛɾˈaɪnt/","en":"That unites every enemy with me","zh":"把我的敌人变成伙伴","note":""},{"id":"rebecca-das-musical-58-017","lineIndex":17,"speaker":"","original":"Ich will in London meinen Schneider","sourceLineIndex":17,"ipa":"/ɪç vɪl ɪn lˈɔndoːn mˌaɪnən ʃnˈaɪdɜ/","en":"I want my tailor in London","zh":"在伦敦我要有私人裁缝","note":""},{"id":"rebecca-das-musical-58-018","lineIndex":18,"speaker":"","original":"Solang wir profitieren","sourceLineIndex":18,"ipa":"/zˈoːlaŋ viːɾ pɾoːfiːtˈiːrən/","en":"As long as we benefit","zh":"—只要让大家都得利！","note":""},{"id":"rebecca-das-musical-58-019","lineIndex":19,"speaker":"","original":"Ich will in Strand von Cannes mein Stammhotel","sourceLineIndex":19,"ipa":"/ɪç vɪl ɪn ʃtɾˈant fɔn kˈanəs maɪn ʃtˈamhoːtəl/","en":"I want my regular hotel in Cannes Beach","zh":"在戛纳海滩我要有固定饭店","note":""},{"id":"rebecca-das-musical-58-020","lineIndex":20,"speaker":"","original":"Ich will nicht knausern mit dem Geld","sourceLineIndex":20,"ipa":"/ɪç vɪl nˈɪçt knˈaʊzɜn mɪt deːm ɡˈɛlt/","en":"I don't want to skimp on the money","zh":"在钱上我不想再抠门","note":""},{"id":"rebecca-das-musical-58-021","lineIndex":21,"speaker":"","original":"Und wenn es einmal knapp wird","sourceLineIndex":21,"ipa":"/ʊnt vˌɛn ɛs ˈaɪnmˌɑːl knˈap vˌɪɾt/","en":"And when things get tight","zh":"只要手头有点小紧张","note":""},{"id":"rebecca-das-musical-58-022","lineIndex":22,"speaker":"","original":"Dann will ich Nachschub","sourceLineIndex":22,"ipa":"/dan vɪl ɪç nˈaxʃuːp/","en":"Then I want supplies","zh":"我就要有现金补上来","note":""},{"id":"rebecca-das-musical-58-023","lineIndex":23,"speaker":"","original":"Und zwar schnell","sourceLineIndex":23,"ipa":"/ʊnt tsvɑːɾ ʃnˈɛl/","en":"And quickly","zh":"而且要快","note":""},{"id":"rebecca-das-musical-58-024","lineIndex":24,"speaker":"","original":"Eine Hand wäscht die and're Hand","sourceLineIndex":24,"ipa":"/ˌaɪnə hˈant vˈɛʃt diː ˈandɾə hˈant/","en":"One hand washes the other hand","zh":"做人就要互帮互助","note":""},{"id":"rebecca-das-musical-58-025","lineIndex":25,"speaker":"","original":"Ich halt das Maul und kassiere","sourceLineIndex":25,"ipa":"/ɪç hˈalt das mˈaʊl ʊnt kasˈiːrə/","en":"I keep my mouth shut and collect","zh":"我会闭紧嘴巴，收好钞票","note":""},{"id":"rebecca-das-musical-58-026","lineIndex":26,"speaker":"","original":"Geheimes Wissen ist wie ein Band","sourceLineIndex":26,"ipa":"/ɡəhˈaɪməs vˈɪsən ɪst viː aɪn bˈant/","en":"Secret knowledge is like a ribbon","zh":"不能说的事情就是纽带","note":""},{"id":"rebecca-das-musical-58-027","lineIndex":27,"speaker":"","original":"Das jeden Feind mit mir vereint","sourceLineIndex":27,"ipa":"/das jˈeːdən fˈaɪnt mɪt miːɾ fɛɾˈaɪnt/","en":"That unites every enemy with me","zh":"把我的敌人全变成伙伴","note":""},{"id":"rebecca-das-musical-58-028","lineIndex":28,"speaker":"","original":"Solang wir profitieren","sourceLineIndex":28,"ipa":"/zˈoːlaŋ viːɾ pɾoːfiːtˈiːrən/","en":"As long as we benefit","zh":"—只要让大家都得利！","note":""},{"id":"rebecca-das-musical-58-029","lineIndex":29,"speaker":"","original":"Natürlich geht ihr zu Max de Winter","sourceLineIndex":29,"ipa":"/nɑːtˈyːɾlɪç ɡˈeːt iːɾ tsuː mˈɑːks dˈeː vˈɪntɜ/","en":"Of course you go to Max de Winter","zh":"当然你们会倒向马克斯·德温特","note":""},{"id":"rebecca-das-musical-58-030","lineIndex":30,"speaker":"","original":"Ihr wohnt ja gut in seinem Haus","sourceLineIndex":30,"ipa":"/iːɾ vˈoːnt jˈɑː ɡˈuːt ɪn zˌaɪnəm hˈaʊs/","en":"You live well in his house","zh":"你们在他家住得多舒服","note":""},{"id":"rebecca-das-musical-58-031","lineIndex":31,"speaker":"","original":"Ihr trinkt den feinen Wein von ihm","sourceLineIndex":31,"ipa":"/iːɾ tɾˈɪŋkt deːn fˈaɪnən vˈaɪn fɔn ˈiːm/","en":"You drink his fine wine","zh":"你们喝着他的好酒","note":""},{"id":"rebecca-das-musical-58-032","lineIndex":32,"speaker":"","original":"Und steckt ihr in der Tinte","sourceLineIndex":32,"ipa":"/ʊnt ʃtˈɛkt iːɾ ɪn dɛɾ tˈɪntə/","en":"And she's in trouble","zh":"自己还沾了一身黑","note":""},{"id":"rebecca-das-musical-58-033","lineIndex":33,"speaker":"","original":"Holt er euch selbstverständlich raus","sourceLineIndex":33,"ipa":"/hˈɔlt ɛɾ ɔøç zˈɛlpstfɛɾʃtˌɛntlɪç rˈaʊs/","en":"Of course he'll get you out","zh":"知道吗，他早晚把你们赶出门！","note":""},{"id":"rebecca-das-musical-58-034","lineIndex":34,"speaker":"","original":"Eine Hand wäscht die and're Hand","sourceLineIndex":34,"ipa":"/ˌaɪnə hˈant vˈɛʃt diː ˈandɾə hˈant/","en":"One hand washes the other hand","zh":"做人就要互帮互助","note":""},{"id":"rebecca-das-musical-58-035","lineIndex":35,"speaker":"","original":"Jeder lässt sich gern schmieren","sourceLineIndex":35,"ipa":"/jˈeːdɜ lˈɛst zɪç ɡˈɛɾn ʃmˈiːrən/","en":"Everyone likes to be greased","zh":"没人不喜欢被收买","note":""},{"id":"rebecca-das-musical-58-036","lineIndex":36,"speaker":"","original":"Wer ist schon gern ein Denunziant","sourceLineIndex":36,"ipa":"/vˈeːɾ ɪst ʃˌoːn ɡˈɛɾn aɪn dˌeːnʊntsiːˈant/","en":"Who wants to be an informer?","zh":"现在谁还会愿意去告密：","note":""},{"id":"rebecca-das-musical-58-037","lineIndex":37,"speaker":"","original":"Wir sind loyal auf jeden Fall","sourceLineIndex":37,"ipa":"/viːɾ zɪnt loːjˈɑːl aʊf jˈeːdən fˈal/","en":"We are definitely loyal","zh":"我们彼此忠诚，不离不弃","note":""},{"id":"rebecca-das-musical-58-038","lineIndex":38,"speaker":"","original":"Solang wir profitieren (hahahahaha!)","sourceLineIndex":38,"ipa":"/zˈoːlaŋ viːɾ pɾoːfiːtˈiːrən hˈɑːɑːˌɑːɑːˌɑː/","en":"As long as we benefit (hahahahaha!)","zh":"—只要让大家都得利！（大笑）","note":""},{"id":"rebecca-das-musical-58-039","lineIndex":39,"speaker":"","original":"Eine Hand wäscht die and're Hand","sourceLineIndex":39,"ipa":"/ˌaɪnə hˈant vˈɛʃt diː ˈandɾə hˈant/","en":"One hand washes the other hand","zh":"做人就要互帮互助","note":""},{"id":"rebecca-das-musical-58-040","lineIndex":40,"speaker":"","original":"Ich halt das Maul und kassiere","sourceLineIndex":40,"ipa":"/ɪç hˈalt das mˈaʊl ʊnt kasˈiːrə/","en":"I keep my mouth shut and collect","zh":"我会闭紧嘴巴，收好钞票","note":""},{"id":"rebecca-das-musical-58-041","lineIndex":41,"speaker":"","original":"Geheimes Wissen ist wie ein Band","sourceLineIndex":41,"ipa":"/ɡəhˈaɪməs vˈɪsən ɪst viː aɪn bˈant/","en":"Secret knowledge is like a ribbon","zh":"不能说的事情就是纽带","note":""},{"id":"rebecca-das-musical-58-042","lineIndex":42,"speaker":"","original":"Das jeden Feind mit mir vereint","sourceLineIndex":42,"ipa":"/das jˈeːdən fˈaɪnt mɪt miːɾ fɛɾˈaɪnt/","en":"That unites every enemy with me","zh":"把我的敌人全变成伙伴","note":""},{"id":"rebecca-das-musical-58-043","lineIndex":43,"speaker":"","original":"Solang ich dabei profitiere!","sourceLineIndex":43,"ipa":"/zˈoːlaŋ ɪç dɑːbˈaɪ pɾoːfiːtˈiːrə/","en":"As long as I benefit from it!","zh":"—只要我能分到一份利益！","note":""},{"id":"rebecca-das-musical-58-044","lineIndex":44,"speaker":"","original":"(Favell)","sourceLineIndex":44,"ipa":"/favˈɛl/","en":"(Favell)","zh":"（法维尔）","note":""},{"id":"rebecca-das-musical-58-045","lineIndex":45,"speaker":"","original":"Ach, da ist ja der gute Max! Ich trinke auf Dein Wohl.","sourceLineIndex":45,"ipa":"/ˈax dɑː ɪst jˈɑː dɛɾ ɡˈuːtə mˈɑːks ɪç tɾˈɪŋkə aʊf daɪn vˈoːl/","en":"Oh, there's good Max! I drink to your health.","zh":"哎呀，这不是好人马克西姆吗！我敬你一杯。","note":""},{"id":"rebecca-das-musical-58-046","lineIndex":46,"speaker":"","original":"Du kannst es brauchen, und mir hilft es über den Schock.","sourceLineIndex":46,"ipa":"/duː kˌanst ɛs bɾˈaʊxən ʊnt miːɾ hˈɪlft ɛs ˌyːbɜ deːn ʃˈɔk/","en":"You can use it, and it helps me through the shock.","zh":"你需要喝点，我也要来几口压惊—","note":""},{"id":"rebecca-das-musical-58-047","lineIndex":47,"speaker":"","original":"(Maxim)","sourceLineIndex":47,"ipa":"/mˈaksiːm/","en":"(Maxim)","zh":"（马克西姆）","note":""},{"id":"rebecca-das-musical-58-048","lineIndex":48,"speaker":"","original":"Raus!","sourceLineIndex":48,"ipa":"/rˈaʊs/","en":"Get out!","zh":"滚出去！","note":""},{"id":"rebecca-das-musical-58-049","lineIndex":49,"speaker":"","original":"(Favell)","sourceLineIndex":49,"ipa":"/favˈɛl/","en":"(Favell)","zh":"（法维尔）","note":""},{"id":"rebecca-das-musical-58-050","lineIndex":50,"speaker":"","original":"Etwas mehr Mitgefühl, Max! Rebecca war doch meine Lieblingscousine.","sourceLineIndex":50,"ipa":"/ˈɛtvɑːs mˈeːɾ mˈɪtɡəfˌyːl mˈɑːks reːbˈɛkɑː vɑːɾ dɔx mˌaɪnə lˌiːblɪŋskuːzˈiːnə/","en":"A little more compassion, Max! Rebecca was my favorite cousin.","zh":"多点同情心吧，马克西姆！丽贝卡可是我最喜欢的表妹。","note":""},{"id":"rebecca-das-musical-58-051","lineIndex":51,"speaker":"","original":"Und was ich heute erfahren habe, ist nicht leicht zu verdauen. Ihr Boot vorsätzlich versenkt! Löcher im Bootsrumpf.","sourceLineIndex":51,"ipa":"/ʊnt vˈas ɪç hˈɔøtə ɛɾfˈɑːrən hɑːbə ɪst nˈɪçt lˈaɪçt tsuː fɛɾdˈaʊən iːɾ bˈoːt fˈoːɾzˌɛtslɪç fɛɾzˈɛŋkt lˈœçɜ ɪm bˈoːtsrʊmpf/","en":"And what I learned today is not easy to digest. Your boat was deliberately sunk! Holes in the boat hull.","zh":"今天听到的消息真让我受不了。她的船是被人故意弄沉的，船上面有洞……","note":""},{"id":"rebecca-das-musical-58-052","lineIndex":52,"speaker":"","original":"Tt-tt-tt! Wer macht denn so was?!","sourceLineIndex":52,"ipa":"/tˌeːtˈeːtˌeːtˈeːtˌeːtˈeː vˈeːɾ mˈaxt dɛn zoː vˈas/","en":"Tt-tt-tt! Who does something like that?!","zh":"啧啧啧，谁会干这种事呢？","note":""},{"id":"rebecca-das-musical-58-053","lineIndex":53,"speaker":"","original":"(Maxim)","sourceLineIndex":53,"ipa":"/mˈaksiːm/","en":"(Maxim)","zh":"（马克西姆）","note":""},{"id":"rebecca-das-musical-58-054","lineIndex":54,"speaker":"","original":"Kommen Sie zur Sache.","sourceLineIndex":54,"ipa":"/kˈɔmən ziː tsuːɾ zˈaxə/","en":"Get to the point.","zh":"说正事。","note":""},{"id":"rebecca-das-musical-58-055","lineIndex":55,"speaker":"","original":"(Favell)","sourceLineIndex":55,"ipa":"/favˈɛl/","en":"(Favell)","zh":"（法维尔）","note":""},{"id":"rebecca-das-musical-58-056","lineIndex":56,"speaker":"","original":"Nun, ich besitze den klaren Beweis dafür, dass es kein Selbstmord war.","sourceLineIndex":56,"ipa":"/nˈuːn ɪç bəzˈɪtsə deːn klˈɑːrən bəvˈaɪs dɑːfˈyːɾ das ɛs kˈaɪn zˈɛlpstmɔɾt vɑːɾ/","en":"Well, I have clear evidence that it wasn't suicide.","zh":"这个嘛，我有确凿证据证明那不是自杀。","note":""},{"id":"rebecca-das-musical-58-057","lineIndex":57,"speaker":"","original":"(Maxim)","sourceLineIndex":57,"ipa":"/mˈaksiːm/","en":"(Maxim)","zh":"（马克西姆）","note":""},{"id":"rebecca-das-musical-58-058","lineIndex":58,"speaker":"","original":"Wenn Sie im Besitz eines Beweisstücks sind, müssen Sie es den Behörden aushändigen.","sourceLineIndex":58,"ipa":"/vˌɛn ziː ɪm bəzˈɪts ˌaɪnəs bəvˈaɪsʃtʏks zɪnt mˈʏsən ziː ɛs deːn bəhˈœɾdən ˈaʊshˌɛndɪɡən/","en":"If you have a piece of evidence, you must hand it over to the authorities.","zh":"如果你手里有证据，就必须把它交给当局。","note":""},{"id":"rebecca-das-musical-58-059","lineIndex":59,"speaker":"","original":"(Favell)","sourceLineIndex":59,"ipa":"/favˈɛl/","en":"(Favell)","zh":"（法维尔）","note":""},{"id":"rebecca-das-musical-58-060","lineIndex":60,"speaker":"","original":"Ja, (hahaha), das muss ich.","sourceLineIndex":60,"ipa":"/jˈɑː hˈɑːɑːˌɑː das mˈʊs ɪç/","en":"Yes, (hahaha), I have to.","zh":"是啊，（笑）我当然得交。","note":""},{"id":"rebecca-das-musical-58-061","lineIndex":61,"speaker":"","original":"Aber das heißt für einen gewissen Max de Winter Gefängnis, Schwurgericht, Galgen.","sourceLineIndex":61,"ipa":"/ˌɑːbɜ das hˈaɪst fyːɾ ˌaɪnən ɡəvˈɪsən mˈɑːks dˈeː vˈɪntɜ ɡəfˈɛŋnɪs ʃvˈʊɐɡeːrˌɪçt ɡˈalɡən/","en":"But for a certain Max de Winter that means prison, jury trial and gallows.","zh":"但对某个马克斯·德温特而言，这意味着监狱、巡回法庭和绞刑架。","note":""},{"id":"rebecca-das-musical-58-062","lineIndex":62,"speaker":"","original":"Und seine junge Frau würde ich damit zur Witwe machen und das bring' ich nicht übers Herz.","sourceLineIndex":62,"ipa":"/ʊnt zˌaɪnə jˈʊŋə frˈaʊ vˈʏɾdə ɪç dɑːmˈɪt tsuːɾ vˈɪtvə mˈaxən ʊnt das bɾˈɪŋ ɪç nˈɪçt ˌyːbɜs hˈɛɾts/","en":"And I would make his young wife a widow and I can't bring myself to do that.","zh":"而他的年轻妻子会因此成为寡妇，这我于心不忍。","note":""},{"id":"rebecca-das-musical-58-063-a","lineIndex":63,"speaker":"","original":"Mir schwebt da eine Art Vereinbarung vor.","sourceLineIndex":63,"ipa":"/miːɾ ʃvˈeːpt dɑː ˌaɪnə ˈɑːɾt fɛɾˈaɪnbˌɑrʊŋ fˈɔɾ ˌaɪnə hˈant vˈɛʃt diː ˈandərə hˈant ɪç kˈɔmə ˌiːnən ɛntɡˈeːɡən ʊnt ziː mˈiːɾ ziː fɛɾʃtˈeːən ʃˈoːn/","en":"I have some kind of agreement in mind.","zh":"我想还有“协议”这个办法。","note":""},{"id":"rebecca-das-musical-58-063-b","lineIndex":64,"speaker":"","original":"Eine Hand wäscht die andere Hand.","sourceLineIndex":63,"ipa":"/miːɾ ʃvˈeːpt dɑː ˌaɪnə ˈɑːɾt fɛɾˈaɪnbˌɑrʊŋ fˈɔɾ ˌaɪnə hˈant vˈɛʃt diː ˈandərə hˈant ɪç kˈɔmə ˌiːnən ɛntɡˈeːɡən ʊnt ziː mˈiːɾ ziː fɛɾʃtˈeːən ʃˈoːn/","en":"One hand washes the other hand.","zh":"人要互帮互助嘛","note":""},{"id":"rebecca-das-musical-58-063-c","lineIndex":65,"speaker":"","original":"Ich komme Ihnen entgegen, und Sie mir.","sourceLineIndex":63,"ipa":"/miːɾ ʃvˈeːpt dɑː ˌaɪnə ˈɑːɾt fɛɾˈaɪnbˌɑrʊŋ fˈɔɾ ˌaɪnə hˈant vˈɛʃt diː ˈandərə hˈant ɪç kˈɔmə ˌiːnən ɛntɡˈeːɡən ʊnt ziː mˈiːɾ ziː fɛɾʃtˈeːən ʃˈoːn/","en":"I come to meet you, and you to me.","zh":"我帮您一把，您也要照顾我。","note":""},{"id":"rebecca-das-musical-58-063-d","lineIndex":66,"speaker":"","original":"Sie verstehen schon.","sourceLineIndex":63,"ipa":"/miːɾ ʃvˈeːpt dɑː ˌaɪnə ˈɑːɾt fɛɾˈaɪnbˌɑrʊŋ fˈɔɾ ˌaɪnə hˈant vˈɛʃt diː ˈandərə hˈant ɪç kˈɔmə ˌiːnən ɛntɡˈeːɡən ʊnt ziː mˈiːɾ ziː fɛɾʃtˈeːən ʃˈoːn/","en":"You understand.","zh":"您马上就明白啦。","note":""},{"id":"rebecca-das-musical-58-064","lineIndex":67,"speaker":"","original":"(Maxim)","sourceLineIndex":64,"ipa":"/mˈaksiːm/","en":"(Maxim)","zh":"（马克西姆）","note":""},{"id":"rebecca-das-musical-58-065","lineIndex":68,"speaker":"","original":"Allerdings. Ich verstehe sehr gut. Zum Glück hat mich Oberst Julyan hier her begleitet. Oberst! Bitte kommen Sie.","sourceLineIndex":65,"ipa":"/ˈalɜdˌɪŋs ɪç fɛɾʃtˈeːə zˈeːɾ ɡˈuːt tsʊm ɡlˈʏk hat mɪç ˈoːbɜst jˌuːlyːˈɑːn hˈiːɾ hˈeːɾ bəɡlˈaɪtət ˈoːbɜst bˈɪtə kˈɔmən ziː/","en":"However. I understand very well. Luckily, Colonel Julyan accompanied me here. Colonel! Please come.","zh":"当然，我明白得很。幸好朱利安上校陪我来了。上校！请进来吧。","note":""},{"id":"rebecca-das-musical-58-066","lineIndex":69,"speaker":"","original":"(Oberst Julyan)","sourceLineIndex":66,"ipa":"/ˈoːbɜst jˌuːlyːˈɑːn/","en":"(Colonel Julyan)","zh":"（朱利安上校）","note":""},{"id":"rebecca-das-musical-58-067","lineIndex":70,"speaker":"","original":"Guten Abend. Ich fürchte, da braut sich was zusammen. (zu \"Ich\") Ich hoffe, Sie fühlen sich besser, Mrs. de Winter?","sourceLineIndex":67,"ipa":"/ɡˈuːtən ˈɑːbənt ɪç fˈʏɾçtə dɑː bɾˈaʊt zɪç vˈas tsuːzˈamən tsuː ɪç ɪç hˈɔfə ziː fˈyːlən zɪç bˈɛsɜ ˌɛmˌɛrˈɛs dˈeː vˈɪntɜ/","en":"Good evening. I'm afraid something's brewing. (to \"I\") I hope you're feeling better, Mrs. de Winter?","zh":"晚上好。恐怕要出事了。（对“我”）德温特夫人，希望您好些了？","note":""},{"id":"rebecca-das-musical-58-068","lineIndex":71,"speaker":"","original":"(\"Ich\")","sourceLineIndex":68,"ipa":"/ˈɪç/","en":"(\"I\")","zh":"（“我”）","note":""},{"id":"rebecca-das-musical-58-069","lineIndex":72,"speaker":"","original":"Ja, danke Oberst.","sourceLineIndex":69,"ipa":"/jˈɑː dˈaŋkə ˈoːbɜst/","en":"Yes, thank you, Colonel.","zh":"好多了，谢谢您，上校。","note":""},{"id":"rebecca-das-musical-58-070","lineIndex":73,"speaker":"","original":"(Maxim)","sourceLineIndex":70,"ipa":"/mˈaksiːm/","en":"(Maxim)","zh":"（马克西姆）","note":""},{"id":"rebecca-das-musical-58-071","lineIndex":74,"speaker":"","original":"Jack Favell, der Cousin meiner verstorbenen Frau. Er hat Ihnen etwas mitzuteilen. Favell, Sie sind dran.","sourceLineIndex":71,"ipa":"/jˈak favˈɛl dɛɾ kuːzˈiːn mˌaɪnɜ fɛɾʃtˈɔɾbənən frˈaʊ ɛɾ hat ˌiːnən ˈɛtvɑːs mˈɪttsuːtˌaɪlən favˈɛl ziː zɪnt dɾˈɑːn/","en":"Jack Favell, my late wife's cousin. He has something to tell you. Favell, it's your turn.","zh":"杰克·法维尔，我亡妻的表兄。他有事要告诉您。法维尔，该你了。","note":""},{"id":"rebecca-das-musical-58-072","lineIndex":75,"speaker":"","original":"(Favell)","sourceLineIndex":72,"ipa":"/favˈɛl/","en":"(Favell)","zh":"（法维尔）","note":""},{"id":"rebecca-das-musical-58-073","lineIndex":76,"speaker":"","original":"Diese Zeilen hat Rebecca an mich gerichtet, wenige Stunden bevor sie angeblich auf ihr Boot ging, um sich umzubringen. Leider war ich nicht zu Hause.","sourceLineIndex":73,"ipa":"/dˌiːzə tsˈaɪlən hat reːbˈɛkɑː an mɪç ɡərˈɪçtət vˈeːnɪɡə ʃtˈʊndən bəfˈoːɾ ziː ˈanɡəblˌɪç aʊf iːɾ bˈoːt ɡˈɪŋ ʊm zɪç ˈʊmtsuːbɾˌɪŋən lˈaɪdɜ vɑːɾ ɪç nˈɪçt tsuː hˈaʊzə/","en":"Rebecca wrote these lines to me a few hours before she supposedly went on her boat to kill herself. Unfortunately I wasn't at home.","zh":"丽贝卡写下这些话给我，是在她据称乘船自杀的几小时前。可惜我当时不在家。","note":""},{"id":"rebecca-das-musical-58-074","lineIndex":77,"speaker":"","original":"(Oberst Julyan)","sourceLineIndex":74,"ipa":"/ˈoːbɜst jˌuːlyːˈɑːn/","en":"(Colonel Julyan)","zh":"（朱利安上校）","note":""},{"id":"rebecca-das-musical-58-075","lineIndex":78,"speaker":"","original":"(liest:)\"Ich bin soeben aus London zurückgekommen und gehe jetzt ins Bootshaus hinunter, wo ich auf Dich warte.\"","sourceLineIndex":75,"ipa":"/lˈiːst ɪç bɪn zoːˈeːbən ˌaʊs lˈɔndoːn tsuːrˈʏkɡəkˌɔmən ʊnt ɡˈeːə jˌɛtst ɪns bˈoːtshaʊs hɪnˈʊntɜ vˌoː ɪç aʊf dɪç vˈaɾtə/","en":"(reads:)\"I have just returned from London and am now going down to the boathouse where I am waiting for you.\"","zh":"（读信）“我刚从伦敦回来，现在去船屋等你。”","note":""},{"id":"rebecca-das-musical-58-076","lineIndex":79,"speaker":"","original":"Egal, wie spät es wird, komm unbedingt.","sourceLineIndex":76,"ipa":"/eːɡˈɑːl viː ʃpˈɛːt ɛs vˌɪɾt kˈɔm ˈʊnbədˌɪŋt/","en":"No matter how late it gets, be sure to come.","zh":"不管多晚，一定要来。","note":""},{"id":"rebecca-das-musical-58-077","lineIndex":80,"speaker":"","original":"Ich habe Dir etwas sehr wichtiges zu sagen. Rebecca.","sourceLineIndex":77,"ipa":"/ɪç hɑːbə diːɾ ˈɛtvɑːs zˈeːɾ vˈɪçtɪɡəs tsuː zˈɑːɡən reːbˈɛkɑː/","en":"I have something very important to tell you. Rebecca.","zh":"我有非常重要的事要告诉你。丽贝卡。","note":""},{"id":"rebecca-das-musical-58-078","lineIndex":81,"speaker":"","original":"(Favell)","sourceLineIndex":78,"ipa":"/favˈɛl/","en":"(Favell)","zh":"（法维尔）","note":""},{"id":"rebecca-das-musical-58-079","lineIndex":82,"speaker":"","original":"Ich frage Sie, Oberst, schreibt so eine Frau, die den Entschluss gefasst hat, Selbstmord zu begehen?","sourceLineIndex":79,"ipa":"/ɪç frˈɑːɡə ziː ˈoːbɜst ʃrˈaɪpt zoː ˌaɪnə frˈaʊ diː deːn ɛntʃlˈʊs ɡəfˈast hat zˈɛlpstmɔɾt tsuː bəɡˈeːən/","en":"I ask you, Colonel, does a woman who has decided to commit suicide write something like that?","zh":"上校，我问您，一个已经决定自杀的女人会写出这样的话吗？","note":""},{"id":"rebecca-das-musical-58-080","lineIndex":83,"speaker":"","original":"(Oberst Julyan)","sourceLineIndex":80,"ipa":"/ˈoːbɜst jˌuːlyːˈɑːn/","en":"(Colonel Julyan)","zh":"（朱利安上校）","note":""},{"id":"rebecca-das-musical-58-081","lineIndex":84,"speaker":"","original":"Haben Sie eine Ahnung, was für eine wichtige Mitteilung Rebecca de Winter Ihnen machen wollte?","sourceLineIndex":81,"ipa":"/hˌɑːbən ziː ˌaɪnə ˈɑːnʊŋ vˈas fyːɾ ˌaɪnə vˈɪçtɪɡə mˈɪttaɪlˌʊŋ reːbˈɛkɑː dˈeː vˈɪntɜ ˌiːnən mˈaxən vɔltə/","en":"Do you have any idea what important message Rebecca de Winter wanted to give you?","zh":"你知道丽贝卡·德温特想告诉你什么重要消息吗？","note":""},{"id":"rebecca-das-musical-58-082","lineIndex":85,"speaker":"","original":"(Favell)","sourceLineIndex":82,"ipa":"/favˈɛl/","en":"(Favell)","zh":"（法维尔）","note":""},{"id":"rebecca-das-musical-58-083","lineIndex":86,"speaker":"","original":"Ich weiß nur, dass Rebecca nie und nimmer Selbstmord begangen hat. Sie hatte gar keinen Grund. Es ging ihr blendend, und ich weiß wovon ich rede.","sourceLineIndex":83,"ipa":"/ɪç vˈaɪs nˈuːɾ das reːbˈɛkɑː nˈiː ʊnt nˈɪmɜ zˈɛlpstmɔɾt bəɡˈaŋən hat ziː hˌatə ɡˈɑːɾ kˈaɪnən ɡɾˈʊnt ɛs ɡˈɪŋ iːɾ blˈɛndənt ʊnt ɪç vˈaɪs vˈoːvoːn ɪç rˈeːdə/","en":"All I know is that Rebecca never, ever committed suicide. She had no reason at all. She was doing great, and I know what I'm talking about.","zh":"我只知道丽贝卡绝不可能自杀。她根本没有理由。她当时好得很，我很清楚自己在说什么。","note":""},{"id":"rebecca-das-musical-58-084","lineIndex":87,"speaker":"","original":"Aber für Mord gibt es ein Motiv, ein starkes Motiv. Die Eifersucht eines eitlen Ehemannes.","sourceLineIndex":84,"ipa":"/ˌɑːbɜ fyːɾ mˈɔɾt ɡˈiːpt ɛs aɪn moːtˈiːf aɪn ʃtˈaɾkəs moːtˈiːf diː ˈaɪfɜzˌuːxt ˌaɪnəs ˈaɪtlən ˈeːeːmˌanəs/","en":"But there is a motive for murder, a strong motive. The jealousy of a vain husband.","zh":"要是谋杀呢，倒有一个动机，一个强烈的动机：一个无能丈夫的嫉妒心；","note":""},{"id":"rebecca-das-musical-58-085","lineIndex":88,"speaker":"","original":"Wenn Sie wissen wollen, wer der Mörder ist - Da steht er mit seiner gottverdammten Arroganz im Gesicht.","sourceLineIndex":85,"ipa":"/vˌɛn ziː vˈɪsən vɔlən vˈeːɾ dɛɾ mˈœɾdɜ ɪst dɑː ʃtˈeːt ɛɾ mɪt zˌaɪnɜ ɡˈɔtfɜdˌamtən ˈaroːɡˌants ɪm ɡəzˈɪçt/","en":"If you want to know who the murderer is, there he is with his goddamn arrogance on his face.","zh":"您要想知道这凶手是谁，就请看我们中间—这家伙还tmd一脸傲慢呢！","note":""},{"id":"rebecca-das-musical-58-086","lineIndex":89,"speaker":"","original":"(Maxim)","sourceLineIndex":86,"ipa":"/mˈaksiːm/","en":"(Maxim)","zh":"（马克西姆）","note":""},{"id":"rebecca-das-musical-58-087","lineIndex":90,"speaker":"","original":"Favell hat mich immer gehasst.","sourceLineIndex":87,"ipa":"/favˈɛl hat mɪç ˈɪmɜ ɡəhˈast/","en":"Favell always hated me.","zh":"法维尔一直恨我。","note":""},{"id":"rebecca-das-musical-58-088","lineIndex":91,"speaker":"","original":"(Oberst Julyan)","sourceLineIndex":88,"ipa":"/ˈoːbɜst jˌuːlyːˈɑːn/","en":"(Colonel Julyan)","zh":"（朱利安上校）","note":""},{"id":"rebecca-das-musical-58-089","lineIndex":92,"speaker":"","original":"Sie erheben da eine schwerwiegende Anschuldigung. Haben Sie irgendeinen Beweis? Einen Zeugen?","sourceLineIndex":89,"ipa":"/ziː ɛɾhˈeːbən dɑː ˌaɪnə ʃvˈeːɾviːɡəndə ˈanʃˌʊldɪɡˌʊŋ hˌɑːbən ziː ˈɪɾɡəndˌaɪnən bəvˈaɪs ˌaɪnən tsˈɔøɡən/","en":"You are making a serious allegation. Do you have any proof? A witness?","zh":"这是非常严重的指控。你有证据吗？有证人吗？","note":""},{"id":"rebecca-das-musical-58-090","lineIndex":93,"speaker":"","original":"(Farvell)","sourceLineIndex":90,"ipa":"/faɾvˈɛl/","en":"(Farvell)","zh":"（法维尔）","note":""},{"id":"rebecca-das-musical-58-091","lineIndex":94,"speaker":"","original":"Emm... Warten Sie.","sourceLineIndex":91,"ipa":"/ˈɛm vˈaɾtən ziː/","en":"Emm... Wait.","zh":"呃……等一下。","note":""},{"id":"rebecca-das-musical-58-092","lineIndex":95,"speaker":"","original":"(Oberst Julyan)","sourceLineIndex":92,"ipa":"/ˈoːbɜst jˌuːlyːˈɑːn/","en":"(Colonel Julyan)","zh":"（朱利安上校）","note":""},{"id":"rebecca-das-musical-58-093","lineIndex":96,"speaker":"","original":"Er war doch heute Nachmittag bei der Verhandlung im Gericht.","sourceLineIndex":93,"ipa":"/ɛɾ vɑːɾ dɔx hˈɔøtə nˈaxmɪtˌɑːk baɪ dɛɾ fɛɾhˈandlʊŋ ɪm ɡərˈɪçt/","en":"He was at the hearing in court this afternoon.","zh":"他今天下午不是参加了法庭听证吗？","note":""},{"id":"rebecca-das-musical-58-094","lineIndex":97,"speaker":"","original":"Warum hat er den Brief nich dem Untersuchungsrichter vorgelegt?","sourceLineIndex":94,"ipa":"/vɑːrˈʊm hat ɛɾ deːn bɾˈiːf nˈɪç deːm ˌʊntɜzˈuːxʊŋsrˌɪçtɜ fˈoːɾɡəlˌeːkt/","en":"Why didn't he present the letter to the examining judge?","zh":"为什么当时没把这个字条提交给法官？","note":""},{"id":"rebecca-das-musical-58-095","lineIndex":98,"speaker":"","original":"(Maxim)","sourceLineIndex":95,"ipa":"/mˈaksiːm/","en":"(Maxim)","zh":"（马克西姆）","note":""},{"id":"rebecca-das-musical-58-096","lineIndex":99,"speaker":"","original":"Er wollte Geld.","sourceLineIndex":96,"ipa":"/ɛɾ vɔltə ɡˈɛlt/","en":"He wanted money.","zh":"他想要钱。","note":""},{"id":"rebecca-das-musical-58-097","lineIndex":100,"speaker":"","original":"(\"Ich\")","sourceLineIndex":97,"ipa":"/ˈɪç/","en":"(\"I\")","zh":"（“我”）","note":""},{"id":"rebecca-das-musical-58-098","lineIndex":101,"speaker":"","original":"Er wollte uns den Brief verkaufen.","sourceLineIndex":98,"ipa":"/ɛɾ vɔltə ʊns deːn bɾˈiːf fɛɾkˈaʊfən/","en":"He wanted to sell us the letter.","zh":"他想把这封信卖给我们。","note":""},{"id":"rebecca-das-musical-58-099","lineIndex":102,"speaker":"","original":"(Maxim)","sourceLineIndex":99,"ipa":"/mˈaksiːm/","en":"(Maxim)","zh":"（马克西姆）","note":""},{"id":"rebecca-das-musical-58-100","lineIndex":103,"speaker":"","original":"Einfach eine saubere Erpressung.","sourceLineIndex":100,"ipa":"/ˈaɪnfˌax ˌaɪnə zˈaʊbərə ɛɾpɾˈɛsʊŋ/","en":"Just pure blackmail.","zh":"就是赤裸裸的敲诈。","note":""},{"id":"rebecca-das-musical-58-101","lineIndex":104,"speaker":"","original":"(Oberst Julyan)","sourceLineIndex":101,"ipa":"/ˈoːbɜst jˌuːlyːˈɑːn/","en":"(Colonel Julyan)","zh":"（朱利安上校）","note":""},{"id":"rebecca-das-musical-58-102","lineIndex":105,"speaker":"","original":"Erpressung ist nie sauber. Und selten einfach.","sourceLineIndex":102,"ipa":"/ɛɾpɾˈɛsʊŋ ɪst nˈiː zˈaʊbɜ ʊnt zˈɛltən ˈaɪnfˌax/","en":"Blackmail is never clean. And rarely easy.","zh":"敲诈从来不干净，也很少简单。","note":""}],"sourceOrder":58,"displayOrder":36},{"order":60,"id":"60-ich-hor-dich-singen-rebecca-mrs-danvers-schatten","title":"Ich hör dich singen","titleZh":"我听见你在歌唱","lines":[{"id":"rebecca-das-musical-60-001","lineIndex":1,"speaker":"","original":"Ich hoer'dich singen mit dem Meer","sourceLineIndex":1,"ipa":"/ɪç hˈøːɾdɪç zˈɪŋən mɪt deːm mˈeːɾ/","en":"I hear you singing with the sea","zh":"我听见你同大海一起吟唱","note":""},{"id":"rebecca-das-musical-60-002","lineIndex":2,"speaker":"","original":"Ich hoer'dich klagen in der Dunkelheit.","sourceLineIndex":2,"ipa":"/ɪç hˈøːɾdɪç klˈɑːɡən ɪn dɛɾ dˈʊnkəlhˌaɪt/","en":"I hear you wailing in the darkness.","zh":"我听见你在黑暗中控诉","note":""},{"id":"rebecca-das-musical-60-003","lineIndex":3,"speaker":"","original":"Dein Geist ist noch in Manderley","sourceLineIndex":3,"ipa":"/daɪn ɡˈaɪst ɪst nɔx ɪn mˈandɜlˌaɪ/","en":"Your spirit is still in Manderley","zh":"你的灵魂依然留在曼德雷","note":""},{"id":"rebecca-das-musical-60-004","lineIndex":4,"speaker":"","original":"und keine nimmt dir deinen Platz","sourceLineIndex":4,"ipa":"/ʊnt kˈaɪnə nˈɪmt diːɾ dˌaɪnən plˈats/","en":"and no one will take your place","zh":"没人能取代你的位置","note":""},{"id":"rebecca-das-musical-60-005","lineIndex":5,"speaker":"","original":"Niemals!","sourceLineIndex":5,"ipa":"/nˈiːmɑːls/","en":"Never!","zh":"永远没有！","note":""},{"id":"rebecca-das-musical-60-006","lineIndex":6,"speaker":"","original":"Rebecca","sourceLineIndex":6,"ipa":"/reːbˈɛkɑː/","en":"Rebecca","zh":"丽贝卡","note":""},{"id":"rebecca-das-musical-60-007","lineIndex":7,"speaker":"","original":"wo du auch immer bist","sourceLineIndex":7,"ipa":"/vˌoː duː ˌaʊx ˈɪmɜ bɪst/","en":"wherever you are","zh":"无论你身在何方","note":""},{"id":"rebecca-das-musical-60-008","lineIndex":8,"speaker":"","original":"dein Herz bleit ruhlos wie die wilde, freie See","sourceLineIndex":8,"ipa":"/daɪn hˈɛɾts blˈaɪt rˈuːloːs viː diː vˈɪldə frˈaɪə zˈeː/","en":"your heart remains restless like the wild, free sea","zh":"你的心澎湃汹涌，就如这片放荡不羁的海","note":""},{"id":"rebecca-das-musical-60-009","lineIndex":9,"speaker":"","original":"Wenn der Abend beginnt, singt der Wind:","sourceLineIndex":9,"ipa":"/vˌɛn dɛɾ ˈɑːbənt bəɡˈɪnt zˈɪŋt dɛɾ vˈɪnt/","en":"When the evening begins, the wind sings:","zh":"每当夜晚到来，风就开始吟唱","note":""},{"id":"rebecca-das-musical-60-010","lineIndex":10,"speaker":"","original":"Rebecca","sourceLineIndex":10,"ipa":"/reːbˈɛkɑː/","en":"Rebecca","zh":"丽贝卡","note":""},{"id":"rebecca-das-musical-60-011","lineIndex":11,"speaker":"","original":"komm heim Rebecca!","sourceLineIndex":11,"ipa":"/kˈɔm hˈaɪm reːbˈɛkɑː/","en":"come home Rebecca!","zh":"回来吧，丽贝卡！","note":""},{"id":"rebecca-das-musical-60-012","lineIndex":12,"speaker":"","original":"Aus dem Nebelreich zurueck nach Manderley.","sourceLineIndex":12,"ipa":"/ˌaʊs deːm nˈeːbəlrˌaɪç tsuːrˈuːɛk nɑːx mˈandɜlˌaɪ/","en":"From the Misty Realm back to Manderley.","zh":"从那雾的国度，再次回到曼德雷","note":""}],"sourceOrder":60,"displayOrder":37},{"order":61,"id":"61-jenseits-der-nacht-ich-maxim","title":"Jenseits der Nacht","titleZh":"穿越黑夜","lines":[{"id":"rebecca-das-musical-61-001","lineIndex":1,"speaker":"","original":"Sie kann uns nicht mehr antun","sourceLineIndex":1,"ipa":"/ziː kˌan ʊns nˈɪçt mˌeːɾ ˈantˌuːn/","en":"She can't do anything more to us","zh":"她不能再对我们怎么样了","note":""},{"id":"rebecca-das-musical-61-002","lineIndex":2,"speaker":"","original":"Ich stand am Abgrund","sourceLineIndex":2,"ipa":"/ɪç ʃtˈant am ˈapɡɾˌʊnt/","en":"I was on the edge","zh":"我站在悬崖边","note":""},{"id":"rebecca-das-musical-61-003","lineIndex":3,"speaker":"","original":"Und sah in die Tiefe","sourceLineIndex":3,"ipa":"/ʊnt zˈɑː ɪn diː tˈiːfə/","en":"And looked into the depths","zh":"看向深渊","note":""},{"id":"rebecca-das-musical-61-004","lineIndex":4,"speaker":"","original":"Mein Herz war Eis","sourceLineIndex":4,"ipa":"/maɪn hˈɛɾts vɑːɾ ˈaɪs/","en":"My heart was ice","zh":"心如死灰","note":""},{"id":"rebecca-das-musical-61-005","lineIndex":5,"speaker":"","original":"Und jede Hoffnung tot","sourceLineIndex":5,"ipa":"/ʊnt jˈeːdə hˈɔfnʊŋ tˈoːt/","en":"And all hope dead","zh":"没有一点希望","note":""},{"id":"rebecca-das-musical-61-006","lineIndex":6,"speaker":"","original":"Und ich stand hinter dir","sourceLineIndex":6,"ipa":"/ʊnt ɪç ʃtˈant hˈɪntɜ dˈiːɾ/","en":"And I had your back","zh":"而我站在你身后","note":""},{"id":"rebecca-das-musical-61-007","lineIndex":7,"speaker":"","original":"Und hatte Angst um dich","sourceLineIndex":7,"ipa":"/ʊnt hˌatə ˈaŋst ʊm dˈɪç/","en":"And was afraid for you","zh":"为你担忧","note":""},{"id":"rebecca-das-musical-61-008","lineIndex":8,"speaker":"","original":"Weil unsichtbare Schatten dich umgaben","sourceLineIndex":8,"ipa":"/vˌaɪl ˈʊnzˌɪçtbɑːrə ʃˈatən dɪç ˈʊmɡˌɑːbən/","en":"Because invisible shadows surrounded you","zh":"因为看不见的阴霾笼罩着你","note":""},{"id":"rebecca-das-musical-61-009","lineIndex":9,"speaker":"","original":"Wie wär es mir ergangen ohne Dich?","sourceLineIndex":9,"ipa":"/viː vˈɛːɾ ɛs miːɾ ɛɾɡˈaŋən ˈoːnə dˈɪç/","en":"How would I have been without you?","zh":"如果没有你我会变成什么样？","note":""},{"id":"rebecca-das-musical-61-010","lineIndex":10,"speaker":"","original":"Warum danach fragen?","sourceLineIndex":10,"ipa":"/vɑːrˈʊm danˈax frˈɑːɡən/","en":"Why ask?","zh":"为什么要这么问？","note":""},{"id":"rebecca-das-musical-61-011","lineIndex":11,"speaker":"","original":"Zeit, zu vergessen","sourceLineIndex":11,"ipa":"/tsˈaɪt tsuː fɛɾɡˈɛsən/","en":"Time to forget","zh":"让我们放下过去","note":""},{"id":"rebecca-das-musical-61-012","lineIndex":12,"speaker":"","original":"Zeit, zu erwachen","sourceLineIndex":12,"ipa":"/tsˈaɪt tsuː ɛɾvˈaxən/","en":"Time to awaken","zh":"重获新生","note":""},{"id":"rebecca-das-musical-61-013","lineIndex":13,"speaker":"","original":"Jenseits der Nacht","sourceLineIndex":13,"ipa":"/jˈɛnzaɪts dɛɾ nˈaxt/","en":"Beyond the night","zh":"在黑夜的另一头","note":""},{"id":"rebecca-das-musical-61-014","lineIndex":14,"speaker":"","original":"Jenseits der Angst","sourceLineIndex":14,"ipa":"/jˈɛnzaɪts dɛɾ ˈaŋst/","en":"Beyond fear","zh":"恐惧的彼岸","note":""},{"id":"rebecca-das-musical-61-015","lineIndex":15,"speaker":"","original":"Holt kein Schatten uns mehr ein","sourceLineIndex":15,"ipa":"/hˈɔlt kˈaɪn ʃˈatən ʊns mˈeːɾ ˈaɪn/","en":"No shadow will overtake us anymore","zh":"不会再有阴霾相随","note":""},{"id":"rebecca-das-musical-61-016","lineIndex":16,"speaker":"","original":"Jetzt sind wir frei","sourceLineIndex":16,"ipa":"/jˌɛtst zɪnt viːɾ frˈaɪ/","en":"Now we are free","zh":"现在我们自由了","note":""},{"id":"rebecca-das-musical-61-017","lineIndex":17,"speaker":"","original":"Unsere Träume zu leben","sourceLineIndex":17,"ipa":"/ˌʊnzrə tɾˈɔømə tsuː lˈeːbən/","en":"To live our dreams","zh":"我们的梦想成真了","note":""},{"id":"rebecca-das-musical-61-018","lineIndex":18,"speaker":"","original":"Wir werden glücklich werden","sourceLineIndex":18,"ipa":"/viːɾ vˌɛɾdən ɡlˈʏklɪç vˌɛɾdən/","en":"We will be happy","zh":"我们会很幸福","note":""},{"id":"rebecca-das-musical-61-019","lineIndex":19,"speaker":"","original":"Ich glaub daran","sourceLineIndex":19,"ipa":"/ɪç ɡlˈaʊp dɑːrˈan/","en":"I believe in it","zh":"我对此坚信着","note":""},{"id":"rebecca-das-musical-61-020","lineIndex":20,"speaker":"","original":"Ich weiß, was Liebe kann","sourceLineIndex":20,"ipa":"/ɪç vˈaɪs vˈas lˈiːbə kˌan/","en":"I know what love can do","zh":"（因为）我深知爱的力量","note":""},{"id":"rebecca-das-musical-61-021","lineIndex":21,"speaker":"","original":"Wenn wir auf den Klippen stehen","sourceLineIndex":21,"ipa":"/vˌɛn viːɾ aʊf deːn klˈɪpən ʃtˈeːən/","en":"When we stand on the cliffs","zh":"当我们站在礁石上","note":""},{"id":"rebecca-das-musical-61-022","lineIndex":22,"speaker":"","original":"Werden wir zum Himmel sehen","sourceLineIndex":22,"ipa":"/vˌɛɾdən viːɾ tsʊm hˈɪməl zˈeːən/","en":"We will look to the sky","zh":"我们会看向天空","note":""},{"id":"rebecca-das-musical-61-023","lineIndex":23,"speaker":"","original":", Sieh nur, zwei Möwen im Wind\"","sourceLineIndex":23,"ipa":"/zˈiː nˈuːɾ tsvˈaɪ mˈøːvən ɪm vˈɪnt/","en":"\"Look, two seagulls in the wind\"","zh":"\"看，两只海鸥在风中翱翔！“","note":""},{"id":"rebecca-das-musical-61-024","lineIndex":24,"speaker":"","original":"Jenseits der Nacht","sourceLineIndex":24,"ipa":"/jˈɛnzaɪts dɛɾ nˈaxt/","en":"Beyond the night","zh":"在黑夜的另一头","note":""},{"id":"rebecca-das-musical-61-025","lineIndex":25,"speaker":"","original":"Jenseits der Angst","sourceLineIndex":25,"ipa":"/jˈɛnzaɪts dɛɾ ˈaŋst/","en":"Beyond fear","zh":"恐惧的彼岸","note":""},{"id":"rebecca-das-musical-61-026","lineIndex":26,"speaker":"","original":"Holt kein Schatten uns mehr ein","sourceLineIndex":26,"ipa":"/hˈɔlt kˈaɪn ʃˈatən ʊns mˈeːɾ ˈaɪn/","en":"No shadow will overtake us anymore","zh":"不会再有阴霾相随","note":""},{"id":"rebecca-das-musical-61-027","lineIndex":27,"speaker":"","original":"Jetzt geh'n wir zwei","sourceLineIndex":27,"ipa":"/jˌɛtst ɡˈeːn viːɾ tsvˈaɪ/","en":"Now let's go two of us","zh":"现在让我们两个","note":""},{"id":"rebecca-das-musical-61-028","lineIndex":28,"speaker":"","original":"Uns'rer Zukunft entgegen","sourceLineIndex":28,"ipa":"/ˈʊnsrɜ tsuːkˈʊnft ɛntɡˈeːɡən/","en":"Towards our future","zh":"一起迎接我们的未来","note":""},{"id":"rebecca-das-musical-61-029","lineIndex":29,"speaker":"","original":"Und nichts kann uns besiegen","sourceLineIndex":29,"ipa":"/ʊnt nˈɪçts kˌan ʊns bəzˈiːɡən/","en":"And nothing can defeat us","zh":"没有什么能够战胜我们","note":""},{"id":"rebecca-das-musical-61-030","lineIndex":30,"speaker":"","original":"Was es auch sei","sourceLineIndex":30,"ipa":"/vˈas ɛs ˌaʊx zˈaɪ/","en":"Whatever it is","zh":"无论是什么都不能","note":""},{"id":"rebecca-das-musical-61-031","lineIndex":31,"speaker":"","original":"Weil du mich liebst","sourceLineIndex":31,"ipa":"/vˌaɪl duː mɪç lˈiːpst/","en":"Because you love me","zh":"因为有你爱我","note":""},{"id":"rebecca-das-musical-61-032","lineIndex":32,"speaker":"","original":"Bin ich frei","sourceLineIndex":32,"ipa":"/bɪn ɪç frˈaɪ/","en":"Am I free","zh":"故我在","note":""}],"sourceOrder":61,"displayOrder":38},{"order":62,"id":"62-manderley-in-flammen-nein-weiss-gott-ensemble-crawley-maxim","title":"Manderley in Flammen / Nein, weiss Gott!","titleZh":"曼德利陷入火海／不，绝不！","lines":[{"id":"rebecca-das-musical-62-001","lineIndex":1,"speaker":"","original":"Feuer! Feuer!","sourceLineIndex":1,"ipa":"/fˈɔøɜ fˈɔøɜ/","en":"Fire! Fire!","zh":"大火！大火！","note":""},{"id":"rebecca-das-musical-62-002","lineIndex":2,"speaker":"","original":"Manderlay in Flammen!","sourceLineIndex":2,"ipa":"/mˈandɜlˌɛɪ ɪn flˈamən/","en":"Manderlay in flames!","zh":"曼德雷在燃烧！","note":""},{"id":"rebecca-das-musical-62-003","lineIndex":3,"speaker":"","original":"Diener alle, löscht den Brand","sourceLineIndex":3,"ipa":"/dˈiːnɜ ˈalə lˈœʃt deːn bɾˈant/","en":"All servants, put out the fire","zh":"所有佣人，都去灭火！","note":""},{"id":"rebecca-das-musical-62-004","lineIndex":4,"speaker":"","original":"Schnell, wir brauchen Wasser!","sourceLineIndex":4,"ipa":"/ʃnˈɛl viːɾ bɾˈaʊxən vˈasɜ/","en":"Quick, we need water!","zh":"快点打水来！","note":""},{"id":"rebecca-das-musical-62-005","lineIndex":5,"speaker":"","original":"Feuer! Feuer!","sourceLineIndex":5,"ipa":"/fˈɔøɜ fˈɔøɜ/","en":"Fire! Fire!","zh":"大火！大火！","note":""},{"id":"rebecca-das-musical-62-006","lineIndex":6,"speaker":"","original":"Manderley in Flammen!","sourceLineIndex":6,"ipa":"/mˈandɜlˌaɪ ɪn flˈamən/","en":"Manderley on fire!","zh":"曼德雷在燃烧！","note":""},{"id":"rebecca-das-musical-62-007","lineIndex":7,"speaker":"","original":"Eimer her, von Hand zu Hand","sourceLineIndex":7,"ipa":"/ˈaɪmɜ hˈeːɾ fɔn hˈant tsuː hˈant/","en":"Bucket over, hand to hand","zh":"众志成城灭大火","note":""},{"id":"rebecca-das-musical-62-008","lineIndex":8,"speaker":"","original":"Schneller, schneller, schneller!","sourceLineIndex":8,"ipa":"/ʃnˈɛlɜ ʃnˈɛlɜ ʃnˈɛlɜ/","en":"Faster, faster, faster!","zh":"快点！快点！快点！","note":""},{"id":"rebecca-das-musical-62-009","lineIndex":9,"speaker":"","original":"Feuer! Feuer!","sourceLineIndex":9,"ipa":"/fˈɔøɜ fˈɔøɜ/","en":"Fire! Fire!","zh":"大火！大火！","note":""},{"id":"rebecca-das-musical-62-010","lineIndex":10,"speaker":"","original":"Manderlay ist sonst verlor'n!","sourceLineIndex":10,"ipa":"/mˈandɜlˌɛɪ ɪst zˈɔnst fɛɾlˈoːɾn/","en":"Otherwise Manderlay will be lost!","zh":"曼德雷要被烧尽了！","note":""},{"id":"rebecca-das-musical-62-011","lineIndex":11,"speaker":"","original":"Jeder verlasst das Haus! Rettet deine Leben!","sourceLineIndex":11,"ipa":"/jˈeːdɜ fɛɾlˈast das hˈaʊs rˈɛtət dˌaɪnə lˈeːbən/","en":"Everyone leaves the house! Save your lives!","zh":"所有人离开房子！保命要紧！","note":""},{"id":"rebecca-das-musical-62-012","lineIndex":12,"speaker":"","original":"Feuer! (Vorsicht!) Feuer! (Rennt hier!)","sourceLineIndex":12,"ipa":"/fˈɔøɜ fˈoːɾzˌɪçt fˈɔøɜ rˈɛnt hˈiːɾ/","en":"Fire! (Caution!) Fire! (Run here!)","zh":"大火！（当心！）大火！（到这里来！）","note":""},{"id":"rebecca-das-musical-62-013","lineIndex":13,"speaker":"","original":"Manderlay in Flammen! (Rasch!)","sourceLineIndex":13,"ipa":"/mˈandɜlˌɛɪ ɪn flˈamən rˈaʃ/","en":"Manderlay in flames! (Quickly!)","zh":"曼德雷在燃烧！（快点！）","note":""},{"id":"rebecca-das-musical-62-014","lineIndex":14,"speaker":"","original":"Wo kein Wasser ist nehmt Sand","sourceLineIndex":14,"ipa":"/vˌoː kˈaɪn vˈasɜ ɪst nˈeːmt zˈant/","en":"Where there is no water use sand","zh":"没有水就用沙子","note":""},{"id":"rebecca-das-musical-62-015","lineIndex":15,"speaker":"","original":"Schneller mit der Leiter! (Los!)","sourceLineIndex":15,"ipa":"/ʃnˈɛlɜ mɪt dɛɾ lˈaɪtɜ lˈoːs/","en":"Faster with the ladder! (Go!)","zh":"用梯子更快些！（失控！）","note":""},{"id":"rebecca-das-musical-62-016","lineIndex":16,"speaker":"","original":"Feuer! (Höher!) Feuer! (Weiter!)","sourceLineIndex":16,"ipa":"/fˈɔøɜ hˈøːɜ fˈɔøɜ vˈaɪtɜ/","en":"Fire! (Higher!) Fire! (Continue!)","zh":"大火！（高些！）大火！（远些！）","note":""},{"id":"rebecca-das-musical-62-017","lineIndex":17,"speaker":"","original":"Manderlay in Flammen (Lauft!)","sourceLineIndex":17,"ipa":"/mˈandɜlˌɛɪ ɪn flˈamən lˈaʊft/","en":"Manderlay in flames (Run!)","zh":"曼德雷在燃烧！（跑吧！）","note":""},{"id":"rebecca-das-musical-62-018","lineIndex":18,"speaker":"","original":"Rettet was ihr tragen könnt","sourceLineIndex":18,"ipa":"/rˈɛtət vˈas iːɾ tɾˈɑːɡən kˌœnt/","en":"Save what you can carry","zh":"救下你们能拿走的一切","note":""},{"id":"rebecca-das-musical-62-019","lineIndex":19,"speaker":"","original":"Schneller, schneller, schneller!","sourceLineIndex":19,"ipa":"/ʃnˈɛlɜ ʃnˈɛlɜ ʃnˈɛlɜ/","en":"Faster, faster, faster!","zh":"快些！快些！快些！","note":""},{"id":"rebecca-das-musical-62-020","lineIndex":20,"speaker":"","original":"Das stolze Manderlay, Kohle und Asche","sourceLineIndex":20,"ipa":"/das ʃtˈɔltsə mˈandɜlˌɛɪ kˈoːlə ʊnt ˈaʃə/","en":"The proud Manderlay, coal and ash","zh":"骄傲的曼德雷，化成了浓烟和灰烬","note":""},{"id":"rebecca-das-musical-62-021","lineIndex":21,"speaker":"","original":"Welch ein tragischer Schicksalsschlag.","sourceLineIndex":21,"ipa":"/vˈɛlç aɪn tɾˈɑɡɪʃɜ ʃˈɪkzalsçlˌɑːk/","en":"What a tragic stroke of fate.","zh":"这境地多么悲哀！","note":""},{"id":"rebecca-das-musical-62-022","lineIndex":22,"speaker":"","original":"Wehrt eure Möbel und Bücher und Bilder!","sourceLineIndex":22,"ipa":"/vˈeːɾt ˈɔørə mˈøːbəl ʊnt bˈyːçɜ ʊnt bˈɪldɜ/","en":"Defend your furniture and books and pictures!","zh":"保护好家具，书籍和图画！","note":""},{"id":"rebecca-das-musical-62-023","lineIndex":23,"speaker":"","original":"Alles verbrennt, Manderlay ist verlor'n!","sourceLineIndex":23,"ipa":"/ˈaləs fɛɾbɾˈɛnt mˈandɜlˌɛɪ ɪst fɛɾlˈoːɾn/","en":"Everything burns down, Manderlay is lost!","zh":"一切都在燃烧，曼德雷已经失陷了！","note":""},{"id":"rebecca-das-musical-62-024","lineIndex":24,"speaker":"","original":"Ich schwöre, im Haus war jedes Feuer ausgemacht. (Feuer! Feuer! Manderlay in Flammen! Wahnsinn! Wahnsinn!)","sourceLineIndex":24,"ipa":"/ɪç ʃvˈøːrə ɪm hˈaʊs vɑːɾ jˈeːdəs fˈɔøɜ ˈaʊsɡəmˌaxt fˈɔøɜ fˈɔøɜ mˈandɜlˌɛɪ ɪn flˈamən vˈɑːnzɪn vˈɑːnzɪn/","en":"I swear every fire in the house was turned off. (Fire! Fire! Manderlay in flames! Madness! Madness!)","zh":"我发誓，屋子里没有一簇未熄灭的火。（大火！大火！曼德雷在燃烧！无法想象！无法想象！）","note":""},{"id":"rebecca-das-musical-62-025","lineIndex":25,"speaker":"","original":"Ich sah nur im Gang noch Mrs. Danvers nach Mitternacht. (Feuer! Feuer! Manderlay in Flammen! Wahnsinn! Wahnsinn!)","sourceLineIndex":25,"ipa":"/ɪç zˈɑː nˈuːɾ ɪm ɡˈaŋ nɔx ˌɛmˌɛrˈɛs dˈanfɜs nɑːx mˈɪtɜnˌaxt fˈɔøɜ fˈɔøɜ mˈandɜlˌɛɪ ɪn flˈamən vˈɑːnzɪn vˈɑːnzɪn/","en":"I only saw Mrs. Danvers in the hallway after midnight. (Fire! Fire! Manderlay in flames! Madness! Madness!)","zh":"只是午夜后我在走廊里看见了丹佛斯夫人。（大火！大火！曼德雷在燃烧！无法想象！无法想象！）","note":""},{"id":"rebecca-das-musical-62-026","lineIndex":26,"speaker":"","original":"Doch als ich rief, hat sie nur laut gelacht. (Feuer! Feuer! Manderlay in Flammen! Sie verlor den Verstand!)","sourceLineIndex":26,"ipa":"/dɔx als ɪç rˈiːf hat ziː nˈuːɾ lˈaʊt ɡəlˈaxt fˈɔøɜ fˈɔøɜ mˈandɜlˌɛɪ ɪn flˈamən ziː fɛɾlˈoːɾ deːn fɛɾʃtˈant/","en":"But when I called out, she just laughed out loud. (Fire! Fire! Manderlay on fire! She lost her mind!)","zh":"但我喊她姓名时，她只放声大笑。（大火！大火！曼德雷在燃烧！她失去了理智！）","note":""},{"id":"rebecca-das-musical-62-027","lineIndex":27,"speaker":"","original":"Bald wird Schutt und Asche sein Was mir mein stolzer Vater hinterließ.","sourceLineIndex":27,"ipa":"/bˈalt vˌɪɾt ʃˈʊt ʊnt ˈaʃə zaɪn vˈas miːɾ maɪn ʃtˈɔltsɜ fˈɑːtɜ hˌɪntɜlˈiːs/","en":"Soon there will be rubble and ashes What my proud father left me.","zh":"很快我骄傲的父亲留下的一切就会变成废石和灰烬。","note":""},{"id":"rebecca-das-musical-62-029","lineIndex":28,"speaker":"","original":"Es war mal mein Zuhaus!","sourceLineIndex":29,"ipa":"/ɛs vɑːɾ mˈɑːl maɪn tsuːhˈaʊs/","en":"It used to be my home!","zh":"它曾经是我的家啊！","note":""},{"id":"rebecca-das-musical-62-030","lineIndex":29,"speaker":"","original":"Jedoch das Böse nahm Besitz davon","sourceLineIndex":30,"ipa":"/jˈeːdɔx das bˈøːzə nˈɑːm bəzˈɪts dɑːfˈɔn/","en":"However, evil took possession of it","zh":"但是罪恶吞噬了这栋宅邸","note":""},{"id":"rebecca-das-musical-62-031","lineIndex":30,"speaker":"","original":"So wurde daraus mein Gefängnis.","sourceLineIndex":31,"ipa":"/zoː vˌʊɐdə dɑːrˈaʊs maɪn ɡəfˈɛŋnɪs/","en":"So it became my prison.","zh":"它变成了我的囚笼。","note":""},{"id":"rebecca-das-musical-62-032","lineIndex":31,"speaker":"","original":"Nein, weiß Gott, ich wollte nicht, dass Flammen es zerstör'n!","sourceLineIndex":32,"ipa":"/nˈaɪn vˈaɪs ɡˈɔt ɪç vɔltə nˈɪçt das flˈamən ɛs tsɛɾʃtˈøːɾn/","en":"No, God knows, I didn't want flames to destroy it!","zh":"不！天知道我不想让火焰把它摧毁！","note":""},{"id":"rebecca-das-musical-62-033","lineIndex":32,"speaker":"","original":"Doch mit dem Haus verbrennt die Angst","sourceLineIndex":33,"ipa":"/dɔx mɪt deːm hˈaʊs fɛɾbɾˈɛnt diː ˈaŋst/","en":"But fear burns with the house","zh":"但是我的痛苦会随着屋子一起烧掉","note":""},{"id":"rebecca-das-musical-62-034","lineIndex":33,"speaker":"","original":"Von den dunklen Schatten bleibt nur Rauch!","sourceLineIndex":34,"ipa":"/fɔn deːn dˈʊŋklən ʃˈatən blˈaɪpt nˈuːɾ rˈaʊx/","en":"Only smoke remains from the dark shadows!","zh":"黑色阴影留下的仅仅是烟尘！","note":""}],"sourceOrder":62,"displayOrder":39},{"order":63,"id":"63-epilog-ich-hab-getraumt-von-manderley-reprise-ich-schatten-ensemble","title":"Epilog - Ich hab geträumt von Manderley - Reprise","titleZh":"尾声：我梦见曼德利（重唱）","lines":[{"id":"rebecca-das-musical-63-001","lineIndex":1,"speaker":"","original":"Jetzt sehe ich Manderley nur noch im Traum was dort geschah ist lange her.","sourceLineIndex":1,"ipa":"/jˌɛtst zˈeːə ɪç mˈandɜlˌaɪ nˈuːɾ nɔx ɪm tɾˈaʊm vˈas dˈɔɾt ɡəʃˈɑː ɪst lˈaŋə hˈeːɾ/","en":"Now I only see Manderley in my dreams what happened there was a long time ago.","zh":"如今曼德雷只出现在我梦中在那里发生的故事早已成为过往","note":""},{"id":"rebecca-das-musical-63-003","lineIndex":2,"speaker":"","original":"Unser Zuhaus ist ein kleines Hotel mit Blick auf das Mittelmeer.","sourceLineIndex":3,"ipa":"/ˌʊnzɜ tsuːhˈaʊs ɪst aɪn klˈaɪnəs hˈoːtəl mɪt blˈɪk aʊf das mˈɪtəlmˌeːɾ/","en":"Our home is a small hotel overlooking the Mediterranean.","zh":"我们住在一间小旅馆里可以望见地中海","note":""},{"id":"rebecca-das-musical-63-005","lineIndex":3,"speaker":"","original":"Wenn der Flieder blüht und Erinnerung bringt gehen wir durch den Park zum Strand.","sourceLineIndex":5,"ipa":"/vˌɛn dɛɾ flˈiːdɜ blˈyːt ʊnt ɛɾˈɪnərˌʊŋ bɾˈɪŋt ɡˈeːən viːɾ dʊɐç deːn pˈaɾk tsʊm ʃtɾˈant/","en":"When the lilacs bloom and bring memories let's walk through the park to the beach.","zh":"当丁香盛开 回忆被勾起我们穿过花园漫步到海滩","note":""},{"id":"rebecca-das-musical-63-007","lineIndex":4,"speaker":"","original":"Und wir hören das Lied","sourceLineIndex":7,"ipa":"/ʊnt viːɾ hˈøːrən das lˈiːt/","en":"And we hear the song","zh":"海浪在歌唱","note":""},{"id":"rebecca-das-musical-63-008","lineIndex":5,"speaker":"","original":"das die Brandung singt","sourceLineIndex":8,"ipa":"/das diː bɾˈandʊŋ zˈɪŋt/","en":"that the surf sings","zh":"我们屏息听","note":""},{"id":"rebecca-das-musical-63-009","lineIndex":6,"speaker":"","original":"Und wir schweigen Hand in Hand.","sourceLineIndex":9,"ipa":"/ʊnt viːɾ ʃvˈaɪɡən hˈant ɪn hˈant/","en":"And we are silent hand in hand.","zh":"紧牵住对方的手","note":""},{"id":"rebecca-das-musical-63-010","lineIndex":7,"speaker":"","original":"Ich hab geträumt von Manderley und der vergangnen Zeit","sourceLineIndex":10,"ipa":"/ɪç hˈɑːp ɡətɾˈɔømt fɔn mˈandɜlˌaɪ ʊnt dɛɾ fɛɾɡˈaŋnən tsˈaɪt/","en":"I dreamed of Manderley and the past","zh":"我又梦到了曼德雷和那往昔时光","note":""},{"id":"rebecca-das-musical-63-011","lineIndex":8,"speaker":"","original":"von Sehnsucht","sourceLineIndex":11,"ipa":"/fɔn zˈeːnzuːxt/","en":"of longing","zh":"欲望","note":""},{"id":"rebecca-das-musical-63-012","lineIndex":9,"speaker":"","original":"Schuld und Dunkelheit und von Liebe wir befreit.","sourceLineIndex":12,"ipa":"/ʃˈʊlt ʊnt dˈʊnkəlhˌaɪt ʊnt fɔn lˈiːbə viːɾ bəfrˈaɪt/","en":"Guilt and darkness and love we are freed from.","zh":"罪恶 还有黑暗 和拯救我们的爱","note":""},{"id":"rebecca-das-musical-63-013","lineIndex":10,"speaker":"","original":"Zwei die sich vertraun die verzweifeln nicht wenn sie vor dem Abgrund stehen.","sourceLineIndex":13,"ipa":"/tsvˈaɪ diː zɪç fɛɾtɾˈaʊn diː fɛɾtsvˈaɪfəln nˈɪçt vˌɛn ziː fˌɔɾ deːm ˈapɡɾˌʊnt ʃtˈeːən/","en":"Two who trust each other they don't despair when they stand on the edge of the abyss.","zh":"两人心连心能打破绝望就算站在深渊前","note":""},{"id":"rebecca-das-musical-63-016","lineIndex":11,"speaker":"","original":"Weil sie Brücken bauen","sourceLineIndex":16,"ipa":"/vˌaɪl ziː bɾˈʏkən bˈaʊən/","en":"Because they build bridges","zh":"因为这两人","note":""},{"id":"rebecca-das-musical-63-017","lineIndex":12,"speaker":"","original":"Brücken bauen aus Licht über die sie weitergehen.","sourceLineIndex":17,"ipa":"/bɾˈʏkən bˈaʊən ˌaʊs lˈɪçt ˌyːbɜ diː ziː vˈaɪtɜɡˌeːən/","en":"Building bridges from light over which they continue.","zh":"用光架起桥继续大步向前走","note":""},{"id":"rebecca-das-musical-63-019","lineIndex":13,"speaker":"","original":"Wir finden Stärke in Gefahr und Hoffnung in schwerer Zeit.","sourceLineIndex":19,"ipa":"/viːɾ fˈɪndən ʃtˈɛɾkə ɪn ɡəfˈɑːɾ ʊnt hˈɔfnʊŋ ɪn ʃvˈeːrɜ tsˈaɪt/","en":"We find strength in danger and hope in difficult times.","zh":"从危险中汲取力量 在逆境看到希望","note":""},{"id":"rebecca-das-musical-63-020","lineIndex":14,"speaker":"","original":"Ich habe geträumt von Manderley und von Liebe wir befreit.","sourceLineIndex":20,"ipa":"/ɪç hɑːbə ɡətɾˈɔømt fɔn mˈandɜlˌaɪ ʊnt fɔn lˈiːbə viːɾ bəfrˈaɪt/","en":"I dreamed of Manderley and of love we set free.","zh":"我又梦到了曼德雷 和拯救我们的爱","note":""}],"sourceOrder":63,"displayOrder":40},{"order":65,"id":"65-am-abgrund","title":"Am Abgrund","titleZh":"在深渊边缘","lines":[{"id":"rebecca-das-musical-65-001","lineIndex":1,"speaker":"","original":"Sie zeichnen wirklich gut","sourceLineIndex":1,"ipa":"/ziː tsˈaɪçnən vˈɪɾklɪç ɡˈuːt/","en":"You draw really well","zh":"你画得真好","note":""},{"id":"rebecca-das-musical-65-002","lineIndex":2,"speaker":"","original":"Sie haben Talent","sourceLineIndex":2,"ipa":"/ziː hˌɑːbən talˈɛnt/","en":"You have talent","zh":"你有才华","note":""},{"id":"rebecca-das-musical-65-003","lineIndex":3,"speaker":"","original":"Das habe ich von meinem Vater","sourceLineIndex":3,"ipa":"/das hɑːbə ɪç fɔn mˌaɪnəm fˈɑːtɜ/","en":"I got that from my father","zh":"这是我从我父亲那里得到的","note":""},{"id":"rebecca-das-musical-65-004","lineIndex":4,"speaker":"","original":"Er war Künstler?","sourceLineIndex":4,"ipa":"/ɛɾ vɑːɾ kˈʏnstlɜ/","en":"He was an artist?","zh":"他是一位艺术家？","note":""},{"id":"rebecca-das-musical-65-005","lineIndex":5,"speaker":"","original":"Oh ja, Maler","sourceLineIndex":5,"ipa":"/ˈoː jˈɑː mˈɑːlɜ/","en":"Oh yes, painter","zh":"哦，是的，画家","note":""},{"id":"rebecca-das-musical-65-006","lineIndex":6,"speaker":"","original":"Seiner Zeit weit voraus","sourceLineIndex":6,"ipa":"/zˌaɪnɜ tsˈaɪt vˈaɪt foːrˈaʊs/","en":"Way ahead of his time","zh":"远远领先于他的时代","note":""},{"id":"rebecca-das-musical-65-007","lineIndex":7,"speaker":"","original":"Er fehlt Ihnen wohl sehr?","sourceLineIndex":7,"ipa":"/ɛɾ fˈeːlt ˌiːnən vˈoːl zˈeːɾ/","en":"Do you miss him a lot?","zh":"你很想念他吗？","note":""},{"id":"rebecca-das-musical-65-008","lineIndex":8,"speaker":"","original":"Er war ein wunderbarer Mensch","sourceLineIndex":8,"ipa":"/ɛɾ vɑːɾ aɪn vˈʊndɜbˌɑːrɜ mˈɛnʃ/","en":"He was a wonderful person","zh":"他是一个很棒的人","note":""},{"id":"rebecca-das-musical-65-009","lineIndex":9,"speaker":"","original":"Mir scheint, wir beide haben etwas gemeinsam, Sie und ich","sourceLineIndex":9,"ipa":"/miːɾ ʃˈaɪnt viːɾ bˈaɪdə hˌɑːbən ˈɛtvɑːs ɡəmˈaɪnzɑːm ziː ʊnt ˈɪç/","en":"It seems to me that we both have something in common, you and me","zh":"在我看来，我们有一些共同点，你和我","note":""},{"id":"rebecca-das-musical-65-010","lineIndex":10,"speaker":"","original":"Wir stehen beide allein in der Welt","sourceLineIndex":10,"ipa":"/viːɾ ʃtˈeːən bˈaɪdə alˈaɪn ɪn dɛɾ vˈɛlt/","en":"We are both alone in the world","zh":"我们都是世界上孤独的人","note":""},{"id":"rebecca-das-musical-65-011","lineIndex":11,"speaker":"","original":"Da, das Bild ist fertig","sourceLineIndex":11,"ipa":"/dˈɑː das bˈɪlt ɪst fˈɛɾtɪç/","en":"There, the picture is finished","zh":"到这里，图片就完成了","note":""},{"id":"rebecca-das-musical-65-012","lineIndex":12,"speaker":"","original":"Für mich?","sourceLineIndex":12,"ipa":"/fˈyːɾ mɪç/","en":"For me?","zh":"为了我？","note":""},{"id":"rebecca-das-musical-65-013","lineIndex":13,"speaker":"","original":"Als kleines Dankeschön","sourceLineIndex":13,"ipa":"/als klˈaɪnəs dˈankɛʃˌøːn/","en":"As a small thank you","zh":"作为一个小小的感谢","note":""},{"id":"rebecca-das-musical-65-014","lineIndex":14,"speaker":"","original":"Für jede Stunde mit Ihnen","sourceLineIndex":14,"ipa":"/fyːɾ jˈeːdə ʃtˈʊndə mɪt ˈiːnən/","en":"For every hour with you","zh":"和你在一起的每一个小时","note":""},{"id":"rebecca-das-musical-65-015","lineIndex":15,"speaker":"","original":"Durch Sie hab ich erfahren","sourceLineIndex":15,"ipa":"/dʊɐç ziː hˈɑːp ɪç ɛɾfˈɑːrən/","en":"I found out about it through you","zh":"我是通过你知道的","note":""},{"id":"rebecca-das-musical-65-016","lineIndex":16,"speaker":"","original":"Wie schön ein Augenblick sein kann","sourceLineIndex":16,"ipa":"/viː ʃˈøːn aɪn ˈaʊɡənblˌɪk zaɪn kˌan/","en":"How beautiful a moment can be","zh":"一个瞬间可以是多么美好","note":""},{"id":"rebecca-das-musical-65-017","lineIndex":17,"speaker":"","original":"Ich möcht die Tage aufbewahren","sourceLineIndex":17,"ipa":"/ɪç mˈœçt diː tˈɑːɡə ˈaʊfbəvˌɑːrən/","en":"I want to keep the days","zh":"我想留住日子","note":""},{"id":"rebecca-das-musical-65-018","lineIndex":18,"speaker":"","original":"Verschließen in einem Flakon","sourceLineIndex":18,"ipa":"/fɛɾʃlˈiːsən ɪn ˌaɪnəm flˈɑkoːn/","en":"Seal in a bottle","zh":"密封在瓶子里","note":""},{"id":"rebecca-das-musical-65-019","lineIndex":19,"speaker":"","original":"Wie ein kostbares Parfüm","sourceLineIndex":19,"ipa":"/viː aɪn kˈɔstbɑːrəs pˈaɾfyːm/","en":"Like a precious perfume","zh":"就像珍贵的香水一样","note":""}],"sourceOrder":65,"displayOrder":41},{"order":66,"id":"66-der-ball-von-manderley","title":"Der Ball von Manderley","titleZh":"曼德利舞会","lines":[{"id":"rebecca-das-musical-66-001","lineIndex":1,"speaker":"","original":"Sind sie ein Scheich oder Maharadscha?","sourceLineIndex":1,"ipa":"/zɪnt ziː aɪn ʃˈaɪç ˌoːdɜ mˌɑːarˈatʃɑː/","en":"Are you a Sheikh or Maharaja?","zh":"您是酋长或王公吗？","note":""},{"id":"rebecca-das-musical-66-002","lineIndex":2,"speaker":"","original":"Nein, ich wärm nur mein Toupet","sourceLineIndex":2,"ipa":"/nˈaɪn ɪç vˈɛɾm nˈuːɾ maɪn tˈuːpət/","en":"No, I'm just warming my toupee","zh":"不，我只是在加热我的假发","note":""},{"id":"rebecca-das-musical-66-003","lineIndex":3,"speaker":"","original":"Einmal im Jahr blüht die Fantasie beim Maskenball von Manderley","sourceLineIndex":3,"ipa":"/ˈaɪnmˌɑːl ɪm jˈɑːɾ blˈyːt diː fˌantazˈiː baɪm mˈaskənbˌal fɔn mˈandɜlˌaɪ/","en":"Once a year, imagination blossoms at Manderley's masquerade ball","zh":"每年一次，想象力在曼德利的化装舞会上绽放","note":""},{"id":"rebecca-das-musical-66-004","lineIndex":4,"speaker":"","original":"Das Imponieren lassen wir heut' mal bleiben","sourceLineIndex":4,"ipa":"/das ˌɪmpoːnˈiːrən lˈasən viːɾ hˈɔøt mˈɑːl blˈaɪbən/","en":"We'll leave the impressiveness alone today","zh":"今天我们先不谈令人印象深刻的事情","note":""},{"id":"rebecca-das-musical-66-005","lineIndex":5,"speaker":"","original":"Was wir reden und treiben darf hohl sein","sourceLineIndex":5,"ipa":"/vˈas viːɾ rˈeːdən ʊnt tɾˈaɪbən dˈaɾf hˈoːl zaɪn/","en":"What we say and do can be hollow","zh":"我们所说的和所做的可能都是空洞的","note":""},{"id":"rebecca-das-musical-66-006","lineIndex":6,"speaker":"","original":"Und wenn es später wird wagt man ein Küsschen","sourceLineIndex":6,"ipa":"/ʊnt vˌɛn ɛs ʃpˈɛːtɜ vˌɪɾt vˈɑːkt man aɪn kˈʏsçən/","en":"And when it gets later you dare to kiss her","zh":"后来你敢吻她","note":""},{"id":"rebecca-das-musical-66-007","lineIndex":7,"speaker":"","original":"Heut' darf man ein bisschen frivol sein","sourceLineIndex":7,"ipa":"/hˈɔøt dˈaɾf man aɪn bˈɪsçən friːvˈoːl zaɪn/","en":"Today you can be a little frivolous","zh":"今天你可以有点轻浮","note":""},{"id":"rebecca-das-musical-66-008","lineIndex":8,"speaker":"","original":"Man fährt statt nach Brighton und Saint Tropez zum Ball von Manderley","sourceLineIndex":8,"ipa":"/man fˈɛːɾt ʃtˈat nɑːx bɹˈaɪtən ʊnt zˈaɪnt tɾˈoːpeːts tsʊm bˈal fɔn mˈandɜlˌaɪ/","en":"Instead of going to Brighton and Saint Tropez, you go to the Manderley ball","zh":"你不去布莱顿和圣特罗佩，而是去曼德利舞会","note":""},{"id":"rebecca-das-musical-66-009","lineIndex":9,"speaker":"","original":"Denn wer in Cornwall was und war, ist hier heut' Nacht","sourceLineIndex":9,"ipa":"/dɛn vˈeːɾ ɪn kˈɔɾnval vˈas ʊnt vɑːɾ ɪst hˈiːɾ hˈɔøt nˈaxt/","en":"Because whoever was in Cornwall is here tonight","zh":"因为无论谁在康沃尔郡今晚都在这里","note":""},{"id":"rebecca-das-musical-66-010","lineIndex":10,"speaker":"","original":"Denn eins ist klar: Das Fest Nummer","sourceLineIndex":10,"ipa":"/dɛn aɪns ɪst klˈɑːɾ das fˈɛst nˈʊmɜ/","en":"Because one thing is clear: the festival number","zh":"因为有一件事是明确的：节日编号","note":""},{"id":"rebecca-das-musical-66-011","lineIndex":11,"speaker":"","original":"Eins ist seit eh und jeh der Ball von Manderley","sourceLineIndex":11,"ipa":"/aɪns ɪst zaɪt ˈeː ʊnt jˈeː dɛɾ bˈal fɔn mˈandɜlˌaɪ/","en":"One thing has always been the Manderley ball","zh":"一件事一直是曼德利球","note":""}],"sourceOrder":66,"displayOrder":42},{"order":67,"id":"67-die-voruntersuchung","title":"Die Voruntersuchung","titleZh":"初步调查","lines":[{"id":"rebecca-das-musical-67-001","lineIndex":1,"speaker":"","original":"Woher soll ich das wissen?","sourceLineIndex":1,"ipa":"/voːhˈeːɾ zˌɔl ɪç das vˈɪsən/","en":"How should I know that?","zh":"我怎么知道呢？","note":""},{"id":"rebecca-das-musical-67-002","lineIndex":2,"speaker":"","original":"Nun, Sie war eingesperrt., Die Luke nach oben war geschlossen.\"","sourceLineIndex":2,"ipa":"/nˈuːn ziː vɑːɾ ˈaɪnɡəʃpˌɛɾt diː lˈuːkə nɑːx ˈoːbən vɑːɾ ɡəʃlˈɔsən/","en":"Well, she was locked up. \"The hatch upstairs was closed.\"","zh":"嗯，她被关起来了。 “楼上的舱门关着。”","note":""},{"id":"rebecca-das-musical-67-003","lineIndex":3,"speaker":"","original":"Die Luke war versperrt!","sourceLineIndex":3,"ipa":"/diː lˈuːkə vɑːɾ fɛɾʃpˈɛɾt/","en":"The hatch was blocked!","zh":"舱门被堵住了！","note":""},{"id":"rebecca-das-musical-67-004","lineIndex":4,"speaker":"","original":"Warum? Zu welchem Zweck?","sourceLineIndex":4,"ipa":"/vɑːrˈʊm tsuː vˈɛlçəm tsvˈɛk/","en":"Why? For what purpose?","zh":"为什么？出于什么目的？","note":""},{"id":"rebecca-das-musical-67-005","lineIndex":5,"speaker":"","original":"Auf jeden Fall war sie","sourceLineIndex":5,"ipa":"/aʊf jˈeːdən fˈal vɑːɾ ziː/","en":"In any case she was","zh":"无论如何，她是","note":""},{"id":"rebecca-das-musical-67-006","lineIndex":6,"speaker":"","original":"Beim Kentern unter Deck","sourceLineIndex":6,"ipa":"/baɪm kˈɛntɜn ˌʊntɜ dˈɛk/","en":"When capsizing below deck","zh":"当在甲板下倾覆时","note":""},{"id":"rebecca-das-musical-67-007","lineIndex":7,"speaker":"","original":"Und als das Segelboot versank","sourceLineIndex":7,"ipa":"/ʊnt als das zˈeːɡəlbˌoːt fɛɾzˈaŋk/","en":"And when the sailboat sank","zh":"当帆船沉没的时候","note":""},{"id":"rebecca-das-musical-67-008","lineIndex":8,"speaker":"","original":"War sie gefangen und ertrank","sourceLineIndex":8,"ipa":"/vɑːɾ ziː ɡəfˈaŋən ʊnt ɛɾtɾˈaŋk/","en":"She was trapped and drowned","zh":"她被困并淹死了","note":""},{"id":"rebecca-das-musical-67-009","lineIndex":9,"speaker":"","original":"Kam das öfter vor, dass Ihre Frau nachts aufs Meer hinausfuhr?","sourceLineIndex":9,"ipa":"/kˌɑːm das ˈœftɜ fˈɔɾ das ˌiːrə frˈaʊ nˈaxts aʊfs mˈeːɾ hɪnˈaʊsfˌuːɾ/","en":"Did it often happen that your wife went out to sea at night?","zh":"你的妻子经常晚上出海吗？","note":""},{"id":"rebecca-das-musical-67-010","lineIndex":10,"speaker":"","original":"Sie war ein gute Seglerin und das Boot war seefest. Niemand konnte ahnen, dass er kentern würde","sourceLineIndex":10,"ipa":"/ziː vɑːɾ aɪn ɡˈuːtə zˈɛɡlərˌɪn ʊnt das bˈoːt vɑːɾ zˈeːfəst nˈiːmant kˈɔntə ˈɑːnən das ɛɾ kˈɛntɜn vˈʏɾdə/","en":"She was a good sailor and the boat was seaworthy. Nobody could have guessed that he would capsize","zh":"她是一位优秀的水手，这艘船适合航行。没有人能想到他会翻船","note":""},{"id":"rebecca-das-musical-67-011","lineIndex":11,"speaker":"","original":"Das Boot ist nicht gekentert.","sourceLineIndex":11,"ipa":"/das bˈoːt ɪst nˈɪçt ɡəkˈɛntɜt/","en":"The boat didn't capsize.","zh":"船没有翻。","note":""},{"id":"rebecca-das-musical-67-012","lineIndex":12,"speaker":"","original":"Der Bericht das Hafenmeisters ist ganz eindeutig:","sourceLineIndex":12,"ipa":"/dɛɾ bərˈɪçt das hˈɑfənmˌaɪstɜs ɪst ɡˌants ˈaɪndˌɔøtɪç/","en":"The harbor master's report is very clear:","zh":"港务长的报告非常明确：","note":""},{"id":"rebecca-das-musical-67-013-a","lineIndex":13,"speaker":"","original":", Im Bootsrumpf waren Löcher","sourceLineIndex":13,"ipa":"/ɪm bˈoːtsrʊmpf vɑːrən lˈœçɜ ˈɔfɛnzˌɪçtlɪç fɔn ˈɪnən ɡəbˈoːɾt ʊnt diː ʃˈɔtən vˈaɾn ɡəˈœfnət das bˈoːt vˌʊɐdə fˈoːɾzˌɛtslɪç ɡəflˈuːtət ʊnt fɛɾzˈɛŋkt/","en":"\"There were holes in the boat's hull","zh":"“船体上有洞","note":""},{"id":"rebecca-das-musical-67-013-b","lineIndex":14,"speaker":"","original":"offensichtlich von innen gebohrt","sourceLineIndex":13,"ipa":"/ɪm bˈoːtsrʊmpf vɑːrən lˈœçɜ ˈɔfɛnzˌɪçtlɪç fɔn ˈɪnən ɡəbˈoːɾt ʊnt diː ʃˈɔtən vˈaɾn ɡəˈœfnət das bˈoːt vˌʊɐdə fˈoːɾzˌɛtslɪç ɡəflˈuːtət ʊnt fɛɾzˈɛŋkt/","en":"obviously drilled from the inside","zh":"显然是从里面钻出来的","note":""},{"id":"rebecca-das-musical-67-013-c","lineIndex":15,"speaker":"","original":"und die Schotten warn geöffnet.","sourceLineIndex":13,"ipa":"/ɪm bˈoːtsrʊmpf vɑːrən lˈœçɜ ˈɔfɛnzˌɪçtlɪç fɔn ˈɪnən ɡəbˈoːɾt ʊnt diː ʃˈɔtən vˈaɾn ɡəˈœfnət das bˈoːt vˌʊɐdə fˈoːɾzˌɛtslɪç ɡəflˈuːtət ʊnt fɛɾzˈɛŋkt/","en":"and the bulkheads were open.","zh":"而且舱壁是敞开的。","note":""},{"id":"rebecca-das-musical-67-013-d","lineIndex":16,"speaker":"","original":"Das Boot wurde vorsätzlich geflutet und versenkt.\"","sourceLineIndex":13,"ipa":"/ɪm bˈoːtsrʊmpf vɑːrən lˈœçɜ ˈɔfɛnzˌɪçtlɪç fɔn ˈɪnən ɡəbˈoːɾt ʊnt diː ʃˈɔtən vˈaɾn ɡəˈœfnət das bˈoːt vˌʊɐdə fˈoːɾzˌɛtslɪç ɡəflˈuːtət ʊnt fɛɾzˈɛŋkt/","en":"The boat was deliberately flooded and sunk.\"","zh":"船是被故意淹没并沉没的。”","note":""},{"id":"rebecca-das-musical-67-014","lineIndex":17,"speaker":"","original":"Der Bootsrumpf war durchbohrt!","sourceLineIndex":14,"ipa":"/dɛɾ bˈoːtsrʊmpf vɑːɾ dʊɐçbˈoːɾt/","en":"The boat's hull was punctured!","zh":"船体被击穿！","note":""},{"id":"rebecca-das-musical-67-015","lineIndex":18,"speaker":"","original":"Man hat das Boot versenkt","sourceLineIndex":15,"ipa":"/man hat das bˈoːt fɛɾzˈɛŋkt/","en":"The boat was sunk","zh":"船沉了","note":""},{"id":"rebecca-das-musical-67-016","lineIndex":19,"speaker":"","original":"Ein Unfall scheidet aus","sourceLineIndex":16,"ipa":"/aɪn ˈʊnfˌal ʃˈaɪdət ˈaʊs/","en":"An accident is ruled out","zh":"排除事故发生的可能","note":""},{"id":"rebecca-das-musical-67-017","lineIndex":20,"speaker":"","original":"Was immer man auch denkt","sourceLineIndex":17,"ipa":"/vˈas ˈɪmɜ man ˌaʊx dˈɛŋkt/","en":"Whatever you think","zh":"不管你怎么想","note":""},{"id":"rebecca-das-musical-67-018","lineIndex":21,"speaker":"","original":"Hielt nicht ein Unglück sie an Bord","sourceLineIndex":18,"ipa":"/hˈiːlt nˈɪçt aɪn ˈʊnɡlˌʏk ziː an bˈɔɾt/","en":"There was no misfortune that kept them on board","zh":"没有什么不幸让他们留在船上","note":""},{"id":"rebecca-das-musical-67-019","lineIndex":22,"speaker":"","original":"Dann war es Selbstmord oder Mord","sourceLineIndex":19,"ipa":"/dan vɑːɾ ɛs zˈɛlpstmɔɾt ˌoːdɜ mˈɔɾt/","en":"Then it was suicide or murder","zh":"然后就是自杀或者谋杀","note":""},{"id":"rebecca-das-musical-67-020","lineIndex":23,"speaker":"","original":"Mr. de Winter. Wussten Sie von den Löchern im Rumpf des Bootes?","sourceLineIndex":20,"ipa":"/ˌɛmˈɛɾ dˈeː vˈɪntɜ vˈʊstən ziː fɔn deːn lˈœçɜn ɪm rˈʊmpf dɛs bˈoːtəs/","en":"Mr. de Winter. Did you know about the holes in the boat's hull?","zh":"德温特先生。你知道船体上的洞吗？","note":""},{"id":"rebecca-das-musical-67-021","lineIndex":24,"speaker":"","original":"Wie hätte ich davon wissen können?","sourceLineIndex":21,"ipa":"/viː hˌɛtə ɪç dɑːfˈɔn vˈɪsən kˈœnən/","en":"How could I have known about this?","zh":"我怎么会知道这件事？","note":""},{"id":"rebecca-das-musical-67-022","lineIndex":25,"speaker":"","original":"Zu hören, dass das Boot vorsätzlich versenkt wurde, überrascht Sie also?","sourceLineIndex":22,"ipa":"/tsuː hˈøːrən das das bˈoːt fˈoːɾzˌɛtslɪç fɛɾzˈɛŋkt vˌʊɐdə ˌyːbɜrˈaʃt ziː ˈalzoː/","en":"So hearing that the boat was intentionally sunk surprises you?","zh":"听说这艘船是故意沉没的，你感到惊讶吗？","note":""},{"id":"rebecca-das-musical-67-023","lineIndex":26,"speaker":"","original":"Selbstverständlich überrascht ich dass. Was soll diese Frage?","sourceLineIndex":23,"ipa":"/zˈɛlpstfɛɾʃtˌɛntlɪç ˌyːbɜrˈaʃt ɪç dˈas vˈas zˌɔl dˌiːzə frˈɑːɡə/","en":"Of course that surprises me. What is this question about?","zh":"当然，这让我感到惊讶。这个问题是关于什么的？","note":""},{"id":"rebecca-das-musical-67-024","lineIndex":27,"speaker":"","original":"Wenn es nicht Rebecca de Winter selbst war, muss jemand mit ihr auf dem Boot gewesen sein","sourceLineIndex":24,"ipa":"/vˌɛn ɛs nˈɪçt reːbˈɛkɑː dˈeː vˈɪntɜ zˈɛlpst vɑːɾ mˈʊs jˈeːmant mɪt iːɾ aʊf deːm bˈoːt ɡəvˈeːzən zaɪn/","en":"If it wasn't Rebecca de Winter herself, someone must have been on the boat with her","zh":"如果不是丽贝卡·德温特本人，一定有人和她一起在船上","note":""},{"id":"rebecca-das-musical-67-025","lineIndex":28,"speaker":"","original":"Warum sagen Sie mir das?","sourceLineIndex":25,"ipa":"/vɑːrˈʊm zˈɑːɡən ziː miːɾ das/","en":"Why are you telling me this?","zh":"你为什么告诉我这个？","note":""},{"id":"rebecca-das-musical-67-026","lineIndex":29,"speaker":"","original":"Mr. de Winter. Gab es Probleme in der Beziehung zwischen Ihnen und Ihrer verstorbenen Frau?","sourceLineIndex":26,"ipa":"/ˌɛmˈɛɾ dˈeː vˈɪntɜ ɡˈɑːp ɛs pɾoːblˈeːmə ɪn dɛɾ bətsˈiːʊŋ tsvˈɪʃən ˌiːnən ʊnt ˌiːrɜ fɛɾʃtˈɔɾbənən frˈaʊ/","en":"Mr. de Winter. Were there any problems in the relationship between you and your late wife?","zh":"德温特先生。您和已故妻子之间的关系有问题吗？","note":""},{"id":"rebecca-das-musical-67-027","lineIndex":30,"speaker":"","original":"Das ist eine Unverschämtheit","sourceLineIndex":27,"ipa":"/das ɪst ˌaɪnə ˈʊnfɛɾʃˌɛmtaɪt/","en":"This is an outrage","zh":"这是一种愤怒","note":""},{"id":"rebecca-das-musical-67-028","lineIndex":31,"speaker":"","original":"Was soll das?","sourceLineIndex":28,"ipa":"/vˈas zˌɔl das/","en":"What's that supposed to mean?","zh":"那是什么意思？","note":""},{"id":"rebecca-das-musical-67-029","lineIndex":32,"speaker":"","original":"Meine Ehe war... Ich lehne es ab... das sind verdammte Unterstellungen...","sourceLineIndex":29,"ipa":"/mˌaɪnə ˈeːə vɑːɾ ɪç lˈeːnə ɛs ˈap das zɪnt fɛɾdˈamtə ˌʊntɜʃtˈɛlʊŋən/","en":"My marriage was... I refuse... those are damning insinuations...","zh":"我的婚姻是……我拒绝……这些都是该死的暗示……","note":""},{"id":"rebecca-das-musical-67-030","lineIndex":33,"speaker":"","original":"Um Gottes Willen! Mrs. de Winter! Sie ist ohnmächtig geworden","sourceLineIndex":30,"ipa":"/ʊm ɡˈɔtəs vˈɪlən ˌɛmˌɛrˈɛs dˈeː vˈɪntɜ ziː ɪst ˈoːnmɛçtˌɪç ɡəvˌɔɾdən/","en":"For God's sake! Mrs de Winter! She fainted","zh":"看在上帝的份上！德温特夫人！她晕倒了","note":""},{"id":"rebecca-das-musical-67-031","lineIndex":34,"speaker":"","original":"Die Verhandlung wird auf Freitag, zwei Uhr Nachmittag, vertagt","sourceLineIndex":31,"ipa":"/diː fɛɾhˈandlʊŋ vˌɪɾt aʊf frˈaɪtɑːk tsvˈaɪ ˈuːɾ nˈaxmɪtˌɑːk fɛɾtˈɑːkt/","en":"The hearing is adjourned to Friday at two o'clock in the afternoon","zh":"听证会延期至周五下午两点","note":""}],"sourceOrder":67,"displayOrder":43},{"order":68,"id":"68-du-machst-mir-angst","title":"Du machst mir Angst","titleZh":"你让我害怕","lines":[{"id":"rebecca-das-musical-68-001","lineIndex":1,"speaker":"","original":"Die Wahrheit ist","sourceLineIndex":1,"ipa":"/diː vˈɑːɾhaɪt ɪst/","en":"The truth is","zh":"事实是","note":""},{"id":"rebecca-das-musical-68-002","lineIndex":2,"speaker":"","original":"Ich weiß nicht, wer ich bin","sourceLineIndex":2,"ipa":"/ɪç vˈaɪs nˈɪçt vˈeːɾ ɪç bɪn/","en":"I don't know who I am","zh":"我不知道我是谁","note":""},{"id":"rebecca-das-musical-68-003","lineIndex":3,"speaker":"","original":"Ich habe mich verloren","sourceLineIndex":3,"ipa":"/ɪç hɑːbə mɪç fɛɾlˈoːrən/","en":"I lost myself","zh":"我迷失了自己","note":""},{"id":"rebecca-das-musical-68-004","lineIndex":4,"speaker":"","original":"Nirgendwo Hoffnung","sourceLineIndex":4,"ipa":"/nɪɾɡˈɛndvoː hˈɔfnʊŋ/","en":"No hope anywhere","zh":"任何地方都没有希望","note":""},{"id":"rebecca-das-musical-68-005","lineIndex":5,"speaker":"","original":"Überall Lüge","sourceLineIndex":5,"ipa":"/ˌyːbɜˈal lˈyːɡə/","en":"Lies everywhere","zh":"谎言无处不在","note":""},{"id":"rebecca-das-musical-68-006","lineIndex":6,"speaker":"","original":"Hilf mir durch die Nacht","sourceLineIndex":6,"ipa":"/hˈɪlf miːɾ dʊɐç diː nˈaxt/","en":"Help me through the night","zh":"帮助我度过整个夜晚","note":""},{"id":"rebecca-das-musical-68-007","lineIndex":7,"speaker":"","original":"Gib mir die Kraft","sourceLineIndex":7,"ipa":"/ɡˈiːp miːɾ diː kɾˈaft/","en":"Give me the strength","zh":"给我力量","note":""},{"id":"rebecca-das-musical-68-008","lineIndex":8,"speaker":"","original":"Durch die Dunkelheit zu gehn","sourceLineIndex":8,"ipa":"/dʊɐç diː dˈʊnkəlhˌaɪt tsuː ɡˈeːn/","en":"To walk through the darkness","zh":"去走过黑暗","note":""},{"id":"rebecca-das-musical-68-009","lineIndex":9,"speaker":"","original":"Halt mich ganz fest","sourceLineIndex":9,"ipa":"/hˈalt mɪç ɡˌants fˈɛst/","en":"Hold me tight","zh":"抱紧我","note":""},{"id":"rebecca-das-musical-68-010","lineIndex":10,"speaker":"","original":"Wenn das Gestern mir Angst macht","sourceLineIndex":10,"ipa":"/vˌɛn das ɡˈɛstɜn miːɾ ˈaŋst mˈaxt/","en":"If yesterday scares me","zh":"如果昨天让我害怕","note":""},{"id":"rebecca-das-musical-68-011","lineIndex":11,"speaker":"","original":"Und wenn ich gelernt hab","sourceLineIndex":11,"ipa":"/ʊnt vˌɛn ɪç ɡəlˈɛɾnt hˈɑːp/","en":"And when I've learned","zh":"当我学会了","note":""},{"id":"rebecca-das-musical-68-012","lineIndex":12,"speaker":"","original":"Wie man vergisst","sourceLineIndex":12,"ipa":"/viː man fɛɾɡˈɪst/","en":"How to forget","zh":"如何忘记","note":""},{"id":"rebecca-das-musical-68-013","lineIndex":13,"speaker":"","original":"Zeig mir, was Liebe ist","sourceLineIndex":13,"ipa":"/tsˈaɪk mˈiːɾ vˈas lˈiːbə ɪst/","en":"Show me what love is","zh":"让我看看什么是爱","note":""},{"id":"rebecca-das-musical-68-014","lineIndex":14,"speaker":"","original":"Hilf mir durch die Nacht","sourceLineIndex":14,"ipa":"/hˈɪlf miːɾ dʊɐç diː nˈaxt/","en":"Help me through the night","zh":"帮助我度过整个夜晚","note":""},{"id":"rebecca-das-musical-68-015","lineIndex":15,"speaker":"","original":"Gib mir die Kraft","sourceLineIndex":15,"ipa":"/ɡˈiːp miːɾ diː kɾˈaft/","en":"Give me the strength","zh":"给我力量","note":""},{"id":"rebecca-das-musical-68-016","lineIndex":16,"speaker":"","original":"Durch die Dunkelheit zu gehn","sourceLineIndex":16,"ipa":"/dʊɐç diː dˈʊnkəlhˌaɪt tsuː ɡˈeːn/","en":"To walk through the darkness","zh":"去走过黑暗","note":""},{"id":"rebecca-das-musical-68-017","lineIndex":17,"speaker":"","original":"Halt mich ganz fest","sourceLineIndex":17,"ipa":"/hˈalt mɪç ɡˌants fˈɛst/","en":"Hold me tight","zh":"抱紧我","note":""},{"id":"rebecca-das-musical-68-018","lineIndex":18,"speaker":"","original":"Wenn das Gestern mir Angst macht","sourceLineIndex":18,"ipa":"/vˌɛn das ɡˈɛstɜn miːɾ ˈaŋst mˈaxt/","en":"If yesterday scares me","zh":"如果昨天让我害怕","note":""},{"id":"rebecca-das-musical-68-019","lineIndex":19,"speaker":"","original":"Und wenn ich gelernt hab","sourceLineIndex":19,"ipa":"/ʊnt vˌɛn ɪç ɡəlˈɛɾnt hˈɑːp/","en":"And when I've learned","zh":"当我学会了","note":""},{"id":"rebecca-das-musical-68-020","lineIndex":20,"speaker":"","original":"Wie man vergisst","sourceLineIndex":20,"ipa":"/viː man fɛɾɡˈɪst/","en":"How to forget","zh":"如何忘记","note":""},{"id":"rebecca-das-musical-68-021","lineIndex":21,"speaker":"","original":"Zeig mir, was Liebe ist","sourceLineIndex":21,"ipa":"/tsˈaɪk mˈiːɾ vˈas lˈiːbə ɪst/","en":"Show me what love is","zh":"让我看看什么是爱","note":""}],"sourceOrder":68,"displayOrder":44},{"order":69,"id":"69-keiner-hat-sie-durchschaut","title":"Keiner hat sie durchschaut","titleZh":"没有人看透她","lines":[{"id":"rebecca-das-musical-69-001","lineIndex":1,"speaker":"","original":"Ja","sourceLineIndex":1,"ipa":"/jˈɑː/","en":"Yes","zh":"是的","note":""},{"id":"rebecca-das-musical-69-002","lineIndex":2,"speaker":"","original":"Sie wollte sterben","sourceLineIndex":2,"ipa":"/ziː vɔltə ʃtˈɛɾbən/","en":"She wanted to die","zh":"她想死","note":""},{"id":"rebecca-das-musical-69-003","lineIndex":3,"speaker":"","original":"Und mein Leben zertören","sourceLineIndex":3,"ipa":"/ʊnt maɪn lˈeːbən tsɛɾtˈøːrən/","en":"And destroy my life","zh":"并毁掉我的生活","note":""}],"sourceOrder":69,"displayOrder":45},{"order":70,"id":"70-petit-dejeuner","title":"Petit Dejeuner","titleZh":"早餐","lines":[{"id":"rebecca-das-musical-70-001","lineIndex":1,"speaker":"","original":"Sie hat Halsschmerzen","sourceLineIndex":1,"ipa":"/ziː hat hˈalsçmɜtsən/","en":"She has a sore throat","zh":"她嗓子疼","note":""},{"id":"rebecca-das-musical-70-002","lineIndex":2,"speaker":"","original":"Die übliche Grippe, denke ich","sourceLineIndex":2,"ipa":"/diː ˈyːplɪçə ɡɾˈɪpə dˈɛŋkə ɪç/","en":"The usual flu, I'd say","zh":"大概是老毛病流感了，我想","note":""},{"id":"rebecca-das-musical-70-003","lineIndex":3,"speaker":"","original":"Bittesehr, Mademoiselle!","sourceLineIndex":3,"ipa":"/bˈɪteːzˌeːɾ mˌɑdeːmˌoːiːzˈɛlə/","en":"Here you are, Mademoiselle!","zh":"给您，小姐！","note":""},{"id":"rebecca-das-musical-70-004","lineIndex":4,"speaker":"","original":"Oh nein, oh es tut mir leid!","sourceLineIndex":4,"ipa":"/ˈoː nˈaɪn ˈoː ɛs tˈuːt miːɾ lˈaɪt/","en":"Oh no, oh, I'm so sorry!","zh":"哦不，哦，真抱歉！","note":""},{"id":"rebecca-das-musical-70-005","lineIndex":5,"speaker":"","original":"Lassen Sie das und legen Sie hier noch ein Gedeck auf","sourceLineIndex":5,"ipa":"/lˈasən ziː das ʊnt lˈeːɡən ziː hˈiːɾ nɔx aɪn ɡədˈɛk ˈaʊf/","en":"Leave that and lay another place setting here","zh":"把那个放下，再在这儿摆上一份餐具","note":""},{"id":"rebecca-das-musical-70-006","lineIndex":6,"speaker":"","original":"Mademoiselle wird mit mir frühstücken","sourceLineIndex":6,"ipa":"/mˌɑdeːmˌoːiːzˈɛlə vˌɪɾt mɪt miːɾ frˈyːʃtʏkən/","en":"Mademoiselle will breakfast with me","zh":"小姐要陪我用早餐","note":""},{"id":"rebecca-das-musical-70-007","lineIndex":7,"speaker":"","original":"Nein, nein... Das geht doch nicht!","sourceLineIndex":7,"ipa":"/nˈaɪn nˈaɪn das ɡˈeːt dɔx nˈɪçt/","en":"No, no... That simply won't do!","zh":"不，不……这怎么行！","note":""},{"id":"rebecca-das-musical-70-008","lineIndex":8,"speaker":"","original":"Wollen Sie vor einem nassen Tischtuch sitzen?","sourceLineIndex":8,"ipa":"/vɔlən ziː fˌɔɾ ˌaɪnəm nˈasən tˈɪʃtʊx zˈɪtsən/","en":"You'd sit at a wet tablecloth?","zh":"您要坐在湿桌布跟前吗？","note":""},{"id":"rebecca-das-musical-70-009","lineIndex":9,"speaker":"","original":"Es macht mir nichts aus, wirklich nicht","sourceLineIndex":9,"ipa":"/ɛs mˈaxt miːɾ nˈɪçts ˈaʊs vˈɪɾklɪç nˈɪçt/","en":"It doesn't bother me, truly not","zh":"我一点都不介意，真的","note":""},{"id":"rebecca-das-musical-70-010","lineIndex":10,"speaker":"","original":"Ach was, kommen Sie!","sourceLineIndex":10,"ipa":"/ˈax vˈas kˈɔmən ziː/","en":"Nonsense, come along!","zh":"哪儿的话，来吧！","note":""},{"id":"rebecca-das-musical-70-011","lineIndex":11,"speaker":"","original":"Ich wollte Sie ohnehin bitten sich zu mir zu setzen, Bitteschön!","sourceLineIndex":11,"ipa":"/ɪç vɔltə ziː ˈoːneːˌɪn bˈɪtən zɪç tsuː miːɾ tsuː zˈɛtsən bˈɪtɛʃˌøːn/","en":"I was going to ask you to sit with me anyway, do!","zh":"我本就想请您过来同坐，请吧！","note":""},{"id":"rebecca-das-musical-70-012","lineIndex":12,"speaker":"","original":"Das ist sehr freundlich von Ihnen!","sourceLineIndex":12,"ipa":"/das ɪst zˈeːɾ frˈɔøntlɪç fɔn ˈiːnən/","en":"That's very kind of you!","zh":"您真是太客气了！","note":""},{"id":"rebecca-das-musical-70-013","lineIndex":13,"speaker":"","original":"Sie müssen mir verzeihen","sourceLineIndex":13,"ipa":"/ziː mˈʏsən miːɾ fɛɾtsˈaɪən/","en":"You must forgive me","zh":"您得原谅我","note":""},{"id":"rebecca-das-musical-70-014","lineIndex":14,"speaker":"","original":"Ich war... ziemlich unhöflich, gestern","sourceLineIndex":14,"ipa":"/ˈɪç vɑːɾ tsˈiːmlɪç ˈʊnhˌøːflɪç ɡˈɛstɜn/","en":"I was... rather rude yesterday","zh":"我昨天……颇有些失礼","note":""},{"id":"rebecca-das-musical-70-015","lineIndex":15,"speaker":"","original":"Oh, das fand ich nicht","sourceLineIndex":15,"ipa":"/ˈoː das fˈant ɪç nˈɪçt/","en":"Oh, I didn't think so at all","zh":"哦，我可没那么觉得","note":""},{"id":"rebecca-das-musical-70-016","lineIndex":16,"speaker":"","original":"Mir schien eher, dass Mrs. van Hopper zieml-","sourceLineIndex":16,"ipa":"/miːɾ ʃˈiːn ˈeːɜ das ˌɛmˌɛrˈɛs vˈɑːn hˈɔpɜ tsˈiːml/","en":"It seemed to me that Mrs. van Hopper was ra-","zh":"我倒觉得，范霍珀夫人倒是有","note":""},{"id":"rebecca-das-musical-70-017","lineIndex":17,"speaker":"","original":"Oh ja, ihre Freundin","sourceLineIndex":17,"ipa":"/ˈoː jˈɑː ˌiːrə frˈɔøndɪn/","en":"Oh yes, her friend","zh":"哦对，她的朋友","note":""},{"id":"rebecca-das-musical-70-018","lineIndex":18,"speaker":"","original":"Ich bin angestellt bei ihr als Gesellschafterin","sourceLineIndex":18,"ipa":"/ɪç bɪn ˈanɡəʃtˌɛlt baɪ iːɾ als ɡəzˈɛlʃaftərˌɪn/","en":"I'm employed by her as her companion","zh":"我受雇于她，做她的陪伴女伴","note":""},{"id":"rebecca-das-musical-70-019","lineIndex":19,"speaker":"","original":"Dafür zahlt sie mir neunzig Pfund... im Jahr","sourceLineIndex":19,"ipa":"/dɑːfˈyːɾ tsˈɑːlt ziː miːɾ nˈɔøntsɪç pfˈʊnt ɪm jˈɑːɾ/","en":"For that she pays me ninety pounds... a year","zh":"为此她每年付我九十英镑……","note":""},{"id":"rebecca-das-musical-70-020","lineIndex":20,"speaker":"","original":"Nun, ich wusste nicht, dass man Gesellschaft kaufen kann...","sourceLineIndex":20,"ipa":"/nˈuːn ɪç vˈʊstə nˈɪçt das man ɡəzˈɛlʃaft kˈaʊfən kˌan/","en":"Well, I didn't know companionship could be bought...","zh":"嗯，我还不知道陪伴竟是可以买来的呢……","note":""},{"id":"rebecca-das-musical-70-021","lineIndex":21,"speaker":"","original":"Was soll ich tun? Ich brauche das Geld...","sourceLineIndex":21,"ipa":"/vˈas zˌɔl ɪç tˈuːn ɪç bɾˈaʊxə das ɡˈɛlt/","en":"What am I to do? I need the money...","zh":"我有什么办法？我需要这份钱……","note":""},{"id":"rebecca-das-musical-70-022","lineIndex":22,"speaker":"","original":"Haben Sie denn keine Verwandten?","sourceLineIndex":22,"ipa":"/hˌɑːbən ziː dɛn kˈaɪnə fɛɾvˈantən/","en":"But you have no family, then?","zh":"您难道没有亲人吗？","note":""},{"id":"rebecca-das-musical-70-023","lineIndex":23,"speaker":"","original":"Nein, sie sind alle gestorben","sourceLineIndex":23,"ipa":"/nˈaɪn ziː zɪnt ˈalə ɡəʃtˈɔɾbən/","en":"No, they've all passed away","zh":"没有，他们都过世了","note":""},{"id":"rebecca-das-musical-70-024","lineIndex":24,"speaker":"","original":"Waren Sie hier schon einmal in den Bergen?","sourceLineIndex":24,"ipa":"/vɑːrən ziː hˈiːɾ ʃˌoːn ˈaɪnmˌɑːl ɪn deːn bˈɛɾɡən/","en":"Have you ever been up in the mountains here?","zh":"您可曾来过这山里？","note":""},{"id":"rebecca-das-musical-70-025","lineIndex":25,"speaker":"","original":"Man hat von dort eine fantastische Aussicht!","sourceLineIndex":25,"ipa":"/man hat fɔn dˈɔɾt ˌaɪnə fantˈastɪʃə ˈaʊszˌɪçt/","en":"The view from up there is magnificent!","zh":"从那儿望出去的景致美极了！","note":""},{"id":"rebecca-das-musical-70-026","lineIndex":26,"speaker":"","original":"Nein, Mrs. van Hopper geht keinen Schritt aus dem Hotel","sourceLineIndex":26,"ipa":"/nˈaɪn ˌɛmˌɛrˈɛs vˈɑːn hˈɔpɜ ɡˈeːt kˈaɪnən ʃrˈɪt ˌaʊs deːm hˈoːtəl/","en":"No, Mrs. van Hopper won't step outside the hotel","zh":"没有，范霍珀夫人一步也不肯离开旅馆","note":""},{"id":"rebecca-das-musical-70-027","lineIndex":27,"speaker":"","original":"Dann vergessen wir doch das hier, wir können ja irgendwo einkehren","sourceLineIndex":27,"ipa":"/dan fɛɾɡˈɛsən viːɾ dɔx das hˈiːɾ viːɾ kˌœnən jˈɑː ɪɾɡˈɛndvoː ˈaɪnkˌeːrən/","en":"Then let's forget this, we can stop in somewhere","zh":"那就不提这个了，我们随便找个地方歇脚便是","note":""},{"id":"rebecca-das-musical-70-028","lineIndex":28,"speaker":"","original":"Oh, ja. Aber ich kann doch nicht einfach...","sourceLineIndex":28,"ipa":"/ˈoː jˈɑː ˌɑːbɜ ɪç kˌan dɔx nˈɪçt ˈaɪnfˌax/","en":"Oh, yes. But I can't simply...","zh":"哦，好。可我不能就这么……","note":""},{"id":"rebecca-das-musical-70-029","lineIndex":29,"speaker":"","original":"Ach was, holen Sie sich was zum Überziehen","sourceLineIndex":29,"ipa":"/ˈax vˈas hˈoːlən ziː zɪç vˈas tsʊm ˌyːbɜtsˈiːən/","en":"Nonsense, go fetch something to throw on","zh":"哪儿的话，去拿件外套披上吧","note":""},{"id":"rebecca-das-musical-70-030","lineIndex":30,"speaker":"","original":"Ich lasse inzwischen den Wagen vorfahren","sourceLineIndex":30,"ipa":"/ɪç lˈasə ɪntsvˈɪʃən deːn vˈɑːɡən fˈoːɾfˌɑːrən/","en":"I'll have the car brought round in the meantime","zh":"车我这就让人开到门口等着","note":""},{"id":"rebecca-das-musical-70-031","lineIndex":31,"speaker":"","original":"Kann das sein? Geht das an?","sourceLineIndex":31,"ipa":"/kˈan das zaɪn ɡˈeːt das ˈan/","en":"Can it be true? Is this on?","zh":"这能当真吗？这事能成吗？","note":""},{"id":"rebecca-das-musical-70-032","lineIndex":32,"speaker":"","original":"Ist er freundlich oder flirtet er?","sourceLineIndex":32,"ipa":"/ɪst ɛɾ frˈɔøntlɪç ˌoːdɜ flˈɪɾtət ɛɾ/","en":"Is he being friendly, or flirting?","zh":"他这是客气，还是在调情？","note":""},{"id":"rebecca-das-musical-70-033","lineIndex":33,"speaker":"","original":"Die Frau hat doch nicht sein Niveau!","sourceLineIndex":33,"ipa":"/diː frˈaʊ hat dɔx nˈɪçt zaɪn niːvˈoː/","en":"The girl is hardly his equal!","zh":"那姑娘哪配得上他的档次！","note":""},{"id":"rebecca-das-musical-70-034","lineIndex":34,"speaker":"","original":"Vielleicht doch! Interessant!","sourceLineIndex":34,"ipa":"/fɪlˈaɪçt dˈɔx ˌɪntərɛsˈant/","en":"Perhaps she is! How interesting!","zh":"说不定还真配得上呢！有意思！","note":""},{"id":"rebecca-das-musical-70-035","lineIndex":35,"speaker":"","original":"Hab ich richtig gehört?","sourceLineIndex":35,"ipa":"/hˈɑːp ɪç rˈɪçtɪç ɡəhˈœɾt/","en":"Did I hear that right?","zh":"我刚才没听错吧？","note":""},{"id":"rebecca-das-musical-70-036","lineIndex":36,"speaker":"","original":"Er macht heut' einen Ausflug mit ihr","sourceLineIndex":36,"ipa":"/ɛɾ mˈaxt hˈɔøt ˌaɪnən ˈaʊsflˌuːk mɪt iːɾ/","en":"He's taking an outing with her today","zh":"今天他竟要带她出去游玩","note":""},{"id":"rebecca-das-musical-70-037","lineIndex":37,"speaker":"","original":"Warum nicht? Allerhand","sourceLineIndex":37,"ipa":"/vɑːrˈʊm nˈɪçt ˈalɜhˌant/","en":"Why not? Well, well","zh":"有何不可？啧啧","note":""},{"id":"rebecca-das-musical-70-038","lineIndex":38,"speaker":"","original":"Kaum zu glauben! Ist der Mann denn blind?","sourceLineIndex":38,"ipa":"/kˈaʊm tsuː ɡlˈaʊbən ɪst dɛɾ mˈan dɛn blˈɪnt/","en":"Hard to believe! Is the man blind?","zh":"真叫人难以置信！这男人莫非瞎了眼？","note":""},{"id":"rebecca-das-musical-70-039","lineIndex":39,"speaker":"","original":"Sie ist noch ein Kind! Ein dummes Ding!","sourceLineIndex":39,"ipa":"/ziː ɪst nɔx aɪn kˈɪnt aɪn dˈʊməs dˈɪŋ/","en":"She's still a child! A silly little thing!","zh":"她还是个孩子啊！一个傻丫头！","note":""},{"id":"rebecca-das-musical-70-040","lineIndex":40,"speaker":"","original":"Er sucht Trost, degoutant!","sourceLineIndex":40,"ipa":"/ɛɾ zˈuːxt tɾˈoːst dˌeːɡuːtˈant/","en":"He's seeking comfort—disgusting!","zh":"他这是在寻慰藉，真恶心！","note":""},{"id":"rebecca-das-musical-70-041","lineIndex":41,"speaker":"","original":"Es gehört sich nicht","sourceLineIndex":41,"ipa":"/ɛs ɡəhˈœɾt zɪç nˈɪçt/","en":"It isn't seemly","zh":"成何体统","note":""},{"id":"rebecca-das-musical-70-042","lineIndex":42,"speaker":"","original":"Ich glaub nicht, dass er etwas von ihr will","sourceLineIndex":42,"ipa":"/ɪç ɡlˈaʊp nˈɪçt das ɛɾ ˈɛtvɑːs fɔn iːɾ vɪl/","en":"I don't think he wants anything of hers","zh":"我看他压根不是图她什么","note":""},{"id":"rebecca-das-musical-70-043","lineIndex":43,"speaker":"","original":"Er verlor doch erst kürzlich, seine Frau Rebecca","sourceLineIndex":43,"ipa":"/ɛɾ fɛɾlˈoːɾ dɔx ˈeːɾst kˈʏɾtslɪç zˌaɪnə frˈaʊ reːbˈɛkɑː/","en":"He only just lost his wife Rebecca, after all","zh":"他才刚失去妻子丽贝卡啊","note":""},{"id":"rebecca-das-musical-70-044","lineIndex":44,"speaker":"","original":"Welch ein Schlag","sourceLineIndex":44,"ipa":"/vˈɛlç aɪn ʃlˈɑːk/","en":"What a blow","zh":"何等沉重的打击","note":""},{"id":"rebecca-das-musical-70-045","lineIndex":45,"speaker":"","original":"Jeder weiß, der Mann vergötterte Rebecca","sourceLineIndex":45,"ipa":"/jˈeːdɜ vˈaɪs dɛɾ mˈan fɛɾɡˈœtɜtə reːbˈɛkɑː/","en":"Everyone knows the man idolized Rebecca","zh":"谁都知道，这男人曾把丽贝卡奉若神明","note":""}],"sourceOrder":70,"displayOrder":46},{"order":71,"id":"71-sie-fuhr-n-um-acht","title":"Sie fuhr'n um acht","titleZh":"他们八点出发","lines":[{"id":"rebecca-das-musical-71-001","lineIndex":1,"speaker":"","original":"Es ist Oberst Julyans Pflicht","sourceLineIndex":1,"ipa":"/ɛsɪst ˈoːbɜst jˌuːlyːˈɑːns pflˈɪçt/","en":"It is Colonel Julyan's duty","zh":"这是朱利安上校的职责","note":""},{"id":"rebecca-das-musical-71-002","lineIndex":2,"speaker":"","original":"Er muss den Vorwurf klären","sourceLineIndex":2,"ipa":"/ɛɾ mˈʊs deːn fˈoːɾvˌʊɐf klˈɛːrən/","en":"He has to clarify the accusation","zh":"他必须澄清指控","note":""},{"id":"rebecca-das-musical-71-003","lineIndex":3,"speaker":"","original":"Doch hinter alledem","sourceLineIndex":3,"ipa":"/dɔx hˈɪntɜ ˈaleːdəm/","en":"But behind all that","zh":"但这一切的背后","note":""},{"id":"rebecca-das-musical-71-004","lineIndex":4,"speaker":"","original":"Steckt Favell","sourceLineIndex":4,"ipa":"/ʃtˈɛkt favˈɛl/","en":"Stuck Favell","zh":"卡住法维尔","note":""},{"id":"rebecca-das-musical-71-005","lineIndex":5,"speaker":"","original":"Der Kerl gibt keine Ruhe","sourceLineIndex":5,"ipa":"/dɛɾ kˈɛɾl ɡˈiːpt kˈaɪnə rˈuːə/","en":"The guy won't rest","zh":"这家伙不会休息","note":""},{"id":"rebecca-das-musical-71-006","lineIndex":6,"speaker":"","original":"Die Ratte wittert Morgenluft","sourceLineIndex":6,"ipa":"/diː rˈatə vˈɪtɜt mˈɔɾɡənlˌʊft/","en":"The rat smells morning air","zh":"老鼠闻早晨的空气","note":""},{"id":"rebecca-das-musical-71-007","lineIndex":7,"speaker":"","original":"Die Wahrheit kommt heraus","sourceLineIndex":7,"ipa":"/diː vˈɑːɾhaɪt kˈɔmt hɛrˈaʊs/","en":"The truth comes out","zh":"真相大白","note":""},{"id":"rebecca-das-musical-71-008","lineIndex":8,"speaker":"","original":"So oder so","sourceLineIndex":8,"ipa":"/zoː ˌoːdɜ zˈoː/","en":"Either way","zh":"不管怎样","note":""},{"id":"rebecca-das-musical-71-009","lineIndex":9,"speaker":"","original":"Ist dieser Baker","sourceLineIndex":9,"ipa":"/ɪst dˌiːzɜ bˈɑːkɜ/","en":"Is this Baker","zh":"这是贝克吗","note":""},{"id":"rebecca-das-musical-71-010","lineIndex":10,"speaker":"","original":"Ein richtiger Arzt?","sourceLineIndex":10,"ipa":"/aɪn rˈɪçtɪɡɜ ˈaɾtst/","en":"A real doctor?","zh":"真正的医生？","note":""},{"id":"rebecca-das-musical-71-011","lineIndex":11,"speaker":"","original":"Ja, und das heisst","sourceLineIndex":11,"ipa":"/jˈɑː ʊnt das hˈaɪst/","en":"Yes, and that means","zh":"是的，这意味着","note":""},{"id":"rebecca-das-musical-71-012","lineIndex":12,"speaker":"","original":"Dass er schweigen muss","sourceLineIndex":12,"ipa":"/das ɛɾ ʃvˈaɪɡən mˈʊs/","en":"That he must remain silent","zh":"他必须保持沉默","note":""},{"id":"rebecca-das-musical-71-013","lineIndex":13,"speaker":"","original":"Was wird aus uns","sourceLineIndex":13,"ipa":"/vˈas vˌɪɾt ˌaʊs ˈʊns/","en":"What will become of us?","zh":"我们会变成什么样子？","note":""},{"id":"rebecca-das-musical-71-014","lineIndex":14,"speaker":"","original":"Wenn es wirklich ein Mord war?","sourceLineIndex":14,"ipa":"/vˌɛn ɛs vˈɪɾklɪç aɪn mˈɔɾt vɑːɾ/","en":"What if it really was a murder?","zh":"如果真的是谋杀怎么办？","note":""}],"sourceOrder":71,"displayOrder":47},{"order":72,"id":"72-sie-war-gewohnt-geliebt-zu-werden","title":"Sie war gewohnt, geliebt zu werden","titleZh":"她习惯了被爱","lines":[{"id":"rebecca-das-musical-72-001","lineIndex":1,"speaker":"","original":"Sie war gewohnt, geliebt zu werden","sourceLineIndex":1,"ipa":"/ziː vɑːɾ ɡəvˈoːnt ɡəlˈiːpt tsuː vˌɛɾdən/","en":"She was used to being loved","zh":"她已经习惯了被爱","note":""},{"id":"rebecca-das-musical-72-002","lineIndex":2,"speaker":"","original":"Die Männer waren verrückt nach ihr","sourceLineIndex":2,"ipa":"/diː mˈɛnɜ vɑːrən fɛɾrˈʏkt nɑːx iːɾ/","en":"The men were crazy about her","zh":"男人们为她疯狂","note":""},{"id":"rebecca-das-musical-72-003","lineIndex":3,"speaker":"","original":"Denn sie war mehr als schön","sourceLineIndex":3,"ipa":"/dɛn ziː vɑːɾ mˈeːɾ als ʃˈøːn/","en":"Because she was more than beautiful","zh":"因为她不仅美丽","note":""},{"id":"rebecca-das-musical-72-004","lineIndex":4,"speaker":"","original":"Von ihr ging ein Zauber aus","sourceLineIndex":4,"ipa":"/fɔn iːɾ ɡˈɪŋ aɪn tsˈaʊbɜ ˈaʊs/","en":"A magic emanated from her","zh":"一股魔力从她身上散发出来","note":""},{"id":"rebecca-das-musical-72-005","lineIndex":5,"speaker":"","original":"Den Traum, von ihr geliebt zu werden","sourceLineIndex":5,"ipa":"/deːn tɾˈaʊm fɔn iːɾ ɡəlˈiːpt tsuː vˌɛɾdən/","en":"The dream of being loved by her","zh":"梦见被她爱着","note":""},{"id":"rebecca-das-musical-72-006","lineIndex":6,"speaker":"","original":"Träumte fast jeder Mann","sourceLineIndex":6,"ipa":"/tɾˈɔømtə fˈast jˈeːdɜ mˈan/","en":"Almost every man dreamed","zh":"几乎每个男人都梦想过","note":""},{"id":"rebecca-das-musical-72-007","lineIndex":7,"speaker":"","original":"Und dabei wussten sie, dass sie keiner haben kann","sourceLineIndex":7,"ipa":"/ʊnt dɑːbˈaɪ vˈʊstən ziː das ziː kˈaɪnɜ hˈɑːbən kˌan/","en":"And they knew that no one could have them","zh":"他们知道没人能拥有它们","note":""},{"id":"rebecca-das-musical-72-008","lineIndex":8,"speaker":"","original":"Doch ich bin ihr verwandt","sourceLineIndex":8,"ipa":"/dɔx ɪç bɪn iːɾ fɛɾvˈant/","en":"But I am related to her","zh":"但我和她有血缘关系","note":""},{"id":"rebecca-das-musical-72-009","lineIndex":9,"speaker":"","original":"Ich liebe sie genau wie du","sourceLineIndex":9,"ipa":"/ɪç lˈiːbə ziː ɡənˈaʊ viː duː/","en":"I love her just like you","zh":"我像你一样爱她","note":""},{"id":"rebecca-das-musical-72-010","lineIndex":10,"speaker":"","original":"Wie du finde ich es gar nicht gut","sourceLineIndex":10,"ipa":"/viː duː fˈɪndə ɪç ɛs ɡˌɑːɾnˈɪçt ɡˈuːt/","en":"Like you, I don't think it's good at all","zh":"和你一样，我觉得这根本不好","note":""},{"id":"rebecca-das-musical-72-011","lineIndex":11,"speaker":"","original":"Dass eine And're ihren Platz einnehmen will","sourceLineIndex":11,"ipa":"/das ˌaɪnə ˈandɾə ˌiːrən plˈats ˈaɪnnˌeːmən vɪl/","en":"That someone else wants to take her place","zh":"别人想取代她的位置","note":""},{"id":"rebecca-das-musical-72-012","lineIndex":12,"speaker":"","original":"Rebecca liebte mich","sourceLineIndex":12,"ipa":"/reːbˈɛkɑː lˈiːptə mɪç/","en":"Rebecca loved me","zh":"丽贝卡爱我","note":""},{"id":"rebecca-das-musical-72-013","lineIndex":13,"speaker":"","original":"Ich war doch ihr Lieblingscousin","sourceLineIndex":13,"ipa":"/ɪç vɑːɾ dɔx iːɾ lˌiːblɪŋskuːzˈiːn/","en":"I was her favorite cousin","zh":"我是她最喜欢的表弟","note":""},{"id":"rebecca-das-musical-72-014","lineIndex":14,"speaker":"","original":"Sie war gewohnt, geliebt zu werden","sourceLineIndex":14,"ipa":"/ziː vɑːɾ ɡəvˈoːnt ɡəlˈiːpt tsuː vˌɛɾdən/","en":"She was used to being loved","zh":"她已经习惯了被爱","note":""},{"id":"rebecca-das-musical-72-015","lineIndex":15,"speaker":"","original":"Niemand stand ihr näher","sourceLineIndex":15,"ipa":"/nˈiːmant ʃtˈant iːɾ nˈɛːɜ/","en":"No one was closer to her","zh":"没有人离她更近","note":""},{"id":"rebecca-das-musical-72-016","lineIndex":16,"speaker":"","original":"Die Männer waren verrückt nach ihr","sourceLineIndex":16,"ipa":"/diː mˈɛnɜ vɑːrən fɛɾrˈʏkt nɑːx iːɾ/","en":"The men were crazy about her","zh":"男人们为她疯狂","note":""},{"id":"rebecca-das-musical-72-017","lineIndex":17,"speaker":"","original":"Ich war viel mehr als ein Cousin","sourceLineIndex":17,"ipa":"/ɪç vɑːɾ fˈiːl mˈeːɾ als aɪn kuːzˈiːn/","en":"I was much more than a cousin","zh":"我不仅仅是一个表弟","note":""},{"id":"rebecca-das-musical-72-018","lineIndex":18,"speaker":"","original":"Denn sie war mehr als schön","sourceLineIndex":18,"ipa":"/dɛn ziː vɑːɾ mˈeːɾ als ʃˈøːn/","en":"Because she was more than beautiful","zh":"因为她不仅美丽","note":""},{"id":"rebecca-das-musical-72-019","lineIndex":19,"speaker":"","original":"Von ihr ging ein Zauber aus","sourceLineIndex":19,"ipa":"/fɔn iːɾ ɡˈɪŋ aɪn tsˈaʊbɜ ˈaʊs/","en":"A magic emanated from her","zh":"一股魔力从她身上散发出来","note":""},{"id":"rebecca-das-musical-72-020","lineIndex":20,"speaker":"","original":"Hilf mir suchen, Danny","sourceLineIndex":20,"ipa":"/hˈɪlf miːɾ zˈuːxən dˈaniː/","en":"Help me look, Danny","zh":"帮我看看，丹尼","note":""},{"id":"rebecca-das-musical-72-021","lineIndex":21,"speaker":"","original":"Den Traum, von ihr geliebt zu werden","sourceLineIndex":21,"ipa":"/deːn tɾˈaʊm fɔn iːɾ ɡəlˈiːpt tsuː vˌɛɾdən/","en":"The dream of being loved by her","zh":"梦见被她爱着","note":""},{"id":"rebecca-das-musical-72-022","lineIndex":22,"speaker":"","original":"Ihren Schmuck","sourceLineIndex":22,"ipa":"/ˌiːrən ʃmˈʊk/","en":"your jewelry","zh":"你的珠宝","note":""},{"id":"rebecca-das-musical-72-023","lineIndex":23,"speaker":"","original":"Träumte fast jeder Mann","sourceLineIndex":23,"ipa":"/tɾˈɔømtə fˈast jˈeːdɜ mˈan/","en":"Almost every man dreamed","zh":"几乎每个男人都梦想过","note":""},{"id":"rebecca-das-musical-72-024","lineIndex":24,"speaker":"","original":"Mir würd' es helfen","sourceLineIndex":24,"ipa":"/miːɾ vˈʏɾt ɛs hˈɛlfən/","en":"It would help me","zh":"这会帮助我","note":""},{"id":"rebecca-das-musical-72-025","lineIndex":25,"speaker":"","original":"Und dabei wussten sie, dass sie keiner haben kann","sourceLineIndex":25,"ipa":"/ʊnt dɑːbˈaɪ vˈʊstən ziː das ziː kˈaɪnɜ hˈɑːbən kˌan/","en":"And they knew that no one could have them","zh":"他们知道没人能拥有它们","note":""},{"id":"rebecca-das-musical-72-026","lineIndex":26,"speaker":"","original":"Das wäre in ihrem Sinn, Danny","sourceLineIndex":26,"ipa":"/das vˈɛːrə ɪn ˌiːrəm zˈɪn dˈaniː/","en":"That would be in your mind, Danny","zh":"那会在你的脑海里，丹尼","note":""}],"sourceOrder":72,"displayOrder":48}];
